// Word document defaults used by LibreOffice import/export are 11pt text,
// 0.5in tab stops, and widow/orphan control of two lines.
const PARAGRAPH_SPACING_AFTER_PT: f32 = 0.0;
const DEFAULT_TAB_STOP_PT: f32 = 36.0;
// Without an explicit w:defaultTabStop, Word recovers a separate 420-twip
// application grid for literal U+0009 characters preserved inside w:t.
// Import maps a literal tab to this marker only on that omitted-setting path.
const PRESERVED_WORD_TEXT_TAB_STOP_PT: f32 = 21.0;
const DEFAULT_FONT_SIZE_PT: f32 = 11.0;
const DEFAULT_LINE_HEIGHT_PT: f32 = 14.0;
// Without a section grid, Word's Global::LinesToPoints and Writer's
// nSingleLineSpacing use 240 twips. An active section grid supplies the
// paragraph-spacing unit even when this paragraph disables grid snapping.
const WORD_PARAGRAPH_LINE_UNIT_PT: f32 = 240.0 / units::TWIPS_PER_POINT;
// Writer frame size, including table rows.
const LO_MIN_FRAME_SIZE_PT: f32 = 23.0 / units::TWIPS_PER_POINT;
const TABLE_ROW_MIN_HEIGHT_PT: f32 = LO_MIN_FRAME_SIZE_PT;
const COLLAPSED_EMPTY_CELL_PARAGRAPH_HEIGHT_PT: f32 = 1.0 / units::TWIPS_PER_POINT;
const TABLE_SPACING_AFTER_PT: f32 = 0.0;
const DEFAULT_ORPHAN_LINES: usize = 2;
const DEFAULT_WIDOW_LINES: usize = 2;
const MAX_HYPHENATION_BOTTOM_REFLOWS: u8 = 32;
const MOVE_BACKWARD_SUPPRESS_THRESHOLD: usize = 20;
const LAYOUT_LOOP_CONTROL_MAX: usize = 10_000;
const UNBOUNDED_LAYOUT_EXTENT_PT: f32 = f32::MAX / 4.0;
const MEASURE_SCRATCH_PAGE_HEIGHT_PT: f32 = UNBOUNDED_LAYOUT_EXTENT_PT;
const LAYOUT_EPSILON_PT: f32 = 0.1;
// sets OOXML document defaults to proportional line spacing 115.
const LO_DOCUMENT_DEFAULT_LINE_SPACING_PERCENT: f32 = 115.0;
const PERCENT_SCALE: f32 = 100.0;
const LO_EMPTY_PARAGRAPH_FIRST_LINE_HEIGHT_PER_FONT_SIZE: f32 = 340.0 / 220.0;
// Office fixed output gives both gridbefore.docx (Lucida Sans Unicode in the
// East Asian slot) and large-twips.docx (Droid Sans Fallback in that slot) a
// 17.28pt horizontal table line at 12pt. The shared 36/25 ratio proves this is
// a compatibility line box, not either requested face's platform metrics.
const WORD_LEGACY_ZH_TABLE_LINE_HEIGHT_PER_FONT_SIZE: f32 = 36.0 / 25.0;
// Writer's Word-compatible font cache scales ascent and height by 127% when
// the effective font participates in its CJK compatibility path
// (sw/source/core/txtnode/fntcache.cxx, tdf#129808). Word fixed output exposes
// the same scale for a directly formatted paragraph mark: the 12pt
// tdf135774_numberingShading/tdf138345_numberingHighlight marks produce
// 17.28pt lines, while the 24pt tdf135774_numberingCRProps marks produce
// 34.8--34.944pt lines. Keep the factor on the resolved mark font metrics so
// different faces retain their own natural height.
const WORD_DIRECT_PARAGRAPH_MARK_CJK_HEIGHT_SCALE: f32 = 127.0 / 100.0;
const LO_DRAWING_ANCHOR_MARGIN_LINE_HEIGHT_PT: f32 = 288.0 / units::TWIPS_PER_POINT;
// Word extends a paragraph decoration box beyond its text frame before
// applying w:pBdr/@space and the border stroke. Keep decoration paint and
// paragraph-frame wrap geometry on the same sourced boundary.
const WORD_PARAGRAPH_DECORATION_HORIZONTAL_PADDING_PT: f32 = 1.5;
// Word fixed-format output uses a two-inch separator for ordinary footnotes
// and endnotes. SwPageFootnoteInfo supplies the 10-twip line width and
// 57-twip top/bottom distances used by the footnote layout path.
const WORD_NOTE_SEPARATOR_WIDTH_PT: f32 = 2.0 * units::POINTS_PER_INCH;
const LO_FOOTNOTE_SEPARATOR_STROKE_PT: f32 = 10.0 / units::TWIPS_PER_POINT;
const LO_FOOTNOTE_SEPARATOR_TOP_DIST_PT: f32 = 57.0 / units::TWIPS_PER_POINT;
const LO_FOOTNOTE_SEPARATOR_BOTTOM_DIST_PT: f32 = 57.0 / units::TWIPS_PER_POINT;
const WORD_LEGACY_OUTLINE_WIDTH_PT: f32 = 0.14;
const WORD_LEGACY_RELIEF_OFFSET_PT: f32 = 0.96;
const WORD_FIXED_OUTPUT_DPI: f32 = 600.0;
// Exact-config Word 16.0.20326 left/center/right focus interpolation across
// font sizes, families, bold/italic, character spacing, and horizontal scale
// pins this as a fixed paragraph-terminal cell. It is not a font overhang and
// is deliberately independent of glyph scaling and character spacing.
const WORD_PARAGRAPH_MARK_GRADIENT_ADVANCE_PT: f32 = 9.0;
// Word's fixed-output shadow/reflection working surface retains a transparent
// 10-DIP allocation guard outside its transformed output. The complete effect
// presence matrix keeps this guard when shadow or reflection participates,
// while the glow-only counterexample is cropped to the glow graph's own
// output range. This belongs to raster materialization, not to an authored
// DrawingML radius or alignment rectangle.
const WORD_TEXT_SHADOW_REFLECTION_RASTER_GUARD_PT: f32 = 10.0 * 72.0 / 96.0;
const WORD_STATIC_3D_RASTER_EDGE_GUARD_PT: f32 = 72.0 / 200.0;
// A perspective WPS text host is allocated from the logical source plane with
// four clear cells outside every edge.  Exact Word 16.0.20326 camera/depth and
// natural/white x outline x contour controls keep this allocation invariant
// while the physical solid and painted pixels change independently.  Parallel
// cameras are the stopping controls and do not receive this input allocation.
const WORD_STATIC_3D_PERSPECTIVE_HOST_INPUT_GUARD_PT: f32 = 4.0 * 72.0 / 200.0;
const WORD_STATIC_3D_LAST_COVERAGE_SAMPLE_INSET_PX: f32 = 1.0 / 8.0;
const WORD_HOSTED_STATIC_3D_LEADING_X_GUARD_DOTS: f32 = 13.0;
const WORD_HOSTED_STATIC_3D_LEADING_Y_GUARD_DOTS: f32 = 14.0;
const WORD_HOSTED_STATIC_3D_TRAILING_GUARD_DOTS: f32 = 10.0;
const WORD_HOSTED_STATIC_3D_TRAILING_SAMPLE_INSET_DOTS: f32 = 1.0 / 8.0;
// Word re-realizes the foreground of an on-screen static-3-D effect relative
// to the independently 600-DPI-quantized PDF image rectangle. Controlled
// Office alpha-impulse exports put both axes 2/5 of a pixel beyond that
// rectangle-relative page coordinate. This is the fixed-output sampling
// phase; it is independent of the shape's absolute page position.
const WORD_SCREEN_STATIC_3D_SAMPLE_OFFSET_PX: f32 = 2.0 / 5.0;
// The final resolved coverage lies five 1/32 samples inside the last vertical
// pixel. Office's bottom-edge impulse is alpha 105 (13/32 coverage); the local
// 32-sample resolve produces the adjacent representable value 104.
const WORD_SCREEN_STATIC_3D_LAST_SAMPLE_INSET_PX: f32 = 5.0 / 32.0;
// Internal transport tag for a Word-generated static-3D/effect render target.
// The bytes remain PNG so layout consumers can decode them normally; the PDF
// writer uses the tag to apply Word's fixed-output JPEG color-plane policy.
const WORD_STATIC_3D_BITMAP_CONTENT_TYPE: &str =
  "application/vnd.ooxmlsdk.wordprocessing-static-3d+png";
// Word's fixed output realizes a legacy DrawingML locked canvas as one
// bitmap.  The independent fdo76249 width/height probes produce 220x194
// pixels for a 79.35x70.165pt wp:extent: both axes use the same 200-DPI
// surface and truncate the allocated pixel extent.
const WORD_LOCKED_CANVAS_DPI: f32 = 200.0;
const WORD_LOCKED_CANVAS_NATIVE_DPI: f64 = 600.0;
// Internal transport tag for the completed locked-canvas PNG. The PDF writer
// applies Word's generated-surface JPEG color-plane policy while retaining
// the independently lossless alpha plane.
const WORD_LOCKED_CANVAS_BITMAP_CONTENT_TYPE: &str =
  "application/vnd.ooxmlsdk.wordprocessing-locked-canvas+png";
const WORD_LOCKED_CANVAS_DEVICE_BITMAP_CONTENT_TYPE: &str =
  "application/vnd.ooxmlsdk.wordprocessing-locked-canvas-device+png";
// Legacy locked-canvas text is measured through the screen-compatible GDI
// path. This measurement density is independent of the native paint device.
const WORD_LOCKED_CANVAS_TEXT_MEASURE_DPI: f32 = units::CSS_PIXELS_PER_INCH;
// The 200-DPI locked-canvas allocation retains ten transparent device pixels
// beyond the far edge of the GDI text rectangle. Controlled font-size,
// alignment, inset, shadow, and root-extent probes keep this guard constant
// while the measured text boundary changes independently.
const WORD_LOCKED_CANVAS_TEXT_FAR_EDGE_GUARD_PX: f32 = 10.0;
// Internal transport tag for a PNG drawn through a WPS text story. Word's
// fixed-output writer realizes that child on the WPG 96-DPI bitmap surface
// before applying the configured PDF image compression policy.
const WORD_SHAPE_STORY_BITMAP_CONTENT_TYPE: &str =
  "application/vnd.ooxmlsdk.wordprocessing-shape-story+png";
// Word prints table shading and rules inside a WPS text story on one 200-DPI
// surface while preserving the table text as PDF text.
const WORD_SHAPE_STORY_PAINT_BITMAP_CONTENT_TYPE: &str =
  "application/vnd.ooxmlsdk.wordprocessing-shape-story-paint+png";
// Internal transport tag for a Word WPG backdrop whose RGB samples are
// already associated with a black matte. The PDF writer uses the tag to keep
// the exact color and alpha planes and install `/Matte [0 0 0]` on the SMask.
const WORD_GROUP_GLOW_BITMAP_CONTENT_TYPE: &str =
  "application/vnd.ooxmlsdk.wordprocessing-group-glow+png";
// Internal transport tag for a standalone WPS glow whose RGB samples are
// already associated with a black matte. It has its own tag because the WPS
// and WPG bitmap-surface quantizers are independently evidenced and must not
// become interchangeable merely because their PDF transport is identical.
const WORD_SHAPE_GLOW_BITMAP_CONTENT_TYPE: &str =
  "application/vnd.ooxmlsdk.wordprocessing-shape-glow+png";
// Internal transport tag for a standalone WPS outer shadow whose RGB samples
// are already associated with a black matte. Keep it distinct from glow: the
// two effects share the PDF soft-mask contract, but their Office raster
// surfaces and quantizers are independently evidenced.
const WORD_SHAPE_SHADOW_BITMAP_CONTENT_TYPE: &str =
  "application/vnd.ooxmlsdk.wordprocessing-shape-shadow+png";
// Internal transport tag for Word's device-sampled table-border tiles. The
// fully transparent samples deliberately retain the border color: Office
// writes that same straight RGB plane beside its binary SMask, so a PDF
// viewer's edge sampling stays in the border hue instead of introducing a
// black fringe.
const WORD_TABLE_BORDER_BITMAP_CONTENT_TYPE: &str =
  "application/vnd.ooxmlsdk.wordprocessing-table-border+png";
// Word clips the far end of a vertical table rule after adding a sub-pixel
// device-space ownership bias. The 376/384/390/394-twip row-height x
// 1410..1421-twip page-origin Office matrix isolates the common interval to
// 0.7556..0.7561 of a 600-DPI device dot. Keep the midpoint in device space:
// applying a point-space approximation moves two controls across the floor
// threshold because the A4 logical and fixed-output extents differ.
const WORD_TABLE_VERTICAL_BORDER_END_BIAS_DOTS: f64 = 0.755_85;
// Word fixed output snaps the legacy field glyph to its 600-DPI printer grid.
// The independent 10-point Arial (checkboxes.docx), 11-point Calibri
// (n766477.docx), and colored 10-point Open Sans fallback (tdf92472.docx)
// counterexamples agree on these grid widths while retaining different
// font-metric portion sizes and the authored run color.
const WORD_LEGACY_FORM_CHECK_BOX_OUTER_INSET_DOTS: f32 = 6.5;
const WORD_LEGACY_FORM_CHECK_BOX_BORDER_DOTS: f32 = 6.0;
const WORD_LEGACY_FORM_CHECK_BOX_MARK_DOTS: f32 = 4.0;
const WORD_LEGACY_FORM_CHECK_BOX_MARK_OVERHANG_DOTS: f32 = 1.0;
const WORD_LEGACY_SHADOW_OFFSET_PER_FONT_SIZE: f32 = 0.04;
const WORD_VERTICAL_FRAME_SINGLE_LINE_HEIGHT_PER_FONT_SIZE: f32 = 1.25;
const WORD_LEGACY_EFFECT_BLACK: RgbColor = RgbColor { r: 0, g: 0, b: 0 };
const WORD_LEGACY_EFFECT_GRAY: RgbColor = RgbColor {
  r: 0x99,
  g: 0x99,
  b: 0x99,
};
const WORD_LEGACY_SHADOW_GRAY: RgbColor = RgbColor {
  r: 0xc0,
  g: 0xc0,
  b: 0xc0,
};

