#[derive(Clone, Copy, Debug, Default, PartialEq)]
struct ParagraphFootnoteReservation {
  height_pt: f32,
  lower_space: Option<FootnoteLowerSpace>,
  // Retain the reservation that forced a reference onto a follow. Removing
  // it would pull that reference back, producing an unstable page assignment.
  reference_keep_height_pt: f32,
  count: usize,
}

fn apply_paragraph_footnote_reservation(
  mut flow: FlowContext,
  page_index: usize,
  plan: &HashMap<usize, ParagraphFootnoteReservation>,
) -> FlowContext {
  flow.footnote_lower_space = None;
  if let Some(reservation) = plan.get(&page_index) {
    flow.content_bottom = flow
      .content_bottom
      .min(flow.body_content_bottom_pt - reservation.height_pt);
    flow.content_bottom = flow
      .content_bottom
      .min(flow.body_content_bottom_pt - reservation.reference_keep_height_pt);
    if reservation.reference_keep_height_pt <= reservation.height_pt {
      flow.footnote_lower_space = reservation.lower_space;
    }
  }
  flow
}

