#[derive(Clone, Copy, Debug)]
struct ResolvedTabStop {
  x_pt: f32,
  alignment: TabStopAlignment,
  leader: TabLeader,
  automatic: bool,
}

#[derive(Clone, Debug)]
struct PendingAlignedTab {
  stop: ResolvedTabStop,
  leader_start_x_pt: f32,
  leader_layout: TabLeaderLayout,
  y_pt: f32,
  line_height_pt: f32,
  style: TextStyle,
  item_start_index: usize,
  field_result_tab: bool,
  paragraph_bidi: bool,
}

fn aligned_tab_provisional_line_right(
  pending_tab: Option<&PendingAlignedTab>,
  line_right: f32,
) -> f32 {
  let Some(tab) = pending_tab else {
    return line_right;
  };
  if tab.stop.alignment == TabStopAlignment::Left {
    return line_right;
  }
  if tab.stop.x_pt > line_right + LAYOUT_EPSILON_PT {
    // A compatibility tab beyond the text margin deliberately activates the
    // existing tab-over-margin path, whose following portions do not wrap at
    // the paragraph edge.
    return line_right;
  }

  // An aligned tab may shrink to zero when its following portions overrun
  // the alignment point. Word first fits those portions into the complete
  // remaining paragraph width, then settles the tab; it does not wrap at
  // the distance to the alignment point. SwTabPortion::PreFormat/PostFormat
  // likewise starts with a minimum tab and only stretches it afterward.
  // Our provisional cursor starts at the tab point instead of the pre-tab
  // cursor, so translate the remaining capacity into those coordinates.
  tab.stop.x_pt + (line_right - tab.leader_start_x_pt).max(0.0)
}

