  #[test]
  fn footer_bottom_margin_area_starts_at_the_higher_story_or_margin_top() {
    let page_height = 841.9;
    let cases = [
      (36.0, Some(780.75), 780.75),
      (54.0, Some(780.75), 780.75),
      (72.0, Some(780.75), 769.9),
      (108.0, Some(780.75), 733.9),
      (36.0, Some(794.25), 794.25),
      (36.0, Some(765.0), 765.0),
      (36.0, None, 805.9),
    ];
    for (margin, story_top, expected_top) in cases {
      let (top, height) = bottom_margin_reference_bounds(page_height, margin, story_top);
      assert!(
        (top - expected_top).abs() < 0.001,
        "margin={margin}, story={story_top:?}"
      );
      assert!((top + height - page_height).abs() < 0.001);
    }
  }

  #[test]
