  #[test]
  fn vml_text_frame_keeps_natural_leading_independent_of_auto_line_multiple() {
    let mut metrics = TextMetrics::new();
    for family in ["Times New Roman", "Arial", "Calibri"] {
      for size in [12.0, 18.0, 24.0] {
        let mut source = text_warp_bounds_test_item(size);
        source.style.font_family = Some(Arc::from(family));
        source.style.bold = false;
        source.style.use_windows_font_metrics = true;
        source.y_pt = 20.0;
        let natural = metrics.line_vertical_metrics_for_text(&source.text, &source.style);
        source.line_height_pt = natural.line_height_pt();
        for multiple in [1.0, 1.15, 1.5] {
          let mut items = vec![PageItem::Text(Box::new(source.clone()))];
          align_word_text_frame_line_baselines(
            &mut items,
            0,
            20.0,
            natural.line_height_pt() * multiple,
            LineHeightRule::Auto,
            false,
            &mut metrics,
          );
          let baseline = item_alignment_y(&items[0], &mut metrics, true).unwrap();
          assert!(
            (baseline - 20.0 - natural.directwrite_baseline_offset_pt).abs() < 0.001,
            "{family} {size}pt / {multiple}x"
          );
        }
      }
    }
  }

  #[test]
  fn vml_text_frame_later_larger_run_raises_earlier_run_to_shared_baseline() {
    let mut small = text_warp_bounds_test_item(11.0);
    small.text = "аукциона (Комиссия".to_string();
    small.style.font_family = Some(Arc::from("Times New Roman"));
    small.style.bold = false;
    small.style.use_windows_font_metrics = true;
    small.line_height_pt = 12.65;
    let mut large = text_warp_bounds_test_item(14.0);
    large.text = ")".to_string();
    large.style.font_family = Some(Arc::from("Times New Roman"));
    large.style.bold = false;
    large.style.use_windows_font_metrics = true;
    large.line_height_pt = 16.1;
    large.x_pt = 210.0;
    let mut items = vec![
      PageItem::Text(Box::new(small)),
      PageItem::Text(Box::new(large)),
    ];
    let mut metrics = TextMetrics::new();
    let first_baseline = item_alignment_y(&items[0], &mut metrics, true).unwrap();
    let second_baseline = item_alignment_y(&items[1], &mut metrics, true).unwrap();
    assert!((second_baseline - first_baseline).abs() > 0.25);

    align_word_text_frame_line_baselines(
      &mut items,
      0,
      20.0,
      16.1,
      LineHeightRule::Auto,
      false,
      &mut metrics,
    );

    let first_baseline = item_alignment_y(&items[0], &mut metrics, true).unwrap();
    let second_baseline = item_alignment_y(&items[1], &mut metrics, true).unwrap();
    assert!((first_baseline - second_baseline).abs() < 0.001);
    let PageItem::Text(large) = &items[1] else {
      unreachable!()
    };
    let large_metrics = metrics.line_vertical_metrics_for_text(&large.text, &large.style);
    let windows_baseline = metrics.baseline_offset_in_line_with_windows_metrics_for_text(
      &large.text,
      &large.style,
      large.line_height_pt,
    );
    assert!(
      (large.y_pt - 20.0 - (large_metrics.directwrite_baseline_offset_pt - windows_baseline)).abs()
        < 0.001
    );
    assert!((large.x_pt - 210.0).abs() < 0.001);
  }

  fn curved_vml_wordart_test_shape(text: &str, shadow: &str) -> InlineShape {
    use ooxmlsdk::schemas::schemas_microsoft_com_vml as v;
    use ooxmlsdk::sdk::SdkType;
    let xml = format!(
      r##"<v:shape xmlns:v="urn:schemas-microsoft-com:vml" type="#_x0000_t140"
        style="width:379.25pt;height:59.45pt" fillcolor="black">
        {shadow}<v:textpath style="font-family:&quot;Times New Roman&quot;;v-text-kern:t"
          string="{text}" trim="t" fitpath="t"/>
      </v:shape>"##,
    );
    let shape = v::Shape::from_bytes(xml.as_bytes()).unwrap();
    let shape_type = v::Shapetype::from_bytes(
      br#"<v:shapetype xmlns:v="urn:schemas-microsoft-com:vml"
        xmlns:o="urn:schemas-microsoft-com:office:office" id="_x0000_t140"
        coordsize="21600,21600" o:spt="140" adj="5400"
        path="m0@0l10800,,21600@0m,21600l10800@1,21600,21600e">
        <v:formulas><v:f eqn="val #0"/><v:f eqn="sum 21600 0 @0"/></v:formulas>
        <v:path textpathok="t"/><v:textpath on="t" fitshape="t"/>
      </v:shapetype>"#,
    )
    .unwrap();
    crate::docx::vml_shape_shape(
      &shape,
      &crate::docx::ImageCatalog::default(),
      &[&shape_type],
    )
    .unwrap()
  }

  #[test]
  fn vml_textpath_keeps_authored_blank_and_its_kerned_fit_extent() {
    let mut metrics = TextMetrics::new();
    for source in ["AV ", "BULLETIN OFFICIEL ", "BULLETIN OFFICIEL"] {
      let shape = curved_vml_wordart_test_shape(source, "");
      let Block::Paragraph(paragraph) = &shape.text_box_blocks[0] else {
        unreachable!()
      };
      let mut text = text_warp_bounds_test_item(11.0);
      text.text = source.to_string();
      text.style = paragraph.base_style.clone();
      let mut items = vec![PageItem::Text(Box::new(text.clone()))];
      trim_word_compatible_trailing_blanks(&mut items, paragraph, &mut metrics);
      let PageItem::Text(actual) = &items[0] else {
        unreachable!()
      };
      assert_eq!(actual.text, source);
      let ink = text_item_ink_bounds(&text, &mut metrics).unwrap();
      // The native TNR trim rectangle includes its last design-unit edge;
      // an authored final blank still reserves the larger logical advance.
      let inclusive_ink_end = ink.2 + text.style.font_size_pt / 2048.0;
      let logical_end = text.x_pt + metrics.measure_text(source, &text.style);
      apply_shape_text_warp(
        &mut items,
        &shape,
        ShapeTextBoxRect {
          x: 36.0,
          y: 278.35,
          width: shape.width_pt,
          height: shape.height_pt,
        },
        &mut metrics,
      );
      let PageItem::Text(actual) = &items[0] else {
        unreachable!()
      };
      let warp = actual
        .style
        .pdf_glyph_outline_options
        .as_ref()
        .unwrap()
        .text_warp
        .as_ref()
        .unwrap();
      let expected_end = if source.ends_with(' ') {
        inclusive_ink_end.max(logical_end)
      } else {
        inclusive_ink_end
      };
      assert!(
        (warp.source_bounds.origin.x.0 + warp.source_bounds.size.width.0 - expected_end).abs()
          < 0.0001
      );
      assert_eq!(
        warp.vml_fit_path.unwrap().advance_width.0,
        metrics.measure_text(source, &text.style)
      );
      let mut ordinary = (**paragraph).clone();
      ordinary.format.vml_text_path = false;
      let mut ordinary_items = vec![PageItem::Text(Box::new(text))];
      trim_word_compatible_trailing_blanks(&mut ordinary_items, &ordinary, &mut metrics);
      let PageItem::Text(actual) = &ordinary_items[0] else {
        unreachable!()
      };
      assert_eq!(actual.text, source.trim_end());
    }
  }

  #[test]
  fn curved_vml_wordart_uses_native_device_enclosures() {
    // Pinned native MSO bounds readback, seven independent shadow controls.
    for (matrix, offset, enabled, expected) in [
      ("1,,,1", "0pt,0pt", false, [-1.0, 0.0, 495.0, 79.0]),
      ("1,,,1", "-26pt,36pt", true, [-35.0, 0.0, 495.0, 126.0]),
      ("1,,,1", "-26pt,-36pt", true, [-35.0, -47.0, 495.0, 79.0]),
      (
        "1.25,,,1.25",
        "-26pt,-36pt",
        true,
        [-35.0, -47.0, 583.0, 79.0],
      ),
      (
        "1.25,,,1.25",
        "-26pt,36pt",
        true,
        [-35.0, 0.0, 583.0, 146.0],
      ),
      (
        "1.5,,,1.5",
        "-26pt,-36pt",
        true,
        [-35.0, -47.0, 706.0, 79.0],
      ),
      ("1.25,,,1.25", "0pt,0pt", true, [-1.0, 0.0, 617.0, 98.0]),
    ] {
      let shadow = format!(
        r##"<v:shadow on="{}" type="perspective" color="#c7dfd3"
          opacity="52429f" origin="-.5,-.5" offset="{offset}" matrix="{matrix}"/>"##,
        if enabled { "t" } else { "f" },
      );
      let shape = curved_vml_wordart_test_shape("BULLETIN OFFICIEL ", &shadow);
      let Block::Paragraph(paragraph) = &shape.text_box_blocks[0] else {
        unreachable!()
      };
      let mut text = text_warp_bounds_test_item(11.0);
      text.text = "BULLETIN OFFICIEL ".to_string();
      text.style = paragraph.base_style.clone();
      let mut items = vec![PageItem::Text(Box::new(text))];
      let mut metrics = TextMetrics::new();
      apply_shape_text_warp(
        &mut items,
        &shape,
        ShapeTextBoxRect {
          x: 0.0,
          y: 0.0,
          width: shape.width_pt,
          height: shape.height_pt,
        },
        &mut metrics,
      );
      let PageItem::Text(text) = &items[0] else {
        unreachable!()
      };
      let bounds = common::drawingml_shape_raster::vml_wordart_paint_bounds(
        &into_common_text_run((**text).clone()),
        &mut metrics,
      )
      .unwrap()
      .layout_bounds
      .unwrap();
      let actual = [
        bounds.origin.x.0,
        bounds.origin.y.0,
        bounds.origin.x.0 + bounds.size.width.0,
        bounds.origin.y.0 + bounds.size.height.0,
      ]
      .map(|v| v / 0.75);
      assert_eq!(
        actual, expected,
        "matrix={matrix}, offset={offset}, enabled={enabled}"
      );
    }
  }

  #[test]
  fn curved_vml_shadow_owns_upper_and_lower_inline_effect_ranges() {
    // Native up/zero/down matrix controls keep foreground height fixed and
    // grow the line by these independent effect outsets (1440/600-DPI Word).
    for (matrix, offset, shift, growth) in [
      ("1,,,1", "0pt,0pt", 0.0, 0.0),
      ("1,,,1", "-26pt,-36pt", 35.25, 35.25),
      ("1,,,1", "-26pt,36pt", 0.0, 35.25),
      ("1.25,,,1.25", "0pt,0pt", 0.0, 14.25),
      ("1.25,,,1.25", "-26pt,-36pt", 35.25, 35.25),
      ("1.25,,,1.25", "-26pt,36pt", 0.0, 50.25),
    ] {
      let shadow = format!(
        r##"<v:shadow on="t" type="perspective" color="#c7dfd3"
        opacity="52429f" origin="-.5,-.5" offset="{offset}" matrix="{matrix}"/>"##
      );
      let shape = curved_vml_wordart_test_shape("BULLETIN OFFICIEL ", &shadow);
      let Block::Paragraph(paragraph) = &shape.text_box_blocks[0] else {
        unreachable!()
      };
      let mut text = text_warp_bounds_test_item(11.0);
      text.text = "BULLETIN OFFICIEL ".to_string();
      text.style = paragraph.base_style.clone();
      let mut items = vec![PageItem::Text(Box::new(text))];
      let mut metrics = TextMetrics::new();
      apply_shape_text_warp(
        &mut items,
        &shape,
        ShapeTextBoxRect {
          x: 36.0,
          y: 278.34668,
          width: shape.width_pt,
          height: shape.height_pt,
        },
        &mut metrics,
      );
      let actual = vml_wordart_inline_metrics(&items, &shape, 278.34668, &mut metrics).unwrap();
      assert_eq!(
        actual.paint_shift_y_pt, shift,
        "matrix={matrix} offset={offset}"
      );
      assert!(
        (actual.frame_height_pt - shape.height_pt - growth).abs() < 0.0001,
        "matrix={matrix} offset={offset}: {}",
        actual.frame_height_pt
      );
    }
  }

  #[test]
  fn centered_curved_vml_wordart_uses_the_complete_shadow_frame() {
    // Configured native identity/scaled shadows retain the same foreground
    // envelope but move its left edge from 108.35 to 121.20/92.15pt. These
    // controls exercise the formatter and final paragraph adjustment, where
    // remeasuring the foreground alone formerly lost the right effect range.
    for height in [40.0, 59.45] {
      for (shadow, native_left) in [
        (r#"<v:shadow on="f"/>"#, 108.35),
        (
          r##"<v:shadow on="t" type="perspective" color="#c7dfd3"
            opacity="52429f" origin="-.5,-.5" offset="-26pt,-36pt" matrix="1,,,1"/>"##,
          121.20,
        ),
        (
          r##"<v:shadow on="t" type="perspective" color="#c7dfd3"
            opacity="52429f" origin="-.5,-.5" offset="-26pt,-36pt" matrix="1.25,,,1.25"/>"##,
          92.15,
        ),
      ] {
        let mut shape = curved_vml_wordart_test_shape("BULLETIN OFFICIEL ", shadow);
        shape.height_pt = height;
        let Block::Paragraph(mut paragraph) =
          crate::docx::simple_text_block(String::new(), TextStyle::default())
        else {
          unreachable!()
        };
        paragraph.inlines = vec![InlineItem::Shape(shape)];
        paragraph.format.justification.adjust = crate::docx::ParagraphAdjust::Center;
        paragraph.format.alignment = ParagraphAlignment::Center;
        let setup = PageSetup {
          width_pt: 595.3,
          margin_left_pt: 36.0,
          margin_right_pt: 36.0,
          ..Default::default()
        };
        let mut flow = flow_context(setup, 0, SectionColumns::default(), 0, 0, 36.0);
        flow.compatibility_mode = 15;
        let mut page = empty_page(setup, 0);
        let mut pages = Vec::new();
        let mut metrics = TextMetrics::new();
        layout_paragraph(
          &paragraph,
          flow,
          ParagraphLayoutTarget {
            current: &mut page,
            pages: &mut pages,
            anchor_pages: None,
            text_metrics: &mut metrics,
          },
          278.34668,
          278.34668,
          0.0,
        );
        assert!(pages.is_empty());
        fn warped_left(items: &[PageItem]) -> Option<f32> {
          for item in items {
            match item {
              PageItem::Text(text) => {
                if let Some((left, _)) = vml_wordart_alignment_bounds(text) {
                  return Some(left);
                }
              }
              PageItem::Group(children) | PageItem::InlineObjectGroup(children) => {
                if let Some(left) = warped_left(children) {
                  return Some(left);
                }
              }
              _ => {}
            }
          }
          None
        }
        let left = warped_left(&page.items).expect("WordArt paint frame");
        // The native edge includes its printer-realized first glyph bearing;
        // this layout-frame test permits one legacy 0.75pt line-grid step.
        assert!(
          (left - native_left).abs() < 0.75,
          "height={height}, shadow={shadow}: frame={left}, native ink={native_left}"
        );
      }
    }
  }

