  #[test]
  fn vml_flat_inline_frame_uses_native_device_path_bounds() {
    // Independent MSO 96-DPI enclosure captures. Replacing each complete
    // string by I changes the date's right edge; a constant shape padding
    // cannot satisfy these paired controls.
    let mut metrics = TextMetrics::new();
    for (value, size, bold, width, height, native_width, native_height, left) in [
      ("N°01", 16.0, true, 99.65, 46.05, 101.25, 47.25, 0.75),
      ("I", 16.0, true, 99.65, 46.05, 101.25, 47.25, 0.75),
      ("13.09.2018", 20.0, false, 331.55, 67.0, 333.75, 68.25, 1.5),
      ("I", 20.0, false, 331.55, 67.0, 332.25, 68.25, 0.75),
    ] {
      let mut shape = curved_vml_wordart_test_shape(value, "");
      shape.width_pt = width;
      shape.height_pt = height;
      shape.text_warp.as_mut().unwrap().preset = a::TextShapeValues::TextPlain;
      let mut text = text_warp_bounds_test_item(size);
      text.text = value.to_string();
      text.style.bold = bold;
      text.style.font_family = Some(Arc::from("Times New Roman"));
      text.style.outline_width_pt = 0.75;
      let mut items = vec![PageItem::Text(Box::new(text))];
      apply_shape_text_warp(
        &mut items,
        &shape,
        ShapeTextBoxRect {
          x: 0.0,
          y: 0.0,
          width,
          height,
        },
        &mut metrics,
      );
      let PageItem::Text(text) = &items[0] else {
        unreachable!()
      };
      let enclosure = common::drawingml_shape_raster::vml_wordart_paint_bounds(
        &into_common_text_run((**text).clone()),
        &mut metrics,
      )
      .unwrap()
      .layout_bounds
      .unwrap();
      assert!(
        (enclosure.size.width.0 - native_width).abs() < 0.001,
        "{value} ({width}pt): native path width {}, expected {native_width}",
        enclosure.size.width.0
      );
      let actual = vml_wordart_inline_metrics(&items, &shape, 0.0, &mut metrics).unwrap();
      assert!(
        (actual.effect_left_pt - left).abs() < 0.001,
        "{value}: left"
      );
      assert!(
        (actual.frame_height_pt - native_height).abs() < 0.001,
        "{value}: height {}",
        actual.frame_height_pt
      );
      assert_eq!(actual.paint_shift_y_pt, 0.75);
    }
  }

