  #[test]
  fn vml_fitted_wordart_paint_is_independent_of_intermediate_font_size() {
    // Office's eight fixed-frame textpath size controls are pixel-identical.
    // Check the final paint enclosure, including outline stroke, for both
    // flat and bent envelopes; the unrelated ordinary-text grid test above
    // retains its printer font realization contract.
    let mut metrics = TextMetrics::new();
    for flat in [false, true] {
      for family in ["Times New Roman", "Courier New"] {
        for source in ["BULLETIN OFFICIEL ", "AV 1234"] {
          let mut shape = curved_vml_wordart_test_shape(source, "");
          if flat {
            shape.text_warp.as_mut().unwrap().preset = a::TextShapeValues::TextPlain;
          }
          let mut expected: Option<[f32; 4]> = None;
          for size in [11.0, 11.04, 12.0, 16.0, 20.0, 24.0, 36.0] {
            let mut text = text_warp_bounds_test_item(size);
            text.text = source.to_string();
            text.style.font_family = Some(Arc::from(family));
            text.style.bold = false;
            text.style.use_windows_font_metrics = true;
            let mut items = vec![PageItem::Text(Box::new(text))];
            apply_shape_text_warp(
              &mut items,
              &shape,
              ShapeTextBoxRect {
                x: 36.0,
                y: 278.35,
                width: shape.width_pt,
                height: shape.height_pt,
              },
              &mut metrics,
            );
            let PageItem::Text(text) = items.remove(0) else {
              unreachable!()
            };
            let bounds = common::drawingml_shape_raster::vml_wordart_paint_bounds(
              &into_common_text_run(*text),
              &mut metrics,
            )
            .expect("fitted VML outline")
            .foreground;
            let actual = [
              bounds.origin.x.0,
              bounds.origin.y.0,
              bounds.size.width.0,
              bounds.size.height.0,
            ];
            if let Some(expected) = expected {
              for (actual, expected) in actual.into_iter().zip(expected) {
                assert!(
                  (actual - expected).abs() < 0.002,
                  "flat={flat}, family={family}, source={source:?}, size={size}: {actual} != {expected}"
                );
              }
            } else {
              expected = Some(actual);
            }
          }
        }
      }
    }
  }

  #[test]
  fn traditional_chinese_hanging_comma_uses_native_quarter_em_budget() {
    fn text_item(x_pt: f32, text: &str) -> PageItem {
      PageItem::Text(Box::new(TextItem {
        x_pt,
        y_pt: 20.0,
        line_height_pt: DEFAULT_LINE_HEIGHT_PT,
        wordprocessing_auto_line_spacing_units: None,
        wordprocessing_line_metrics: None,
        origin_is_baseline: false,
        line_metrics_participant: true,
        paint_clip: None,
        wordprocessing_effect_host: None,
        wordprocessing_terminal_effect_style: None,
        text: text.to_string(),
        style: TextStyle::default(),
        rotation_center_pt: None,
        hyperlink_url: None,
        dynamic_field: None,
        dynamic_field_line_anchor: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        form_widget_id: None,
        paragraph_bidi: false,
        word_spacing_pt: 0.0,
        preserve_text_portion: false,
        decoration_span_start_x_pt: None,
        pdf_text_segmentation: PdfTextSegmentation::Line,
      }))
    }
    let mut metrics = TextMetrics::new();
    // Native MSLS70: the 10.5pt terminal comma has ideal advance32256
    // instead of43008, while all preceding characters retain43008.
    for family in ["SimSun", "ＭＳ 明朝"] {
      for (language, enabled, overflow, expected) in [
        ("zh-TW", true, 1.0, true),
        ("zh-TW", true, 2.5, true),
        ("zh-TW", true, 2.625, true),
        ("zh-TW", true, 2.75, false),
        ("zh-TW", true, 0.0, false),
        ("zh-TW", false, 2.5, false),
        ("zh-CN", true, 2.5, false),
        ("ja-JP", true, 2.5, false),
      ] {
        let mut item = text_item(0.0, "漢，漢漢，");
        let PageItem::Text(text) = &mut item else {
          unreachable!()
        };
        text.style = TextStyle {
          font_family: Some(family.into()),
          east_asia_font_family: Some(family.into()),
          east_asia_language: Some(language.into()),
          font_size_pt: 10.5,
          wordprocessingml_font_slots: true,
          wordprocessingml_punctuation_spacing: true,
          cjk_punctuation_compression_ratio: 1.0,
          ..Default::default()
        };
        let mut items = vec![item];
        finalize_cjk_punctuation_compression(
          &mut items,
          0,
          20.0,
          52.5 - overflow,
          enabled,
          &mut metrics,
        );
        let PageItem::Text(text) = &items[0] else {
          unreachable!()
        };
        assert_eq!(
          text
            .style
            .wordprocessing_justification_expansion_pt
            .is_some(),
          expected,
          "{family}/{language}/{enabled}/{overflow}"
        );
        if expected {
          assert_eq!(text.style.cjk_punctuation_compression_ratio, 0.0);
          assert!((metrics.measure_text(&text.text, &text.style) - 49.875).abs() < 0.001);
          assert_eq!(
            text
              .style
              .wordprocessing_justification_expansion_pt
              .as_deref(),
            Some([0.0, 0.0, 0.0, 0.0, -2.625].as_slice())
          );
        }
      }
    }
  }

  #[test]
  fn trailing_hanging_punctuation_does_not_decompress_the_line() {
    let natural_right = 341.85;
    let line_right = 329.699_98;
    let total_capacity = 15.75;
    let trailing_full_stop_capacity = 5.25;

    let without_hanging_boundary =
      resolved_cjk_punctuation_compression_ratio(natural_right, line_right, total_capacity, 0.0);
    let with_hanging_boundary = resolved_cjk_punctuation_compression_ratio(
      natural_right,
      line_right,
      total_capacity,
      trailing_full_stop_capacity,
    );

    assert!((without_hanging_boundary - 0.771_43).abs() < 0.0001);
    assert_eq!(with_hanging_boundary, 1.0);
  }

