  #[test]
  fn wordprocessing_overflow_punctuation_fit_honors_compatibility_story_and_script_language() {
    let mut style = TextStyle {
      language: Some(Arc::from("es-ES_tradnl")),
      ..TextStyle::default()
    };
    let legacy_body = WordprocessingOverflowPunctuationPolicy {
      enabled: true,
      allow_legacy_western: allows_legacy_western_overflow_punctuation(13, TextSegmentation::Body),
      inside_field_group: false,
      preceding_language: WordprocessingTextLanguage::Unknown,
    };
    let word_2010_body = WordprocessingOverflowPunctuationPolicy {
      allow_legacy_western: allows_legacy_western_overflow_punctuation(14, TextSegmentation::Body),
      ..legacy_body
    };
    let word_2013_body = WordprocessingOverflowPunctuationPolicy {
      allow_legacy_western: allows_legacy_western_overflow_punctuation(15, TextSegmentation::Body),
      ..legacy_body
    };
    assert_eq!(
      wordprocessing_line_fit_text("", "author, ", &style, legacy_body),
      "author"
    );
    assert_eq!(
      wordprocessing_line_fit_text("", "Machbarkeit- ", &style, legacy_body),
      "Machbarkeit-"
    );
    for text in ["1153–", "S144–", "order—"] {
      for policy in [legacy_body, word_2010_body, word_2013_body] {
        assert_eq!(wordprocessing_line_fit_text("", text, &style, policy), text);
      }
    }
    assert_eq!(
      wordprocessing_line_fit_text("", "…………………………", &style, legacy_body),
      "…………………………"
    );
    assert_eq!(
      wordprocessing_line_fit_text("", "________________", &style, legacy_body),
      "________________"
    );
    assert_eq!(
      wordprocessing_line_fit_text("", "author, ", &style, word_2010_body),
      "author"
    );
    // Independent native boundary controls put the complete token on the
    // next line for all of these characters, even with overflowPunct=1.
    // Treating every Unicode punctuation category as hanging loses their fit
    // width (the cross-run A* boundary in 45690 is one instance).
    for character in "*#&@_/\\'\"([{†‡•§¶–—…‘“´`«»‹›·".chars() {
      let text = format!("A{character} ");
      for policy in [legacy_body, word_2010_body, word_2013_body] {
        assert_eq!(
          wordprocessing_line_fit_text("", &text, &style, policy),
          text.trim_end(),
          "width-bearing {character:?}"
        );
      }
    }
    for character in ",.;:!?)]}>%‰’”¢°".chars() {
      let text = format!("A{character} ");
      for policy in [legacy_body, word_2010_body] {
        assert_eq!(wordprocessing_line_fit_text("", &text, &style, policy), "A");
      }
      assert_eq!(
        wordprocessing_line_fit_text("", &text, &style, word_2013_body),
        text.trim_end()
      );
    }
    style.right_to_left = Some(true);
    assert_eq!(
      wordprocessing_line_fit_text("", "author, ", &style, word_2010_body),
      "author,"
    );
    style.right_to_left = None;
    assert_eq!(
      wordprocessing_line_fit_text("", "اا اااااا، ", &style, word_2010_body),
      "اا اااااا،"
    );
    assert_eq!(
      wordprocessing_line_fit_text("اا", "، ", &style, word_2010_body),
      "،"
    );
    assert_eq!(
      wordprocessing_line_fit_text("", "author, ", &style, word_2013_body),
      "author,"
    );
    assert_eq!(
      wordprocessing_line_fit_text(
        "",
        "author, ",
        &style,
        WordprocessingOverflowPunctuationPolicy {
          allow_legacy_western: allows_legacy_western_overflow_punctuation(
            13,
            TextSegmentation::TableCell,
          ),
          ..legacy_body
        },
      ),
      "author,"
    );
    assert_eq!(
      wordprocessing_line_fit_text(
        "",
        "author, ",
        &style,
        WordprocessingOverflowPunctuationPolicy {
          enabled: false,
          ..legacy_body
        },
      ),
      "author,"
    );

    // ECMA-376 §17.3.2.20 assigns the Latin and East Asian language slots by
    // actual character script. A Latin URL therefore does not inherit zh-CN
    // merely because @eastAsia is present, while Chinese text does.
    style.language = Some(Arc::from("en-US"));
    style.east_asia_language = Some(Arc::from("zh-CN"));
    assert_eq!(
      wordprocessing_line_fit_text("", "text.", &style, word_2013_body),
      "text."
    );
    assert_eq!(
      wordprocessing_line_fit_text("", "文字%", &style, word_2013_body),
      "文字"
    );

    // [MS-OE376] records '%' for Simplified Chinese but not Traditional
    // Chinese, so this pair guards the locale-specific Word lists rather than
    // merely accepting every symbol at the margin.
    style.east_asia_language = Some(Arc::from("zh-TW"));
    assert_eq!(
      wordprocessing_line_fit_text("", "文字%", &style, word_2013_body),
      "文字%"
    );

    // SwTextGuess excludes field portions from hanging punctuation. This is
    // independent of the paragraph default and the CJK locale character set.
    style.east_asia_language = Some(Arc::from("zh-CN"));
    assert_eq!(
      wordprocessing_line_fit_text("", "文字。", &style, word_2013_body),
      "文字"
    );
    assert_eq!(
      wordprocessing_line_fit_text(
        "",
        "文字。",
        &style,
        WordprocessingOverflowPunctuationPolicy {
          inside_field_group: true,
          ..word_2013_body
        },
      ),
      "文字。"
    );

    // A punctuation-only run inherits the last real character's language
    // resolved by the paragraph walker, including across a run boundary.
    assert_eq!(
      wordprocessing_line_fit_text(
        "",
        "%",
        &style,
        WordprocessingOverflowPunctuationPolicy {
          preceding_language: WordprocessingTextLanguage::SimplifiedChinese,
          ..word_2013_body
        },
      ),
      ""
    );
  }

