  #[test]
  fn mixed_vertical_columns_follow_uax50_and_the_declared_column_direction() {
    let mut text_metrics = TextMetrics::new();
    let mut mixed = legacy_effect_test_text(TextStyle::default());
    mixed.x_pt = 10.0;
    mixed.y_pt = 20.0;
    mixed.line_height_pt = 14.0;
    mixed.text = "AB水（".to_string();
    let lowered = materialize_shape_text_item_column(
      mixed,
      ShapeTextBoxColumnMode::MixedLeftToRight,
      10.0,
      20.0,
      110.0,
      &mut text_metrics,
    );
    assert_eq!(lowered.len(), 3);
    let text = lowered
      .iter()
      .map(|item| match item {
        PageItem::Text(text) => text.as_ref(),
        _ => panic!("vertical grapheme should stay text"),
      })
      .collect::<Vec<_>>();
    assert_eq!(text[0].text, "AB");
    assert_eq!(text[0].style.rotation_deg, 90.0);
    assert_eq!(text[1].text, "水");
    assert_eq!(text[1].style.rotation_deg, 0.0);
    assert_eq!(text[2].text, "（");
    assert_eq!(text[2].style.rotation_deg, 0.0);
    assert!(text[0].y_pt < text[1].y_pt);
    assert!(text[1].y_pt < text[2].y_pt);

    let mut column_x = |mode: ShapeTextBoxColumnMode, y_pt| {
      let mut item = legacy_effect_test_text(TextStyle::default());
      item.x_pt = if mode.starts_at_right() { 110.0 } else { 10.0 };
      item.y_pt = y_pt;
      item.text = "A".to_string();
      let lowered =
        materialize_shape_text_item_column(item, mode, 10.0, 20.0, 110.0, &mut text_metrics);
      match &lowered[0] {
        PageItem::Text(text) => text.x_pt,
        _ => unreachable!(),
      }
    };
    assert!(
      column_x(ShapeTextBoxColumnMode::MixedLeftToRight, 34.0)
        > column_x(ShapeTextBoxColumnMode::MixedLeftToRight, 20.0)
    );
    assert!(
      column_x(ShapeTextBoxColumnMode::MixedRightToLeft, 34.0)
        < column_x(ShapeTextBoxColumnMode::MixedRightToLeft, 20.0)
    );
  }

  #[test]
  fn vml_text_frame_clips_paragraph_shading_without_clipping_inline_pictures() {
    use ooxmlsdk::sdk::SdkType;
    let shape = v::Shape::from_bytes(
      br##"<v:shape
        xmlns:v="urn:schemas-microsoft-com:vml"
        xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"
        xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"
        style="width:150pt;height:100pt" stroked="f">
      <v:textbox inset="7.2pt,3.6pt,7.2pt,12pt"><w:txbxContent>
        <w:p><w:pPr><w:shd w:val="clear" w:fill="BFBFBF"/></w:pPr>
          <w:r><w:pict><v:shape style="width:140pt;height:130pt">
            <v:imagedata r:id="rId1"/>
          </v:shape></w:pict></w:r>
        </w:p>
      </w:txbxContent></v:textbox>
    </v:shape>"##,
    )
    .unwrap();
    let mut catalog = crate::docx::ImageCatalog::default();
    catalog.by_relationship_id.insert(
      "rId1".into(),
      crate::docx::package::ImageResource {
        data: Bytes::from_static(&[1, 2, 3]),
        content_type: Some("image/png".into()),
      },
    );
    let textbox = shape
      .shape_choice
      .iter()
      .find_map(|choice| match choice {
        v::ShapeChoice::TextBox(textbox) => Some(textbox.as_ref()),
        _ => None,
      })
      .unwrap();
    let shape = crate::docx::vml_textbox_frame(
      shape.style.as_deref(),
      true,
      textbox,
      &crate::docx::StylesCatalog::default(),
      &catalog,
      &crate::docx::HyperlinkCatalog::default(),
    )
    .unwrap();
    let setup = PageSetup::default();
    let flow = flow_context(setup, 0, SectionColumns::default(), 0, 0, 36.0);
    let mut page = empty_page(setup, 0);
    let mut metrics = TextMetrics::new();
    layout_shape_text_box(
      &mut page,
      flow,
      &mut metrics,
      &shape,
      ShapeTextBoxRect {
        x: 20.0,
        y: 30.0,
        width: 150.0,
        height: 100.0,
      },
    );
    let fill = page
      .items
      .iter()
      .find_map(|item| match item {
        PageItem::Fill(fill) => Some(fill),
        _ => None,
      })
      .expect("paragraph shading");
    assert!((fill.y_pt - 33.6).abs() < 0.001);
    assert!((fill.y_pt + fill.height_pt - 118.0).abs() < 0.001);
    fn image(items: &[PageItem]) -> Option<&ImageItem> {
      items.iter().find_map(|item| match item {
        PageItem::Image(item) => Some(item),
        PageItem::Group(items) | PageItem::InlineObjectGroup(items) => image(items),
        _ => None,
      })
    }
    let picture = image(&page.items).expect("overflowing inline picture");
    assert_eq!(picture.height_pt, 130.0);
    assert!(picture.y_pt + picture.height_pt > 160.0);
    assert!(picture.clip_path.is_empty());
  }

