  #[test]
  fn western_punctuation_keeps_an_adjacent_bracket_suffix_in_its_word() {
    for mode in [12, 14, 15] {
      for token in [
        "population.(4)",
        "foo.(4)",
        "foo,(4)",
        "foo:(4)",
        "foo;(4)",
        "foo!(4)",
        "foo?(4)",
        "foo.[4]",
        "foo.{4}",
        "123.(4)",
        "foo(4)",
        "response).(6)",
        "foo].(4)",
        "foo...(4)",
        "foo!?(4)",
      ] {
        // Include surrounding words: an isolated ASCII token takes the
        // existing fast path and would not exercise Unicode break tailoring.
        assert_eq!(
          text_segments_for_compatibility(&format!("alpha {token} omega"), mode, false),
          [
            "alpha ".to_string(),
            format!("{token} "),
            "omega".to_string()
          ],
        );
      }
      assert_eq!(
        text_segments_for_compatibility("foo. (4)", mode, false),
        ["foo. ", "(4)"],
      );
    }
  }

  #[test]
  fn curly_opening_quotes_keep_the_following_word_across_spaces() {
    for mode in [12, 14, 15] {
      for token in ["Q“ TAIL", "Q‘ TAIL", "„Q“ TAIL"] {
        assert_eq!(
          text_segments_for_compatibility(&format!("alpha {token} omega"), mode, false),
          [
            "alpha ".to_string(),
            format!("{token} "),
            "omega".to_string()
          ],
        );
      }
      for token in ["Q”", "Q’", "Q\"", "Q'", "Q«", "Q‹", "Q„", "Q‟", "Q»", "“Q”"] {
        assert_eq!(
          text_segments_for_compatibility(&format!("alpha {token} omega"), mode, false),
          [
            "alpha ".to_string(),
            format!("{token} "),
            "omega".to_string()
          ],
        );
      }
    }
  }

  #[test]
  fn reversed_quoted_numbers_keep_their_opening_quote_with_the_marker() {
    // Native Word's narrow Arabic controls keep both edges of the marker
    // on one line. In particular, ’2‘ NBSP إزالة moves intact after
    // وحمايتها؛ rather than leaving the first quote on the preceding line.
    for mode in [12, 14, 15] {
      for number in ["1", "2", "20"] {
        assert_eq!(
          text_segments_for_compatibility(
            &format!("وحمايتها؛ ’{number}‘\u{a0}إزالة عبء"),
            mode,
            false,
          ),
          [
            "وحمايتها؛ ".to_string(),
            format!("’{number}‘\u{a0}إزالة "),
            "عبء".to_string(),
          ],
        );
      }
      assert_eq!(
        text_segments_for_compatibility("alpha Q’ omega", mode, false),
        ["alpha ", "Q’ ", "omega"],
      );
    }
  }

  #[test]
  fn kashida_quotes_keep_space_breaks_after_words() {
    // Native Word's low/medium/highKashida controls put the following word
    // on a new line, while the same text with both/right alignment retains
    // the quote-connected token and can require an emergency character break.
    for compatibility_mode in [12, 14, 15] {
      let options = WordprocessingLineBreakOptions {
        compatibility_mode,
        compress_punctuation: false,
        strict_japanese: false,
        kashida: true,
      };
      for word in ["الأسرة", "house"] {
        for quote in ['“', '‘'] {
          assert_eq!(
            text_segments_for_break_options(&format!("{word}{quote} next"), options),
            [format!("{word}{quote} "), "next".to_string()],
          );
        }
      }
      assert_eq!(
        text_segments_for_break_options("الأسرة “وتشاطر", options),
        ["الأسرة ", "“وتشاطر"],
      );
      assert_eq!(
        text_segments_for_break_options("وحمايتها؛ ’2‘\u{a0}إزالة عبء", options),
        ["وحمايتها؛ ", "’2‘\u{a0}إزالة ", "عبء"],
      );

      let run = |text: &str| {
        InlineItem::Text(TextRun {
          text: text.to_string(),
          style: TextStyle::default(),
          hyperlink_url: None,
          dynamic_field: None,
          style_ref_keys: Vec::new(),
          style_ref_text: None,
          style_ref_numbering_text: None,
          preserve_text_portion: false,
        })
      };
      let mut metrics = TextMetrics::default();
      let following = vec![run("house“"), run(" next")];
      assert!(
        cross_run_unbreakable_continuation_width_for_break_options(
          &following,
          0,
          "house“",
          options,
          None,
          &mut metrics,
        )
        .is_none(),
      );
      let split_quote = vec![run("house"), run("“ next")];
      let continuation = cross_run_unbreakable_continuation_width_for_break_options(
        &split_quote,
        0,
        "house",
        options,
        None,
        &mut metrics,
      )
      .expect("the adjoining quote stays on its preceding word");
      assert_eq!(
        continuation.source_end,
        InlineCursor {
          inline_index: 1,
          text_offset: "“ ".len(),
        },
      );
    }
  }

  #[test]
  fn kashida_opening_quotes_own_their_following_words() {
    // Native low/medium/highKashida controls allow these initial quotes
    // after a space, even without a matching final quote. Right alignment
    // retains the Western no-line-start rule. A standalone final quote
    // still belongs to the preceding portion in either policy.
    for compatibility_mode in [12, 14, 15] {
      let options = WordprocessingLineBreakOptions {
        compatibility_mode,
        compress_punctuation: false,
        strict_japanese: false,
        kashida: true,
      };
      for quote in ['”', '’'] {
        for word in [
          "منظمة",
          "house",
          "ΔΕΖ",
          "гдеж",
          "בית",
          "12345",
          "母",
          "가정",
        ] {
          let text = format!("lead {quote}{word} tail");
          assert_eq!(
            text_segments_for_break_options(&text, options),
            [
              "lead ".to_string(),
              format!("{quote}{word} "),
              "tail".to_string()
            ],
            "{text}",
          );
        }
        assert_eq!(
          text_segments_for_break_options(&format!("lead {quote} tail"), options),
          [format!("lead {quote} "), "tail".to_string()],
        );
        assert_eq!(
          text_segments_for_compatibility(
            &format!("lead {quote}house tail"),
            compatibility_mode,
            false
          ),
          [
            format!("lead {quote}"),
            "house ".to_string(),
            "tail".to_string()
          ],
        );
      }
      assert_eq!(
        text_segments_for_break_options("باسم ”منظمة جاتييو“ التالي", options),
        ["باسم ", "”منظمة ", "جاتييو“ ", "التالي"],
      );

      let run = |text: &str| {
        InlineItem::Text(TextRun {
          text: text.to_string(),
          style: TextStyle::default(),
          hyperlink_url: None,
          dynamic_field: None,
          style_ref_keys: Vec::new(),
          style_ref_text: None,
          style_ref_numbering_text: None,
          preserve_text_portion: false,
        })
      };
      let mut metrics = TextMetrics::default();
      let following = vec![run("باسم "), run("”"), run("منظمة جاتييو“")];
      assert!(
        cross_run_unbreakable_continuation_width_for_break_options(
          &following,
          0,
          "باسم ",
          options,
          None,
          &mut metrics,
        )
        .is_none(),
      );
      let continuation = cross_run_unbreakable_continuation_width_for_break_options(
        &following,
        1,
        "”",
        options,
        None,
        &mut metrics,
      )
      .expect("an opening quote keeps its word across formatting runs");
      assert_eq!(
        continuation.source_end,
        InlineCursor {
          inline_index: 2,
          text_offset: "منظمة ".len(),
        },
      );
    }
  }

  #[test]
  fn western_dot_leaders_keep_connected_words_but_allow_following_spaces() {
    for mode in [12, 14, 15] {
      for dots in ['․', '‥', '…', '⋯'] {
        for (left, right) in [
          ("Panikattacken", "die"),
          ("123456789012", "3456"),
          ("ΑΒΓΔΕΖΗΘ", "ΙΚΛΜ"),
          ("АБВГДЕЖЗИ", "КЛМ"),
        ] {
          for before in ["", " "] {
            let token = format!("{left}{before}{dots}{right}");
            assert_eq!(
              text_segments_for_compatibility(&format!("alpha {token} omega"), mode, false),
              [
                "alpha ".to_string(),
                format!("{token} "),
                "omega".to_string()
              ],
            );
          }
          assert_eq!(
            text_segments_for_compatibility(
              &format!("alpha {left}{dots} {right} omega"),
              mode,
              false,
            ),
            [
              "alpha ".to_string(),
              format!("{left}{dots} "),
              format!("{right} "),
              "omega".to_string(),
            ],
          );
        }
      }
      assert_eq!(
        text_segments_for_compatibility("alpha Panikattacken…漢字 omega", mode, false),
        ["alpha ", "Panikattacken…", "漢", "字 ", "omega"],
      );
      assert_eq!(
        text_segments_for_compatibility("alpha Panikattacken—die omega", mode, false),
        ["alpha ", "Panikattacken—", "die ", "omega"],
      );
    }
  }

  #[test]
  fn quoted_dot_leaders_retain_opening_and_closing_punctuation_ownership() {
    for mode in [12, 14, 15] {
      for opening in ['“', '‘', '(', '[', '{', '«', '»', '\'', '"'] {
        let token = format!("{opening}…Beta");
        assert_eq!(
          text_segments_for_compatibility(&format!("alpha {token} tail"), mode, false),
          [
            "alpha ".to_string(),
            format!("{token} "),
            "tail".to_string()
          ],
          "opening {opening}"
        );
      }
      for closing in ['”', ')', ']', '}', ',', '.'] {
        let token = format!("alpha {closing}…Beta");
        assert_eq!(
          text_segments_for_compatibility(&format!("{token} tail"), mode, false),
          [format!("{token} "), "tail".to_string()],
          "closing {closing}"
        );
      }
      assert_eq!(
        text_segments_for_compatibility("alpha . …Beta tail", mode, false),
        ["alpha . …Beta ", "tail"]
      );
      assert_eq!(
        text_segments_for_compatibility("alpha ”… Beta tail", mode, false),
        ["alpha ”… ", "Beta ", "tail"]
      );
      assert_eq!(
        text_segments_for_compatibility("alpha “… Beta tail", mode, false),
        ["alpha ", "“… ", "Beta ", "tail"]
      );
    }
  }

  #[test]
  fn greater_than_retains_its_preceding_word_across_spaces_and_runs() {
    let style = TextStyle {
      font_size_pt: 10.0,
      ..Default::default()
    };
    let mut metrics = TextMetrics::new();
    for mode in [12, 14, 15] {
      for token in ["Alpha >", "Alpha >>", "Alpha >Beta", "Alpha>"] {
        assert_eq!(
          text_segments_for_compatibility(&format!("prefix {token} tail"), mode, false),
          [
            "prefix ".to_string(),
            format!("{token} "),
            "tail".to_string()
          ],
        );
      }
      for symbol in ["<", "=", "+", "≥", "→"] {
        assert_eq!(
          text_segments_for_compatibility(&format!("Alpha {symbol} Beta"), mode, false),
          [
            "Alpha ".to_string(),
            format!("{symbol} "),
            "Beta".to_string()
          ],
        );
      }
      let inlines = ["Alpha ", ">", " Beta"].map(|text| {
        InlineItem::Text(TextRun {
          text: text.into(),
          style: style.clone(),
          hyperlink_url: None,
          dynamic_field: None,
          style_ref_keys: Vec::new(),
          style_ref_text: None,
          style_ref_numbering_text: None,
          preserve_text_portion: false,
        })
      });
      let continuation = cross_run_unbreakable_continuation_width_for_break_options(
        &inlines,
        0,
        "Alpha ",
        WordprocessingLineBreakOptions {
          compatibility_mode: mode,
          compress_punctuation: false,
          strict_japanese: false,
          kashida: false,
        },
        None,
        &mut metrics,
      )
      .expect("the following greater-than portion cannot begin a line");
      assert_eq!(
        continuation.source_end,
        InlineCursor {
          inline_index: 2,
          text_offset: 1
        }
      );
      assert!(continuation.western_forbidden_line_start_only);
    }
  }

  #[test]
  fn middle_dot_connects_words_across_ordinary_spaces() {
    for mode in [12, 14, 15] {
      for token in [
        "Scholar · View",
        "Scholar· View",
        "Scholar ·View",
        "Scholar·View",
      ] {
        assert_eq!(
          text_segments_for_compatibility(&format!("alpha {token} omega"), mode, false),
          [
            "alpha ".to_string(),
            format!("{token} "),
            "omega".to_string()
          ],
        );
      }
      assert_eq!(
        text_segments_for_compatibility("alpha Scholar • View omega", mode, false),
        ["alpha ", "Scholar ", "• ", "View ", "omega"],
      );
    }
  }

