  #[test]
  fn korean_hangul_words_keep_their_syllables_together() {
    assert_eq!(
      text_segments_for_compatibility("AAAA 여기에 표시할 텍스트", 15, false),
      vec!["AAAA ", "여기에 ", "표시할 ", "텍스트"]
    );
    assert_eq!(
      text_segments_for_compatibility("母女", 15, false),
      vec!["母", "女"]
    );
    let mut metrics = TextMetrics::new();
    let style = TextStyle {
      font_family: Some(Arc::from("Calibri")),
      east_asia_font_family: Some(Arc::from("Batang")),
      font_size_pt: 11.0,
      wordprocessingml_font_slots: true,
      wordprocessingml_cjk_line_metrics: true,
      bold: true,
      ..TextStyle::default()
    };
    let hangul = metrics.line_vertical_metrics_for_text("여기에", &style);
    let mixed = metrics.line_vertical_metrics_for_text("오류! 여기에 Heading 1", &style);
    assert!((hangul.line_height_pt() - 14.3).abs() < 0.1);
    assert!((mixed.line_height_pt() - hangul.line_height_pt()).abs() < 0.1);
  }

  #[test]
  fn emergency_breaks_span_formatting_runs_without_restarting_the_word() {
    let word = "abcdefghijklmnopqrstuvwxyz".repeat(4);
    let style = TextStyle {
      font_family: Some(Arc::from("Liberation Serif")),
      font_size_pt: 13.0,
      ..TextStyle::default()
    };
    let mut expected = None;
    for chunk in [word.len(), 1, 7, 37] {
      let parts = std::iter::once("prefix ")
        .chain(
          word
            .as_bytes()
            .chunks(chunk)
            .map(|bytes| std::str::from_utf8(bytes).unwrap()),
        )
        .chain(std::iter::once(" suffix."));
      let paragraph = Paragraph {
        inlines: parts
          .map(|text| {
            InlineItem::Text(TextRun {
              text: text.into(),
              style: style.clone(),
              hyperlink_url: None,
              dynamic_field: None,
              style_ref_keys: Vec::new(),
              style_ref_text: None,
              style_ref_numbering_text: None,
              preserve_text_portion: false,
            })
          })
          .collect(),
        field_events: Vec::new(),
        footnote_reference_ids: Vec::new(),
        endnote_reference_ids: Vec::new(),
        starts_after_last_rendered_page_break: false,
        base_style: style.clone(),
        runs: Vec::new(),
        format: Box::new(ParagraphFormat::default()),
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        list_label: None,
        list_label_image: None,
        list_label_style: style.clone(),
        list_label_hyperlink_url: None,
        list_label_tab_stop_pt: None,
      };
      let mut flow = flow_context(
        PageSetup::default(),
        0,
        SectionColumns::default(),
        0,
        0,
        DEFAULT_TAB_STOP_PT,
      );
      flow.content_width = 99.7;
      let mut current = empty_page(flow.setup, 0);
      let mut pages = Vec::new();
      let mut metrics = TextMetrics::new();
      layout_paragraph(
        &paragraph,
        flow,
        ParagraphLayoutTarget {
          current: &mut current,
          pages: &mut pages,
          anchor_pages: None,
          text_metrics: &mut metrics,
        },
        flow.content_top_pt,
        flow.content_top_pt,
        0.0,
      );
      assert!(pages.is_empty());
      let mut lines: Vec<(f32, String)> = Vec::new();
      for item in &current.items {
        if let PageItem::Text(text) = item {
          if lines
            .last()
            .is_none_or(|line| (line.0 - text.y_pt).abs() > 0.01)
          {
            lines.push((text.y_pt, String::new()));
          }
          lines.last_mut().unwrap().1.push_str(&text.text);
        }
      }
      let lines = lines
        .into_iter()
        .map(|(_, text)| text.trim_end().to_owned())
        .collect::<Vec<_>>();
      assert_eq!(lines[0], "prefix");
      if let Some(expected) = &expected {
        assert_eq!(&lines, expected, "run length {chunk}");
      } else {
        expected = Some(lines);
      }
    }
  }

