  #[test]
  fn auto_script_spacing_uses_word_east_asian_boundary_rules() {
    let style = TextStyle {
      font_size_pt: 10.5,
      ..TextStyle::default()
    };
    let line = AutoScriptLine {
      page_index: 0,
      item_start_index: 0,
      y_pt: 72.0,
    };
    let mut state = AutoScriptSpacingState::default();
    let default_format = ParagraphFormat::default();

    state.observe_text(line, "标题", &style, false);
    assert!(
      (state.leading_space_pt(line, "fs", &style, &default_format, false) - 2.625).abs()
        < f32::EPSILON
    );

    state.reset();
    state.observe_text(line, "标题", &style, false);
    assert_eq!(
      state.leading_space_pt(
        line,
        "fs",
        &style,
        &ParagraphFormat {
          auto_space_de: Some(false),
          ..ParagraphFormat::default()
        },
        false,
      ),
      0.0
    );

    state.reset();
    state.observe_text(line, "标题", &style, false);
    assert!(
      (state.leading_space_pt(line, "12", &style, &default_format, false) - 2.625).abs()
        < f32::EPSILON
    );
    assert_eq!(
      state.leading_space_pt(
        line,
        "12",
        &style,
        &ParagraphFormat {
          auto_space_dn: Some(false),
          ..ParagraphFormat::default()
        },
        false,
      ),
      0.0
    );

    state.reset();
    state.observe_text(line, "标题", &style, false);
    assert_eq!(
      state.leading_space_pt(line, ".", &style, &default_format, false),
      0.0
    );
    assert_eq!(
      state.leading_space_pt(line, "fs", &style, &default_format, true),
      0.0
    );
    assert_eq!(
      state.leading_space_pt(
        AutoScriptLine {
          item_start_index: 1,
          ..line
        },
        "fs",
        &style,
        &default_format,
        false,
      ),
      0.0
    );

    state.reset();
    state.observe_text(line, "한", &style, false);
    assert_eq!(
      state.leading_space_pt(line, "fs", &style, &default_format, false),
      0.0
    );
  }

