  #[test]
  fn word_static_3d_final_crop_excludes_an_aligned_terminal_sample() {
    let pixels_per_point = 200.0 / units::POINTS_PER_INCH;
    let cropped_extent = |extent_px: f32| {
      let extent_pt = extent_px / pixels_per_point;
      wordprocessing_fixed_output_static_3d_bitmap_target(
        common::drawingml_image_effects::EffectOutputBounds {
          left_pt: 0.0,
          top_pt: 0.0,
          right_pt: extent_pt,
          bottom_pt: extent_pt,
        },
        common::drawingml_image_effects::EffectOutputBounds {
          left_pt: 0.0,
          top_pt: 0.0,
          right_pt: 32.0,
          bottom_pt: 32.0,
        },
        pixels_per_point,
        96,
        96,
      )
      .expect("positive static-3-D crop")
      .width_px
    };

    // Six one-glyph Office controls cross three exact terminal boundaries.
    // The same last 7/8 sample rule must decide all six instead of inheriting
    // the sign of floating-point round-off at 17 and 21 pixels.
    assert_eq!(cropped_extent(14.0 + 1.0 / 3.0), 14);
    assert_eq!(cropped_extent(15.0 + 2.0 / 3.0), 15);
    assert_eq!(cropped_extent(17.0), 16);
    assert_eq!(cropped_extent(18.0 + 1.0 / 3.0), 18);
    assert_eq!(cropped_extent(19.0 + 2.0 / 3.0), 19);
    assert_eq!(cropped_extent(21.0), 20);
  }

  #[test]
  fn empty_effect_list_keeps_an_independent_scene_3d_shape_visible() {
    let effects = common::DrawingEffectSource::List {
      source: Box::default(),
      resolved: Some(common::drawingml_image_effects::ImageEffectContainer {
        kind: common::drawingml_image_effects::ImageEffectContainerKind::Sibling,
        effects: Vec::new(),
      }),
    };
    let static3d = common::drawingml_3d::Static3dStyle {
      scene: Box::new(a::Scene3DType {
        camera: Box::new(a::Camera {
          preset: a::PresetCameraValues::OrthographicFront,
          ..a::Camera::default()
        }),
        light_rig: Box::new(a::LightRig {
          rig: a::LightRigValues::ThreePoints,
          direction: a::LightRigDirectionValues::Top,
          ..a::LightRig::default()
        }),
        ..a::Scene3DType::default()
      }),
      shape: Box::new(a::Shape3DType::default()),
      extrusion_color: None,
      contour_color: None,
      wordprocessing_effect_plane_z_pt: None,
    };
    let bounds = common_rect(0.0, 0.0, 34.5, 18.75);
    let mut items = vec![PageItem::Rect(RectItem {
      x_pt: 0.0,
      y_pt: 0.0,
      width_pt: 34.5,
      height_pt: 18.75,
      paragraph_alignment_locked: false,
      fill_color: Some(RgbColor {
        r: 255,
        g: 255,
        b: 255,
      }),
      fill_opacity: 1.0,
      stroke: None,
      stroke_opacity: 1.0,
    })];

    finish_docx_drawing_effects(
      &mut items,
      0,
      DocxDrawingEffectHost {
        effects: Some(&effects),
        static3d: Some(&static3d),
        wordprocessing_shape_host: false,
        wordprocessing_canvas_has_background_paint: false,
        rotation_degrees: 0.0,
        visual_rotation_degrees: 0.0,
        placement: crate::docx::ImagePlacement::Inline,
        fixed_output_base_pixels_per_point: Some(200.0 / units::POINTS_PER_INCH),
      },
      bounds,
    );

    let [PageItem::Image(image)] = items.as_slice() else {
      panic!("empty effectLst plus scene3d must lower the shape to one bitmap");
    };
    let decoded = image::load_from_memory(&image.data)
      .expect("static 3-D bitmap PNG")
      .into_rgba8();
    assert!(decoded.pixels().any(|pixel| pixel[3] != 0));
  }

  #[test]
  fn word_text_effect_target_keeps_exact_origin_and_truncates_pixel_extent() {
    let target = common::drawingml_image_effects::effect_bitmap_target(
      common::drawingml_image_effects::EffectOutputBounds {
        left_pt: -1.3,
        top_pt: 2.2,
        right_pt: 37.2,
        bottom_pt: 19.95,
      },
      common::drawingml_image_effects::EffectOutputBounds {
        left_pt: -7.5,
        top_pt: -4.0,
        right_pt: 45.0,
        bottom_pt: 25.0,
      },
      2.0,
      105,
      58,
    )
    .expect("positive Direct2D output target");

    // Microsoft's archived DirectX Postcard sample preserves the floating
    // GetImageLocalBounds origin, but static_cast<uint32> truncates the DIP
    // width and height after conversion to device pixels. A fractional crop
    // start therefore must not turn into an independently ceiled far edge.
    assert_eq!(
      target,
      common::drawingml_image_effects::EffectBitmapTarget {
        left_px: 12,
        top_px: 12,
        width_px: 77,
        height_px: 35,
      }
    );
  }

