  #[test]
  fn word_static_3d_off_page_support_keeps_visible_shadows_and_unplaced_sources() {
    let style = TextStyle {
      font_size_pt: 12.0,
      wordprocessing_text_3d_parts: Some(common::drawingml_3d::Static3dStyleParts {
        shape: Some(Box::new(a::Shape3DType {
          extrusion_height: Some("12700".parse().unwrap()),
          ..a::Shape3DType::default()
        })),
        scene: Some(Box::new(a::Scene3DType {
          camera: Box::new(a::Camera {
            preset: a::PresetCameraValues::OrthographicFront,
            ..a::Camera::default()
          }),
          ..a::Scene3DType::default()
        })),
        ..common::drawingml_3d::Static3dStyleParts::default()
      }),
      ..TextStyle::default()
    };
    let host = FrameBounds {
      x_pt: 0.0,
      y_pt: 0.0,
      width_pt: 80.0,
      height_pt: 80.0,
    };
    for (x, y, shadow, should_cull) in [
      (10.0, 20.0, false, false),
      (10.0, 160.0, false, true),
      (160.0, 20.0, true, false),
    ] {
      let mut text = legacy_effect_test_text(style.clone());
      text.text = "a".into();
      text.x_pt = x;
      text.y_pt = y;
      if shadow {
        let mut shadow = word_text_shadow(2.0);
        // The glyph is right of the page, but its shadow reaches into it.
        // Horizontal displacement isolates visibility from Word's separate
        // shadow-dependent line/baseline expansion.
        shadow.direction_degrees = 180.0;
        shadow.distance_px = 128.0 / wordprocessing_text_geometry_render_scale(12.0);
        text.style.text_shadow = Some(shadow);
      }
      text.wordprocessing_effect_host = Some(WordprocessingTextEffectHost {
        clip_text_to_frame: false,
        shape_bounds: host,
        text_frame_bounds: host,
        scene_source_frame: None,
        pdf_graphics_initialized: false,
        allocation_source_x_pt: None,
        paint_source_origin_y_pt: None,
      });
      let mut items = [PageItem::Group(vec![PageItem::Text(Box::new(text))])];
      let mut unplaced = items.clone();
      for (items, page) in [
        (&mut items, Some(common_rect(0.0, 0.0, 100.0, 100.0))),
        (&mut unplaced, None),
      ] {
        materialize_wordprocessing_text_effect_source_plane_with_native(
          items,
          &mut TextMetrics::new(),
          96.0,
          WordprocessingStatic3dSourcePlane::LocalEffectColor,
          None,
          page,
        );
      }
      let PageItem::Group(reference) = &unplaced[0] else {
        panic!("outer group");
      };
      let PageItem::Image(reference) = &reference[0] else {
        panic!("unplaced source must render");
      };
      let PageItem::Group(output) = &items[0] else {
        panic!("outer group");
      };
      if should_cull {
        assert!(matches!(&output[0], PageItem::Group(empty) if empty.is_empty()));
      } else {
        let rgba = image::load_from_memory(&reference.data).unwrap().to_rgba8();
        assert!(
          rgba.enumerate_pixels().any(|(x, y, pixel)| {
            let page_x =
              reference.x_pt + (x as f32 + 0.5) * reference.width_pt / rgba.width() as f32;
            let page_y =
              reference.y_pt + (y as f32 + 0.5) * reference.height_pt / rgba.height() as f32;
            pixel[3] != 0 && (0.0..100.0).contains(&page_x) && (0.0..100.0).contains(&page_y)
          }),
          "the unculled control must actually paint inside the page"
        );
        let PageItem::Image(output) = &output[0] else {
          panic!("visible paint must render: y={y}, shadow={shadow}");
        };
        assert_eq!(output.data, reference.data);
        assert_eq!(
          (output.x_pt, output.y_pt, output.width_pt, output.height_pt),
          (
            reference.x_pt,
            reference.y_pt,
            reference.width_pt,
            reference.height_pt
          )
        );
      }
    }
  }

