  #[test]
  fn locked_canvas_text_measure_uses_gdi_overhang_padding() {
    // The fdo76249 66pt Rockwell control has a 103px screen font height.
    // TextRenderer therefore contributes ceil(103/6) + ceil(103/4) = 44px,
    // independently matching the 33pt Office MeasureText/default-format
    // excess over its no-padding GDI extent.
    let padding_pt = locked_canvas_text_measure_padding_pt(77.504_875);
    assert!((padding_pt - 33.0).abs() < 0.0001);

    // GetTextExtentPoint32W measures the unpositioned 418px run while
    // DrawingML paints the same centered run at its 412px kerned extent.
    // The measurement frame therefore gains three 96-DPI pixels on each
    // side, instead of fitting the fixture with a far-edge-only constant.
    let (left_pt, right_pt) =
      locked_canvas_gdi_measurement_horizontal_bounds(100.0, 309.0, 313.5, padding_pt);
    assert!((left_pt - 97.75).abs() < 0.0001);
    assert!((right_pt - 444.25).abs() < 0.0001);
  }

  #[test]
  fn word_text_effect_transport_keeps_straight_alpha_components() {
    let image = image::RgbaImage::from_pixel(1, 1, image::Rgba([146, 208, 80, 92]));

    let encoded = encode_wordprocessing_effect_bitmap_png(&image).unwrap();
    let decoded = image::load_from_memory_with_format(&encoded, image::ImageFormat::Png)
      .unwrap()
      .into_rgba8();

    // The PDF exporter owns the Direct2D premultiply/JPEG/black-Matte chain;
    // layout consumers receive the ordinary straight-alpha source.
    assert_eq!(decoded.get_pixel(0, 0).0, [146, 208, 80, 92]);
  }

  #[test]
  fn word_black_matte_effect_transport_preblends_rgb_but_keeps_alpha() {
    let mut image = image::RgbaImage::from_fn(3, 1, |x, _| match x {
      0 => image::Rgba([255, 144, 4, 128]),
      1 => image::Rgba([17, 33, 65, 0]),
      _ => image::Rgba([17, 33, 65, 255]),
    });

    associate_wordprocessing_effect_rgb_with_black_matte(&mut image);

    assert_eq!(image.get_pixel(0, 0).0, [128, 72, 2, 128]);
    assert_eq!(image.get_pixel(1, 0).0, [0, 0, 0, 0]);
    assert_eq!(image.get_pixel(2, 0).0, [17, 33, 65, 255]);
  }

