  #[test]
  fn hosted_word_text_3d_physical_window_retains_native_projection_boundaries() {
    let scene = a::Scene3DType {
      camera: Box::new(a::Camera {
        preset: a::PresetCameraValues::OrthographicFront,
        ..a::Camera::default()
      }),
      ..a::Scene3DType::default()
    };
    let projection = common::drawingml_3d::camera_projection(&scene, 0.0);
    // Width/height and translation controls have independently captured native
    // projection matrices. The 200pt host's far edge becomes 200.04pt on the
    // source device, before the symmetric 0.24pt window guard is applied.
    for (width, height, expected_width, expected_height) in [
      (200.0, 120.0, 200.52, 113.28),
      (300.0, 180.0, 300.48, 173.28),
    ] {
      for phase in [0.0, 0.06] {
        let host = WordprocessingTextEffectHost {
          clip_text_to_frame: true,
          shape_bounds: FrameBounds {
            x_pt: 72.0 + phase,
            y_pt: 144.0 + phase,
            width_pt: width,
            height_pt: height,
          },
          text_frame_bounds: FrameBounds {
            x_pt: 79.2 + phase,
            y_pt: 147.6 + phase,
            width_pt: width - 14.4,
            height_pt: height - 7.2,
          },
          scene_source_frame: None,
          pdf_graphics_initialized: false,
          allocation_source_x_pt: Some(wordprocessing_shape_source_axis(72.0 + phase, 0.0, width)),
          paint_source_origin_y_pt: Some(144.0 + phase),
        };
        let continuous = common_rect(72.0 + phase, 147.6 + phase, width, height - 7.2);
        let window = wordprocessing_hosted_static_3d_physical_window(projection, host, continuous)
          .expect("host owns source-plane bounds");
        for (actual, expected) in [
          (window.origin.x.0, 71.76 + phase),
          (window.origin.y.0, 147.36 + phase),
          (window.size.width.0, expected_width),
          (window.size.height.0, expected_height),
        ] {
          assert!((actual - expected).abs() < 0.0001, "{actual} != {expected}");
        }
        let overflowing = common_rect(
          continuous.origin.x.0,
          continuous.origin.y.0,
          width + 1.0,
          height,
        );
        assert!(
          wordprocessing_hosted_static_3d_physical_window(projection, host, overflowing).is_none()
        );
        let rotated = common::drawingml_3d::camera_projection(&scene, 15.0);
        assert!(
          wordprocessing_hosted_static_3d_physical_window(rotated, host, continuous).is_none()
        );
      }
    }
  }

