  #[test]
  fn legacy_word_shadow_uses_native_rgb_similarity_and_strict_boundaries() {
    let rgb = |r, g, b| RgbColor { r, g, b };
    let black = rgb(0, 0, 0);
    let white = rgb(255, 255, 255);
    let gray = rgb(128, 128, 128);
    for (background, foreground, expected) in [
      (rgb(55, 55, 55), black, white),
      (rgb(56, 56, 56), black, WORD_LEGACY_SHADOW_GRAY),
      (black, rgb(55, 55, 55), white),
      (black, rgb(56, 56, 56), gray),
      (rgb(0, 0, 199), white, gray),
      (rgb(0, 0, 200), white, black),
      (rgb(255, 0, 0), rgb(0, 0, 199), white),
      (rgb(255, 0, 0), rgb(0, 0, 200), black),
      (rgb(255, 0, 0), gray, gray),
      (rgb(0, 255, 0), black, white),
      (white, white, WORD_LEGACY_SHADOW_GRAY),
    ] {
      let mut style = TextStyle {
        color: foreground,
        legacy_effect_background: Some(background),
        ..TextStyle::default()
      };
      assert_eq!(legacy_wordprocessing_shadow_color(&style), expected);
      // Run highlight owns the effective backdrop over paragraph/cell fill.
      style.highlight = Some(white);
      assert_eq!(
        legacy_wordprocessing_shadow_color(&style),
        WORD_LEGACY_SHADOW_GRAY
      );
    }
  }

  #[test]
  fn expanded_legacy_effects_preserve_paragraph_cell_and_note_ownership() {
    let mut title = legacy_effect_test_text(TextStyle {
      legacy_shadow: true,
      ..TextStyle::default()
    });
    title.text = "AB".into();
    title.hyperlink_url = None;
    let mut cell = legacy_effect_test_text(TextStyle::default());
    cell.text = "cell".into();
    cell.y_pt = 100.0;
    let mut note = title.clone();
    note.text = "CD".into();
    note.y_pt = 200.0;
    let mut page = empty_page(PageSetup::default(), 0);
    page.items = vec![
      PageItem::Text(Box::new(title)),
      PageItem::Text(Box::new(cell)),
      PageItem::Text(Box::new(note)),
    ];
    page.footnote_item_indices = vec![2];
    let mut text_metrics = TextMetrics::new();
    let mut frames = [
      FollowFrameKind::Paragraph,
      FollowFrameKind::Table,
      FollowFrameKind::Notes,
    ]
    .into_iter()
    .enumerate()
    .map(|(index, kind)| {
      let lines = line_boxes_for_items(&page.items, index, index + 1, &mut text_metrics);
      let mut fragments = frame_fragments_for(kind, &lines);
      if kind == FollowFrameKind::Table {
        for fragment in &mut fragments {
          fragment.kind = FrameFragmentKind::TableCell;
          fragment.cell_index = Some(0);
        }
      }
      LayoutFrame {
        kind,
        block_index: Some(index),
        split_start: frame_cursor(Some(index), kind, index, &lines, true),
        split_end: frame_cursor(Some(index), kind, index + 1, &lines, false),
        page_index: 0,
        section_index: 0,
        section_page_index: 0,
        column_index: 0,
        item_count: 1,
        items: page.items[index..index + 1].to_vec(),
        item_start: index,
        item_end: index + 1,
        bounds: frame_bounds_for_items(&page.items[index..index + 1], &mut text_metrics),
        lines,
        flow_bottom_pt: None,
        fragments,
        influences: vec![FrameInfluence {
          kind: FrameInfluenceKind::FootnoteReservation,
          count: 1,
          block_index: Some(index),
          item_start: index,
          item_end: index + 1,
          bounds: None,
        }],
        invalidation: FrameInvalidation::Clean,
      }
    })
    .collect::<Vec<_>>();
    page.frame_fragments = frames
      .iter()
      .flat_map(|frame| frame.fragments.clone())
      .collect();
    page.frame_influences = frames
      .iter()
      .flat_map(|frame| frame.influences.clone())
      .collect();
    let old_cell_bounds = frames[1].bounds;

    materialize_legacy_wordprocessing_text_effects(
      std::slice::from_mut(&mut page),
      &mut frames,
      &mut text_metrics,
    );

    assert_eq!(page.items.len(), 9);
    assert_eq!(page.footnote_item_indices, vec![5, 6, 7, 8]);
    for (frame, expected) in frames.iter().zip([(0, 4), (4, 5), (5, 9)]) {
      assert_eq!((frame.item_start, frame.item_end), expected);
      assert_eq!(frame.item_count, expected.1 - expected.0);
      assert_eq!(frame.items.len(), frame.item_count);
      assert!(!frame.lines.is_empty());
      for line in &frame.lines {
        assert_eq!((line.item_start, line.item_end), expected);
      }
      for record in &frame.fragments {
        assert_eq!((record.item_start, record.item_end), expected);
      }
      assert_eq!(
        (frame.influences[0].item_start, frame.influences[0].item_end),
        expected
      );
    }
    assert_eq!(frames[1].bounds, old_cell_bounds);
    let cell_fragment = page
      .frame_fragments
      .iter()
      .find(|fragment| fragment.kind == FrameFragmentKind::TableCell)
      .expect("cell clip owner");
    assert_eq!((cell_fragment.item_start, cell_fragment.item_end), (4, 5));
    for (index, item) in page.items.iter().enumerate() {
      let PageItem::Text(text) = item else {
        panic!("text layer")
      };
      if index < 4 {
        assert!(
          index < cell_fragment.item_start,
          "title must not receive the cell's clip"
        );
        assert_eq!(text.style.pdf_painted_artifact, index.is_multiple_of(2));
        assert_eq!(
          text.line_metrics_participant,
          !text.style.pdf_painted_artifact
        );
      }
    }
    assert_eq!(
      (
        page.frame_influences[1].item_start,
        page.frame_influences[1].item_end
      ),
      (4, 5)
    );
  }

