  #[test]
  fn quarter_turned_chart_user_shape_recovers_its_local_layout_rectangle() {
    let anchor = ShapeTextBoxRect {
      x: 10.0,
      y: 20.0,
      width: 36.5,
      height: 122.5,
    };

    let local = chart_user_shape_layout_rect(anchor, 270.0);

    assert_eq!((local.x, local.y), (-33.0, 63.0));
    assert_eq!((local.width, local.height), (122.5, 36.5));
    assert_eq!(
      (local.x + local.width * 0.5, local.y + local.height * 0.5),
      (
        anchor.x + anchor.width * 0.5,
        anchor.y + anchor.height * 0.5,
      )
    );

    let unrotated = chart_user_shape_layout_rect(anchor, 0.0);
    assert_eq!(
      (unrotated.x, unrotated.y, unrotated.width, unrotated.height),
      (anchor.x, anchor.y, anchor.width, anchor.height)
    );
  }

