  #[test]
  fn character_indents_use_the_imported_document_default_unit() {
    let paragraph = Paragraph {
      inlines: Vec::new(),
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: TextStyle {
        font_size_pt: 16.0,
        ..Default::default()
      },
      runs: Vec::new(),
      format: Box::new(ParagraphFormat {
        indent_left_character_units: Some(18.44),
        indent_right_character_units: Some(5.0),
        first_line_indent_character_units: Some(-1.5),
        character_indent_unit_pt: Some(10.5),
        ..Default::default()
      }),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: TextStyle::default(),
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    };
    let mut text_metrics = TextMetrics::new();

    let (left, right, first_line) = resolved_paragraph_indents(&paragraph, &mut text_metrics);

    // Character-unit hanging anchors the first line, then adds the hanging
    // amount to continuation lines (native Word modes 12/14/15).
    assert!((left - 209.37).abs() < 0.001);
    assert!((left + first_line - 193.62).abs() < 0.001);
    assert!((right - 52.5).abs() < 0.001);
    assert!((first_line + 15.75).abs() < 0.001);

    // Native differing-font controls: first-line and hanging use the first
    // text size, while left/right retain the document's 10.5pt unit.
    let mut initial_text = paragraph.clone();
    initial_text.format.first_line_character_indent_unit_pt = Some(18.0);
    for (chars, expected_left, expected_first) in [(3.0, 193.62, 54.0), (-3.0, 247.62, -54.0)] {
      initial_text.format.first_line_indent_character_units = Some(chars);
      let (left, right, first) = resolved_paragraph_indents(&initial_text, &mut text_metrics);
      assert!((left - expected_left).abs() < 0.001);
      assert!((right - 52.5).abs() < 0.001);
      assert!((first - expected_first).abs() < 0.001);
    }

    for (left_chars, first_chars, first_twips_pt, expected_left, expected_first) in [
      (None, None, -31.5, 63.0, -31.5),
      (None, Some(0.0), -31.5, 63.0, -31.5),
      (None, Some(-3.0), -31.5, 31.5, -31.5),
      (Some(0.0), Some(-3.0), -31.5, 31.5, -31.5),
      (Some(1.0), None, -31.5, 42.0, -31.5),
      (Some(3.0), Some(-3.0), -31.5, 63.0, -31.5),
      (Some(3.0), Some(-1.5), -45.0, 47.25, -15.75),
      (None, Some(3.0), 31.5, 63.0, 31.5),
      (Some(3.0), Some(3.0), 31.5, 31.5, 31.5),
    ] {
      let mut control = paragraph.clone();
      control.format.indent_left_pt = 63.0;
      control.format.indent_left_character_units = left_chars;
      control.format.first_line_indent_character_units = first_chars;
      control.format.first_line_indent_pt = first_twips_pt;
      let (left, _, first) = resolved_paragraph_indents(&control, &mut text_metrics);
      assert!((left - expected_left).abs() < 0.001);
      assert!((first - expected_first).abs() < 0.001);
    }
  }

