  #[test]
  fn settled_right_tab_cursor_selects_the_following_authored_stop() {
    let mut metrics = TextMetrics::new();
    for origin in [0.0, 72.0, 100.85, 123.1] {
      for width in [5.81, 20.0, 23.205353] {
        for bidi in [false, true] {
          let stops = [51.1, 63.35].map(|position_pt| TabStop {
            position_pt,
            alignment: if position_pt == 51.1 {
              TabStopAlignment::Right
            } else {
              TabStopAlignment::Left
            },
            leader: TabLeader::None,
          });
          let stop = origin + stops[0].position_pt;
          let mut page = empty_page(PageSetup::default(), 0);
          let mut text = text_warp_bounds_test_item(12.0);
          text.text = " ".into();
          text.x_pt = stop;
          text.y_pt = 20.0;
          text.paragraph_bidi = bidi;
          // Fix the portion's logical width independently of installed fonts.
          // The last width and origin reproduce the native-confirmed source
          // heading's GDB cancellation at stop174.200012→cursor174.199997.
          text.word_spacing_pt = width - metrics.measure_text(&text.text, &text.style);
          let style = text.style.clone();
          page.items.push(PageItem::Text(Box::new(text)));
          let mut pending = Some(PendingAlignedTab {
            stop: ResolvedTabStop {
              x_pt: stop,
              alignment: TabStopAlignment::Right,
              leader: TabLeader::None,
              automatic: false,
            },
            leader_start_x_pt: origin,
            leader_layout: TabLeaderLayout::OfficeLegacyPrintGridEnd,
            y_pt: 20.0,
            line_height_pt: 20.0,
            style,
            item_start_index: 0,
            field_result_tab: false,
            paragraph_bidi: bidi,
          });
          let cursor = apply_pending_aligned_tab_to_cursor(
            &mut page,
            &mut pending,
            &mut metrics,
            20.0,
            origin,
            500.0,
            stop + width,
          );
          assert!(pending.is_none());
          assert!(
            cursor >= stop,
            "origin={origin}, width={width}, bidi={bidi}"
          );
          let next = next_tab_stop(cursor, origin, &stops, 36.0);
          assert_eq!(next.x_pt, origin + stops[1].position_pt);
          assert_eq!(next.alignment, TabStopAlignment::Left);
        }
      }
    }
  }

  #[test]
  fn custom_tab_stop_one_twip_ahead_is_not_skipped() {
    // Native consecutive-tab controls select 721twips after 720twips in
    // both paragraph directions. A cursor already on a stop must advance.
    let stops = [36.0, 36.05, 72.0].map(|position_pt| TabStop {
      position_pt,
      alignment: TabStopAlignment::Left,
      leader: TabLeader::None,
    });
    for origin in [0.0, 72.0, 100.85] {
      let next = next_tab_stop(origin + 36.0, origin, &stops, 36.0);
      assert_eq!(next.x_pt, origin + 36.05);
      let following = next_tab_stop(next.x_pt, origin, &stops, 36.0);
      assert_eq!(following.x_pt, origin + 72.0);
    }
    // Actual stress010 label cursor from GDB: the 86.4pt stop is ahead,
    // while the former 0.1pt epsilon incorrectly selected 108pt.
    let stops = [86.4, 108.0].map(|position_pt| TabStop {
      position_pt,
      alignment: TabStopAlignment::Left,
      leader: TabLeader::None,
    });
    assert_eq!(next_tab_stop(86.3606, 0.0, &stops, 36.0).x_pt, 86.4);
  }

  #[test]
  fn aligned_dot_leader_uses_native_page_device_lattice() {
    // Word C# ExtTextOut capture: A ends at device661, number7 starts2049;
    // the52dots begin676, each26pixels, in modes11/12/14/15.
    let style = TextStyle {
      font_family: Some(Arc::from("Arial")),
      font_size_pt: 11.0,
      ..TextStyle::default()
    };
    let mut metrics = TextMetrics::new();
    for mode in [11, 12, 14, 15] {
      let mut page = empty_page(PageSetup::default(), 0);
      push_tab_leader(
        &mut page,
        TabLeaderPlacement {
          insert_index: None,
          leader: TabLeader::Dot,
          layout: aligned_tab_leader_layout(mode),
          reserve_natural_boundary: false,
          start_x: 661.0 * 0.12,
          end_x: 2049.0 * 0.12,
          y: 20.0,
          line_height: DEFAULT_LINE_HEIGHT_PT,
          paragraph_bidi: false,
        },
        &style,
        &mut metrics,
      );
      let PageItem::Text(leader) = &page.items[0] else {
        panic!("expected leader");
      };
      assert_eq!(leader.text.len(), 52);
      assert!((leader.x_pt - 676.0 * 0.12).abs() < 0.001);
      let advances = leader
        .style
        .semantic_character_advances_pt
        .as_deref()
        .unwrap();
      assert_eq!(advances.len(), 52);
      assert!(
        advances
          .iter()
          .all(|advance| (*advance - 26.0 * 0.12).abs() < 0.001)
      );
    }
  }

  #[test]
  fn rtl_dot_leader_uses_complex_size_without_changing_run_font_or_weight() {
    // Native independent controls: western Times New Roman10 / complex
    // Traditional Arabic14, with w:rtl absent or false. LTR dots advance
    // 2.52pt; RTL dots use Times New Roman14 and advance 3.48pt. The Latin
    // text remains10pt, and bCs/iCs do not switch the western leader face.
    let mut text_metrics = TextMetrics::new();
    for right_to_left in [None, Some(false)] {
      let style = TextStyle {
        font_family: Some(Arc::from("Times New Roman")),
        complex_font_family: Some(Arc::from("Traditional Arabic")),
        font_size_pt: 10.0,
        complex_font_size_pt: Some(14.0),
        complex_bold: Some(true),
        complex_italic: Some(true),
        right_to_left,
        wordprocessingml_font_slots: true,
        ..TextStyle::default()
      };
      for (bidi, size, advance) in [(false, 10.0, 2.52), (true, 14.0, 3.48)] {
        let leader = tab_leader_metrics(
          '.',
          &style,
          TabLeaderLayout::NaturalStart,
          bidi,
          &mut text_metrics,
        );
        assert!((leader.logical_repeat_width_pt - advance).abs() < 0.001);
        assert!((leader.paint_repeat_width_pt - advance).abs() < 0.001);
        assert_eq!(leader.paint_style.font_size_pt, size);
        let shaped = text_metrics.shape_text(".", &leader.paint_style).unwrap();
        let face = &shaped.font_faces[shaped.glyphs[0].font_index];
        let font = FontRef::from_index(face.data.as_ref(), face.index).unwrap();
        assert_eq!(
          font
            .localized_strings(StringId::FAMILY_NAME)
            .english_or_first()
            .unwrap()
            .to_string(),
          "Times New Roman"
        );
        assert!(!face.synthetic_bold && !face.synthetic_italic);
      }
      assert_eq!(style.font_size_pt, 10.0);
      let shaped = text_metrics.shape_text("AB", &style).unwrap();
      assert!(shaped.glyphs.iter().all(|glyph| glyph.font_size_pt == 10.0));
    }
  }

  #[test]
  fn dot_leader_spacing_is_added_after_the_native_font_width_transform() {
    let mut metrics = TextMetrics::new();
    // Native GDI source dx / final RTL PDF step, captured independently for
    // the stress010 tracking owner and negative-spacing counterexamples.
    for (spacing, percent, source, paint) in [
      (3.0, 100, 7.2, 7.2),
      (3.0, 103, 7.32, 7.35),
      (3.0, 110, 7.56, 7.5),
      (-0.5, 103, 3.84, 3.9),
      (-3.0, 103, 1.32, 1.35),
      (0.05, 103, 4.32, 4.35),
    ] {
      let style = TextStyle {
        font_family: Some(Arc::from("Traditional Arabic")),
        font_size_pt: 15.0,
        right_to_left: Some(true),
        horizontal_scale: Some(f32::from(percent) / 100.0),
        wordprocessing_font_width_percent: Some(percent),
        character_spacing_pt: spacing,
        ..TextStyle::default()
      };
      let got = metrics.word_dot_leader_advances(&style, true).unwrap();
      assert!(
        (got.0 - source).abs() < 0.001,
        "{spacing} {percent} {got:?}"
      );
      assert!((got.1 - paint).abs() < 0.001, "{spacing} {percent} {got:?}");
    }
  }

