  fn office_synthetic_bold_tab_leader_tracking_matches_fixed_output() {
    assert!((synthetic_bold_tab_leader_tracking_pt(12.0, true) - 0.168).abs() < f32::EPSILON);
    assert_eq!(synthetic_bold_tab_leader_tracking_pt(12.0, false), 0.0);
  }

  #[test]
  fn word_2010_rtl_arial_tab_leader_uses_native_printer_advance() {
    let style = TextStyle {
      font_family: Some(Arc::from("Arial")),
      fallback_font_family: Some(Arc::from("Arial")),
      font_size_pt: 14.0,
      right_to_left: Some(true),
      ..TextStyle::default()
    };
    let mut text_metrics = TextMetrics::new();
    let metrics = tab_leader_metrics(
      '.',
      &style,
      TabLeaderLayout::NaturalStart,
      true,
      &mut text_metrics,
    );
    // The controlled Word 2010 RTL field emits 3.9312pt between 14.04pt
    // PDF dots. Before the direction-aware metric, this path used 3.84pt.
    assert!((metrics.logical_repeat_width_pt - 3.96).abs() < 0.002);
    assert!((metrics.paint_repeat_width_pt - 3.9312).abs() < 0.002);
  }

  #[test]
  fn word_2010_rtl_dot_leader_starts_on_native_page_grid() {
    // Native Word controls: size-dependent Arial leaders, then four 14pt
    // font families after the same page-number field edge.
    for (content_end, dot_advance, office_first_dot) in [
      (66.816, 3.36, 67.224),
      (67.350, 3.64, 68.424),
      (67.950, 3.92, 71.304),
      (68.484, 4.20, 71.424),
      (69.018, 4.48, 71.064),
      (65.124, 3.92, 67.344),
      (65.124, 3.64, 68.424),
      (65.124, 4.20, 67.224),
      (65.124, 3.50, 66.144),
      // Current source field edges in stress004.docx, at 14pt/13pt.
      (50.836, 3.92, 51.504),
      (58.622, 3.92, 59.424),
      (57.510, 3.64, 57.624),
    ] {
      assert!(
        (office_rtl_tab_leader_first_dot_x(content_end, dot_advance) - office_first_dot).abs()
          < 0.002,
        "content_end={content_end} dot_advance={dot_advance} expected={office_first_dot}"
      );
    }
    // GDB title edges from two stress004 TOC rows lie just below a glyph-cell
    // threshold in points; native Word prints 43 and 31 dots respectively.
    assert_eq!(
      office_rtl_tab_leader_grid_repeat_count(51.504, 221.772_05, 3.92),
      43
    );
    assert_eq!(
      office_rtl_tab_leader_grid_repeat_count(59.424, 182.132_22, 3.92),
      31
    );
  }

  #[test]
  fn resolved_field_tab_leader_reuses_the_authored_tab_start() {
    let style = TextStyle {
      font_family: Some(Arc::from("Arial")),
      font_size_pt: 11.0,
      ..TextStyle::default()
    };
    let mut text_metrics = TextMetrics::new();
    let dot_width = text_metrics.measure_text(".", &style);
    // Native Arial 11pt control: the tab spans device x661..2049,
    // while its 52 fill cells start at x676 and advance by 26 pixels.
    // Field resolution must retain this page lattice and the authored start.
    let tab_start_x = 661.0 * 0.12;
    let field_x = 2049.0 * 0.12;
    let mut page = empty_page(PageSetup::default(), 0);
    push_tab_leader(
      &mut page,
      TabLeaderPlacement {
        insert_index: None,
        leader: TabLeader::Dot,
        layout: TabLeaderLayout::Office2013PrintGridEnd,
        reserve_natural_boundary: false,
        start_x: tab_start_x,
        end_x: field_x,
        y: 20.0,
        line_height: DEFAULT_LINE_HEIGHT_PT,
        paragraph_bidi: false,
      },
      &style,
      &mut text_metrics,
    );
    let aligned_tab_anchor = DynamicFieldLineAnchor {
      position_pt: field_x + dot_width,
      alignment: ParagraphAlignment::Right,
      aligned_tab: Some(DynamicFieldAlignedTab {
        start_x_pt: tab_start_x,
        leader: TabLeader::Dot,
        inside_field_result: false,
        leader_layout: TabLeaderLayout::Office2013PrintGridEnd,
        logical_repeat_width_pt: dot_width,
      }),
    };
    page.items.push(PageItem::Text(Box::new(TextItem {
      x_pt: field_x,
      y_pt: 20.0,
      line_height_pt: DEFAULT_LINE_HEIGHT_PT,
      wordprocessing_auto_line_spacing_units: None,
      wordprocessing_line_metrics: None,
      origin_is_baseline: false,
      line_metrics_participant: true,
      paint_clip: None,
      wordprocessing_effect_host: None,
      wordprocessing_terminal_effect_style: None,
      text: "S".to_string(),
      style: style.clone(),
      rotation_center_pt: None,
      hyperlink_url: None,
      dynamic_field: None,
      dynamic_field_line_anchor: Some(aligned_tab_anchor),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      form_widget_id: None,
      paragraph_bidi: false,
      word_spacing_pt: 0.0,
      preserve_text_portion: false,
      decoration_span_start_x_pt: None,
      pdf_text_segmentation: PdfTextSegmentation::Line,
    })));
    page.items.push(PageItem::Text(Box::new(TextItem {
      x_pt: field_x + dot_width,
      y_pt: 20.0,
      line_height_pt: DEFAULT_LINE_HEIGHT_PT,
      wordprocessing_auto_line_spacing_units: None,
      wordprocessing_line_metrics: None,
      origin_is_baseline: false,
      line_metrics_participant: true,
      paint_clip: None,
      wordprocessing_effect_host: None,
      wordprocessing_terminal_effect_style: None,
      text: "1".to_string(),
      style,
      rotation_center_pt: None,
      hyperlink_url: None,
      dynamic_field: Some(DynamicFieldKind::PageRef {
        bookmark_name: Arc::<str>::from("_Toc1"),
        number_format: FieldNumberFormat::Decimal,
        relative_position: false,
      }),
      dynamic_field_line_anchor: Some(aligned_tab_anchor),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      form_widget_id: None,
      paragraph_bidi: false,
      word_spacing_pt: 0.0,
      preserve_text_portion: false,
      decoration_span_start_x_pt: None,
      pdf_text_segmentation: PdfTextSegmentation::Line,
    })));

    resize_dynamic_field_tab_leaders(&mut page.items, &mut text_metrics);

    let PageItem::Text(leader) = &page.items[0] else {
      panic!("expected tab leader");
    };
    assert_eq!(leader.text.chars().count(), 52);
    assert!((leader.x_pt - 676.0 * 0.12).abs() < 0.001);
    let advances = leader
      .style
      .semantic_character_advances_pt
      .as_deref()
      .unwrap();
    assert_eq!(advances.len(), 52);
    assert!(
      advances
        .iter()
        .all(|advance| (*advance - 26.0 * 0.12).abs() < 0.001)
    );
  }

