  #[test]
  fn inline_alignment_translates_an_image_clip_with_the_image() {
    let mut item = PageItem::Image(ImageItem {
      x_pt: 10.0,
      y_pt: 20.0,
      width_pt: 30.0,
      height_pt: 40.0,
      inline_frame_left_gap_pt: 0.0,
      inline_frame_right_gap_pt: 0.0,
      inline_baseline_gap_pt: 0.0,
      inline_baseline_participant: true,
      layout_only: false,
      paragraph_alignment_locked: false,
      crop: ImageCrop::default(),
      clip_path: vec![
        common::PathCommand::MoveTo(common_point(10.0, 20.0)),
        common::PathCommand::LineTo(common_point(40.0, 20.0)),
        common::PathCommand::Close,
      ],
      rotation_deg: 0.0,
      flip_horizontal: false,
      flip_vertical: false,
      data: Bytes::new(),
      content_type: None,
      blip_compression_state: common::BlipCompressionState::Unspecified,
      metafile_background_color: None,
      alt_text: None,
      hyperlink_url: None,
      semantic_metafile_text: false,
      metafile_semantic_text_includes_raster_backdrop: false,
      signature_line: None,
      metafile_native_size: false,
      metafile_fixed_output_profile: common::MetafileFixedOutputProfile::Default,
      floating: false,
      behind_text: false,
      wordprocessing_shape_shadow_far_edge_extension_pt: 0.0,
    });

    shift_item_x(&mut item, 15.0);

    let PageItem::Image(image) = item else {
      panic!("expected image");
    };
    assert_eq!(image.x_pt, 25.0);
    let common::PathCommand::MoveTo(point) = image.clip_path[0] else {
      panic!("expected clip move");
    };
    assert_eq!((point.x.0, point.y.0), (25.0, 20.0));

    let mut bitmap = image.clone();
    bitmap.x_pt = 86.55;
    bitmap.width_pt = 175.5;
    bitmap.clip_path.clear();
    let mut narrow = [PageItem::Image(bitmap.clone())];
    clip_inline_bitmaps_to_cell_width(&mut narrow, 85.05, 185.05);
    let PageItem::Image(clipped) = &narrow[0] else {
      panic!("expected clipped inline image");
    };
    assert_eq!((clipped.x_pt, clipped.width_pt), (86.55, 175.5));
    let bounds = drawing_path_bounds(&clipped.clip_path).unwrap();
    assert!((bounds.origin.x.0 - 86.55).abs() < LAYOUT_EPSILON_PT);
    assert!((bounds.size.width.0 - 98.5).abs() < LAYOUT_EPSILON_PT);
    clip_inline_bitmaps_to_cell_width(&mut narrow, 85.05, 175.05);
    let PageItem::Image(clipped) = &narrow[0] else {
      unreachable!()
    };
    let bounds = drawing_path_bounds(&clipped.clip_path).unwrap();
    assert!((bounds.size.width.0 - 88.5).abs() < LAYOUT_EPSILON_PT);
    let mut wide = [PageItem::Image(bitmap.clone())];
    clip_inline_bitmaps_to_cell_width(&mut wide, 85.05, 285.05);
    let PageItem::Image(wide) = &wide[0] else {
      panic!("expected unclipped inline image");
    };
    assert!(wide.clip_path.is_empty());
    bitmap.inline_baseline_participant = false;
    let mut floating = [PageItem::Image(bitmap)];
    clip_inline_bitmaps_to_cell_width(&mut floating, 85.05, 185.05);
    let PageItem::Image(floating) = &floating[0] else {
      panic!("expected independently positioned image");
    };
    assert!(floating.clip_path.is_empty());
  }

  #[test]
  fn centered_inline_alignment_uses_the_outer_effect_extent_frame() {
    let mut items = vec![PageItem::Image(ImageItem {
      x_pt: 0.25,
      y_pt: 20.0,
      width_pt: 30.0,
      height_pt: 40.0,
      inline_frame_left_gap_pt: 0.25,
      inline_frame_right_gap_pt: 0.75,
      inline_baseline_gap_pt: 0.0,
      inline_baseline_participant: true,
      layout_only: false,
      paragraph_alignment_locked: false,
      crop: ImageCrop::default(),
      clip_path: Vec::new(),
      rotation_deg: 0.0,
      flip_horizontal: false,
      flip_vertical: false,
      data: Bytes::new(),
      content_type: None,
      blip_compression_state: common::BlipCompressionState::Unspecified,
      metafile_background_color: None,
      alt_text: None,
      hyperlink_url: None,
      semantic_metafile_text: false,
      metafile_semantic_text_includes_raster_backdrop: false,
      signature_line: None,
      metafile_native_size: false,
      metafile_fixed_output_profile: common::MetafileFixedOutputProfile::Default,
      floating: false,
      behind_text: false,
      wordprocessing_shape_shadow_far_edge_extension_pt: 0.0,
    })];
    let source = items[0].clone();
    let mut text_metrics = TextMetrics::new();

    align_paragraph_items(
      &mut items,
      ParagraphAlignment::Center,
      &mut text_metrics,
      100.0,
    );

    let PageItem::Image(image) = &items[0] else {
      panic!("expected image");
    };
    assert!((image.x_pt - 34.75).abs() < 0.001);
    assert!(
      ((image.x_pt - image.inline_frame_left_gap_pt)
        + (image.width_pt + image.inline_frame_left_gap_pt + image.inline_frame_right_gap_pt)
          / 2.0
        - 50.0)
        .abs()
        < 0.001
    );
    let mut framed = vec![PageItem::Group(vec![
      source,
      PageItem::path(common::PathItem {
        bounds: common_rect(0.25, 20.0, 30.0, 40.0),
        points: Vec::new(),
        commands: vec![
          common::PathCommand::MoveTo(common_point(0.25, 20.0)),
          common::PathCommand::LineTo(common_point(30.25, 60.0)),
        ],
        closed: false,
        fill: common::Fill::None,
        stroke: None,
      }),
    ])];
    align_paragraph_items(
      &mut framed,
      ParagraphAlignment::Center,
      &mut text_metrics,
      100.0,
    );
    let PageItem::Group(paint) = &framed[0] else {
      panic!("picture paint");
    };
    let image = inline_alignment_image(&framed[0]).expect("inline picture anchor");
    assert!((image.x_pt - 34.75).abs() < 0.001);
    let PageItem::Path(frame) = &paint[1] else {
      panic!("frame paint");
    };
    assert!((frame.bounds.origin.x.0 - image.x_pt).abs() < 0.001);
    let common::PathCommand::MoveTo(point) = frame.commands[0] else {
      panic!("frame start");
    };
    assert!((point.x.0 - image.x_pt).abs() < 0.001);

    let mut tall = image.clone();
    tall.height_pt = 80.0;
    framed.push(PageItem::Image(tall));
    align_line_items_to_inline_object_baseline(
      &mut framed,
      0,
      20.0,
      InlineBaselineMode::LineTop,
      &mut text_metrics,
    );
    let image = inline_alignment_image(&framed[0]).expect("aligned picture");
    assert!((image.y_pt - 60.0).abs() < 0.001);
    let PageItem::Group(paint) = &framed[0] else {
      panic!("picture paint");
    };
    let PageItem::Path(frame) = &paint[1] else {
      panic!("frame paint");
    };
    assert!((frame.bounds.origin.y.0 - image.y_pt).abs() < 0.001);

    let mut anchored = image.clone();
    anchored.x_pt = 168.725;
    anchored.y_pt = 20.0;
    anchored.width_pt = 55.35;
    anchored.inline_baseline_participant = false;
    anchored.floating = true;
    let mut mixed = vec![
      PageItem::Image(anchored),
      PageItem::Rect(RectItem {
        x_pt: 168.725,
        y_pt: 20.0,
        width_pt: 55.35,
        height_pt: 52.5,
        paragraph_alignment_locked: false,
        fill_color: None,
        fill_opacity: 1.0,
        stroke: Some(BorderStyle::default()),
        stroke_opacity: 0.0,
      }),
      PageItem::Rect(RectItem {
        x_pt: 10.0,
        y_pt: 20.0,
        width_pt: 20.0,
        height_pt: 10.0,
        paragraph_alignment_locked: false,
        fill_color: Some(RgbColor { r: 0, g: 0, b: 0 }),
        fill_opacity: 1.0,
        stroke: None,
        stroke_opacity: 1.0,
      }),
    ];
    align_paragraph_items(
      &mut mixed,
      ParagraphAlignment::Center,
      &mut text_metrics,
      100.0,
    );
    let PageItem::Image(anchored) = &mixed[0] else {
      panic!("anchored picture");
    };
    let PageItem::Rect(placeholder) = &mixed[1] else {
      panic!("picture placeholder");
    };
    let PageItem::Rect(inline_rect) = &mixed[2] else {
      panic!("inline rectangle");
    };
    assert_eq!((anchored.x_pt, placeholder.x_pt), (168.725, 168.725));
    assert_eq!(inline_rect.x_pt, 45.0);
  }

