  #[test]
  fn table_cell_wrap_compares_the_line_box_and_preserves_its_baseline_origin() {
    let mut exclusion = WrapExclusion {
      left_pt: 0.0,
      right_pt: 500.0,
      top_pt: 113.291_9,
      bottom_pt: 227.291_9,
      side: ImageWrapSide::BothSides,
      blocks_flow: true,
      uses_contour: false,
      owner: WrapExclusionOwner::Drawing,
    };
    let line_top = 96.791_9;
    let baseline = 107.265_526;

    let untouched =
      dodge_line_origin_wrap_exclusions(baseline, line_top, 12.72, 76.25, 405.4, &[exclusion]);
    assert!((untouched - baseline).abs() <= LAYOUT_EPSILON_PT);

    exclusion.top_pt = 96.0;
    exclusion.bottom_pt = 150.0;
    let moved =
      dodge_line_origin_wrap_exclusions(baseline, line_top, 12.72, 76.25, 405.4, &[exclusion]);
    assert!((moved - (150.0 + baseline - line_top)).abs() <= LAYOUT_EPSILON_PT);

    let small_picture = WrapExclusion {
      left_pt: 72.0,
      right_pt: 79.0,
      top_pt: 100.0,
      bottom_pt: 107.0,
      blocks_flow: false,
      ..exclusion
    };
    let exclusions = [small_picture];
    let at_baseline = drawing_wrap_exclusions_at_baseline(&exclusions, 12.0);
    assert_eq!(
      line_bounds_for_y(72.0, 400.0, 112.0, 14.0, &at_baseline),
      (79.0, 400.0)
    );
    assert_eq!(
      line_bounds_for_y(72.0, 400.0, 126.0, 14.0, &at_baseline),
      (72.0, 400.0)
    );
    assert_eq!(
      line_bounds_for_y(72.0, 400.0, 112.0, 14.0, &exclusions),
      (72.0, 400.0)
    );
  }

