  #[test]
  fn paragraph_continuation_fits_after_dodging_a_page_bottom_frame() {
    let setup = PageSetup {
      width_pt: 600.0,
      height_pt: 210.0,
      margin_top_pt: 60.0,
      margin_bottom_pt: 60.0,
      margin_left_pt: 60.0,
      margin_right_pt: 60.0,
      ..PageSetup::default()
    };
    let style = TextStyle::default();
    let run = TextRun {
      text: "A\nB\nC".into(),
      style: style.clone(),
      hyperlink_url: None,
      dynamic_field: None,
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      preserve_text_portion: false,
    };
    let paragraph = Paragraph {
      inlines: vec![InlineItem::Text(run.clone())],
      runs: vec![run],
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: style.clone(),
      format: Box::new(ParagraphFormat {
        line_height_rule: LineHeightRule::Exact,
        line_height_pt: Some(12.0),
        widow_control: Some(false),
        ..ParagraphFormat::default()
      }),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: style,
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    };
    for count in [1, 2] {
      for obstacle_bottom in [138.0, 170.0] {
        let columns = SectionColumns {
          count,
          gap_pt: 24.0,
          ..SectionColumns::default()
        };
        let flow = flow_context(setup, 0, columns, 0, 0, DEFAULT_TAB_STOP_PT);
        let mut page = empty_page(setup, 0);
        page.wrap_exclusions.push(WrapExclusion {
          left_pt: flow.content_left_pt,
          right_pt: flow.content_left_pt + flow.content_width,
          top_pt: 120.0,
          bottom_pt: obstacle_bottom,
          side: ImageWrapSide::BothSides,
          blocks_flow: false,
          uses_contour: false,
          owner: WrapExclusionOwner::ParagraphFrame,
        });
        let mut pages = Vec::new();
        let mut metrics = TextMetrics::new();
        layout_paragraph(
          &paragraph,
          flow,
          ParagraphLayoutTarget {
            current: &mut page,
            pages: &mut pages,
            anchor_pages: None,
            text_metrics: &mut metrics,
          },
          100.0,
          100.0,
          0.0,
        );
        pages.push(page);
        let text: Vec<_> = pages
          .iter()
          .enumerate()
          .flat_map(|(index, page)| {
            page.items.iter().filter_map(move |item| match item {
              PageItem::Text(text) => Some((index, text)),
              _ => None,
            })
          })
          .collect();
        assert_eq!(
          text
            .iter()
            .map(|(_, item)| item.text.as_str())
            .collect::<String>(),
          "ABC"
        );
        assert!(
          text.iter().all(|(_, item)| item.y_pt <= 150.0),
          "count={count} bottom={obstacle_bottom}: {text:?}"
        );
        if obstacle_bottom > 150.0 {
          let (page_index, b) = text.iter().find(|(_, item)| item.text == "B").unwrap();
          if count == 1 {
            assert_eq!(*page_index, 1);
          } else {
            assert_eq!(*page_index, 0);
            assert!(b.x_pt > 300.0);
          }
        }
      }
    }
  }

  #[test]
