  #[test]
  fn first_body_line_below_floating_table_keeps_its_own_upper_space() {
    let full_width = WrapExclusion {
      left_pt: 70.0,
      right_pt: 542.0,
      top_pt: 72.0,
      bottom_pt: 112.0,
      side: ImageWrapSide::BothSides,
      blocks_flow: false,
      uses_contour: false,
      owner: WrapExclusionOwner::FloatingTable,
    };
    for before in [0.0, 4.0, 12.0, 24.0] {
      // Native full-width controls preserve the upper margin after the
      // clear in both compatibility modes14 and15.
      assert_eq!(
        dodge_first_line_text_wrap_exclusions(
          72.0 + before,
          12.0,
          72.0,
          540.0,
          before,
          &[full_width],
        ),
        112.0 + before
      );
      let side_wrapped = WrapExclusion {
        right_pt: 192.0,
        ..full_width
      };
      assert_eq!(
        dodge_first_line_text_wrap_exclusions(
          72.0 + before,
          12.0,
          72.0,
          540.0,
          before,
          &[side_wrapped],
        ),
        72.0 + before,
        "a usable side segment retains the existing line-flow policy"
      );
      for owner in [
        WrapExclusionOwner::Drawing,
        WrapExclusionOwner::FollowingFloatingTable,
      ] {
        assert_eq!(
          dodge_first_line_text_wrap_exclusions(
            72.0 + before,
            12.0,
            72.0,
            540.0,
            before,
            &[WrapExclusion {
              owner,
              ..full_width
            }],
          ),
          112.0,
          "the first-line clear must retain the other owners' existing policy"
        );
      }
    }
  }

  #[test]
  fn word_upper_margin_moves_drawing_but_preserves_floating_table_side_wrap() {
    let side_wrapped = WrapExclusion {
      left_pt: 300.0,
      right_pt: 420.0,
      top_pt: 96.0,
      bottom_pt: 112.0,
      side: ImageWrapSide::BothSides,
      blocks_flow: false,
      uses_contour: false,
      owner: WrapExclusionOwner::FloatingTable,
    };
    assert_eq!(
      shift_first_line_below_upper_margin_exclusions(100.0, 6.0, 72.0, 540.0, &[side_wrapped],),
      100.0
    );

    let full_width = WrapExclusion {
      left_pt: 70.0,
      right_pt: 542.0,
      ..side_wrapped
    };
    assert_eq!(
      shift_first_line_below_upper_margin_exclusions(100.0, 6.0, 72.0, 540.0, &[full_width]),
      112.0
    );

    let margin_only = WrapExclusion {
      bottom_pt: 99.0,
      ..full_width
    };
    assert_eq!(
      shift_first_line_below_upper_margin_exclusions(100.0, 6.0, 72.0, 540.0, &[margin_only]),
      100.0
    );

    let side_wrapped_drawing = WrapExclusion {
      owner: WrapExclusionOwner::Drawing,
      ..side_wrapped
    };
    assert_eq!(
      shift_first_line_below_upper_margin_exclusions(
        100.0,
        6.0,
        72.0,
        540.0,
        &[side_wrapped_drawing],
      ),
      118.0
    );

    let right_edge_sidebar = WrapExclusion {
      left_pt: 472.0,
      right_pt: 590.0,
      top_pt: -7.0,
      bottom_pt: 799.0,
      ..side_wrapped_drawing
    };
    assert_eq!(
      shift_first_line_below_upper_margin_exclusions(
        116.0,
        14.0,
        54.0,
        558.0,
        &[right_edge_sidebar],
      ),
      116.0,
      "a square sidebar touching the frame edge keeps the usable left segment"
    );

    let left_edge_sidebar = WrapExclusion {
      left_pt: 20.0,
      right_pt: 140.0,
      ..right_edge_sidebar
    };
    assert_eq!(
      shift_first_line_below_upper_margin_exclusions(
        116.0,
        14.0,
        54.0,
        558.0,
        &[left_edge_sidebar],
      ),
      116.0,
      "the mirrored page-edge control keeps the usable right segment"
    );

    let side_wrapped_contour = WrapExclusion {
      uses_contour: true,
      ..side_wrapped_drawing
    };
    assert_eq!(
      shift_first_line_below_upper_margin_exclusions(
        100.0,
        6.0,
        72.0,
        540.0,
        &[side_wrapped_contour],
      ),
      100.0
    );

    let full_width_drawing = WrapExclusion {
      owner: WrapExclusionOwner::Drawing,
      ..full_width
    };
    assert_eq!(
      shift_first_line_below_upper_margin_exclusions(
        100.0,
        6.0,
        72.0,
        540.0,
        &[full_width_drawing],
      ),
      118.0
    );
  }

