  #[test]
  fn layout_in_cell_margin_anchor_uses_the_cell_print_area() {
    let setup = PageSetup {
      width_pt: 612.0,
      height_pt: 792.0,
      margin_top_pt: 54.0,
      margin_right_pt: 54.0,
      margin_bottom_pt: 54.0,
      margin_left_pt: 54.0,
      ..Default::default()
    };
    let flow = FlowContext {
      text_segmentation: TextSegmentation::TableCell,
      horizontal_table_cell: true,
      content_left_pt: 90.0,
      content_width: 308.15,
      layout_cell_bounds: Some(FrameBounds {
        x_pt: 84.6,
        y_pt: 44.1,
        width_pt: 318.95,
        height_pt: 100.35,
      }),
      layout_cell_print_bounds: Some(FrameBounds {
        x_pt: 90.0,
        y_pt: 44.1,
        width_pt: 308.15,
        height_pt: 100.35,
      }),
      ..flow_from_block_area(BlockArea {
        setup,
        section_index: 0,
        section_page_index: 0,
        column_index: 0,
        columns: SectionColumns::default(),
        content_top_pt: 44.1,
        content_left_pt: 90.0,
        content_bottom: 144.45,
        body_content_bottom_pt: 738.0,
        content_width: 308.15,
        default_tab_stop_pt: DEFAULT_TAB_STOP_PT,
        hyphenation: crate::docx::HyphenationSettings::default(),
        consecutive_hyphenated_lines: 0,
        compatibility_mode: 14,
        justify_lines_with_shrinking: false,
        do_not_expand_shift_return: false,
        suppress_top_spacing: false,
        split_page_break_and_paragraph_mark: false,
        repeating_slots: RepeatingSlotState::default(),
      })
    };
    let placement = FloatingImagePlacement {
      horizontal_relative_to: HorizontalImageReference::Margin,
      vertical_relative_to: VerticalImageReference::Margin,
      horizontal_alignment: None,
      vertical_alignment: None,
      alignment_extent: None,
      group_child_offset_x_pt: 0.0,
      group_child_offset_y_pt: 0.0,
      horizontal_offset_pt: 207.8,
      vertical_offset_pt: 12.15,
      horizontal_offset_pct: None,
      vertical_offset_pct: None,
      wrap: ImageWrapMode::Square,
      wrap_side: ImageWrapSide::BothSides,
      behind_text: false,
      layout_in_cell: true,
      layout_in_cell_forced: false,
      allow_overlap: true,
      paint_order: FloatingPaintOrder::DrawingMlRelativeHeight(251_765_760),
      relative_width_to: None,
      relative_width_pct: None,
      relative_height_to: None,
      relative_height_pct: None,
      margin_top_pt: 0.0,
      margin_right_pt: 9.15,
      margin_bottom_pt: 0.15,
      margin_left_pt: 9.0,
    };

    let (x, y) = floating_image_position(
      placement,
      flow,
      ParagraphIndents::default(),
      104.4,
      44.1,
      71.85,
      71.85,
    );
    assert!((x - 297.8).abs() <= LAYOUT_EPSILON_PT);
    assert!((y - 56.25).abs() <= LAYOUT_EPSILON_PT);

    let print_area_below_cell_top = FlowContext {
      layout_cell_print_bounds: Some(FrameBounds {
        x_pt: 90.0,
        y_pt: 100.8,
        width_pt: 308.15,
        height_pt: 43.65,
      }),
      ..flow
    };
    let (_, margin_y) = floating_image_position(
      FloatingImagePlacement {
        vertical_offset_pt: -28.35,
        ..placement
      },
      print_area_below_cell_top,
      ParagraphIndents::default(),
      104.4,
      44.1,
      71.85,
      71.85,
    );
    assert!((margin_y - 72.45).abs() <= LAYOUT_EPSILON_PT);
    let (_, page_y) = floating_image_position(
      FloatingImagePlacement {
        vertical_relative_to: VerticalImageReference::Page,
        vertical_offset_pt: -28.35,
        ..placement
      },
      print_area_below_cell_top,
      ParagraphIndents::default(),
      104.4,
      44.1,
      71.85,
      71.85,
    );
    assert!((page_y - margin_y).abs() <= LAYOUT_EPSILON_PT);

    // Office cell-capture controls: visual effects stay inside the cell;
    // text distances do not push the picture away from its captured origin.
    for (effects, expected) in [
      ([0.0; 4], (84.6, 44.1)),
      ([1.5, 4.0, 0.0, 0.0], (86.1, 48.1)),
    ] {
      for distance in [0.0, 10.0] {
        let placement = FloatingImagePlacement {
          margin_left_pt: distance,
          ..placement
        };
        let captured =
          capture_picture_in_cell((0.0, -20.0), (5.25, 6.75), effects, placement, flow);
        assert!((captured.0 - expected.0).abs() <= LAYOUT_EPSILON_PT);
        assert!((captured.1 - expected.1).abs() <= LAYOUT_EPSILON_PT);
        for wrap in [ImageWrapMode::None, ImageWrapMode::Through] {
          assert_eq!(
            capture_picture_in_cell(
              (0.0, -20.0),
              (5.25, 6.75),
              effects,
              FloatingImagePlacement { wrap, ..placement },
              flow,
            ),
            (0.0, -20.0)
          );
        }
      }
    }
  }

  #[test]
  fn word_2010_aligned_column_anchors_use_paragraph_print_area() {
    let mut flow = flow_from_block_area(BlockArea {
      setup: PageSetup {
        width_pt: 612.0,
        height_pt: 792.0,
        margin_top_pt: 72.0,
        margin_right_pt: 72.0,
        margin_bottom_pt: 72.0,
        margin_left_pt: 72.0,
        ..Default::default()
      },
      section_index: 0,
      section_page_index: 0,
      column_index: 0,
      columns: SectionColumns::default(),
      content_top_pt: 72.0,
      content_left_pt: 72.0,
      content_bottom: 720.0,
      body_content_bottom_pt: 720.0,
      // The paragraph wrapper has already removed the 80pt left and 40pt
      // right indents from the original 440pt column.
      content_width: 320.0,
      default_tab_stop_pt: DEFAULT_TAB_STOP_PT,
      hyphenation: crate::docx::HyphenationSettings::default(),
      consecutive_hyphenated_lines: 0,
      compatibility_mode: 14,
      justify_lines_with_shrinking: false,
      do_not_expand_shift_return: false,
      suppress_top_spacing: false,
      split_page_break_and_paragraph_mark: false,
      repeating_slots: RepeatingSlotState::default(),
    });
    let paragraph_indents = ParagraphIndents {
      left_pt: 80.0,
      right_pt: 40.0,
    };
    let mut placement = FloatingImagePlacement {
      horizontal_relative_to: HorizontalImageReference::Column,
      vertical_relative_to: VerticalImageReference::Paragraph,
      horizontal_alignment: Some(HorizontalImageAlignment::Left),
      vertical_alignment: None,
      alignment_extent: None,
      group_child_offset_x_pt: 0.0,
      group_child_offset_y_pt: 0.0,
      horizontal_offset_pt: 0.0,
      vertical_offset_pt: 0.0,
      horizontal_offset_pct: None,
      vertical_offset_pct: None,
      wrap: ImageWrapMode::Through,
      wrap_side: ImageWrapSide::BothSides,
      behind_text: true,
      layout_in_cell: true,
      layout_in_cell_forced: false,
      allow_overlap: false,
      paint_order: FloatingPaintOrder::Unspecified,
      relative_width_to: None,
      relative_width_pct: None,
      relative_height_to: None,
      relative_height_pct: None,
      margin_top_pt: 0.0,
      margin_right_pt: 0.0,
      margin_bottom_pt: 0.0,
      margin_left_pt: 0.0,
    };

    assert_eq!(
      floating_image_position(placement, flow, paragraph_indents, 152.0, 100.0, 20.0, 20.0,).0,
      152.0
    );
    placement.horizontal_alignment = Some(HorizontalImageAlignment::Right);
    assert_eq!(
      floating_image_position(placement, flow, paragraph_indents, 152.0, 100.0, 20.0, 20.0,).0,
      452.0
    );

    placement.horizontal_alignment = Some(HorizontalImageAlignment::Center);
    assert_eq!(
      floating_image_position(placement, flow, paragraph_indents, 152.0, 100.0, 20.0, 20.0,).0,
      282.0
    );
    placement.horizontal_alignment = None;
    placement.horizontal_offset_pt = 10.0;
    assert_eq!(
      floating_image_position(placement, flow, paragraph_indents, 152.0, 100.0, 20.0, 20.0,).0,
      82.0
    );

    flow.compatibility_mode = 15;
    placement.horizontal_alignment = Some(HorizontalImageAlignment::Left);
    placement.horizontal_offset_pt = 0.0;
    assert_eq!(
      floating_image_position(placement, flow, paragraph_indents, 152.0, 100.0, 20.0, 20.0,).0,
      72.0
    );

    let next_page_flow = preserve_paragraph_width_on_follow(flow, flow_with_column(flow, 0));
    assert_eq!(next_page_flow.content_width, flow.content_width);

    let expanded_flow = FlowContext {
      content_width: 500.0,
      ..flow
    };
    let next_page_flow =
      preserve_paragraph_width_on_follow(expanded_flow, flow_with_column(expanded_flow, 0));
    assert_eq!(next_page_flow.content_width, 468.0);
  }

  #[test]
  fn oversized_wrapped_picture_is_captured_but_page_fitting_offset_is_preserved() {
    let flow = flow_from_block_area(BlockArea {
      setup: PageSetup {
        width_pt: 419.64,
        height_pt: 297.72,
        margin_top_pt: 70.85,
        margin_right_pt: 70.85,
        margin_bottom_pt: 70.85,
        margin_left_pt: 70.85,
        ..Default::default()
      },
      section_index: 0,
      section_page_index: 1,
      column_index: 0,
      columns: SectionColumns::default(),
      content_top_pt: 70.85,
      content_left_pt: 70.85,
      content_bottom: 226.87,
      body_content_bottom_pt: 226.87,
      content_width: 277.94,
      default_tab_stop_pt: DEFAULT_TAB_STOP_PT,
      hyphenation: crate::docx::HyphenationSettings::default(),
      consecutive_hyphenated_lines: 0,
      compatibility_mode: 14,
      justify_lines_with_shrinking: false,
      do_not_expand_shift_return: false,
      suppress_top_spacing: false,
      split_page_break_and_paragraph_mark: false,
      repeating_slots: RepeatingSlotState::default(),
    });
    let mut placement = FloatingImagePlacement {
      horizontal_relative_to: HorizontalImageReference::Column,
      vertical_relative_to: VerticalImageReference::Paragraph,
      horizontal_alignment: None,
      vertical_alignment: None,
      alignment_extent: None,
      group_child_offset_x_pt: 0.0,
      group_child_offset_y_pt: 0.0,
      horizontal_offset_pt: -0.35,
      vertical_offset_pt: -22.85,
      horizontal_offset_pct: None,
      vertical_offset_pct: None,
      wrap: ImageWrapMode::Square,
      wrap_side: ImageWrapSide::BothSides,
      behind_text: false,
      layout_in_cell: true,
      layout_in_cell_forced: false,
      allow_overlap: true,
      paint_order: FloatingPaintOrder::Unspecified,
      relative_width_to: None,
      relative_width_pct: None,
      relative_height_to: None,
      relative_height_pct: None,
      margin_top_pt: 0.0,
      margin_right_pt: 9.0,
      margin_bottom_pt: 0.0,
      margin_left_pt: 9.0,
    };

    let wrapped = floating_picture_position(
      placement,
      flow,
      ParagraphIndents::default(),
      70.85,
      70.85,
      453.5,
      97.2,
    );
    assert!(wrapped.0.abs() < LAYOUT_EPSILON_PT);
    assert!((wrapped.1 - 48.0).abs() < LAYOUT_EPSILON_PT);

    // A picture narrower than the page can satisfy its authored absolute
    // column offset even when its right edge extends beyond the page. This is
    // the Word fixed-output boundary opposite the oversized capture above.
    placement.horizontal_offset_pt = 250.0;
    let page_fitting = floating_picture_position(
      placement,
      flow,
      ParagraphIndents::default(),
      70.85,
      70.85,
      150.0,
      97.2,
    );
    assert!((page_fitting.0 - 320.85).abs() < LAYOUT_EPSILON_PT);
    assert!(page_fitting.0 + 150.0 > flow.setup.width_pt);

    // Writer's DOCX import permits a wrap-through object to retain the same
    // authored off-page position; it must not inherit the wrapped correction.
    placement.horizontal_offset_pt = -0.35;
    placement.wrap = ImageWrapMode::Through;
    let through = floating_picture_position(
      placement,
      flow,
      ParagraphIndents::default(),
      70.85,
      70.85,
      453.5,
      97.2,
    );
    assert!((through.0 - 70.5).abs() < LAYOUT_EPSILON_PT);
    assert!((through.1 - 48.0).abs() < LAYOUT_EPSILON_PT);
  }

