  #[test]
  fn word_table_grid_keeps_vertical_rails_centered_and_snaps_horizontal_edges() {
    let border = BorderStyle {
      width_pt: 0.5,
      ..BorderStyle::default()
    };
    let mut page = empty_page(PageSetup::default(), 0);
    push_table_border_line_with_grid(&mut page, 56.7, 56.7, 56.7, 80.0, border, true);
    push_table_border_line_with_grid(
      &mut page,
      56.7,
      horizontal_table_border_center(56.7, border),
      177.15,
      horizontal_table_border_center(56.7, border),
      border,
      true,
    );
    let [PageItem::Fill(vertical), PageItem::Fill(horizontal)] = page.items.as_slice() else {
      panic!("solid Word table borders should be printer-grid fills");
    };
    // Native 0.5/1/2pt border controls preserve the vertical grid center
    // while the rail grows to either side. Only the horizontal top edge
    // uses even-tie printer-grid conversion (56.7pt -> 56.64pt).
    assert!((vertical.x_pt - 56.46).abs() < 0.001);
    assert!((horizontal.y_pt - 56.64).abs() < 0.001);
  }

