  #[test]
  fn explicit_nil_and_adjacent_row_exception_resolve_collapsed_table_borders() {
    let border = BorderStyle {
      width_pt: 0.5,
      ..BorderStyle::default()
    };
    let cell = TableCell {
      blocks: Vec::new(),
      shading: None,
      borders: CellBordersModel::default(),
      border_suppressions: CellBorderSuppressions {
        top: true,
        left: true,
        ..Default::default()
      },
      margins: CellMargins::default(),
      preferred_width_pt: None,
      preferred_width_pct: None,
      grid_span: 1,
      vertical_merge_continue: false,
      no_wrap: false,
      fit_text: false,
      hide_end_mark: false,
      vertical_alignment: TableCellVerticalAlignment::Top,
      text_rotation_deg: None,
    };
    let mut table = Table {
      column_widths_pt: vec![24.0],
      preferred_width_pt: None,
      preferred_width_pct: None,
      layout: TableLayoutMode::Fixed,
      indent_left_pt: 0.0,
      alignment: TableAlignment::Left,
      right_to_left: false,
      align_leading_cell_content: true,
      in_header_footer: false,
      placement: None,
      allow_overlap: true,
      split_allowed: false,
      following_text_flow: false,
      explicit_no_repeat_header: false,
      page_break_before: false,
      starts_after_last_rendered_page_break: false,
      borders: Some(TableBordersModel {
        top: Some(border),
        right: Some(border),
        bottom: Some(border),
        left: Some(border),
        inside_horizontal: None,
        inside_vertical: None,
      }),
      cell_spacing: TableCellSpacing::Collapsed,
      rows: vec![TableRow {
        cells: vec![cell],
        height_pt: None,
        exact_height: false,
        repeat_header: false,
        keep_with_next: false,
        cant_split: false,
        cell_spacing: None,
        grid_before: 0,
        grid_after: 0,
        width_before_pt: None,
        width_after_pt: None,
        layout: None,
        borders: None,
        spacing_shading: None,
        redline_color: None,
      }],
    };

    assert_eq!(
      cell_horizontal_border(&table, 0, 0, &table.rows[0].cells[0], true),
      None
    );
    assert_eq!(vertical_border(&table, &table.rows[0], 0, true), None);
    assert_eq!(
      cell_horizontal_border(&table, 0, 0, &table.rows[0].cells[0], false),
      Some(border)
    );
    assert_eq!(
      vertical_border(&table, &table.rows[0], 0, false),
      Some(border)
    );

    // The following row's tblPrEx/insideH owns this shared boundary even
    // though the preceding row has no table-level insideH border.
    let mut following_row = table.rows[0].clone();
    following_row.cells[0].border_suppressions = CellBorderSuppressions::default();
    following_row.borders = Some(TableBordersModel {
      inside_horizontal: Some(border),
      ..table.borders.unwrap()
    });
    table.rows.push(following_row);
    assert_eq!(
      cell_horizontal_border(&table, 0, 0, &table.rows[0].cells[0], false),
      Some(border)
    );
    assert_eq!(
      cell_horizontal_border(&table, 1, 0, &table.rows[1].cells[0], true),
      Some(border)
    );
  }

