  #[test]
  fn east_asian_paragraph_mark_metrics_cover_direct_marks_and_alignment_counterexamples() {
    let mut paragraph = Paragraph {
      inlines: Vec::new(),
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: TextStyle::default(),
      #[cfg(test)]
      runs: Vec::new(),
      format: Box::new(ParagraphFormat {
        justification: crate::docx::ParagraphJustification {
          adjust: crate::docx::ParagraphAdjust::Start,
          logical_start: true,
          ..Default::default()
        },
        ..Default::default()
      }),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: TextStyle::default(),
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    };
    let mut text_metrics = TextMetrics::new();

    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        15,
        TextSegmentation::Body,
        false,
        0,
        &mut text_metrics,
      )
      .is_some()
    );
    paragraph.format.justification.logical_start = false;
    paragraph.format.justification.physical_left = true;
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        15,
        TextSegmentation::Body,
        false,
        0,
        &mut text_metrics,
      )
      .is_none()
    );
    paragraph.format.bidi = true;
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        15,
        TextSegmentation::Body,
        false,
        0,
        &mut text_metrics,
      )
      .is_some()
    );
    paragraph.format.bidi = false;
    paragraph.inlines.push(InlineItem::FormWidgetStart(0));
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        15,
        TextSegmentation::Body,
        false,
        0,
        &mut text_metrics,
      )
      .is_some()
    );
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        15,
        TextSegmentation::TableCell,
        true,
        0,
        &mut text_metrics,
      )
      .is_none()
    );
    paragraph.inlines.clear();
    paragraph.format.justification.physical_left = false;
    paragraph.format.justification.logical_start = true;
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        12,
        TextSegmentation::Body,
        false,
        0,
        &mut text_metrics,
      )
      .is_none()
    );
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        15,
        TextSegmentation::Body,
        false,
        1,
        &mut text_metrics,
      )
      .is_none()
    );

    paragraph.inlines.push(InlineItem::Text(TextRun {
      text: "st".into(),
      style: TextStyle {
        font_size_pt: 7.15,
        baseline_shift_pt: 3.63,
        ..Default::default()
      },
      hyperlink_url: None,
      dynamic_field: None,
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      preserve_text_portion: false,
    }));
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        12,
        TextSegmentation::Body,
        false,
        0,
        &mut text_metrics,
      )
      .is_none()
    );

    paragraph.format.justification.adjust = crate::docx::ParagraphAdjust::Left;
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        15,
        TextSegmentation::Body,
        false,
        0,
        &mut text_metrics,
      )
      .is_none()
    );
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        12,
        TextSegmentation::Body,
        false,
        0,
        &mut text_metrics,
      )
      .is_some()
    );

    paragraph.inlines.clear();
    paragraph.format.numbered_paragraph_mark_background = true;
    let direct_height = word_east_asian_paragraph_mark_single_line_height(
      &paragraph,
      12,
      TextSegmentation::Body,
      false,
      0,
      &mut text_metrics,
    )
    .expect("direct paragraph-mark formatting must participate in the line box");
    paragraph.format.numbered_paragraph_mark_background = false;
    paragraph.format.justification.adjust = crate::docx::ParagraphAdjust::Start;
    let implicit_height = word_east_asian_paragraph_mark_single_line_height(
      &paragraph,
      15,
      TextSegmentation::Body,
      false,
      0,
      &mut text_metrics,
    )
    .expect("modern logical-start paragraph retains the implicit mark metrics");
    assert!((direct_height - implicit_height * 1.27).abs() < 0.001);
  }

  #[test]
  fn legacy_chinese_horizontal_table_cell_uses_fixed_line_box() {
    let mut paragraph = Paragraph {
      inlines: Vec::new(),
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: TextStyle {
        east_asia_language: Some(Arc::from("zh-CN")),
        font_size_pt: 11.0,
        complex_font_size_pt: Some(12.0),
        ..Default::default()
      },
      #[cfg(test)]
      runs: Vec::new(),
      format: Box::new(ParagraphFormat {
        justification: crate::docx::ParagraphJustification {
          adjust: crate::docx::ParagraphAdjust::Left,
          ..Default::default()
        },
        ..Default::default()
      }),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: TextStyle::default(),
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    };
    let mut text_metrics = TextMetrics::new();

    assert_eq!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        12,
        TextSegmentation::TableCell,
        true,
        0,
        &mut text_metrics,
      ),
      Some(17.28)
    );
    paragraph.format.line_height_pt = Some(278.0 / 240.0);
    paragraph.format.office_recovered_line_height = true;
    assert_eq!(
      word_recovered_legacy_chinese_table_break_line_height(
        &paragraph,
        12,
        TextSegmentation::TableCell,
        true,
      ),
      Some(17.28),
      "a break-only line uses the recovered legacy Chinese table box",
    );
    assert_eq!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        12,
        TextSegmentation::TableCell,
        true,
        0,
        &mut text_metrics,
      ),
      Some(17.28),
      "an application-recovered auto multiple must not masquerade as authored line spacing",
    );
    paragraph.format.justification = crate::docx::ParagraphJustification::default();
    paragraph.format.justification.adjust = crate::docx::ParagraphAdjust::Center;
    assert_eq!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        12,
        TextSegmentation::TableCell,
        true,
        0,
        &mut text_metrics,
      ),
      Some(17.28),
      "a recovered empty table paragraph is physically only its Chinese paragraph mark",
    );
    assert_eq!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        12,
        TextSegmentation::Body,
        false,
        0,
        &mut text_metrics,
      ),
      Some(17.28),
      "an unformatted recovered Chinese body mark owns the otherwise empty line",
    );
    paragraph.format.style_id = Some(Arc::from("style0"));
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        12,
        TextSegmentation::Body,
        false,
        0,
        &mut text_metrics,
      )
      .is_none(),
      "an explicit paragraph style remains authoritative for an empty body mark",
    );
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        12,
        TextSegmentation::TableCell,
        true,
        0,
        &mut text_metrics,
      )
      .is_none(),
      "an explicit paragraph style remains authoritative for an empty table mark",
    );
    paragraph.format.style_id = None;
    paragraph.format.paragraph_mark_font_size_set = true;
    assert!(
      word_recovered_legacy_chinese_table_break_line_height(
        &paragraph,
        12,
        TextSegmentation::TableCell,
        true,
      )
      .is_none(),
      "direct paragraph-mark size remains authoritative for a break-only line",
    );
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        12,
        TextSegmentation::Body,
        false,
        0,
        &mut text_metrics,
      )
      .is_none(),
      "direct paragraph-mark size remains authoritative",
    );
    paragraph.format.paragraph_mark_font_size_set = false;
    paragraph.list_label = Some("visible".to_string());
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        12,
        TextSegmentation::TableCell,
        true,
        0,
        &mut text_metrics,
      )
      .is_none(),
      "default-aligned visible content must keep its visible-script line box",
    );
    paragraph.list_label = None;
    paragraph.format.office_recovered_line_height = false;
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        12,
        TextSegmentation::TableCell,
        true,
        0,
        &mut text_metrics,
      )
      .is_none(),
      "a style-inherited auto multiple remains authored line spacing",
    );
    paragraph.format.line_height_set = true;
    assert!(
      word_recovered_legacy_chinese_table_break_line_height(
        &paragraph,
        12,
        TextSegmentation::TableCell,
        true,
      )
      .is_none(),
      "authored line spacing remains authoritative for a break-only line",
    );
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        12,
        TextSegmentation::TableCell,
        true,
        0,
        &mut text_metrics,
      )
      .is_none(),
      "authored line spacing remains authoritative",
    );
    paragraph.format.line_height_pt = None;
    paragraph.format.line_height_set = false;
    paragraph.format.office_recovered_line_height = true;
    assert!(
      word_recovered_legacy_chinese_table_break_line_height(
        &paragraph,
        15,
        TextSegmentation::TableCell,
        true,
      )
      .is_none(),
      "the legacy box is not a modern-compatibility rule",
    );
    assert!(
      word_recovered_legacy_chinese_table_break_line_height(
        &paragraph,
        12,
        TextSegmentation::Body,
        false,
      )
      .is_none(),
      "body breaks are not table-cell compatibility lines",
    );
    assert!(
      word_recovered_legacy_chinese_table_break_line_height(
        &paragraph,
        12,
        TextSegmentation::TableCell,
        false,
      )
      .is_none(),
      "vertical table cells retain their authored orientation metrics",
    );
    paragraph.format.office_recovered_line_height = false;
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        12,
        TextSegmentation::Body,
        false,
        0,
        &mut text_metrics,
      )
      .is_none()
    );
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        12,
        TextSegmentation::TableCell,
        false,
        0,
        &mut text_metrics,
      )
      .is_none()
    );

    paragraph.format.office_recovered_line_height = true;
    paragraph.base_style.east_asia_language = Some(Arc::from("en-US"));
    assert!(
      word_recovered_legacy_chinese_table_break_line_height(
        &paragraph,
        12,
        TextSegmentation::TableCell,
        true,
      )
      .is_none(),
      "non-Chinese cells retain visible-script line metrics",
    );
    assert!(
      word_east_asian_paragraph_mark_single_line_height(
        &paragraph,
        12,
        TextSegmentation::TableCell,
        true,
        0,
        &mut text_metrics,
      )
      .is_none()
    );
  }

  #[test]
  fn table_cell_adjacent_paragraphs_resolve_each_frame_baseline() {
    fn paragraph(text: Option<&str>, font_size_pt: f32) -> Paragraph {
      let style = TextStyle {
        font_size_pt,
        ..TextStyle::default()
      };
      Paragraph {
        inlines: text
          .map(|text| {
            vec![InlineItem::Text(TextRun {
              text: text.into(),
              style: style.clone(),
              hyperlink_url: None,
              dynamic_field: None,
              style_ref_keys: Vec::new(),
              style_ref_text: None,
              style_ref_numbering_text: None,
              preserve_text_portion: false,
            })]
          })
          .unwrap_or_default(),
        field_events: Vec::new(),
        footnote_reference_ids: Vec::new(),
        endnote_reference_ids: Vec::new(),
        starts_after_last_rendered_page_break: false,
        base_style: style,
        #[cfg(test)]
        runs: Vec::new(),
        format: Box::new(ParagraphFormat::default()),
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        list_label: None,
        list_label_image: None,
        list_label_style: TextStyle::default(),
        list_label_hyperlink_url: None,
        list_label_tab_stop_pt: None,
      }
    }

    let large = paragraph(Some("large"), 16.0);
    let empty = paragraph(None, 11.0);
    let small = paragraph(Some("small"), 11.0);
    let same_size = paragraph(Some("same"), 11.0);
    let flow = FlowContext {
      footnote_lower_space: None,
      setup: PageSetup::default(),
      section_index: 0,
      section_page_index: 0,
      column_index: 0,
      columns: SectionColumns::default(),
      content_top_pt: 0.0,
      content_left_pt: 0.0,
      content_bottom: UNBOUNDED_LAYOUT_EXTENT_PT,
      body_content_bottom_pt: UNBOUNDED_LAYOUT_EXTENT_PT,
      content_width: 200.0,
      layout_cell_bounds: None,
      layout_cell_print_bounds: None,
      paragraph_shading_clip: None,
      default_tab_stop_pt: DEFAULT_TAB_STOP_PT,
      hyphenation: crate::docx::HyphenationSettings::default(),
      consecutive_hyphenated_lines: 0,
      compatibility_mode: 15,
      justify_lines_with_shrinking: true,
      do_not_expand_shift_return: false,
      suppress_top_spacing: false,
      split_page_break_and_paragraph_mark: false,
      repeating_slots: RepeatingSlotState::default(),
      text_segmentation: TextSegmentation::TableCell,
      horizontal_table_cell: true,
      paragraph_spacing_context: ParagraphSpacingContext::Normal,
      preserve_horizontal_on_advance: false,
      script_sensitive_line_height: true,
      word_floating_table_cell: false,
      floating_table_cell_follow_top_inset_pt: 0.0,
      note_continuation_top_inset_pt: 0.0,
      inside_paragraph_frame: false,
      paragraph_frame_translation_y_pt: None,
      fixed_output_raster_dpi: units::OFFICE_FIXED_OUTPUT_RASTER_DPI,
      table_cell_complete_first_line_fit: false,
      table_cell_cursor_is_line_top: false,
      table_cell_baseline_delta_pt: 0.0,
    };
    let mut text_metrics = TextMetrics::new();
    let large_style = paragraph_base_line_style(&large);
    let large_height = paragraph_line_height_for_setup(
      &large,
      &large_style,
      flow.setup,
      flow.text_segmentation,
      &mut text_metrics,
    );
    let large_offset =
      table_cell_initial_baseline_offset(&large_style, large_height, &mut text_metrics);
    let small_style = paragraph_base_line_style(&small);
    let small_height = paragraph_line_height_for_setup(
      &small,
      &small_style,
      flow.setup,
      flow.text_segmentation,
      &mut text_metrics,
    );
    let small_offset =
      table_cell_initial_baseline_offset(&small_style, small_height, &mut text_metrics);
    let blocks = vec![
      Block::paragraph(large),
      Block::paragraph(empty),
      Block::paragraph(small),
      Block::paragraph(same_size),
    ];

    let (_, pages, baseline_coordinate_advance) = layout_cell_blocks_for_overlap_probe(
      &blocks,
      flow,
      large_offset,
      large_offset,
      &[],
      &mut text_metrics,
    );
    let baselines = pages
      .iter()
      .flat_map(|page| &page.items)
      .filter_map(|item| {
        let PageItem::Text(text) = item else {
          return None;
        };
        Some((text.text.as_str(), text.y_pt))
      })
      .collect::<Vec<_>>();
    let expected_small = large_height + small_offset + small_height;
    let expected_same = expected_small + small_height;

    assert_eq!(baselines.len(), 3);
    assert_eq!(baselines[0].0, "large");
    assert!((baselines[0].1 - large_offset).abs() < 0.001);
    assert_eq!(baselines[1].0, "small");
    assert!((baselines[1].1 - expected_small).abs() < 0.001);
    assert_eq!(baselines[2].0, "same");
    assert!((baselines[2].1 - expected_same).abs() < 0.001);
    assert!((baseline_coordinate_advance - (small_offset - large_offset)).abs() < 0.001);
  }

  #[test]
  fn empty_soft_break_uses_its_run_height_before_larger_text() {
    fn paragraph(text: &str, style_id: &str, before: f32, after: f32) -> Paragraph {
      Paragraph {
        inlines: vec![InlineItem::Text(TextRun {
          text: text.into(),
          style: TextStyle::default(),
          hyperlink_url: None,
          dynamic_field: None,
          style_ref_keys: Vec::new(),
          style_ref_text: None,
          style_ref_numbering_text: None,
          preserve_text_portion: false,
        })],
        field_events: Vec::new(),
        footnote_reference_ids: Vec::new(),
        endnote_reference_ids: Vec::new(),
        starts_after_last_rendered_page_break: false,
        base_style: TextStyle::default(),
        #[cfg(test)]
        runs: Vec::new(),
        format: Box::new(ParagraphFormat {
          style_id: Some(style_id.into()),
          spacing_before_pt: before,
          spacing_after_pt: after,
          ..Default::default()
        }),
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        list_label: None,
        list_label_image: None,
        list_label_style: TextStyle::default(),
        list_label_hyperlink_url: None,
        list_label_tab_stop_pt: None,
      }
    }
    let mut metrics = TextMetrics::new();
    for size in [9.0, 14.0, 21.0] {
      let mut paragraph = paragraph("heading", "Normal", 0.0, 0.0);
      let InlineItem::Text(text) = &mut paragraph.inlines[0] else {
        unreachable!()
      };
      text.style.font_family = Some(Arc::from("Arial"));
      text.style.font_size_pt = 21.0;
      let mut line_break = text.clone();
      line_break.text = "\n".into();
      line_break.style.font_size_pt = size;
      let expected = metrics
        .line_vertical_metrics(&line_break.style)
        .line_height_pt();
      paragraph.inlines.insert(0, InlineItem::Text(line_break));
      let flow = flow_context(
        PageSetup::default(),
        0,
        SectionColumns::default(),
        0,
        0,
        DEFAULT_TAB_STOP_PT,
      );
      let mut page = empty_page(flow.setup, 0);
      let mut pages = Vec::new();
      let (_, end) = layout_paragraph(
        &paragraph,
        flow,
        ParagraphLayoutTarget {
          current: &mut page,
          pages: &mut pages,
          anchor_pages: None,
          text_metrics: &mut metrics,
        },
        flow.content_top_pt,
        flow.content_top_pt,
        0.0,
      );
      assert!(pages.is_empty());
      let text = page
        .items
        .iter()
        .find_map(|item| match item {
          PageItem::Text(text) => Some(text),
          _ => None,
        })
        .expect("heading after the break");
      assert!(
        (text.y_pt - flow.content_top_pt - expected).abs() < 0.01,
        "break size={size}, actual={}",
        text.y_pt - flow.content_top_pt
      );
      let measured = estimated_paragraph_content_height(&paragraph, flow, &mut metrics);
      assert!((measured - (end - flow.content_top_pt)).abs() < 0.01);
    }
    // A terminal soft break leaves a paragraph-mark-only line. Its owner
    // differs from the break character above, in body and table stories.
    for segmentation in [TextSegmentation::Body, TextSegmentation::TableCell] {
      for rule in [
        LineHeightRule::Auto,
        LineHeightRule::Exact,
        LineHeightRule::AtLeast,
      ] {
        for mark_size in [1.0, 14.0, 24.0] {
          let mut paragraph = paragraph("TEXT\n", "Normal", 0.0, 0.0);
          let InlineItem::Text(run) = &mut paragraph.inlines[0] else {
            unreachable!()
          };
          run.style.font_family = Some(Arc::from("Arial"));
          run.style.font_size_pt = 14.0;
          paragraph.base_style = run.style.clone();
          paragraph.base_style.font_size_pt = mark_size;
          paragraph.format.paragraph_mark_font_size_set = true;
          paragraph.format.widow_control = Some(false);
          paragraph.format.line_height_rule = rule;
          paragraph.format.line_height_pt = Some(if rule == LineHeightRule::Auto {
            1.0
          } else {
            18.0
          });
          let text_height = metrics.line_vertical_metrics(&run.style).line_height_pt();
          let mark_height = metrics
            .line_vertical_metrics(&paragraph.base_style)
            .line_height_pt();
          let expected = match rule {
            LineHeightRule::Auto => text_height + mark_height,
            LineHeightRule::Exact => 36.0,
            LineHeightRule::AtLeast => text_height.max(18.0) + mark_height.max(18.0),
          };
          let mut flow = flow_context(
            PageSetup::default(),
            0,
            SectionColumns::default(),
            0,
            0,
            DEFAULT_TAB_STOP_PT,
          );
          flow.text_segmentation = segmentation;
          flow.horizontal_table_cell = segmentation == TextSegmentation::TableCell;
          let mut page = empty_page(flow.setup, 0);
          let mut pages = Vec::new();
          let (_, end) = layout_paragraph(
            &paragraph,
            flow,
            ParagraphLayoutTarget {
              current: &mut page,
              pages: &mut pages,
              anchor_pages: None,
              text_metrics: &mut metrics,
            },
            flow.content_top_pt,
            flow.content_top_pt,
            0.0,
          );
          assert!(pages.is_empty());
          assert!(
            (end - flow.content_top_pt - expected).abs() < 0.01,
            "{segmentation:?}/{rule:?}/mark={mark_size}: actual={}, expected={expected}",
            end - flow.content_top_pt
          );
          let measured = estimated_paragraph_content_height(&paragraph, flow, &mut metrics);
          assert!(
            (measured - expected).abs() < 0.01,
            "measured={measured}, expected={expected}"
          );
          if segmentation == TextSegmentation::Body
            && rule == LineHeightRule::Auto
            && mark_size == 24.0
          {
            let setup = PageSetup {
              height_pt: 173.0,
              ..PageSetup::default()
            };
            let flow = flow_context(
              setup,
              0,
              SectionColumns::default(),
              0,
              0,
              DEFAULT_TAB_STOP_PT,
            );
            let mut current = empty_page(setup, 0);
            let mut pages = Vec::new();
            let (follow, end) = layout_paragraph(
              &paragraph,
              flow,
              ParagraphLayoutTarget {
                current: &mut current,
                pages: &mut pages,
                anchor_pages: None,
                text_metrics: &mut metrics,
              },
              flow.content_top_pt,
              flow.content_top_pt,
              0.0,
            );
            assert_eq!(pages.len(), 1);
            assert!(
              current.items.is_empty(),
              "only the paragraph mark owns the follow"
            );
            assert!(page_has_body_region_items(&current, follow));
            assert!(!is_page_frame_empty(&current));
            assert!((end - follow.content_top_pt - mark_height).abs() < 0.01);
          }
        }
      }
    }
  }

