  #[test]
  fn cell_paint_clip_keeps_its_physical_page_after_split_fly_follows() {
    let text = || PageItem::Text(Box::new(legacy_effect_test_text(TextStyle::default())));
    let clip = common_rect(10.0, 20.0, 90.0, 30.0);
    for follow_pages in [0, 1, 2] {
      let mut pages = vec![
        empty_page(PageSetup::default(), 0),
        empty_page(PageSetup::default(), 1),
      ];
      let mut current = empty_page(PageSetup::default(), 2);
      current.items = vec![text(), text()];
      let start = PageItemStart {
        pages_len: pages.len(),
        current_items_len: current.items.len(),
      };
      current
        .items
        .push(PageItem::InlineObjectGroup(vec![text()]));
      for _ in 0..follow_pages {
        let next = empty_page(PageSetup::default(), pages.len() + 1);
        pages.push(std::mem::replace(&mut current, next));
        // A new page has fewer items than the old cell's start index.
        current.items.push(text());
      }

      let owner = start.owner_page_mut(&mut current, &mut pages);
      clip_inline_text_after_page_start(owner, start.current_items_len, clip);
      for item in &owner.items[..start.current_items_len] {
        let PageItem::Text(text) = item else {
          panic!("preceding text");
        };
        assert_eq!(text.paint_clip, None);
      }
      let PageItem::InlineObjectGroup(items) = &owner.items[start.current_items_len] else {
        panic!("cell content");
      };
      let PageItem::Text(text) = &items[0] else {
        panic!("inline cell text");
      };
      assert_eq!(text.paint_clip, Some(clip));
      if follow_pages > 0 {
        for page in pages.iter().skip(start.pages_len + 1).chain([&current]) {
          let PageItem::Text(text) = &page.items[0] else {
            panic!("following-page text");
          };
          assert_eq!(text.paint_clip, None);
        }
      }
    }
  }

