  #[test]
  fn wordprocessing_shape_line_owns_native_font_and_exact_baselines() {
    let mut text_metrics = TextMetrics::new();
    for (family, size, native_offset) in [
      ("Times New Roman", 24.0, 22.432),
      ("Times New Roman", 48.0, 44.8),
      ("Arial", 24.0, 22.584),
      ("Arial", 48.0, 44.952),
    ] {
      for (exact, compression) in [(false, 1.0), (false, 0.8), (false, 0.4), (true, 1.0)] {
        let mut page = empty_page(PageSetup::default(), 0);
        for scale in [0.5, 1.0] {
          let style = TextStyle {
            font_family: Some(Arc::from(family)),
            font_size_pt: size * scale,
            use_windows_font_metrics: true,
            ..TextStyle::default()
          };
          let height = if exact {
            60.0
          } else {
            text_metrics.line_vertical_metrics(&style).line_height_pt() * compression
          };
          push_text_item(
            &mut page,
            TextPlacement {
              x_pt: 0.0,
              y_pt: 100.0,
              line_height_pt: height,
            },
            "Alpha".into(),
            &style,
            &TextChunkMeta {
              hyperlink_url: None,
              dynamic_field: None,
              style_ref_keys: &[],
              style_ref_text: None,
              style_ref_numbering_text: None,
              form_widget_id: None,
              paragraph_bidi: false,
              preserve_text_portion: false,
              normalize_baseline_shift: false,
              wordprocessing_auto_line_spacing_units: (!exact).then_some(240),
              segmentation: TextSegmentation::TableCell,
            },
          );
        }
        align_wordprocessing_shape_line_baselines(
          &mut page.items,
          0,
          100.0,
          60.0,
          if exact {
            LineHeightRule::Exact
          } else {
            LineHeightRule::Auto
          },
          false,
          &mut text_metrics,
        );
        for item in &page.items {
          let PageItem::Text(text) = item else {
            panic!("text")
          };
          let baseline = text.y_pt
            + text_metrics.baseline_offset_in_line_with_windows_metrics_for_text(
              &text.text,
              &text.style,
              text.line_height_pt,
            );
          let expected = 100.0
            + if exact {
              48.0
            } else {
              native_offset * compression
            };
          assert!(
            (baseline - expected).abs() < 0.12,
            "{family} {size} exact={exact}: {baseline} vs {expected}"
          );
        }
      }
    }
  }

  #[test]
  fn wordprocessing_shape_story_converts_its_text_rect_top_to_a_baseline() {
    let mut paragraph = Paragraph {
      inlines: Vec::new(),
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: TextStyle::default(),
      #[cfg(test)]
      runs: Vec::new(),
      format: Box::new(ParagraphFormat {
        wordprocessing_shape_story: true,
        ..ParagraphFormat::default()
      }),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: TextStyle::default(),
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    };
    let flow = FlowContext {
      text_segmentation: TextSegmentation::TableCell,
      horizontal_table_cell: false,
      layout_cell_bounds: Some(FrameBounds {
        x_pt: 76.25,
        y_pt: 96.791_9,
        width_pt: 339.95,
        height_pt: 144.2,
      }),
      layout_cell_print_bounds: Some(FrameBounds {
        x_pt: 76.25,
        y_pt: 96.791_9,
        width_pt: 329.15,
        height_pt: 144.2,
      }),
      ..flow_context(
        PageSetup::default(),
        0,
        SectionColumns::default(),
        0,
        0,
        DEFAULT_TAB_STOP_PT,
      )
    };
    let line_top = 157.619;
    let mut text_metrics = TextMetrics::new();
    let text_frame = TextFrame::new(&paragraph, flow, &mut text_metrics);
    let expected_offset = table_cell_initial_baseline_offset(
      &paragraph_base_line_style(&paragraph),
      text_frame.base_line_height,
      &mut text_metrics,
    );
    let blocks = [Block::paragraph(paragraph.clone())];
    let baseline =
      shape_text_box_initial_cursor_y(&blocks, flow, line_top, true, &mut text_metrics);
    assert!((baseline - line_top - expected_offset).abs() <= LAYOUT_EPSILON_PT);
    assert!(baseline > line_top + LAYOUT_EPSILON_PT);

    paragraph.format.wordprocessing_shape_story = false;
    let control = [Block::paragraph(paragraph.clone())];
    assert_eq!(
      shape_text_box_initial_cursor_y(&control, flow, line_top, true, &mut text_metrics),
      line_top,
    );

    paragraph.format.wordprocessing_shape_story = true;
    let non_centered_control = [Block::paragraph(paragraph)];
    assert_eq!(
      shape_text_box_initial_cursor_y(
        &non_centered_control,
        flow,
        line_top,
        false,
        &mut text_metrics,
      ),
      line_top,
    );

    let body_owned_control_flow = FlowContext {
      layout_cell_bounds: None,
      layout_cell_print_bounds: None,
      paragraph_shading_clip: None,
      ..flow
    };
    assert_eq!(
      shape_text_box_initial_cursor_y(
        &blocks,
        body_owned_control_flow,
        line_top,
        true,
        &mut text_metrics,
      ),
      line_top,
    );
  }

