  #[test]
  fn document_grid_line_spacing_covers_auto_at_least_and_exact_rules() {
    let mut paragraph = Paragraph {
      inlines: Vec::new(),
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: TextStyle::default(),
      #[cfg(test)]
      runs: Vec::new(),
      format: Box::new(ParagraphFormat {
        line_height_rule: LineHeightRule::Auto,
        line_height_pt: Some(1.35),
        office_recovered_line_height: true,
        snap_to_grid: Some(true),
        ..Default::default()
      }),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: TextStyle::default(),
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    };
    let setup = PageSetup {
      doc_grid_line_pitch_pt: Some(15.6),
      ..Default::default()
    };
    let mut text_metrics = TextMetrics::new();
    let base_style = paragraph_base_line_style(&paragraph);
    let mut east_asia_hint_style = base_style.clone();
    east_asia_hint_style.wordprocessingml_font_slots = true;
    east_asia_hint_style.wordprocessingml_font_hint =
      Some(ooxmlsdk_fonts::WordprocessingFontTypeHint::EastAsia);
    assert!(
      document_grid_line_metric_style(&east_asia_hint_style).wordprocessingml_cjk_line_metrics
    );
    assert!(
      !document_grid_line_metric_style(&base_style).wordprocessingml_cjk_line_metrics,
      "a non-East-Asian hint must not opt a grid line into CJK face metrics",
    );
    let body_height = paragraph_line_height_for_setup(
      &paragraph,
      &base_style,
      setup,
      TextSegmentation::Body,
      &mut text_metrics,
    );
    assert!((body_height - 21.06).abs() < 0.01);
    let body_grid_heights = grid_auto_line_heights(
      &paragraph,
      &base_style,
      setup,
      TextSegmentation::Body,
      &mut text_metrics,
    )
    .expect("body grid heights");
    assert!((body_grid_heights.following_line_pt - 21.06).abs() < 0.01);
    assert!(
      (line_real_height(
        &paragraph,
        body_height,
        1,
        Some(body_grid_heights.following_line_pt),
        false,
      ) - 21.06)
        .abs()
        < 0.01
    );

    let table_height = paragraph_line_height_for_setup(
      &paragraph,
      &base_style,
      setup,
      TextSegmentation::TableCell,
      &mut text_metrics,
    );
    assert!(table_height < body_grid_heights.following_line_pt);

    let mut inherited_paragraph = paragraph.clone();
    inherited_paragraph.format.office_recovered_line_height = false;
    let inherited_body_height = paragraph_line_height_for_setup(
      &inherited_paragraph,
      &base_style,
      setup,
      TextSegmentation::Body,
      &mut text_metrics,
    );
    assert!(
      (inherited_body_height - 15.6).abs() < 0.01,
      "an empty paragraph mark stays on the first one-grid line",
    );

    inherited_paragraph.inlines = vec![InlineItem::Text(TextRun {
      text: "visible".into(),
      style: base_style.clone(),
      hyperlink_url: None,
      dynamic_field: None,
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      preserve_text_portion: false,
    })];
    let recovered_grid_visible_body_height = paragraph_line_height_for_setup(
      &inherited_paragraph,
      &base_style,
      setup,
      TextSegmentation::Body,
      &mut text_metrics,
    );
    assert!(
      (recovered_grid_visible_body_height - 15.6).abs() < 0.01,
      "an authored multiple does not enlarge a synthetic recovered grid row",
    );
    let authored_grid_setup = PageSetup {
      table_cell_doc_grid_line_pitch_pt: Some(15.6),
      ..setup
    };
    let authored_grid_visible_body_height = paragraph_line_height_for_setup(
      &inherited_paragraph,
      &base_style,
      authored_grid_setup,
      TextSegmentation::Body,
      &mut text_metrics,
    );
    assert!(
      (authored_grid_visible_body_height - 21.06).abs() < 0.01,
      "a visible line keeps its inherited proportional height on an authored grid",
    );

    let mut wordprocessing_shape_paragraph = paragraph.clone();
    wordprocessing_shape_paragraph
      .format
      .wordprocessing_shape_story = true;
    let wordprocessing_shape_height = paragraph_line_height_for_setup(
      &wordprocessing_shape_paragraph,
      &base_style,
      setup,
      TextSegmentation::TableCell,
      &mut text_metrics,
    );
    assert!((wordprocessing_shape_height - 21.06).abs() < 0.01);
    assert!(
      doc_grid_character_pitch(
        &wordprocessing_shape_paragraph,
        PageSetup {
          doc_grid_character_spacing_pt: Some(1.0),
          ..setup
        },
        TextSegmentation::TableCell,
      )
      .is_some(),
      "the WPS text-frame story uses the body grid despite its TableCell formatter"
    );

    let table_grid_setup = PageSetup {
      adjust_table_line_heights_to_grid: true,
      ..setup
    };
    let table_grid_height = paragraph_line_height_for_setup(
      &paragraph,
      &base_style,
      table_grid_setup,
      TextSegmentation::TableCell,
      &mut text_metrics,
    );
    assert!((table_grid_height - 15.6).abs() < 0.01);

    let omitted_type_table_setup = PageSetup {
      doc_grid_line_pitch_pt: None,
      table_cell_doc_grid_line_pitch_pt: Some(15.6),
      adjust_table_line_heights_to_grid: true,
      ..setup
    };
    assert!(
      grid_auto_line_heights(
        &paragraph,
        &base_style,
        omitted_type_table_setup,
        TextSegmentation::Body,
        &mut text_metrics,
      )
      .is_none()
    );
    assert!(
      grid_auto_line_heights(
        &paragraph,
        &base_style,
        omitted_type_table_setup,
        TextSegmentation::TableCell,
        &mut text_metrics,
      )
      .is_some()
    );

    paragraph.format.line_height_pt = Some(0.75);
    let below_single_height = paragraph_line_height_for_setup(
      &paragraph,
      &base_style,
      setup,
      TextSegmentation::Body,
      &mut text_metrics,
    );
    assert!((below_single_height - 15.6).abs() < 0.01);

    paragraph.base_style.font_size_pt = 22.0;
    paragraph.format.line_height_pt = Some(578.0 / 240.0);
    let heading_style = paragraph_base_line_style(&paragraph);
    let heading_height = paragraph_line_height_for_setup(
      &paragraph,
      &heading_style,
      setup,
      TextSegmentation::Body,
      &mut text_metrics,
    );
    assert!((heading_height - 37.57).abs() < 0.02);
    let heading_grid_heights = grid_auto_line_heights(
      &paragraph,
      &heading_style,
      setup,
      TextSegmentation::Body,
      &mut text_metrics,
    )
    .expect("heading grid heights");
    assert!((heading_grid_heights.following_line_pt - 37.57).abs() < 0.02);

    paragraph.base_style = TextStyle::default();
    paragraph.format.line_height_rule = LineHeightRule::AtLeast;
    paragraph.format.line_height_pt = Some(0.0);
    let ordinary_style = paragraph_base_line_style(&paragraph);
    let natural_height = inline_text_height(&ordinary_style, &mut text_metrics);
    let zero_minimum_height = paragraph_line_height_for_setup(
      &paragraph,
      &ordinary_style,
      setup,
      TextSegmentation::Body,
      &mut text_metrics,
    );
    assert!((zero_minimum_height - natural_height).abs() < 0.01);

    paragraph.format.line_height_pt = Some(1.0);
    let nonzero_minimum_height = paragraph_line_height_for_setup(
      &paragraph,
      &ordinary_style,
      setup,
      TextSegmentation::Body,
      &mut text_metrics,
    );
    assert!((nonzero_minimum_height - 15.6).abs() < 0.01);

    paragraph.format.line_height_pt = Some(80.0);
    let dominant_minimum_height = paragraph_line_height_for_setup(
      &paragraph,
      &ordinary_style,
      setup,
      TextSegmentation::Body,
      &mut text_metrics,
    );
    assert!((dominant_minimum_height - 80.0).abs() < 0.01);

    paragraph.format.line_height_rule = LineHeightRule::Exact;
    paragraph.format.line_height_pt = Some(12.0);
    let exact_height = paragraph_line_height_for_setup(
      &paragraph,
      &ordinary_style,
      setup,
      TextSegmentation::Body,
      &mut text_metrics,
    );
    assert!((exact_height - 12.0).abs() < 0.01);
  }

  #[test]
  fn repeating_story_measurement_preserves_header_origin_and_footer_flow() {
    let empty_paragraph = || {
      Block::paragraph(Paragraph {
        inlines: Vec::new(),
        field_events: Vec::new(),
        footnote_reference_ids: Vec::new(),
        endnote_reference_ids: Vec::new(),
        starts_after_last_rendered_page_break: false,
        base_style: TextStyle::default(),
        runs: Vec::new(),
        format: Box::new(ParagraphFormat::default()),
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        list_label: None,
        list_label_image: None,
        list_label_style: TextStyle::default(),
        list_label_hyperlink_url: None,
        list_label_tab_stop_pt: None,
      })
    };
    let run = TextRun {
      text: "table".into(),
      style: TextStyle::default(),
      hyperlink_url: None,
      dynamic_field: None,
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      preserve_text_portion: false,
    };
    let mut table_cell_paragraph = empty_paragraph();
    let Block::Paragraph(paragraph) = &mut table_cell_paragraph else {
      unreachable!("default test paragraph is inline")
    };
    paragraph.inlines.push(InlineItem::Text(run.clone()));
    paragraph.runs.push(run);
    let floating_table = Block::Table(Table {
      column_widths_pt: vec![468.0],
      preferred_width_pt: Some(468.0),
      preferred_width_pct: None,
      layout: TableLayoutMode::Fixed,
      indent_left_pt: 0.0,
      alignment: TableAlignment::Left,
      right_to_left: false,
      align_leading_cell_content: false,
      in_header_footer: true,
      placement: Some(FloatingFramePlacement {
        horizontal_anchor: FrameHorizontalAnchor::Page,
        vertical_anchor: FrameVerticalAnchor::Page,
        horizontal_offset_pt: 72.0,
        vertical_offset_pt: 100.0,
        vertical_offset_explicit: true,
        wrap: FrameWrapMode::Around,
        ..Default::default()
      }),
      allow_overlap: true,
      split_allowed: false,
      following_text_flow: false,
      explicit_no_repeat_header: false,
      page_break_before: false,
      starts_after_last_rendered_page_break: false,
      borders: None,
      cell_spacing: TableCellSpacing::Collapsed,
      rows: vec![TableRow {
        cells: vec![TableCell {
          blocks: vec![table_cell_paragraph],
          shading: None,
          borders: CellBordersModel::default(),
          border_suppressions: CellBorderSuppressions::default(),
          margins: CellMargins::zero(),
          preferred_width_pt: Some(468.0),
          preferred_width_pct: None,
          grid_span: 1,
          vertical_merge_continue: false,
          no_wrap: false,
          fit_text: false,
          hide_end_mark: false,
          vertical_alignment: TableCellVerticalAlignment::Top,
          text_rotation_deg: None,
        }],
        height_pt: Some(60.0),
        exact_height: true,
        repeat_header: false,
        keep_with_next: false,
        cant_split: true,
        cell_spacing: None,
        grid_before: 0,
        grid_after: 0,
        width_before_pt: None,
        width_after_pt: None,
        layout: None,
        borders: None,
        spacing_shading: None,
        redline_color: None,
      }],
    });
    let mut blocks = vec![floating_table];
    blocks.extend((0..6).map(|_| empty_paragraph()));
    let setup = PageSetup {
      width_pt: 612.0,
      height_pt: 792.0,
      margin_top_pt: 72.0,
      margin_right_pt: 72.0,
      margin_bottom_pt: 72.0,
      margin_left_pt: 72.0,
      header_distance_pt: 36.0,
      ..Default::default()
    };
    let mut text_metrics = TextMetrics::new();

    let normalized = measured_repeating_blocks_height_at(
      &blocks,
      setup,
      DEFAULT_TAB_STOP_PT,
      &mut text_metrics,
      false,
      0.0,
      12,
    )
    .including_floats_pt;
    let before_fly = measured_repeating_blocks_height_at(
      &blocks,
      setup,
      DEFAULT_TAB_STOP_PT,
      &mut text_metrics,
      false,
      10.0,
      12,
    )
    .including_floats_pt;
    let at_header_origin = measured_header_blocks_height(
      &blocks,
      setup,
      DEFAULT_TAB_STOP_PT,
      &mut text_metrics,
      false,
      12,
    );

    // Translating a short header without reaching the page-anchored fly does
    // not change its measured height. At the real header origin, a later line
    // intersects the full-width table and must continue below its 160pt edge.
    assert!(
      (before_fly - normalized).abs() < 0.01,
      "normalized={normalized}, before_fly={before_fly}, at_header_origin={at_header_origin}",
    );
    assert!(
      at_header_origin > normalized + 40.0,
      "normalized={normalized}, before_fly={before_fly}, at_header_origin={at_header_origin}",
    );
    assert!(
      setup.header_distance_pt + at_header_origin > 160.0,
      "normalized={normalized}, before_fly={before_fly}, at_header_origin={at_header_origin}",
    );

    blocks.truncate(2);
    let anchor_height = measured_footer_positioning_height(
      &blocks[1..],
      setup,
      DEFAULT_TAB_STOP_PT,
      &mut text_metrics,
    );
    for height in [60.0, 120.0] {
      let Block::Table(table) = &mut blocks[0] else {
        unreachable!("test fly is a table")
      };
      table.following_text_flow = true;
      table.placement = Some(FloatingFramePlacement::default());
      table.rows[0].height_pt = Some(height);
      let measured = measured_repeating_blocks_height_at(
        &blocks,
        setup,
        DEFAULT_TAB_STOP_PT,
        &mut text_metrics,
        false,
        0.0,
        12,
      );
      assert!((measured.flow_pt - anchor_height).abs() < 0.01);
      assert!(measured.including_floats_pt >= height);
    }
    let Block::Table(table) = &mut blocks[0] else {
      unreachable!("test fly is a table")
    };
    table.placement = None;
    let inline_height =
      measured_footer_positioning_height(&blocks, setup, DEFAULT_TAB_STOP_PT, &mut text_metrics);
    assert!(inline_height >= anchor_height + 120.0);
  }

  #[test]
