  #[test]
  fn legacy_repeating_text_ignores_drawing_side_wrap_and_preserves_body_obstacle() {
    let setup = PageSetup {
      width_pt: 500.0,
      margin_left_pt: 36.0,
      margin_right_pt: 36.0,
      ..Default::default()
    };
    let paragraph = Paragraph {
      inlines: vec![InlineItem::Text(TextRun {
        text: "Alpha Beta Gamma Delta Epsilon Zeta Eta Theta".into(),
        style: TextStyle::default(),
        hyperlink_url: None,
        dynamic_field: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        preserve_text_portion: false,
      })],
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: TextStyle::default(),
      runs: Vec::new(),
      format: Box::new(ParagraphFormat::default()),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: TextStyle::default(),
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    };
    let drawing = WrapExclusion {
      left_pt: 80.0,
      right_pt: 200.0,
      top_pt: 60.0,
      bottom_pt: 200.0,
      side: ImageWrapSide::BothSides,
      blocks_flow: false,
      uses_contour: true,
      owner: WrapExclusionOwner::Drawing,
    };
    let layout = |flow: FlowContext, obstacle: Option<WrapExclusion>| {
      let mut page = empty_page(setup, 0);
      page.wrap_exclusions.extend(obstacle);
      let mut discarded_pages = Vec::new();
      let mut metrics = TextMetrics::new();
      layout_paragraph(
        &paragraph,
        flow,
        ParagraphLayoutTarget {
          current: &mut page,
          pages: &mut discarded_pages,
          anchor_pages: None,
          text_metrics: &mut metrics,
        },
        72.0,
        72.0,
        0.0,
      );
      assert!(discarded_pages.is_empty());
      let text = page
        .items
        .iter()
        .filter_map(|item| match item {
          PageItem::Text(text) => Some((text.text.clone(), text.x_pt, text.y_pt)),
          _ => None,
        })
        .collect::<Vec<_>>();
      assert!(!text.is_empty());
      assert_eq!(
        page.wrap_exclusions,
        obstacle.into_iter().collect::<Vec<_>>()
      );
      (text, page)
    };
    for compatibility_mode in [12, 14, 15] {
      for segmentation in [
        TextSegmentation::Body,
        TextSegmentation::TableCell,
        TextSegmentation::RepeatingSlot,
        TextSegmentation::FooterSlot,
      ] {
        let flow = FlowContext {
          compatibility_mode,
          text_segmentation: segmentation,
          ..flow_context(
            setup,
            0,
            SectionColumns::default(),
            0,
            0,
            DEFAULT_TAB_STOP_PT,
          )
        };
        let (plain, _) = layout(flow, None);
        let (wrapped, page) = layout(flow, Some(drawing));
        if compatibility_mode < 15 && segmentation.is_repeating_slot() {
          assert_eq!(wrapped, plain);
          let body_flow = FlowContext {
            text_segmentation: TextSegmentation::Body,
            ..flow
          };
          let retained = repeating_story_body_wrap_exclusions(&page.wrap_exclusions);
          let (body, _) = layout(body_flow, retained.first().copied());
          let (plain_body, _) = layout(body_flow, None);
          assert_ne!(body, plain_body);
        } else {
          assert_ne!(wrapped, plain);
        }
        let ordinary_table = WrapExclusion {
          owner: WrapExclusionOwner::FloatingTable,
          ..drawing
        };
        let (around_table, _) = layout(flow, Some(ordinary_table));
        assert_ne!(around_table, plain);
      }
    }
  }

  #[test]
  fn continuous_title_footer_measurement_matches_selected_story() {
    let empty = Block::paragraph(Paragraph {
      inlines: Vec::new(),
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: TextStyle::default(),
      runs: Vec::new(),
      format: Box::new(ParagraphFormat {
        line_height_rule: LineHeightRule::Exact,
        line_height_pt: Some(14.0),
        ..Default::default()
      }),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: TextStyle::default(),
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    });
    let mut document = DocxDocument {
      page: PageSetup {
        margin_top_pt: 28.35,
        header_distance_pt: 22.7,
        ..Default::default()
      },
      page_background_pattern: None,
      page_background_texture: None,
      line_number_style: TextStyle::default(),
      note_separator_style: TextStyle::default(),
      footnote_separator_stories: Default::default(),
      endnote_separator_stories: Default::default(),
      uses_office_recovered_paragraph_defaults: false,
      default_tab_stop_pt: DEFAULT_TAB_STOP_PT,
      hyphenation: crate::docx::HyphenationSettings::default(),
      compatibility_mode: 15,
      justify_lines_with_shrinking: false,
      do_not_expand_shift_return: false,
      suppress_top_spacing: false,
      even_and_odd_headers: false,
      split_page_break_and_paragraph_mark: false,
      form_widgets: Vec::new(),
      sections: Vec::new(),
      header_blocks: vec![empty.clone(); 3],
      footer_blocks: Vec::new(),
      first_header_blocks: Vec::new(),
      first_footer_blocks: Vec::new(),
      footnote_blocks: Vec::new(),
      footnotes: Default::default(),
      footnote_numbering: Vec::new(),
      footnote_positions: Vec::new(),
      endnotes: Default::default(),
      endnote_numbering: Vec::new(),
      endnote_position: w::EndnotePositionValues::DocumentEnd,
      title_page: false,
      blocks: Vec::new(),
    };
    let section = |title_page| crate::docx::ImportedSection {
      break_kind: SectionBreakKind::Continuous,
      discarded_carrier_spacing_after_pt: None,
      section_properties: None,
      page: document.page,
      columns: SectionColumns::default(),
      title_page,
      header_blocks: Vec::new(),
      footer_blocks: vec![empty.clone()],
      first_header_blocks: Vec::new(),
      first_footer_blocks: vec![empty.clone(); 3],
      even_header_blocks: Vec::new(),
      even_footer_blocks: vec![empty.clone(); 2],
      blocks: Vec::new(),
    };
    let mut metrics = TextMetrics::new();
    // Native continuous-section controls: the two titlePg values may differ.
    // The first physical page retains the first section's title-page choice,
    // but a later section's own first page follows that section's titlePg.
    for first_title in [false, true] {
      for later_title in [false, true] {
        document.sections = vec![section(first_title), section(later_title)];
        for even_odd in [false, true] {
          document.even_and_odd_headers = even_odd;
          for (physical, virtual_number, section_page) in [(1, 1, 0), (2, 2, 0), (3, 2, 1)] {
            let page = empty_section_page(document.page, 1, section_page);
            let title = if physical == 1 {
              first_title
            } else {
              later_title
            };
            let expected_lines = if section_page == 0 && title {
              3
            } else if even_odd && virtual_number % 2 == 0 {
              2
            } else {
              1
            };
            let (_, blocks) =
              repeating_slot_blocks_for_page(&document, &page, physical, virtual_number);
            assert_eq!(blocks.len(), expected_lines);
            let slots = repeating_slot_state_for_page(&document, &page, physical, &mut metrics);
            let height =
              repeating_footer_positioning_height_for_page(slots, virtual_number, section_page);
            assert!((height - expected_lines as f32 * 14.0).abs() < 0.01);
          }
        }
      }
    }
  }

  #[test]
  fn empty_header_paragraphs_reserve_space_in_the_selected_story() {
    let empty = Block::paragraph(Paragraph {
      inlines: Vec::new(),
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: TextStyle::default(),
      runs: Vec::new(),
      format: Box::new(ParagraphFormat {
        line_height_rule: LineHeightRule::Exact,
        line_height_pt: Some(14.0),
        ..Default::default()
      }),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: TextStyle::default(),
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    });
    let empty_footer = empty.clone();
    let mut document = DocxDocument {
      page: PageSetup {
        margin_top_pt: 28.35,
        header_distance_pt: 22.7,
        ..Default::default()
      },
      page_background_pattern: None,
      page_background_texture: None,
      line_number_style: TextStyle::default(),
      note_separator_style: TextStyle::default(),
      footnote_separator_stories: Default::default(),
      endnote_separator_stories: Default::default(),
      uses_office_recovered_paragraph_defaults: false,
      default_tab_stop_pt: DEFAULT_TAB_STOP_PT,
      hyphenation: crate::docx::HyphenationSettings::default(),
      compatibility_mode: 15,
      justify_lines_with_shrinking: false,
      do_not_expand_shift_return: false,
      suppress_top_spacing: false,
      even_and_odd_headers: false,
      split_page_break_and_paragraph_mark: false,
      form_widgets: Vec::new(),
      sections: Vec::new(),
      header_blocks: vec![empty.clone(); 3],
      footer_blocks: Vec::new(),
      first_header_blocks: Vec::new(),
      first_footer_blocks: Vec::new(),
      footnote_blocks: Vec::new(),
      footnotes: Default::default(),
      footnote_numbering: Vec::new(),
      footnote_positions: Vec::new(),
      endnotes: Default::default(),
      endnote_numbering: Vec::new(),
      endnote_position: w::EndnotePositionValues::DocumentEnd,
      title_page: false,
      blocks: Vec::new(),
    };
    let mut metrics = TextMetrics::new();
    let slots = repeating_slot_state(&document, 0, &mut metrics);
    assert!(!blocks_have_visible_body_content(&document.header_blocks));
    let (top, _) = body_content_limits_for_page(document.page, slots, 1, 0);
    assert!((top - 64.7).abs() < 0.01);

    // An absent story and a single empty placeholder both suppress the
    // default header. A direction override activates that empty paragraph.
    document.title_page = true;
    let slots = repeating_slot_state(&document, 0, &mut metrics);
    assert_eq!(
      body_content_limits_for_page(document.page, slots, 1, 0).0,
      28.35
    );
    document.first_header_blocks.push(empty);
    let slots = repeating_slot_state(&document, 0, &mut metrics);
    assert_eq!(
      body_content_limits_for_page(document.page, slots, 1, 0).0,
      28.35
    );
    let Block::Paragraph(paragraph) = &mut document.first_header_blocks[0] else {
      unreachable!();
    };
    paragraph.format.bidi_differs_from_style = true;
    let slots = repeating_slot_state(&document, 0, &mut metrics);
    assert!((body_content_limits_for_page(document.page, slots, 1, 0).0 - 36.7).abs() < 0.01);
    assert!((body_content_limits_for_page(document.page, slots, 3, 2).0 - 64.7).abs() < 0.01);

    let Block::Paragraph(paragraph) = &mut document.first_header_blocks[0] else {
      unreachable!();
    };
    paragraph.format.bidi_differs_from_style = false;
    paragraph.inlines.push(InlineItem::Text(TextRun {
      text: " ".to_string(),
      style: TextStyle::default(),
      hyperlink_url: None,
      dynamic_field: None,
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      preserve_text_portion: false,
    }));
    let slots = repeating_slot_state(&document, 0, &mut metrics);
    assert!((body_content_limits_for_page(document.page, slots, 1, 0).0 - 36.7).abs() < 0.01);

    // The same inkless paragraph has a physical footer line frame. Removing
    // its story entirely restores the ordinary bottom margin.
    document.page.height_pt = 792.0;
    document.page.margin_bottom_pt = 48.25;
    document.page.footer_distance_pt = 43.2;
    document.title_page = false;
    let absent = repeating_slot_state(&document, 0, &mut metrics);
    assert!((body_content_limits_for_page(document.page, absent, 1, 0).1 - 743.75).abs() < 0.01);
    document.footer_blocks.push(empty_footer);
    let present = repeating_slot_state(&document, 0, &mut metrics);
    assert!(present.default_footer);
    let (_, body_bottom) = body_content_limits_for_page(document.page, present, 1, 0);
    assert!(
      body_bottom < 743.75,
      "bottom={body_bottom} empty footer height={} title={} first={}",
      present.default_footer_height_pt,
      present.title_page,
      present.first_footer
    );
    assert!((body_bottom - (748.8 - present.default_footer_height_pt)).abs() < 0.01);
  }

