  #[test]
  fn split_paragraph_keeps_early_footnote_on_its_reserved_reference_page() {
    fn run(text: &str, url: Option<&str>) -> TextRun {
      TextRun {
        text: text.into(),
        style: TextStyle::default(),
        hyperlink_url: url.map(str::to_owned),
        dynamic_field: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        preserve_text_portion: false,
      }
    }
    fn paragraph(runs: Vec<TextRun>, ids: Vec<i64>) -> Block {
      Block::paragraph(Paragraph {
        inlines: runs.iter().cloned().map(InlineItem::Text).collect(),
        field_events: Vec::new(),
        footnote_reference_ids: ids,
        endnote_reference_ids: Vec::new(),
        starts_after_last_rendered_page_break: false,
        base_style: TextStyle::default(),
        runs,
        format: Box::new(ParagraphFormat {
          line_height_rule: LineHeightRule::Exact,
          line_height_pt: Some(18.0),
          widow_control: Some(false),
          ..Default::default()
        }),
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        list_label: None,
        list_label_image: None,
        list_label_style: TextStyle::default(),
        list_label_hyperlink_url: None,
        list_label_tab_stop_pt: None,
      })
    }
    let mut near_boundary_template = None;
    for (prefix_lines, expected_page, note_lines, preceding_lines, note_line_height) in [
      (0, 0, 1, 0, 18.0),
      (11, 1, 1, 0, 18.0),
      (18, 1, 1, 0, 18.0),
      (11, 1, 2, 0, 18.0),
      (11, 1, 3, 0, 18.0),
      (11, 1, 3, 5, 18.0),
      (11, 1, 1, 1, 18.0),
      (11, 1, 3, 0, 30.0),
      (11, 1, 3, 0, 6.0),
    ] {
      let body = paragraph(
        vec![
          run(
            &format!("{}FIRST", "PREFIX\n".repeat(prefix_lines - preceding_lines)),
            None,
          ),
          run("1", Some("ooxmlsdk-pdf:footnote-reference:8")),
          run(&"\nFOLLOW".repeat(27 - prefix_lines), None),
        ],
        vec![8],
      );
      let mut note = paragraph(
        vec![run(
          &vec!["NOTE"; note_lines].join("\n"),
          Some("ooxmlsdk-pdf:footnote-backlink:8"),
        )],
        Vec::new(),
      );
      if let Block::Paragraph(note) = &mut note {
        note.format.line_height_pt = Some(note_line_height);
      }
      let mut blocks = Vec::new();
      if preceding_lines > 0 {
        blocks.push(paragraph(
          vec![run(&vec!["PREFIX"; preceding_lines].join("\n"), None)],
          Vec::new(),
        ));
      }
      blocks.push(body);
      let document = DocxDocument {
        page: PageSetup {
          width_pt: 360.0,
          height_pt: 300.0,
          margin_top_pt: 36.0,
          margin_bottom_pt: 36.0,
          margin_left_pt: 36.0,
          margin_right_pt: 36.0,
          ..Default::default()
        },
        page_background_pattern: None,
        page_background_texture: None,
        line_number_style: TextStyle::default(),
        note_separator_style: TextStyle::default(),
        footnote_separator_stories: crate::docx::NoteSeparatorStories {
          separator: vec![paragraph(vec![run("SEPARATOR", None)], Vec::new())],
          ..Default::default()
        },
        endnote_separator_stories: Default::default(),
        uses_office_recovered_paragraph_defaults: false,
        default_tab_stop_pt: DEFAULT_TAB_STOP_PT,
        hyphenation: crate::docx::HyphenationSettings::default(),
        compatibility_mode: 15,
        justify_lines_with_shrinking: false,
        do_not_expand_shift_return: false,
        suppress_top_spacing: false,
        even_and_odd_headers: false,
        split_page_break_and_paragraph_mark: false,
        form_widgets: Vec::new(),
        sections: Vec::new(),
        header_blocks: Vec::new(),
        footer_blocks: Vec::new(),
        first_header_blocks: Vec::new(),
        first_footer_blocks: Vec::new(),
        footnote_blocks: Vec::new(),
        footnotes: [(8, vec![note])].into_iter().collect(),
        footnote_numbering: Vec::new(),
        footnote_positions: Vec::new(),
        endnotes: Default::default(),
        endnote_numbering: Vec::new(),
        endnote_position: w::EndnotePositionValues::DocumentEnd,
        title_page: false,
        blocks,
      };
      if prefix_lines == 0 {
        near_boundary_template = Some(document.clone());
      }
      let mut metrics = TextMetrics::new();
      let flow = flow_context(
        document.page,
        0,
        SectionColumns::default(),
        0,
        0,
        DEFAULT_TAB_STOP_PT,
      );
      let emitted = HashSet::default();
      let reserved = footnote_boss_reserve(
        &document.blocks[0],
        &document,
        &emitted,
        &[],
        &empty_page(flow.setup, 0),
        flow,
        &mut metrics,
      );
      let replayed = footnote_boss_reserve(
        &document.blocks[0],
        &document,
        &emitted,
        &[],
        &empty_page(flow.setup, 0),
        reserved,
        &mut metrics,
      );
      assert_eq!(reserved.content_bottom, replayed.content_bottom);
      assert_eq!(replayed.body_content_bottom_pt, flow.body_content_bottom_pt);
      let mut first_pass = RootFrameLayout::new(&document, &LayoutOptions::default());
      first_pass.format_body_frames();
      first_pass.finish_current_page();
      let body_lines = |page: &Page| {
        page
          .items
          .iter()
          .filter(|item| matches!(item, PageItem::Text(text) if text.text == "FOLLOW"))
          .count()
      };
      let initial_lines = first_pass.pages.iter().map(body_lines).collect::<Vec<_>>();
      let result = RootFrameLayout::new(&document, &LayoutOptions::default()).format();
      assert_eq!(
        result.pages.iter().map(body_lines).collect::<Vec<_>>(),
        initial_lines
      );
      assert!(result.pages.len() > 1);
      if prefix_lines == 11 {
        let body_lines_on_first_page = result.pages[0]
          .items
          .iter()
          .filter(|item| {
            matches!(item, PageItem::Text(text) if matches!(text.text.as_str(), "PREFIX" | "FIRST" | "FOLLOW"))
          })
          .count();
        assert_eq!(
          body_lines_on_first_page,
          if preceding_lines > 0 || note_line_height == 6.0 {
            11
          } else {
            10
          }
        );
      }
      let page_for = |url: &str| {
        result.pages.iter().position(|page| {
          page.items.iter().any(
          |item| matches!(item, PageItem::Text(text) if text.hyperlink_url.as_deref() == Some(url)),
        )
        })
      };
      assert_eq!(
        page_for("ooxmlsdk-pdf:footnote-reference:8"),
        Some(expected_page)
      );
      assert_eq!(
        page_for("ooxmlsdk-pdf:footnote-backlink:8"),
        Some(expected_page)
      );
      assert!(result.pages[expected_page].footnote_reserved_height_pt > 0.0);
      assert!(
        result
          .pages
          .iter()
          .enumerate()
          .filter(|(page_index, _)| *page_index != expected_page)
          .all(|(_, page)| page.footnote_reserved_height_pt == 0.0)
      );
    }

    // The two callouts in the later paragraph straddle the page boundary.
    // Reserving both notes up front pushes the first callout forward, but its
    // complete one-line note fits on the first page once ownership is split.
    let mut document = near_boundary_template.unwrap();
    document.blocks = vec![
      paragraph(
        vec![
          run("EARLY", None),
          run("1", Some("ooxmlsdk-pdf:footnote-reference:8")),
        ],
        vec![8],
      ),
      paragraph(
        vec![
          run(&format!("{}FIRST", "PREFIX\n".repeat(7)), None),
          run("2", Some("ooxmlsdk-pdf:footnote-reference:9")),
          run("\nMIDDLE\nMIDDLE\n", None),
          run("3", Some("ooxmlsdk-pdf:footnote-reference:10")),
          run(&"\nTAIL".repeat(15), None),
        ],
        vec![9, 10],
      ),
    ];
    document.footnotes = [8, 9, 10]
      .into_iter()
      .map(|id| {
        (
          id,
          vec![paragraph(
            vec![run(
              "NOTE",
              Some(&format!("ooxmlsdk-pdf:footnote-backlink:{id}")),
            )],
            Vec::new(),
          )],
        )
      })
      .collect();
    let result = RootFrameLayout::new(&document, &LayoutOptions::default()).format();
    let page_for = |url: &str| {
      result.pages.iter().position(|page| {
        page.items.iter().any(
          |item| matches!(item, PageItem::Text(text) if text.hyperlink_url.as_deref() == Some(url)),
        )
      })
    };
    for (id, page) in [(8, 0), (9, 0), (10, 1)] {
      assert_eq!(
        page_for(&format!("ooxmlsdk-pdf:footnote-reference:{id}")),
        Some(page),
        "callout {id}"
      );
      assert_eq!(
        page_for(&format!("ooxmlsdk-pdf:footnote-backlink:{id}")),
        Some(page),
        "note {id}"
      );
    }

    // Native keepNext controls distinguish an early note that displaces every
    // body line from a late note that leaves a legal prefix beside the heading.
    // Validate replay ownership as well as the absence of duplicated headings,
    // separator stories, callouts and backlinks. Authored breaks take priority.
    for heading_count in 1..=3 {
      for keep in [false, true] {
        for owner in ["none", "early", "late"] {
          for forced in [false, true] {
            let mut kept_document = document.clone();
            let mut blocks = vec![paragraph(
              vec![run(&vec!["FILLER"; 8 - heading_count].join("\n"), None)],
              Vec::new(),
            )];
            for heading_index in 0..heading_count {
              let mut heading = paragraph(
                vec![run(&format!("HEADING{heading_index}"), None)],
                Vec::new(),
              );
              if let Block::Paragraph(heading) = &mut heading {
                heading.format.keep_with_next = keep;
              }
              blocks.push(heading);
            }
            let callout = run("1", Some("ooxmlsdk-pdf:footnote-reference:8"));
            let mut body_runs = vec![run("BODY", None)];
            if owner == "early" {
              body_runs.push(callout.clone());
            }
            body_runs.push(run(&"\nTAIL".repeat(7), None));
            if owner == "late" {
              body_runs.push(callout);
            }
            let mut body = paragraph(
              body_runs,
              if owner == "none" { Vec::new() } else { vec![8] },
            );
            if let Block::Paragraph(body) = &mut body {
              body.format.page_break_before = forced;
            }
            blocks.push(body);
            kept_document.blocks = blocks;
            let mut kept_note = paragraph(
              vec![run(
                "NOTE\nNOTE\nNOTE",
                Some("ooxmlsdk-pdf:footnote-backlink:8"),
              )],
              Vec::new(),
            );
            if let Block::Paragraph(note) = &mut kept_note {
              note.format.keep_lines = true;
            }
            kept_document.footnotes = [(8, vec![kept_note])].into_iter().collect();
            let kept = RootFrameLayout::new(&kept_document, &LayoutOptions::default()).format();
            for heading_index in 0..heading_count {
              let heading_text = format!("HEADING{heading_index}");
              let heading_pages = kept
                .pages
                .iter()
                .enumerate()
                .flat_map(|(page_index, page)| {
                  let heading_text = &heading_text;
                  page.items.iter().filter_map(move |item| {
                    matches!(item, PageItem::Text(text) if text.text == *heading_text)
                      .then_some(page_index)
                  })
                })
                .collect::<Vec<_>>();
              assert_eq!(
                heading_pages,
                vec![usize::from(keep && owner == "early" && !forced)],
                "headings={heading_count}, keep={keep}, owner={owner}, forced={forced}",
              );
            }
            let body_page = kept.pages.iter().position(|page| {
              page
                .items
                .iter()
                .any(|item| matches!(item, PageItem::Text(text) if text.text == "BODY"))
            });
            assert_eq!(body_page, Some(usize::from(owner == "early" || forced)));
            let reference_pages = kept
              .pages
              .iter()
              .enumerate()
              .flat_map(|(page_index, page)| {
                page.items.iter().filter_map(move |item| {
                  matches!(item, PageItem::Text(text)
                  if text.hyperlink_url.as_deref() == Some("ooxmlsdk-pdf:footnote-reference:8"))
                  .then_some(page_index)
                })
              })
              .collect::<Vec<_>>();
            assert_eq!(reference_pages.len(), usize::from(owner != "none"));
            if owner != "none" {
              let note_pages = kept
                .pages
                .iter()
                .enumerate()
                .filter_map(|(page_index, page)| {
                  page
                    .items
                    .iter()
                    .any(|item| {
                      matches!(item, PageItem::Text(text)
                  if text.hyperlink_url.as_deref() == Some("ooxmlsdk-pdf:footnote-backlink:8"))
                    })
                    .then_some(page_index)
                })
                .collect::<Vec<_>>();
              assert_eq!(note_pages, reference_pages);
            }
          }
        }
      }
    }
  }

  #[test]
  fn note_auto_spacing_uses_each_lines_font_box() {
    let ordinary = TextStyle {
      font_family: Some(Arc::from("Times New Roman")),
      font_size_pt: 10.0,
      use_windows_font_metrics: true,
      ..Default::default()
    };
    let reference = TextStyle {
      font_size_pt: 8.0,
      automatic_escapement_font_size_pt: Some(12.0),
      baseline_shift_pt: 3.96,
      ..ordinary.clone()
    };
    let runs = [
      ("1", reference.clone()),
      ("Example\nSecond\nThird", ordinary.clone()),
    ]
    .into_iter()
    .map(|(text, style)| TextRun {
      text: text.into(),
      style,
      hyperlink_url: None,
      dynamic_field: None,
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      preserve_text_portion: false,
    })
    .collect::<Vec<_>>();
    let paragraph = Paragraph {
      inlines: runs.iter().cloned().map(InlineItem::Text).collect(),
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: ordinary.clone(),
      runs,
      format: Box::new(ParagraphFormat::default()),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: ordinary.clone(),
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    };
    let flow = note_story_flow(flow_context(
      PageSetup::default(),
      0,
      SectionColumns::default(),
      0,
      0,
      DEFAULT_TAB_STOP_PT,
    ));
    let mut metrics = TextMetrics::new();
    let first_height = metrics
      .line_vertical_metrics_for_text("1", &reference)
      .line_height_pt();
    let following_height = metrics
      .line_vertical_metrics_for_text("Example", &ordinary)
      .line_height_pt();
    assert!(first_height > following_height);
    let expected = first_height + 2.0 * following_height;
    let mut page = empty_page(flow.setup, flow.section_index);
    let mut pages = Vec::new();
    let (_, bottom) = layout_paragraph(
      &paragraph,
      flow,
      ParagraphLayoutTarget {
        current: &mut page,
        pages: &mut pages,
        anchor_pages: None,
        text_metrics: &mut metrics,
      },
      flow.content_top_pt,
      flow.content_top_pt,
      0.0,
    );
    assert!(pages.is_empty());
    assert!((bottom - flow.content_top_pt - expected).abs() < LAYOUT_EPSILON_PT);
    let reserved = measured_note_blocks_height(&[Block::paragraph(paragraph)], flow, &mut metrics);
    assert!((reserved - expected).abs() < LAYOUT_EPSILON_PT);
  }

  #[test]
  fn text_owned_auto_continuations_fit_their_measured_font_boxes() {
    // Native stress008's short note switches from Times New Roman to
    // Microsoft Sans Serif. Its measured last line fits exactly; the larger
    // initial font must not manufacture an extra physical page.
    for segmentation in [TextSegmentation::Body, TextSegmentation::Notes] {
      for next_size in [8.0, 10.0, 12.0] {
        let first_style = TextStyle {
          font_family: Some(Arc::from("Times New Roman")),
          font_size_pt: 10.0,
          use_windows_font_metrics: true,
          ..Default::default()
        };
        let runs = [
          ("1 first ", first_style.clone()),
          (
            "A following font supplies several complete lines of ordinary text for this note.",
            TextStyle {
              font_family: Some(Arc::from("Microsoft Sans Serif")),
              font_size_pt: next_size,
              ..first_style.clone()
            },
          ),
        ]
        .into_iter()
        .map(|(text, style)| TextRun {
          text: text.into(),
          style,
          hyperlink_url: None,
          dynamic_field: None,
          style_ref_keys: Vec::new(),
          style_ref_text: None,
          style_ref_numbering_text: None,
          preserve_text_portion: false,
        })
        .collect::<Vec<_>>();
        let paragraph = Paragraph {
          inlines: runs.iter().cloned().map(InlineItem::Text).collect(),
          field_events: Vec::new(),
          footnote_reference_ids: Vec::new(),
          endnote_reference_ids: Vec::new(),
          starts_after_last_rendered_page_break: false,
          base_style: first_style.clone(),
          runs,
          format: Box::new(ParagraphFormat {
            line_height_pt: Some(1.0),
            line_height_set: true,
            ..Default::default()
          }),
          style_ref_keys: Vec::new(),
          style_ref_text: None,
          style_ref_numbering_text: None,
          list_label: None,
          list_label_image: None,
          list_label_style: first_style,
          list_label_hyperlink_url: None,
          list_label_tab_stop_pt: None,
        };
        let setup = PageSetup {
          width_pt: 120.0,
          height_pt: 400.0,
          margin_left_pt: 10.0,
          margin_right_pt: 10.0,
          margin_top_pt: 10.0,
          margin_bottom_pt: 10.0,
          ..Default::default()
        };
        let flow = FlowContext {
          text_segmentation: segmentation,
          ..flow_context(
            setup,
            0,
            SectionColumns::default(),
            0,
            0,
            DEFAULT_TAB_STOP_PT,
          )
        };
        let mut metrics = TextMetrics::new();
        let reserved =
          measured_note_blocks_height(&[Block::paragraph(paragraph.clone())], flow, &mut metrics);
        for short_by in [0.0, 1.0] {
          let mut page = empty_page(setup, 0);
          let mut pages = Vec::new();
          let y = flow.content_bottom - reserved + short_by;
          let (_, bottom) = layout_paragraph(
            &paragraph,
            flow,
            ParagraphLayoutTarget {
              current: &mut page,
              pages: &mut pages,
              anchor_pages: None,
              text_metrics: &mut metrics,
            },
            y,
            y,
            0.0,
          );
          if short_by == 0.0 {
            assert!(
              pages.is_empty(),
              "{segmentation:?} following size {next_size}"
            );
            assert!((bottom - flow.content_bottom).abs() < LAYOUT_EPSILON_PT);
          } else {
            assert!(
              !pages.is_empty(),
              "{segmentation:?} following size {next_size}: an overfull final line still advances"
            );
          }
        }
      }
    }
  }

  #[test]
  fn footnote_reservation_uses_measured_wrapped_note_height() {
    let flow = flow_context(
      PageSetup {
        width_pt: 120.0,
        height_pt: 400.0,
        margin_left_pt: 10.0,
        margin_right_pt: 10.0,
        margin_top_pt: 10.0,
        margin_bottom_pt: 10.0,
        ..Default::default()
      },
      0,
      SectionColumns::default(),
      0,
      0,
      DEFAULT_TAB_STOP_PT,
    );
    let run = TextRun {
      text: "A long footnote body wraps into several lines when measured.".into(),
      style: TextStyle::default(),
      hyperlink_url: None,
      dynamic_field: None,
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      preserve_text_portion: false,
    };
    let blocks = vec![Block::paragraph(Paragraph {
      inlines: vec![InlineItem::Text(run.clone())],
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: TextStyle::default(),
      #[cfg(test)]
      runs: vec![run],
      format: Box::new(ParagraphFormat::default()),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: TextStyle::default(),
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    })];

    let mut text_metrics = TextMetrics::new();
    let measured = measured_note_blocks_height(&blocks, flow, &mut text_metrics);
    let estimated = blocks
      .iter()
      .map(|block| estimated_block_height(block, flow, &mut text_metrics))
      .sum::<f32>();

    assert!(measured > DEFAULT_LINE_HEIGHT_PT);
    assert!((measured - estimated).abs() < DEFAULT_LINE_HEIGHT_PT * 2.0);
  }

  #[test]
  fn legacy_footnote_lower_spacing_can_be_reclaimed_without_losing_note_lines() {
    fn run(text: &str, url: Option<&str>) -> TextRun {
      TextRun {
        text: text.into(),
        style: TextStyle {
          use_windows_font_metrics: true,
          wordprocessingml_font_slots: true,
          ..Default::default()
        },
        hyperlink_url: url.map(str::to_owned),
        dynamic_field: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        preserve_text_portion: false,
      }
    }
    fn paragraph(runs: Vec<TextRun>, ids: Vec<i64>) -> Block {
      Block::paragraph(Paragraph {
        inlines: runs.iter().cloned().map(InlineItem::Text).collect(),
        field_events: Vec::new(),
        footnote_reference_ids: ids,
        endnote_reference_ids: Vec::new(),
        starts_after_last_rendered_page_break: false,
        base_style: TextStyle::default(),
        runs,
        format: Box::new(ParagraphFormat {
          line_height_rule: LineHeightRule::Exact,
          line_height_pt: Some(18.0),
          widow_control: Some(false),
          ..Default::default()
        }),
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        list_label: None,
        list_label_image: None,
        list_label_style: TextStyle::default(),
        list_label_hyperlink_url: None,
        list_label_tab_stop_pt: None,
      })
    }

    // Native mode 12/14/15 × LTR/RTL controls distinguish complete placement
    // from the minimum height needed to retain the callout and its note.
    for mode in [12, 14, 15] {
      for bidi in [false, true] {
        for note_after in [0.0, 3.0, 10.0] {
          for body_after in [0.0, 6.0, 12.0] {
            let mut prefix = paragraph(vec![run("PREFIX", None)], Vec::new());
            let mut body = paragraph(
              vec![
                run("A\nB", None),
                run("1", Some("ooxmlsdk-pdf:footnote-reference:8")),
              ],
              vec![8],
            );
            let mut separator = paragraph(Vec::new(), Vec::new());
            let Block::Paragraph(separator_paragraph) = &mut separator else {
              unreachable!()
            };
            separator_paragraph
              .inlines
              .push(InlineItem::NoteSeparatorMark(NoteSeparatorMark {
                continuation: false,
                style: TextStyle {
                  font_family: Some("Times New Roman".into()),
                  font_size_pt: 10.0,
                  use_windows_font_metrics: true,
                  wordprocessingml_font_slots: true,
                  ..Default::default()
                },
              }));
            let mut note = paragraph(
              vec![run("NOTE", Some("ooxmlsdk-pdf:footnote-backlink:8"))],
              Vec::new(),
            );
            for (block, height, after, size) in [
              (&mut prefix, 170.0, 0.0, 12.0),
              (&mut body, 14.0, body_after, 12.0),
              (&mut separator, 9.0, 0.0, 10.0),
              (&mut note, 15.0, note_after, 10.0),
            ] {
              let Block::Paragraph(paragraph) = block else {
                unreachable!()
              };
              paragraph.format.line_height_pt = Some(height);
              paragraph.format.spacing_after_pt = after;
              paragraph.format.bidi = bidi;
              paragraph.base_style.font_family = Some("Times New Roman".into());
              paragraph.base_style.font_size_pt = size;
              for inline in &mut paragraph.inlines {
                if let InlineItem::Text(run) = inline {
                  run.style.font_family = Some("Times New Roman".into());
                  run.style.font_size_pt = size;
                }
              }
            }
            let Block::Paragraph(body_paragraph) = &mut body else {
              unreachable!()
            };
            for inline in &mut body_paragraph.inlines {
              if let InlineItem::Text(run) = inline
                && run.hyperlink_url.as_deref() == Some("ooxmlsdk-pdf:footnote-reference:8")
              {
                crate::docx::properties::apply_vertical_text_alignment(
                  &mut run.style,
                  w::VerticalPositionValues::Superscript,
                );
              }
            }
            let blocks = vec![prefix, body];
            let document = DocxDocument {
              page: PageSetup {
                width_pt: 360.0,
                height_pt: 300.0,
                margin_top_pt: 36.0,
                margin_bottom_pt: 36.0,
                margin_left_pt: 36.0,
                margin_right_pt: 36.0,
                ..Default::default()
              },
              page_background_pattern: None,
              page_background_texture: None,
              line_number_style: TextStyle::default(),
              note_separator_style: TextStyle::default(),
              footnote_separator_stories: crate::docx::NoteSeparatorStories {
                separator: vec![separator],
                ..Default::default()
              },
              endnote_separator_stories: Default::default(),
              uses_office_recovered_paragraph_defaults: false,
              default_tab_stop_pt: DEFAULT_TAB_STOP_PT,
              hyphenation: crate::docx::HyphenationSettings::default(),
              compatibility_mode: mode,
              justify_lines_with_shrinking: false,
              do_not_expand_shift_return: false,
              suppress_top_spacing: false,
              even_and_odd_headers: false,
              split_page_break_and_paragraph_mark: false,
              form_widgets: Vec::new(),
              sections: Vec::new(),
              header_blocks: Vec::new(),
              footer_blocks: Vec::new(),
              first_header_blocks: Vec::new(),
              first_footer_blocks: Vec::new(),
              footnote_blocks: Vec::new(),
              footnotes: [(8, vec![note])].into_iter().collect(),
              footnote_numbering: Vec::new(),
              footnote_positions: Vec::new(),
              endnotes: Default::default(),
              endnote_numbering: Vec::new(),
              endnote_position: w::EndnotePositionValues::DocumentEnd,
              title_page: false,
              blocks,
            };

            let result = RootFrameLayout::new(&document, &LayoutOptions::default()).format();
            let must_follow = body_after > 6.0 || (mode >= 15 && note_after + body_after > 6.0);
            let expected_page = usize::from(must_follow);
            let note_page = result
              .pages
              .iter()
              .position(|page| {
                page
                  .items
                  .iter()
                  .any(|item| matches!(item, PageItem::Text(text) if text.text == "NOTE"))
              })
              .unwrap();
            let callout_page=result.pages.iter().position(|page| page.items.iter().any(|item| matches!(item, PageItem::Text(text) if text.hyperlink_url.as_deref()==Some("ooxmlsdk-pdf:footnote-reference:8")))).unwrap();
            assert_eq!(
              note_page, expected_page,
              "mode={mode} bidi={bidi} note_after={note_after} body_after={body_after}"
            );
            assert_eq!(callout_page, note_page);
            assert_eq!(
              result
                .pages
                .iter()
                .flat_map(|page| &page.items)
                .filter(|item| matches!(item,PageItem::Text(text) if text.text == "NOTE"))
                .count(),
              1
            );
            let page = &result.pages[note_page];
            assert!((page.footnote_reserved_height_pt - (24.0 + note_after)).abs() < 0.01);
            let reclaimed = if mode < 15 { note_after } else { 0.0 };
            assert_eq!(page.footnote_reclaimable_spacing_after_pt, reclaimed);
            if !must_follow {
              let normal_top = 264.0 - 24.0 - note_after;
              let expected_top = normal_top.max(234.0 + body_after);
              assert!((page.footnote_area_top_pt.unwrap() - expected_top).abs() < 0.01);
            }
            let mut restored = page.clone();
            let checkpoint = page_checkpoint(&restored);
            restored.footnote_reclaimable_spacing_after_pt = 0.0;
            restore_page_checkpoint(&mut restored, checkpoint);
            assert_eq!(restored.footnote_reclaimable_spacing_after_pt, reclaimed);

            if mode < 15 && note_after == 3.0 && body_after == 6.0 {
              // Native identical geometry, but with the callout in PREFIX:
              // later body-after spacing leaves the note at its normal top.
              let mut earlier_reference = document.clone();
              let Block::Paragraph(owner) = &mut earlier_reference.blocks[1] else {
                unreachable!()
              };
              let reference = owner.inlines.pop().unwrap();
              let reference_run = owner.runs.pop().unwrap();
              owner.footnote_reference_ids.clear();
              let Block::Paragraph(prefix) = &mut earlier_reference.blocks[0] else {
                unreachable!()
              };
              prefix.inlines.push(reference);
              prefix.runs.push(reference_run);
              prefix.footnote_reference_ids.push(8);
              let earlier =
                RootFrameLayout::new(&earlier_reference, &LayoutOptions::default()).format();
              assert_eq!(earlier.pages.len(), 1);
              assert!((earlier.pages[0].footnote_area_top_pt.unwrap() - 237.0).abs() < 0.01);
            }

            if body_after == 0.0 {
              // Native mode 12/14/15 × LTR/RTL × note-after 0/3/10 controls:
              // the earlier callout stays, but a separate following paragraph
              // cannot reclaim the note's blank lower space for another line.
              let mut following_document = document.clone();
              let Block::Paragraph(prefix) = &mut following_document.blocks[0] else {
                unreachable!()
              };
              prefix.format.line_height_pt = Some(168.0);
              let Block::Paragraph(owner) = &mut following_document.blocks[1] else {
                unreachable!()
              };
              let InlineItem::Text(owner_text) = &mut owner.inlines[0] else {
                unreachable!()
              };
              owner_text.text = "OWNER".into();
              let mut follower =
                paragraph(vec![run("FOLLOW0\nFOLLOW1\nFOLLOW2", None)], Vec::new());
              let Block::Paragraph(follower_paragraph) = &mut follower else {
                unreachable!()
              };
              follower_paragraph.format.line_height_pt = Some(14.0);
              follower_paragraph.format.bidi = bidi;
              for inline in &mut follower_paragraph.inlines {
                if let InlineItem::Text(run) = inline {
                  run.style.font_family = Some("Times New Roman".into());
                  run.style.font_size_pt = 12.0;
                }
              }
              following_document.blocks.push(follower);
              let following =
                RootFrameLayout::new(&following_document, &LayoutOptions::default()).format();
              assert_eq!(
                following.pages[0]
                  .items
                  .iter()
                  .filter(
                    |item| matches!(item, PageItem::Text(text) if text.text.starts_with("FOLLOW"))
                  )
                  .count(),
                usize::from(note_after <= 3.0),
                "following mode={mode} bidi={bidi} note_after={note_after}"
              );
              assert!(
                following.pages[0]
                  .items
                  .iter()
                  .any(|item| { matches!(item, PageItem::Text(text) if text.text == "NOTE") })
              );
              assert_eq!(
                following
                  .pages
                  .iter()
                  .flat_map(|page| &page.items)
                  .filter(
                    |item| matches!(item, PageItem::Text(text) if text.text.starts_with("FOLLOW"))
                  )
                  .count(),
                3
              );
              let mut same_paragraph_document = following_document.clone();
              let Block::Paragraph(follower) = same_paragraph_document.blocks.remove(2) else {
                unreachable!()
              };
              let Block::Paragraph(owner) = &mut same_paragraph_document.blocks[1] else {
                unreachable!()
              };
              owner.inlines.push(InlineItem::Text(run("\n", None)));
              owner.inlines.extend(follower.inlines);
              owner.runs = owner
                .inlines
                .iter()
                .filter_map(|inline| match inline {
                  InlineItem::Text(run) => Some(run.clone()),
                  _ => None,
                })
                .collect();
              let same_paragraph =
                RootFrameLayout::new(&same_paragraph_document, &LayoutOptions::default()).format();
              // Native same-paragraph controls give the same legal follower
              // ownership as a separate paragraph, including note-after10.
              assert_eq!(
                same_paragraph.pages[0]
                  .items
                  .iter()
                  .filter(
                    |item| matches!(item, PageItem::Text(text) if text.text.starts_with("FOLLOW"))
                  )
                  .count(),
                usize::from(note_after <= 3.0),
                "same paragraph mode={mode} bidi={bidi} note_after={note_after}"
              );
              assert_eq!(
                same_paragraph
                  .pages
                  .iter()
                  .flat_map(|page| &page.items)
                  .filter(
                    |item| matches!(item, PageItem::Text(text) if text.text.starts_with("FOLLOW"))
                  )
                  .count(),
                3
              );
            }
          }
        }
      }
    }
  }

  #[test]
  fn footnote_measurement_preserves_story_spacing_and_collapses_adjacent_notes() {
    let flow = FlowContext {
      paragraph_spacing_context: ParagraphSpacingContext::SectionStart,
      ..flow_context(
        PageSetup {
          width_pt: 240.0,
          height_pt: 400.0,
          margin_left_pt: 10.0,
          margin_right_pt: 10.0,
          margin_top_pt: 10.0,
          margin_bottom_pt: 10.0,
          ..Default::default()
        },
        0,
        SectionColumns::default(),
        0,
        0,
        DEFAULT_TAB_STOP_PT,
      )
    };
    let run = TextRun {
      text: "Footnote".into(),
      style: TextStyle::default(),
      hyperlink_url: None,
      dynamic_field: None,
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      preserve_text_portion: false,
    };
    let automatic = vec![Block::paragraph(Paragraph {
      inlines: vec![InlineItem::Text(run.clone())],
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: TextStyle::default(),
      #[cfg(test)]
      runs: vec![run],
      format: Box::new(ParagraphFormat {
        spacing_before_auto: Some(true),
        spacing_before_auto_pt: Some(super::super::OFFICE_AUTOMATIC_PARAGRAPH_SPACING_PT),
        spacing_after_auto: Some(true),
        spacing_after_auto_pt: Some(super::super::OFFICE_AUTOMATIC_PARAGRAPH_SPACING_PT),
        ..Default::default()
      }),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: TextStyle::default(),
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    })];
    let mut ordinary = automatic.clone();
    let Block::Paragraph(paragraph) = &mut ordinary[0] else {
      unreachable!("test note is a paragraph")
    };
    paragraph.format.spacing_before_auto = Some(false);
    paragraph.format.spacing_before_auto_pt = None;

    let mut text_metrics = TextMetrics::new();
    let automatic_height = measured_note_blocks_height(&automatic, flow, &mut text_metrics);
    let ordinary_height = measured_note_blocks_height(&ordinary, flow, &mut text_metrics);
    let adjacent_height = measured_note_stories_height(
      &[automatic.as_slice(), automatic.as_slice()],
      None,
      flow,
      &mut text_metrics,
    );

    assert_eq!(
      note_story_flow(flow).text_segmentation,
      TextSegmentation::Notes
    );
    assert_eq!(
      note_story_flow(flow).paragraph_spacing_context,
      ParagraphSpacingContext::Normal
    );
    assert!(
      (automatic_height - ordinary_height - super::super::OFFICE_AUTOMATIC_PARAGRAPH_SPACING_PT)
        .abs()
        < LAYOUT_EPSILON_PT
    );
    assert!(
      (automatic_height * 2.0
        - adjacent_height
        - super::super::OFFICE_AUTOMATIC_PARAGRAPH_SPACING_PT)
        .abs()
        < LAYOUT_EPSILON_PT
    );
  }

  #[test]
  fn note_separator_uses_run_strikeout_metrics_and_fill_color() {
    let mut metrics = TextMetrics::new();
    for (family, size, expected) in [
      ("Arial", 10.0, 0.48),
      ("Arial", 18.0, 0.84),
      ("Calibri", 12.0, 0.84),
      ("Calibri", 18.0, 1.2),
    ] {
      let color = RgbColor { r: 255, g: 0, b: 0 };
      let mark = NoteSeparatorMark {
        continuation: false,
        style: TextStyle {
          font_family: Some(Arc::from(family)),
          font_size_pt: size,
          color,
          ..TextStyle::default()
        },
      };
      let mut page = empty_page(PageSetup::default(), 0);
      push_note_separator_mark(&mut page, &mark, 42.0, 20.0, 144.0, 14.0, &mut metrics);
      let [PageItem::Rect(rule)] = page.items.as_slice() else {
        panic!("a filled separator without an additional perimeter stroke");
      };
      assert!((rule.height_pt - expected).abs() < 0.001, "{family} {size}");
      assert_eq!(rule.fill_color, Some(color));
      assert!(rule.stroke.is_none());
    }
  }

  #[test]
  fn overflowing_rtl_line_preserves_its_leading_right_edge() {
    let mut metrics = TextMetrics::new();
    let style = TextStyle {
      font_family: Some(Arc::from("Arial")),
      font_size_pt: 12.0,
      right_to_left: Some(true),
      resolved_bidi_level: Some(1),
      ..TextStyle::default()
    };
    let text = "قبل بعد ";
    let width = metrics.measure_text(text, &style);
    let mut item = text_warp_bounds_test_item(12.0);
    item.text = text.to_string();
    item.style = style;
    item.x_pt = 20.0;
    item.y_pt = 20.0;
    item.paragraph_bidi = true;
    let mut items = vec![PageItem::Text(Box::new(item))];
    let right = 20.0 + width - 2.0;
    align_paragraph_items(&mut items, ParagraphAlignment::Right, &mut metrics, right);
    let PageItem::Text(text) = &items[0] else {
      panic!()
    };
    assert!((text.x_pt + width - right).abs() < 0.001);
  }

  #[test]
  fn ordinary_note_separator_is_two_inches_wide() {
    let setup = PageSetup {
      width_pt: 612.0,
      margin_left_pt: 72.0,
      margin_right_pt: 72.0,
      ..Default::default()
    };
    for kind in [NoteSeparatorKind::Footnote, NoteSeparatorKind::Endnote] {
      let mut page = empty_page(setup, 0);

      add_note_separator_line(kind, setup, &mut page, 20.0);

      let [PageItem::Line(line)] = page.items.as_slice() else {
        panic!("note separator line");
      };
      assert_eq!(line.x1_pt, 72.0);
      assert_eq!(line.x2_pt, 216.0);
    }
  }

  #[test]
  fn adjacent_border_priority_matches_writer_width_then_compound_rule() {
    fn border(width_pt: f32, compound: bool) -> BorderStyle {
      BorderStyle {
        width_pt,
        compound,
        ..Default::default()
      }
    }

    assert_eq!(
      stronger_border(Some(border(0.5, false)), Some(border(2.0, true))).unwrap(),
      border(2.0, true)
    );
    assert_eq!(
      stronger_border(Some(border(1.0, true)), Some(border(1.0, false))).unwrap(),
      border(1.0, false)
    );
    assert_eq!(
      stronger_border(Some(border(1.0, false)), Some(border(1.0, true))).unwrap(),
      border(1.0, false)
    );
  }

