  #[test]
  fn inline_table_uses_fitting_side_of_floating_table_exclusion() {
    let setup = PageSetup {
      width_pt: 841.9,
      margin_left_pt: 13.5,
      margin_right_pt: 3.6,
      ..Default::default()
    };
    let area = block_area(flow_context(
      setup,
      0,
      SectionColumns::default(),
      0,
      0,
      DEFAULT_TAB_STOP_PT,
    ));
    let table = Table {
      column_widths_pt: vec![387.0],
      preferred_width_pt: None,
      preferred_width_pct: None,
      layout: TableLayoutMode::Fixed,
      indent_left_pt: 0.0,
      alignment: TableAlignment::Left,
      right_to_left: false,
      align_leading_cell_content: false,
      in_header_footer: false,
      placement: None,
      allow_overlap: true,
      split_allowed: false,
      following_text_flow: false,
      explicit_no_repeat_header: false,
      page_break_before: false,
      starts_after_last_rendered_page_break: false,
      borders: None,
      cell_spacing: TableCellSpacing::Collapsed,
      rows: vec![TableRow {
        cells: vec![TableCell {
          blocks: Vec::new(),
          shading: None,
          borders: CellBordersModel::default(),
          border_suppressions: CellBorderSuppressions::default(),
          margins: CellMargins::zero(),
          preferred_width_pt: None,
          preferred_width_pct: None,
          grid_span: 1,
          vertical_merge_continue: false,
          no_wrap: false,
          fit_text: false,
          hide_end_mark: false,
          vertical_alignment: TableCellVerticalAlignment::Top,
          text_rotation_deg: None,
        }],
        height_pt: Some(304.0),
        exact_height: true,
        repeat_header: false,
        keep_with_next: false,
        cant_split: true,
        cell_spacing: None,
        grid_before: 0,
        grid_after: 0,
        width_before_pt: None,
        width_after_pt: None,
        layout: None,
        borders: None,
        spacing_shading: None,
        redline_color: None,
      }],
    };
    let mut page = empty_page(setup, 0);
    page.wrap_exclusions.push(WrapExclusion {
      left_pt: 9.75,
      right_pt: 414.75,
      top_pt: 45.05,
      bottom_pt: 350.885,
      side: ImageWrapSide::BothSides,
      blocks_flow: false,
      uses_contour: false,
      owner: WrapExclusionOwner::FloatingTable,
    });
    let mut text_metrics = TextMetrics::new();
    let mut layout = TableFrameLayout::new(&table, area, false, false, &mut text_metrics).unwrap();

    let y = layout.resolve_wrap_position(&page, 72.0, layout.initial_dodge_height());

    assert_eq!(y, 72.0);
    assert!((layout.frame.left_pt - 414.75).abs() < LAYOUT_EPSILON_PT);
    assert!((layout.frame.right_pt - 801.75).abs() < LAYOUT_EPSILON_PT);

    let mut too_wide = table.clone();
    too_wide.column_widths_pt[0] = 450.0;
    let mut blocked =
      TableFrameLayout::new(&too_wide, area, false, false, &mut text_metrics).unwrap();
    let blocked_y = blocked.resolve_wrap_position(&page, 72.0, blocked.initial_dodge_height());
    assert!((blocked_y - 350.885).abs() < LAYOUT_EPSILON_PT);
    assert!((blocked.frame.left_pt - 13.5).abs() < LAYOUT_EPSILON_PT);
  }

  #[test]
  fn legacy_top_level_percentage_width_uses_outer_cell_margins_as_its_basis() {
    fn empty_cell(preferred_width_pct: f32) -> TableCell {
      TableCell {
        blocks: Vec::new(),
        shading: None,
        borders: CellBordersModel::default(),
        border_suppressions: CellBorderSuppressions::default(),
        margins: CellMargins {
          left_pt: 5.75,
          right_pt: 5.75,
          ..CellMargins::zero()
        },
        preferred_width_pt: None,
        preferred_width_pct: Some(preferred_width_pct),
        grid_span: 1,
        vertical_merge_continue: false,
        no_wrap: false,
        fit_text: false,
        hide_end_mark: false,
        vertical_alignment: TableCellVerticalAlignment::Top,
        text_rotation_deg: None,
      }
    }

    let table = Table {
      column_widths_pt: vec![143.85, 335.65],
      preferred_width_pt: None,
      preferred_width_pct: Some(1.0),
      layout: TableLayoutMode::AutoFit,
      indent_left_pt: 0.0,
      alignment: TableAlignment::Left,
      right_to_left: false,
      align_leading_cell_content: true,
      in_header_footer: true,
      placement: None,
      allow_overlap: true,
      split_allowed: false,
      following_text_flow: false,
      explicit_no_repeat_header: false,
      page_break_before: false,
      starts_after_last_rendered_page_break: false,
      borders: None,
      cell_spacing: TableCellSpacing::Collapsed,
      rows: vec![TableRow {
        cells: vec![empty_cell(0.3), empty_cell(0.8)],
        height_pt: None,
        exact_height: false,
        repeat_header: false,
        keep_with_next: false,
        cant_split: false,
        cell_spacing: None,
        grid_before: 0,
        grid_after: 0,
        width_before_pt: None,
        width_after_pt: None,
        layout: None,
        borders: None,
        spacing_shading: None,
        redline_color: None,
      }],
    };
    let mut text_metrics = TextMetrics::new();

    let inline_widths = table_column_widths(&table, 2, 468.0, false, 12, &mut text_metrics);
    assert_eq!(inline_widths, [143.85, 335.65]);

    let following_text_flow_widths = table_column_widths(
      &Table {
        following_text_flow: true,
        ..table.clone()
      },
      2,
      468.0,
      false,
      12,
      &mut text_metrics,
    );
    assert!((following_text_flow_widths[0] - 140.4).abs() < LAYOUT_EPSILON_PT);
    assert!((following_text_flow_widths[1] - 327.6).abs() < LAYOUT_EPSILON_PT);

    let legacy_body = Table {
      preferred_width_pct: Some(0.925),
      alignment: TableAlignment::Center,
      in_header_footer: false,
      ..table.clone()
    };
    let legacy_body_widths =
      table_column_widths(&legacy_body, 2, 468.0, false, 12, &mut text_metrics);
    assert!(
      (legacy_body_widths.iter().sum::<f32>() - (468.0 + 11.5) * 0.925).abs() < LAYOUT_EPSILON_PT
    );

    let modern_body_widths =
      table_column_widths(&legacy_body, 2, 468.0, false, 15, &mut text_metrics);
    assert!((modern_body_widths.iter().sum::<f32>() - 468.0 * 0.925).abs() < LAYOUT_EPSILON_PT);

    let full_width_legacy_body = Table {
      preferred_width_pct: Some(1.0),
      ..legacy_body
    };
    let full_widths = table_column_widths(
      &full_width_legacy_body,
      2,
      468.0,
      false,
      12,
      &mut text_metrics,
    );
    assert!((full_widths.iter().sum::<f32>() - (468.0 + 11.5)).abs() < LAYOUT_EPSILON_PT);

    let mut thick_trailing_border = full_width_legacy_body.clone();
    thick_trailing_border.layout = TableLayoutMode::Fixed;
    thick_trailing_border.column_widths_pt = vec![155.05, 69.9];
    thick_trailing_border.rows[0].cells[0].margins.left_pt = 5.4;
    thick_trailing_border.rows[0].cells[1].margins.left_pt = 28.35;
    thick_trailing_border.rows[0].cells[1].margins.right_pt = 0.0;
    let mut border_only = thick_trailing_border.clone();
    border_only.rows[0].cells[0].borders.left = Some(BorderStyle {
      width_pt: 6.0,
      ..Default::default()
    });
    for (trailing_border_width, expected_total, expected_first) in [
      (0.0, 230.4, 158.8),
      (1.0, 230.9, 159.15),
      (6.0, 233.4, 160.85),
    ] {
      border_only.rows[0].cells[1].borders.right =
        (trailing_border_width > 0.0).then_some(BorderStyle {
          width_pt: trailing_border_width,
          ..Default::default()
        });
      let widths = table_column_widths(&border_only, 2, 225.0, false, 12, &mut text_metrics);
      assert!(
        (widths.iter().sum::<f32>() - expected_total).abs() < LAYOUT_EPSILON_PT,
        "trailing_border_width={trailing_border_width}, widths={widths:?}"
      );
      assert!(
        (widths[0] - expected_first).abs() < LAYOUT_EPSILON_PT,
        "Word exposes the first internal grid boundary in twips: widths={widths:?}"
      );
    }
    border_only.rows[0].cells[1].borders.right = Some(BorderStyle {
      width_pt: 0.5,
      ..Default::default()
    });
    for (margin, expected_basis) in [(0.0, 230.65), (0.2, 230.65), (0.5, 230.9), (2.9, 233.3)] {
      border_only.rows[0].cells[1].margins.right_pt = margin;
      assert!(
        (table_preferred_width_basis(&border_only, 225.0, 12) - expected_basis).abs()
          < LAYOUT_EPSILON_PT,
        "right margin {margin} and a 0.5pt border share the trailing allowance"
      );
    }
    border_only.rows[0].cells[1].margins.right_pt = 0.0;
    border_only.preferred_width_pct = Some(1.0662);
    assert!(
      (table_preferred_width_basis(&border_only, 225.0, 12) - 230.4).abs() < LAYOUT_EPSILON_PT,
      "a 106.62% table must not inherit the measured 100% border allowance"
    );
    for percentage in [1.132, 1.2] {
      let overflowing = Table {
        column_widths_pt: vec![300.0, 400.0],
        preferred_width_pct: Some(percentage),
        ..full_width_legacy_body.clone()
      };
      for (mode, basis) in [(12, 479.5), (15, 468.0)] {
        let widths = table_column_widths(&overflowing, 2, 468.0, false, mode, &mut text_metrics);
        assert!(
          (widths.iter().sum::<f32>() - basis * percentage).abs() < LAYOUT_EPSILON_PT,
          "mode={mode}, percentage={percentage}, widths={widths:?}"
        );
      }
    }
    let mut child = full_width_legacy_body.clone();
    child.column_widths_pt = vec![700.0];
    child.preferred_width_pt = Some(700.0);
    child.preferred_width_pct = None;
    child.rows[0].cells.truncate(1);
    for percentage in [1.0, 1.132] {
      let mut parent = full_width_legacy_body.clone();
      parent.column_widths_pt = vec![300.0];
      parent.preferred_width_pct = Some(percentage);
      parent.rows[0].cells.truncate(1);
      parent.rows[0].cells[0].blocks = vec![Block::Table(child.clone())];
      let widths = table_column_widths(&parent, 1, 468.0, false, 12, &mut text_metrics);
      let expected = if percentage > 1.0 { 711.5 } else { 479.5 };
      assert!(
        (widths[0] - expected).abs() < LAYOUT_EPSILON_PT,
        "percentage={percentage}, widths={widths:?}, expected={expected}"
      );
    }
    // Native Word Spacing=3pt saves tblCellSpacing=30twips and this grid.
    // Its first/second cell text starts at85.15/325.90pt; spacing is already
    // represented in the grid and must not be added between raw columns.
    let mut spaced = full_width_legacy_body.clone();
    spaced.alignment = TableAlignment::Left;
    spaced.column_widths_pt = vec![242.25, 242.30];
    spaced.cell_spacing = TableCellSpacing::Separated(1.5);
    for cell in &mut spaced.rows[0].cells {
      cell.margins.left_pt = 5.4;
      cell.margins.right_pt = 5.4;
    }
    let mut flow = flow_context(
      PageSetup::default(),
      0,
      SectionColumns::default(),
      0,
      0,
      DEFAULT_TAB_STOP_PT,
    );
    flow.compatibility_mode = 12;
    flow.content_left_pt = 85.15;
    flow.content_width = 467.75;
    let layout =
      TableFrameLayout::new(&spaced, block_area(flow), false, false, &mut text_metrics).unwrap();
    assert!((layout.frame.right_pt - layout.frame.left_pt - 484.55).abs() < 0.01);
    let row = &spaced.rows[0];
    let frame = layout.row_frame(row, 0, 0.0);
    let gap = row_cell_spacing_pt(&spaced, row);
    let mut left = row_grid_left(&layout.frame, row, gap);
    let mut grid = 0;
    for (index, expected) in [85.15, 325.90].into_iter().enumerate() {
      let cell = frame
        .cell_frame(&row.cells[index], index, left, 12.0, &mut grid)
        .unwrap();
      assert!((cell.left_pt + cell.cell.margins.left_pt - expected).abs() < 0.01);
      assert!((cell.width_pt - (spaced.column_widths_pt[index] - 4.5)).abs() < 0.01);
      left = cell.left_pt + cell.width_pt + gap;
    }
    for half_gap in [0.0, 0.75, 1.5] {
      let mut single = spaced.clone();
      single.cell_spacing = TableCellSpacing::Separated(half_gap);
      single.column_widths_pt = vec![520.0];
      single.rows[0].cells.truncate(1);
      single.rows = vec![single.rows[0].clone(); 3];
      let mut grid = 0;
      let width = spanned_cell_width(
        &single.rows[0].cells[0],
        &single.column_widths_pt,
        &mut grid,
        row_cell_spacing_pt(&single, &single.rows[0]),
      );
      assert!((width - (520.0 - 4.0 * half_gap)).abs() < 0.01);
      // Word's three-row controls add one full gap before, between and after
      // rows: four gaps total, not a top and bottom inset on every row.
      let height = table_total_height_from_row_heights(&single, &[12.0; 3]);
      assert!((height - (36.0 + 8.0 * half_gap)).abs() < 0.01);
    }
  }

  fn native_percentage_autofit_table<const N: usize>(word: &str, percentages: [f32; N]) -> Table {
    let style = TextStyle {
      font_family: Some(Arc::from("Times New Roman")),
      high_ansi_font_family: Some(Arc::from("Times New Roman")),
      font_size_pt: 12.0,
      use_windows_font_metrics: true,
      ..Default::default()
    };
    let border = BorderStyle {
      width_pt: 0.5,
      ..Default::default()
    };
    Table {
      column_widths_pt: if N == 3 {
        vec![80.0, 140.0, 100.0]
      } else {
        vec![50.0; N]
      },
      preferred_width_pt: Some(320.0),
      preferred_width_pct: None,
      layout: TableLayoutMode::AutoFit,
      indent_left_pt: 0.0,
      alignment: TableAlignment::Left,
      right_to_left: false,
      align_leading_cell_content: false,
      in_header_footer: false,
      placement: None,
      allow_overlap: true,
      split_allowed: true,
      following_text_flow: false,
      explicit_no_repeat_header: false,
      page_break_before: false,
      starts_after_last_rendered_page_break: false,
      borders: Some(TableBordersModel {
        top: Some(border),
        right: Some(border),
        bottom: Some(border),
        left: Some(border),
        inside_horizontal: Some(border),
        inside_vertical: Some(border),
      }),
      cell_spacing: TableCellSpacing::Collapsed,
      rows: (0..2)
        .map(|row| TableRow {
          cells: percentages
            .into_iter()
            .enumerate()
            .map(|(column, percentage)| {
              let text = if column == 0 && !word.is_empty() {
                word.to_owned()
              } else {
                format!("{}{row}", char::from(b'A' + column as u8))
              };
              let paragraph = Paragraph {
                inlines: vec![InlineItem::Text(TextRun {
                  text,
                  style: style.clone(),
                  hyperlink_url: None,
                  dynamic_field: None,
                  style_ref_keys: Vec::new(),
                  style_ref_text: None,
                  style_ref_numbering_text: None,
                  preserve_text_portion: false,
                })],
                field_events: Vec::new(),
                footnote_reference_ids: Vec::new(),
                endnote_reference_ids: Vec::new(),
                starts_after_last_rendered_page_break: false,
                base_style: style.clone(),
                runs: Vec::new(),
                format: Box::new(ParagraphFormat::default()),
                style_ref_keys: Vec::new(),
                style_ref_text: None,
                style_ref_numbering_text: None,
                list_label: None,
                list_label_image: None,
                list_label_style: style.clone(),
                list_label_hyperlink_url: None,
                list_label_tab_stop_pt: None,
              };
              TableCell {
                blocks: vec![Block::paragraph(paragraph)],
                shading: None,
                borders: CellBordersModel::default(),
                border_suppressions: CellBorderSuppressions::default(),
                margins: CellMargins {
                  left_pt: 5.4,
                  right_pt: 5.4,
                  ..CellMargins::zero()
                },
                preferred_width_pt: None,
                preferred_width_pct: Some(percentage),
                grid_span: 1,
                vertical_merge_continue: false,
                no_wrap: false,
                fit_text: false,
                hide_end_mark: false,
                vertical_alignment: TableCellVerticalAlignment::Top,
                text_rotation_deg: None,
              }
            })
            .collect(),
          height_pt: None,
          exact_height: false,
          repeat_header: false,
          keep_with_next: false,
          cant_split: false,
          cell_spacing: None,
          grid_before: 0,
          grid_after: 0,
          width_before_pt: None,
          width_after_pt: None,
          layout: None,
          borders: None,
          spacing_shading: None,
          redline_color: None,
        })
        .collect(),
    }
  }

  #[test]
  fn modern_floating_table_wrap_owns_the_outside_border_frame() {
    // Office COM column sums for the same 40% AutoFit table, independently
    // varied against 156.5pt dxa and 0.5/1.5/3/6pt outside borders. The 6pt
    // case resolves below the saved 155.3pt grid, exercising shrink as well.
    let setup = PageSetup {
      width_pt: 419.6,
      margin_left_pt: 14.2,
      margin_right_pt: 14.2,
      ..Default::default()
    };
    let mut flow = flow_context(
      setup,
      0,
      SectionColumns::default(),
      0,
      0,
      DEFAULT_TAB_STOP_PT,
    );
    flow.compatibility_mode = 15;
    let mut metrics = TextMetrics::new();
    for (border_width, native_grid) in [(0.5, 156.3), (1.5, 155.9), (3.0, 155.3), (6.0, 154.1)] {
      for percentage in [true, false] {
        let mut table = native_percentage_autofit_table("", [0.2, 0.8]);
        table.column_widths_pt = vec![26.85, 128.45];
        table.preferred_width_pt = (!percentage).then_some(156.5);
        table.preferred_width_pct = percentage.then_some(0.4);
        table.placement = Some(FloatingFramePlacement {
          margin_left_pt: 9.0,
          margin_right_pt: 9.0,
          ..Default::default()
        });
        let border = BorderStyle {
          width_pt: border_width,
          ..Default::default()
        };
        table.borders = Some(TableBordersModel {
          left: Some(border),
          right: Some(border),
          ..Default::default()
        });
        for row in &mut table.rows {
          for (cell, width) in row.cells.iter_mut().zip([26.85, 128.45]) {
            cell.preferred_width_pct = None;
            cell.preferred_width_pt = Some(width);
          }
        }
        let mut page = empty_page(setup, 0);
        let mut pages = Vec::new();
        layout_floating_table(&table, flow, &mut page, &mut pages, &mut metrics, 72.0, 0.0);
        let bounds = page.floating_table_bounds[0].bounds;
        let native_grid = if percentage { native_grid } else { 156.5 };
        assert!((bounds.x_pt - 14.2).abs() < 0.001);
        assert!(
          (bounds.width_pt - native_grid - border_width).abs() < 0.051,
          "border={border_width}, pct={percentage}, bounds={bounds:?}"
        );
        assert!(
          (page.wrap_exclusions[0].right_pt - (14.2 + native_grid + border_width + 9.0)).abs()
            < 0.051
        );
      }
    }
  }

  #[test]
  fn percentage_autofit_matches_native_preferred_extents_and_saturated_donors() {
    // Word COM widths after Print PDF export. Saved grid, table preference,
    // unbreakable content and donor saturation were varied independently.
    let cases = [
      (None, 6, [0.2, 0.3, 0.5], [74.85, 90.55, 154.6]),
      (None, 8, [0.2, 0.3, 0.5], [96.2, 79.9, 143.9]),
      (None, 10, [0.2, 0.3, 0.5], [117.5, 69.25, 133.25]),
      (Some(0.64), 6, [0.2, 0.3, 0.5], [74.85, 90.45, 154.4]),
      (Some(0.64), 8, [0.2, 0.3, 0.5], [96.2, 79.75, 143.75]),
      (Some(0.64), 10, [0.2, 0.3, 0.5], [117.5, 69.1, 133.1]),
      (Some(1.0), 6, [0.2, 0.3, 0.5], [99.9, 149.85, 249.75]),
      (Some(1.0), 8, [0.2, 0.3, 0.5], [99.9, 149.85, 249.75]),
      (Some(1.0), 10, [0.2, 0.3, 0.5], [117.5, 141.05, 240.95]),
      (None, 8, [0.2, 0.06, 0.74], [96.2, 24.85, 198.95]),
      (None, 10, [0.2, 0.06, 0.74], [117.5, 24.85, 177.65]),
      (None, 16, [0.2, 0.06, 0.74], [181.55, 24.85, 113.6]),
    ];
    let mut metrics = TextMetrics::new();
    for (table_percentage, count, percentages, expected) in cases {
      let mut table = native_percentage_autofit_table(&"M".repeat(count), percentages);
      if let Some(percentage) = table_percentage {
        table.preferred_width_pt = None;
        table.preferred_width_pct = Some(percentage);
      }
      let actual = table_column_widths(&table, 3, 500.0, false, 15, &mut metrics);
      for (index, expected) in expected.into_iter().enumerate() {
        assert!(
          (actual[index] - expected).abs() < 0.001,
          "pct={table_percentage:?} M{count} column={index}: {actual:?}"
        );
      }
    }
  }

  #[test]
  fn percentage_autofit_native_remainders_follow_content_redistribution() {
    let table = native_percentage_autofit_table("", [0.065, 0.1828, 0.1828, 0.193, 0.3764]);
    let mut widths = vec![50.0; 5];
    let preferred =
      apply_complete_autofit_percentage_row_widths(&table, &mut widths, Some(739.8)).unwrap();
    assert_eq!(preferred, 739.8);
    assert!((widths.iter().sum::<f32>() - 739.85).abs() < 0.001);
    // Native small-column0 retains three unsaturated donors. Collecting its
    // preferred-grid remainder before content fitting moves a different twip.
    let minima = [0.0, 135.9, 135.9, 0.0, 0.0];
    widths[1] = minima[1];
    widths[2] = minima[2];
    let requested = widths.iter().sum::<f32>() - preferred;
    shrink_autofit_donors(&mut widths, 0..0, &minima, &minima, requested, true);
    snap_percentage_autofit_columns_to_twips(&mut widths, &minima, 0);
    for (actual, expected) in widths.iter().zip([47.65, 135.9, 135.9, 142.35, 278.0]) {
      assert!((actual - expected).abs() < 0.001, "{widths:?}");
    }

    fn verify<const N: usize>(percentages: [f32; N], cases: [(f32, usize, [f32; N]); 4]) {
      let mut metrics = TextMetrics::new();
      for (width, count, expected) in cases {
        let mut table = native_percentage_autofit_table(&"M".repeat(count), percentages);
        table.preferred_width_pt = Some(width);
        let actual = table_column_widths(&table, N, 500.0, false, 15, &mut metrics);
        for (actual_width, expected_width) in actual.iter().zip(expected) {
          assert!(
            (actual_width - expected_width).abs() < 0.001,
            "columns={N} width={width} M{count}: {actual:?}"
          );
        }
      }
    }
    verify(
      [0.1, 0.3, 0.2, 0.4],
      [
        (320.0, 6, [74.85, 81.7, 49.7, 113.75]),
        (320.0, 8, [96.2, 74.6, 42.6, 106.6]),
        (321.0, 6, [74.85, 82.05, 49.95, 114.15]),
        (321.0, 8, [96.2, 74.9, 42.85, 107.05]),
      ],
    );
    verify(
      [0.1, 0.15, 0.2, 0.25, 0.3],
      [
        (320.0, 6, [74.85, 37.25, 53.3, 69.3, 85.3]),
        (320.0, 8, [96.2, 31.95, 47.95, 63.95, 79.95]),
        (321.0, 6, [74.85, 37.45, 53.5, 69.55, 85.65]),
        (321.0, 8, [96.2, 32.1, 48.15, 64.25, 80.3]),
      ],
    );
  }

  #[test]
  fn percentage_autofit_native_basis_includes_both_outside_border_halves() {
    let mut metrics = TextMetrics::new();
    for (left, right, expected) in [
      (0.0, 0.0, [100.0, 150.0, 250.0]),
      (0.5, 0.5, [99.9, 149.85, 249.75]),
      (1.0, 1.0, [99.8, 149.7, 249.5]),
      (0.5, 1.5, [99.8, 149.7, 249.5]),
      (0.0, 1.0, [99.9, 149.85, 249.75]),
      (1.0, 0.0, [99.9, 149.85, 249.75]),
    ] {
      let mut table = native_percentage_autofit_table("", [0.2, 0.3, 0.5]);
      table.preferred_width_pt = None;
      table.preferred_width_pct = Some(1.0);
      let borders = table.borders.as_mut().unwrap();
      borders.left = (left > 0.0).then_some(BorderStyle {
        width_pt: left,
        ..Default::default()
      });
      borders.right = (right > 0.0).then_some(BorderStyle {
        width_pt: right,
        ..Default::default()
      });
      let actual = table_column_widths(&table, 3, 500.0, false, 15, &mut metrics);
      for (index, expected) in expected.into_iter().enumerate() {
        assert!(
          (actual[index] - expected).abs() < 0.001,
          "borders=({left},{right}) column={index}: {actual:?}"
        );
      }
    }
  }

