  #[test]
  fn table_header_pagination_distinguishes_master_follow_and_empty_page() {
    fn row() -> TableRow {
      TableRow {
        cells: vec![TableCell {
          blocks: Vec::new(),
          shading: None,
          borders: CellBordersModel::default(),
          border_suppressions: CellBorderSuppressions::default(),
          margins: CellMargins::default(),
          preferred_width_pt: None,
          preferred_width_pct: None,
          grid_span: 1,
          vertical_merge_continue: false,
          no_wrap: false,
          fit_text: false,
          hide_end_mark: false,
          vertical_alignment: TableCellVerticalAlignment::Top,
          text_rotation_deg: None,
        }],
        height_pt: Some(20.0),
        exact_height: false,
        repeat_header: false,
        keep_with_next: false,
        cant_split: true,
        cell_spacing: None,
        grid_before: 0,
        grid_after: 0,
        width_before_pt: None,
        width_after_pt: None,
        layout: None,
        borders: None,
        spacing_shading: None,
        redline_color: None,
      }
    }

    let mut table = Table {
      column_widths_pt: vec![72.0],
      preferred_width_pt: None,
      preferred_width_pct: None,
      layout: TableLayoutMode::Fixed,
      indent_left_pt: 0.0,
      alignment: TableAlignment::Left,
      right_to_left: false,
      align_leading_cell_content: true,
      in_header_footer: false,
      placement: None,
      allow_overlap: false,
      split_allowed: true,
      following_text_flow: false,
      explicit_no_repeat_header: false,
      page_break_before: false,
      starts_after_last_rendered_page_break: false,
      borders: None,
      cell_spacing: TableCellSpacing::Collapsed,
      rows: vec![row(); 21],
    };
    table.rows[0].repeat_header = true;
    let area = BlockArea {
      setup: PageSetup::default(),
      section_index: 0,
      section_page_index: 1,
      column_index: 0,
      columns: SectionColumns::default(),
      content_top_pt: 20.0,
      content_left_pt: 72.0,
      content_bottom: 180.0,
      body_content_bottom_pt: 180.0,
      content_width: 451.0,
      default_tab_stop_pt: DEFAULT_TAB_STOP_PT,
      hyphenation: crate::docx::HyphenationSettings::default(),
      consecutive_hyphenated_lines: 0,
      compatibility_mode: 12,
      justify_lines_with_shrinking: false,
      do_not_expand_shift_return: false,
      suppress_top_spacing: false,
      split_page_break_and_paragraph_mark: false,
      repeating_slots: RepeatingSlotState::default(),
    };
    let mut text_metrics = TextMetrics::new();
    let layout = TableFrameLayout::new(&table, area, false, false, &mut text_metrics).unwrap();

    for (y, has_previous, move_forward, master_end) in [
      (20.0, false, false, 8),
      (120.0, true, false, 3),
      (145.0, true, false, 1),
      (165.0, true, true, 0),
    ] {
      let plan = layout.make_all_split_plan(0, y, has_previous, true, false, &mut text_metrics);
      assert_eq!(plan.move_forward, move_forward, "master y={y}");
      assert!(!plan.disable_repeating_headers, "master y={y}");
      assert_eq!(
        plan.split_decision.unwrap().master_end_row_index,
        master_end
      );
    }

    // After moving the unstarted master, row zero is still formatted by the
    // ordinary loop. Only a follow receives an additional repeated headline.
    let mut page = empty_page(area.setup, 0);
    let mut pages = Vec::new();
    assert_eq!(
      layout.format_repeated_header_rows(
        StoryLayoutTarget {
          current: &mut page,
          pages: &mut pages,
          text_metrics: &mut text_metrics
        },
        0,
        20.0,
        20.0,
        false
      ),
      20.0
    );
    assert_eq!(
      layout.format_repeated_header_rows(
        StoryLayoutTarget {
          current: &mut page,
          pages: &mut pages,
          text_metrics: &mut text_metrics
        },
        1,
        20.0,
        20.0,
        false
      ),
      40.0
    );

    // Multi-row headers can cross the master/follow boundary. That first
    // follow consumes remaining original headers without cloning the group;
    // later follows resume the complete repeated group.
    table.rows[1].repeat_header = true;
    let multi = TableFrameLayout::new(&table, area, false, false, &mut text_metrics).unwrap();
    let split = multi.make_all_split_plan(0, 145.0, true, true, false, &mut text_metrics);
    assert!(!split.move_forward);
    assert!(!split.disable_repeating_headers);
    assert_eq!(split.split_decision.unwrap().master_end_row_index, 1);
    assert_eq!(
      multi.format_repeated_header_rows(
        StoryLayoutTarget {
          current: &mut page,
          pages: &mut pages,
          text_metrics: &mut text_metrics
        },
        1,
        20.0,
        20.0,
        false
      ),
      20.0
    );
    assert_eq!(
      multi.format_repeated_header_rows(
        StoryLayoutTarget {
          current: &mut page,
          pages: &mut pages,
          text_metrics: &mut text_metrics
        },
        9,
        20.0,
        20.0,
        false
      ),
      60.0
    );
    table.rows[1].repeat_header = false;

    let mut bordered = table.clone();
    bordered.rows[0].cells[0].borders.left = Some(BorderStyle::default());
    bordered.rows[0].cells[0].borders.right = Some(BorderStyle::default());
    let bordered_layout =
      TableFrameLayout::new(&bordered, area, false, false, &mut text_metrics).unwrap();
    let mut header_page = empty_page(area.setup, 0);
    bordered_layout.format_repeated_header_rows(
      StoryLayoutTarget {
        current: &mut header_page,
        pages: &mut pages,
        text_metrics: &mut text_metrics,
      },
      9,
      20.0,
      20.0,
      false,
    );
    let vertical_edges = header_page.items.iter().filter(|item| {
      matches!(item, PageItem::Fill(fill) if fill.width_pt < 1.0 && fill.height_pt >= 19.0)
    }).count();
    assert_eq!(
      vertical_edges, 2,
      "a repeated header keeps both outer edges"
    );

    // A single content line plus 14.4pt paragraph-after and 3.6pt cell
    // margins needs 33.6pt even though the text itself fits a 30pt fragment.
    let mut padded = table.clone();
    let row = &mut padded.rows[1];
    row.height_pt = None;
    row.cant_split = false;
    row.cells[0].margins.top_pt = 3.6;
    row.cells[0].margins.bottom_pt = 3.6;
    row.cells[0].blocks = vec![Block::paragraph(Paragraph {
      inlines: Vec::new(),
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: TextStyle::default(),
      runs: Vec::new(),
      format: Box::new(ParagraphFormat {
        line_height_pt: Some(12.0),
        line_height_set: true,
        line_height_rule: LineHeightRule::Exact,
        spacing_after_pt: 14.4,
        ..Default::default()
      }),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: TextStyle::default(),
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    })];
    let padded_layout =
      TableFrameLayout::new(&padded, area, false, false, &mut text_metrics).unwrap();
    let minimum = padded_layout
      .row_first_content_line_height(1, &padded.rows[1], &mut text_metrics)
      .unwrap();
    assert!((minimum - 33.6).abs() < LAYOUT_EPSILON_PT);
    assert!(!padded_layout.row_can_split_at_cut(
      &padded_layout.row_frame(&padded.rows[1], 1, area.content_bottom - 30.0),
      0,
      true,
      false,
      false,
      &mut text_metrics,
    ));

    table.rows[0].height_pt = Some(150.0);
    let tall = TableFrameLayout::new(&table, area, false, false, &mut text_metrics).unwrap();
    let master = tall.make_all_split_plan(0, 20.0, false, true, false, &mut text_metrics);
    assert!(!master.disable_repeating_headers);
    assert_eq!(master.split_decision.unwrap().master_end_row_index, 1);
    let follow = tall.make_all_split_plan(1, 170.0, true, true, false, &mut text_metrics);
    assert!(!follow.move_forward);
    assert!(!follow.disable_repeating_headers);
    assert!(!follow.split_decision.unwrap().move_rows_to_follow);

    table.rows[0].height_pt = Some(170.0);
    let oversized = TableFrameLayout::new(&table, area, false, false, &mut text_metrics).unwrap();
    let master = oversized.make_all_split_plan(0, 120.0, true, true, false, &mut text_metrics);
    assert!(master.move_forward);
    assert!(!master.disable_repeating_headers);
    let empty_page = oversized.make_all_split_plan(0, 20.0, false, true, false, &mut text_metrics);
    assert!(empty_page.disable_repeating_headers);
  }

