  #[test]
  fn vertical_merge_origin_content_height_spans_continuation_rows() {
    fn cell(continue_merge: bool) -> TableCell {
      TableCell {
        blocks: Vec::new(),
        shading: None,
        borders: CellBordersModel::default(),
        border_suppressions: CellBorderSuppressions::default(),
        margins: CellMargins::default(),
        preferred_width_pt: None,
        preferred_width_pct: None,
        grid_span: 1,
        vertical_merge_continue: continue_merge,
        no_wrap: false,
        fit_text: false,
        hide_end_mark: false,
        vertical_alignment: TableCellVerticalAlignment::Top,
        text_rotation_deg: None,
      }
    }

    fn row(continue_merge: bool, height_pt: f32, spacing_pt: Option<f32>) -> TableRow {
      TableRow {
        cells: vec![cell(continue_merge)],
        height_pt: Some(height_pt),
        exact_height: true,
        repeat_header: false,
        keep_with_next: false,
        cant_split: false,
        cell_spacing: spacing_pt.map(TableCellSpacing::Separated),
        grid_before: 0,
        grid_after: 0,
        width_before_pt: None,
        width_after_pt: None,
        layout: None,
        borders: None,
        spacing_shading: None,
        redline_color: None,
      }
    }

    let table = Table {
      column_widths_pt: vec![72.0],
      preferred_width_pt: None,
      preferred_width_pct: None,
      layout: TableLayoutMode::Fixed,
      indent_left_pt: 0.0,
      alignment: TableAlignment::Left,
      right_to_left: false,
      align_leading_cell_content: true,
      in_header_footer: false,
      placement: None,
      allow_overlap: true,
      split_allowed: false,
      following_text_flow: false,
      explicit_no_repeat_header: false,
      page_break_before: false,
      starts_after_last_rendered_page_break: false,
      borders: None,
      cell_spacing: TableCellSpacing::Separated(2.0),
      rows: vec![
        row(false, 10.0, Some(3.0)),
        row(true, 11.0, None),
        row(true, 12.0, None),
      ],
    };

    assert_eq!(
      vertical_merge_content_height(
        &table,
        &[10.0, 11.0, 12.0],
        VerticalMergeSpan {
          row_index: 0,
          grid_start: 0,
          current_row_height: 10.0,
        },
      ),
      Some(43.0) // 10 + 11 + 12 plus physical cell gaps 2*3 + 2*2.
    );
    assert_eq!(vertical_merge_origin_row_index(&table, 2, 0), Some(0));
    assert_eq!(
      complete_vertical_merge_fragment_span(
        &table,
        &[10.0, 11.0, 12.0],
        VerticalMergeFragmentContext {
          row_index: 0,
          grid_start: 0,
          row_top_pt: 100.0,
          row_bottom_pt: 110.0,
          content_offset: 0.0,
          page_content_top_pt: 72.0,
          page_content_bottom_pt: 720.0,
        },
      ),
      Some((100.0, 43.0))
    );
    assert_eq!(
      complete_vertical_merge_fragment_span(
        &table,
        &[10.0, 11.0, 12.0],
        VerticalMergeFragmentContext {
          row_index: 1,
          grid_start: 0,
          row_top_pt: 116.0,
          row_bottom_pt: 127.0,
          content_offset: 0.0,
          page_content_top_pt: 72.0,
          page_content_bottom_pt: 720.0,
        },
      ),
      Some((100.0, 43.0))
    );
    assert_eq!(
      complete_vertical_merge_fragment_span(
        &table,
        &[10.0, 11.0, 12.0],
        VerticalMergeFragmentContext {
          row_index: 2,
          grid_start: 0,
          row_top_pt: 131.0,
          row_bottom_pt: 143.0,
          content_offset: 0.0,
          page_content_top_pt: 72.0,
          page_content_bottom_pt: 720.0,
        },
      ),
      Some((100.0, 43.0))
    );
    assert_eq!(
      complete_vertical_merge_fragment_span(
        &table,
        &[10.0, 11.0, 12.0],
        VerticalMergeFragmentContext {
          row_index: 1,
          grid_start: 0,
          row_top_pt: 72.0,
          row_bottom_pt: 83.0,
          content_offset: 0.0,
          page_content_top_pt: 72.0,
          page_content_bottom_pt: 720.0,
        },
      ),
      None,
      "a continuation moved to a new upper keeps its page-local clip",
    );
    assert!(row_has_vertical_merge_context(&table, 0));
    assert!(row_has_vertical_merge_context(&table, 1));
    assert!(row_has_vertical_merge_context(&table, 2));
  }

  #[test]
  fn terminal_footnote_spacing_reflows_source_lines_and_preserves_widows() {
    let style = TextStyle {
      font_family: Some("Times New Roman".into()),
      font_size_pt: 12.0,
      ..Default::default()
    };
    let run = |text: &str, url: Option<&str>| {
      InlineItem::Text(TextRun {
        text: text.into(),
        style: style.clone(),
        hyperlink_url: url.map(str::to_owned),
        dynamic_field: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        preserve_text_portion: false,
      })
    };
    let paragraph = |inlines, after, widow| Paragraph {
      inlines,
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: style.clone(),
      runs: Vec::new(),
      format: Box::new(ParagraphFormat {
        line_height_rule: LineHeightRule::Exact,
        line_height_pt: Some(14.0),
        spacing_after_pt: after,
        widow_control: Some(widow),
        ..Default::default()
      }),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: style.clone(),
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    };
    for mode in [12, 14, 15] {
      for kind in ["none", "existing", "early", "last", "endnote", "backlink"] {
        for line_count in [1, 6] {
          for after in [0.0, 10.0] {
            for widow in [false, true] {
              let setup = PageSetup {
                width_pt: 360.0,
                height_pt: 240.0,
                margin_top_pt: 36.0,
                margin_bottom_pt: 36.0,
                margin_left_pt: 36.0,
                margin_right_pt: 36.0,
                ..Default::default()
              };
              let mut flow = flow_context(
                setup,
                0,
                SectionColumns::default(),
                0,
                0,
                DEFAULT_TAB_STOP_PT,
              );
              flow.compatibility_mode = mode;
              let mut current = empty_page(setup, 0);
              let mut pages = Vec::new();
              let mut anchors = Vec::new();
              let mut metrics = TextMetrics::new();
              let prefix = paragraph(vec![run("PREFIX", None)], 0.0, false);
              let (_, y) = TextFrameLayout::new(
                &prefix,
                flow,
                f64::from(flow.content_width),
                0.0,
                &mut metrics,
              )
              .format(&mut current, &mut pages, None, &mut metrics, 36.0, 36.0);
              flow.content_bottom = y + line_count as f32 * 14.0;
              if kind == "existing" {
                current.footnote_reserved_height_pt =
                  flow.body_content_bottom_pt - flow.content_bottom;
              }
              let mut inlines = vec![InlineItem::BookmarkStart("body-start".into())];
              for index in 0..line_count {
                if index > 0 {
                  inlines.push(run("\n", None));
                }
                inlines.push(run(&format!("BODY{index}"), None));
                let url = match kind {
                  "early" if index == 0 => Some("ooxmlsdk-pdf:footnote-reference:8"),
                  "last" if index + 1 == line_count => Some("ooxmlsdk-pdf:footnote-reference:8"),
                  "endnote" if index + 1 == line_count => Some("ooxmlsdk-pdf:endnote-reference:8"),
                  "backlink" if index + 1 == line_count => Some("ooxmlsdk-pdf:footnote-backlink:8"),
                  _ => None,
                };
                if let Some(url) = url {
                  inlines.push(run("8", Some(url)));
                }
              }
              let body = paragraph(inlines, after, widow);
              TextFrameLayout::new(
                &body,
                flow,
                f64::from(flow.content_width),
                after,
                &mut metrics,
              )
              .format(
                &mut current,
                &mut pages,
                Some(&mut anchors),
                &mut metrics,
                y,
                y,
              );
              pages.push(current);
              let must_follow = after > 0.0
                && (kind == "last"
                  || (kind == "early" && (mode >= 15 || line_count == 1))
                  || (kind == "existing" && mode >= 15));
              let moved = if must_follow {
                if widow { line_count.min(2) } else { 1 }
              } else {
                0
              };
              let first_page_lines = pages[0]
                .items
                .iter()
                .filter(
                  |item| matches!(item, PageItem::Text(text) if text.text.starts_with("BODY")),
                )
                .count();
              assert_eq!(
                first_page_lines,
                line_count - moved,
                "mode={mode} kind={kind} lines={line_count} after={after} widow={widow}"
              );
              assert_eq!(pages.len(), if must_follow { 2 } else { 1 });
              assert_eq!(anchors.len(), 1);
              assert_eq!(
                anchors[0].page_index,
                usize::from(must_follow && line_count == 1)
              );
              let terminal_page = pages.last().unwrap();
              assert_eq!(
                terminal_page
                  .frame_fragments
                  .last()
                  .unwrap()
                  .paragraph_spacing_after_pt,
                after
              );
              assert_eq!(
                pages
                  .iter()
                  .flat_map(|page| &page.items)
                  .filter(|item| {
                    matches!(item, PageItem::Text(text) if text.text.starts_with("BODY"))
                  })
                  .count(),
                line_count
              );
            }
          }
        }
      }
    }
  }

  #[test]
  fn text_frame_split_policy_matches_orphan_and_widow_minimums() {
    let mut state = TextFrameState::new();
    for index in 0..4 {
      state.set_position(InlineCursor {
        inline_index: 0,
        text_offset: index + 1,
      });
      state.finish_line(10.0 + index as f32 * 14.0, 14.0);
      if index == 1 {
        state.note_page_follow(1, 10.0, 0);
      }
    }

    assert_eq!(
      state.page_split_decision(false, DEFAULT_ORPHAN_LINES, DEFAULT_WIDOW_LINES),
      TextSplitDecision::Allowed
    );
    assert_eq!(
      state.page_split_decision(true, DEFAULT_ORPHAN_LINES, DEFAULT_WIDOW_LINES),
      TextSplitDecision::Rejected
    );
  }

  #[test]
  fn text_frame_split_policy_rejects_a_widow_transfer_that_would_create_an_orphan() {
    let mut state = TextFrameState::new();
    for index in 0..3 {
      state.set_position(InlineCursor {
        inline_index: 0,
        text_offset: index + 1,
      });
      state.finish_line(10.0 + index as f32 * 14.0, 14.0);
      if index == 1 {
        state.note_page_follow(1, 10.0, 0);
      }
    }

    assert_eq!(
      state.page_split_decision(false, DEFAULT_ORPHAN_LINES, DEFAULT_WIDOW_LINES),
      TextSplitDecision::Rejected
    );
    assert_eq!(
      state.page_split_decision(false, 0, 0),
      TextSplitDecision::Allowed
    );

    let mut transferable = TextFrameState::new();
    for index in 0..4 {
      transferable.set_position(InlineCursor {
        inline_index: 0,
        text_offset: index + 1,
      });
      transferable.finish_line(10.0 + index as f32 * 14.0, 14.0);
      if index == 2 {
        transferable.note_page_follow(1, 10.0, 0);
      }
    }
    assert_eq!(
      transferable.page_split_decision(false, DEFAULT_ORPHAN_LINES, DEFAULT_WIDOW_LINES),
      TextSplitDecision::RebalanceWidow {
        page_index: 0,
        line_start: InlineCursor {
          inline_index: 0,
          text_offset: 2,
        },
      }
    );
  }

  #[test]
  fn terminal_paragraph_mark_line_satisfies_widow_minimum_after_soft_break() {
    let mut state = TextFrameState::new();
    for index in 0..4 {
      state.set_position(InlineCursor {
        inline_index: index,
        text_offset: 1,
      });
      state.finish_line(10.0 + index as f32 * 14.0, 14.0);
      if index == 2 {
        state.note_page_follow(1, 10.0, 0);
      }
    }
    // A trailing soft break puts the paragraph mark on a real final line, but
    // it has no run-content range of its own.
    state.finish_line(66.0, 14.0);

    assert_eq!(
      state.page_split_decision(false, DEFAULT_ORPHAN_LINES, DEFAULT_WIDOW_LINES),
      TextSplitDecision::Allowed
    );
  }

  #[test]
  fn keep_with_next_preflight_reserves_legal_follow_prefixes_and_chains() {
    let paragraph = |text: &str, widow_control: Option<bool>, keep_lines: bool| {
      let run = TextRun {
        text: text.to_string(),
        style: TextStyle::default(),
        hyperlink_url: None,
        dynamic_field: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        preserve_text_portion: false,
      };
      Paragraph {
        inlines: vec![InlineItem::Text(run.clone())],
        field_events: Vec::new(),
        footnote_reference_ids: Vec::new(),
        endnote_reference_ids: Vec::new(),
        starts_after_last_rendered_page_break: false,
        base_style: TextStyle::default(),
        runs: vec![run],
        format: Box::new(ParagraphFormat {
          widow_control,
          keep_lines,
          ..ParagraphFormat::default()
        }),
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        list_label: None,
        list_label_image: None,
        list_label_style: TextStyle::default(),
        list_label_hyperlink_url: None,
        list_label_tab_stop_pt: None,
      }
    };
    let flow = flow_from_block_area(BlockArea {
      setup: PageSetup::default(),
      section_index: 0,
      section_page_index: 0,
      column_index: 0,
      columns: SectionColumns::default(),
      content_top_pt: 72.0,
      content_left_pt: 72.0,
      content_bottom: 720.0,
      body_content_bottom_pt: 720.0,
      content_width: 468.0,
      default_tab_stop_pt: DEFAULT_TAB_STOP_PT,
      hyphenation: crate::docx::HyphenationSettings::default(),
      consecutive_hyphenated_lines: 0,
      compatibility_mode: 15,
      justify_lines_with_shrinking: false,
      do_not_expand_shift_return: false,
      suppress_top_spacing: false,
      split_page_break_and_paragraph_mark: false,
      repeating_slots: RepeatingSlotState::default(),
    });
    let mut text_metrics = TextMetrics::new();
    let three_lines = paragraph("one\ntwo\nthree", None, false);
    let widow_disabled = paragraph("one\ntwo\nthree", Some(false), false);
    let one_line = paragraph("one", None, false);
    let one_line_widow_disabled = paragraph("one", Some(false), false);
    let kept_three_lines = paragraph("one\ntwo\nthree", None, true);

    let two_line_prefix =
      estimated_paragraph_keep_start_height(&three_lines, flow, &mut text_metrics);
    let one_line_prefix =
      estimated_paragraph_keep_start_height(&widow_disabled, flow, &mut text_metrics);
    assert!(two_line_prefix > one_line_prefix + LAYOUT_EPSILON_PT);
    assert!(
      (estimated_paragraph_keep_start_height(&one_line, flow, &mut text_metrics)
        - estimated_paragraph_keep_start_height(&one_line_widow_disabled, flow, &mut text_metrics,))
      .abs()
        < LAYOUT_EPSILON_PT
    );
    assert!(
      estimated_paragraph_keep_start_height(&kept_three_lines, flow, &mut text_metrics)
        > two_line_prefix + LAYOUT_EPSILON_PT
    );

    // Native exact-height controls distinguish two headings kept with the
    // body from an ordinary adjacent pair. The pair fits this remaining
    // space, but keeping both headings with a legal body prefix does not.
    for middle_keep in [false, true] {
      let mut first = paragraph("H1", Some(false), false);
      first.format.keep_with_next = true;
      let mut second = paragraph("H2", Some(false), false);
      second.format.keep_with_next = middle_keep;
      let blocks = vec![
        Block::paragraph(first),
        Block::paragraph(second),
        Block::paragraph(three_lines.clone()),
      ];
      let pair_height =
        keep_group_height(&blocks[0], blocks.get(1), flow, &mut text_metrics, false);
      let chain = keep_with_next_chain(&blocks, 0, flow, &mut text_metrics);
      assert!(!chain.exceeds_page);
      assert_eq!(chain.remaining_height_pt.is_some(), middle_keep);
      if middle_keep {
        assert!(chain.remaining_height_pt.unwrap() > pair_height + 1.0);
      }
      let mut current = empty_section_page(flow.setup, 0, 0);
      current.items.push(PageItem::Rect(RectItem {
        x_pt: flow.content_left_pt,
        y_pt: flow.content_top_pt,
        width_pt: 1.0,
        height_pt: 1.0,
        paragraph_alignment_locked: false,
        fill_color: None,
        fill_opacity: 1.0,
        stroke: None,
        stroke_opacity: 1.0,
      }));
      let mut pages = Vec::new();
      prepare_block_flow(
        &blocks[0],
        blocks.get(1),
        FlowPosition {
          context: flow,
          y_pt: flow.content_bottom - pair_height - 0.5,
        },
        &mut current,
        &mut pages,
        &mut text_metrics,
        chain,
      );
      assert_eq!(pages.len(), usize::from(middle_keep));
    }

    // Native leading page/column break controls retain exactly the authored
    // transition, both when it starts the current kept paragraph and when
    // it separates the next paragraph from the incoming keep chain.
    for forced_index in [0, 1] {
      for break_kind in 0..3 {
        let mut first = paragraph("H1", Some(false), false);
        first.format.keep_with_next = true;
        let mut second = paragraph("H2", Some(false), false);
        second.format.keep_with_next = true;
        let forced = if forced_index == 0 {
          &mut first
        } else {
          &mut second
        };
        if break_kind == 2 {
          forced.format.page_break_before = true;
        } else {
          let mut empty_run = forced.runs[0].clone();
          empty_run.text.clear();
          forced.inlines.splice(
            0..0,
            [
              InlineItem::BookmarkStart("kept-heading".into()),
              InlineItem::Text(empty_run),
              InlineItem::LastRenderedPageBreak,
              if break_kind == 0 {
                InlineItem::PageBreak
              } else {
                InlineItem::ColumnBreak
              },
            ],
          );
        }
        let blocks = vec![
          Block::paragraph(first),
          Block::paragraph(second),
          Block::paragraph(three_lines.clone()),
        ];
        let chain = keep_with_next_chain(&blocks, 0, flow, &mut text_metrics);
        if forced_index == 1 {
          assert!(chain.remaining_height_pt.is_none());
        }
        let current_height = estimated_block_height(&blocks[0], flow, &mut text_metrics);
        let mut current = empty_section_page(flow.setup, 0, 0);
        current.items.push(PageItem::Rect(RectItem {
          x_pt: flow.content_left_pt,
          y_pt: flow.content_top_pt,
          width_pt: 1.0,
          height_pt: 1.0,
          paragraph_alignment_locked: false,
          fill_color: None,
          fill_opacity: 1.0,
          stroke: None,
          stroke_opacity: 1.0,
        }));
        let y_pt = flow.content_bottom - current_height - 0.5;
        let mut pages = Vec::new();
        let position = prepare_block_flow(
          &blocks[0],
          blocks.get(1),
          FlowPosition {
            context: flow,
            y_pt,
          },
          &mut current,
          &mut pages,
          &mut text_metrics,
          chain,
        );
        assert!(pages.is_empty());
        assert_eq!(position.y_pt, y_pt);
      }
    }
  }

  #[test]
  fn overfull_keep_with_next_chain_flows_instead_of_relocating_its_final_pair() {
    fn paragraph(text: &str, keep_with_next: bool) -> Block {
      let style = TextStyle {
        font_size_pt: 28.0,
        bold: true,
        ..TextStyle::default()
      };
      let run = TextRun {
        text: text.to_string(),
        style: style.clone(),
        hyperlink_url: None,
        dynamic_field: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        preserve_text_portion: false,
      };
      Block::paragraph(Paragraph {
        inlines: vec![InlineItem::Text(run.clone())],
        field_events: Vec::new(),
        footnote_reference_ids: Vec::new(),
        endnote_reference_ids: Vec::new(),
        starts_after_last_rendered_page_break: false,
        base_style: style,
        runs: vec![run],
        format: Box::new(ParagraphFormat {
          style_id: Some("Title".into()),
          spacing_before_pt: 12.0,
          spacing_after_pt: 6.0,
          keep_with_next,
          ..ParagraphFormat::default()
        }),
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        list_label: None,
        list_label_image: None,
        list_label_style: TextStyle::default(),
        list_label_hyperlink_url: None,
        list_label_tab_stop_pt: None,
      })
    }

    let setup = PageSetup {
      width_pt: 419.55,
      height_pt: 297.65,
      margin_top_pt: 56.7,
      margin_right_pt: 56.7,
      margin_bottom_pt: 56.7,
      margin_left_pt: 56.7,
      ..PageSetup::default()
    };
    let flow = flow_from_block_area(BlockArea {
      setup,
      section_index: 0,
      section_page_index: 0,
      column_index: 0,
      columns: SectionColumns::default(),
      content_top_pt: 56.7,
      content_left_pt: 56.7,
      content_bottom: setup.height_pt - setup.margin_bottom_pt,
      body_content_bottom_pt: setup.height_pt - setup.margin_bottom_pt,
      content_width: setup.width_pt - setup.margin_left_pt - setup.margin_right_pt,
      default_tab_stop_pt: DEFAULT_TAB_STOP_PT,
      hyphenation: crate::docx::HyphenationSettings::default(),
      consecutive_hyphenated_lines: 0,
      compatibility_mode: 15,
      justify_lines_with_shrinking: false,
      do_not_expand_shift_return: false,
      suppress_top_spacing: false,
      split_page_break_and_paragraph_mark: false,
      repeating_slots: RepeatingSlotState::default(),
    });
    let blocks = vec![
      paragraph("Default para style:\nStandard or Title?", true),
      paragraph("", true),
      paragraph("", true),
      paragraph("Title", false),
    ];
    let mut text_metrics = TextMetrics::new();
    for index in 0..blocks.len() {
      assert!(keep_with_next_chain(&blocks, index, flow, &mut text_metrics,).exceeds_page);
    }

    let mut shortened = blocks.clone();
    shortened.remove(1);
    for index in 0..shortened.len() {
      assert!(!keep_with_next_chain(&shortened, index, flow, &mut text_metrics,).exceeds_page);
    }
  }

  #[test]
  fn line_relative_word_text_frame_keeps_its_undodged_first_line_anchor() {
    assert!(first_line_word_text_frame_was_dodged_by_own_wrap(
      false, 56.7, 111.1, 111.1,
    ));
    assert!(!first_line_word_text_frame_was_dodged_by_own_wrap(
      true, 56.7, 111.1, 111.1,
    ));
    assert!(!first_line_word_text_frame_was_dodged_by_own_wrap(
      false, 56.7, 125.0, 111.1,
    ));
    assert!(!first_line_word_text_frame_was_dodged_by_own_wrap(
      false, 56.7, 56.7, 111.1,
    ));
  }

  #[test]
  fn explicit_page_break_preserves_alignment_of_each_paragraph_fragment() {
    for alignment in [
      ParagraphAlignment::Left,
      ParagraphAlignment::Center,
      ParagraphAlignment::Right,
    ] {
      let run = |text: &str| {
        InlineItem::Text(TextRun {
          text: text.into(),
          style: TextStyle::default(),
          hyperlink_url: None,
          dynamic_field: None,
          style_ref_keys: Vec::new(),
          style_ref_text: None,
          style_ref_numbering_text: None,
          preserve_text_portion: false,
        })
      };
      let paragraph = Paragraph {
        inlines: vec![
          run("first"),
          InlineItem::PageBreak,
          run("second"),
          InlineItem::PageBreak,
          run("third"),
        ],
        field_events: Vec::new(),
        footnote_reference_ids: Vec::new(),
        endnote_reference_ids: Vec::new(),
        starts_after_last_rendered_page_break: false,
        base_style: TextStyle::default(),
        runs: Vec::new(),
        format: Box::new(ParagraphFormat {
          alignment,
          ..ParagraphFormat::default()
        }),
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        list_label: None,
        list_label_image: None,
        list_label_style: TextStyle::default(),
        list_label_hyperlink_url: None,
        list_label_tab_stop_pt: None,
      };
      let flow = flow_context(
        PageSetup::default(),
        0,
        SectionColumns::default(),
        0,
        0,
        DEFAULT_TAB_STOP_PT,
      );
      let mut current = empty_page(flow.setup, flow.section_index);
      // Earlier paragraph items must never become part of this alignment.
      current.items.push(PageItem::Rect(RectItem {
        x_pt: 7.0,
        y_pt: 4.0,
        width_pt: 5.0,
        height_pt: 3.0,
        paragraph_alignment_locked: false,
        fill_color: None,
        fill_opacity: 1.0,
        stroke: None,
        stroke_opacity: 1.0,
      }));
      let mut pages = Vec::new();
      let mut metrics = TextMetrics::new();
      layout_paragraph(
        &paragraph,
        flow,
        ParagraphLayoutTarget {
          current: &mut current,
          pages: &mut pages,
          anchor_pages: None,
          text_metrics: &mut metrics,
        },
        flow.content_top_pt,
        flow.content_top_pt,
        0.0,
      );
      pages.push(current);
      assert_eq!(pages.len(), 3);
      let PageItem::Rect(sentinel) = &pages[0].items[0] else {
        panic!("preceding item");
      };
      assert_eq!(sentinel.x_pt, 7.0);
      for (page, expected_text) in pages.iter().zip(["first", "second", "third"]) {
        let texts = page
          .items
          .iter()
          .filter_map(|item| match item {
            PageItem::Text(text) => Some(text),
            _ => None,
          })
          .collect::<Vec<_>>();
        assert_eq!(texts.len(), 1);
        let text = texts[0];
        assert_eq!(text.text, expected_text);
        let width = metrics.measure_text(&text.text, &text.style);
        let factor = match alignment {
          ParagraphAlignment::Left => 0.0,
          ParagraphAlignment::Center => 0.5,
          ParagraphAlignment::Right => 1.0,
          ParagraphAlignment::Justify => unreachable!(),
        };
        let expected = flow.content_left_pt + (flow.content_width - width) * factor;
        assert!(
          (text.x_pt - expected).abs() < 0.01,
          "{alignment:?} {expected_text}: actual {}, expected {expected}",
          text.x_pt
        );
      }
    }
  }

  #[test]
  fn leading_page_break_preserves_the_paragraphs_first_line_hanging_indent() {
    let run = |text: &str| {
      InlineItem::Text(TextRun {
        text: text.into(),
        style: TextStyle::default(),
        hyperlink_url: None,
        dynamic_field: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        preserve_text_portion: false,
      })
    };
    let flow = flow_context(
      PageSetup::default(),
      0,
      SectionColumns::default(),
      0,
      0,
      DEFAULT_TAB_STOP_PT,
    );
    for (has_prior_text, expected_indent) in [(false, 36.0), (true, 90.0)] {
      let mut inlines = Vec::new();
      if has_prior_text {
        inlines.push(run("prior"));
      }
      inlines.push(InlineItem::PageBreak);
      inlines.push(run("Heading 4"));
      let paragraph = Paragraph {
        inlines,
        field_events: Vec::new(),
        footnote_reference_ids: Vec::new(),
        endnote_reference_ids: Vec::new(),
        starts_after_last_rendered_page_break: false,
        base_style: TextStyle::default(),
        runs: Vec::new(),
        format: Box::new(ParagraphFormat {
          indent_left_pt: 90.0,
          first_line_indent_pt: -54.0,
          indent_left_set: true,
          first_line_indent_set: true,
          ..Default::default()
        }),
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        list_label: None,
        list_label_image: None,
        list_label_style: TextStyle::default(),
        list_label_hyperlink_url: None,
        list_label_tab_stop_pt: None,
      };
      let mut current = empty_page(flow.setup, flow.section_index);
      let mut pages = Vec::new();
      let mut metrics = TextMetrics::new();
      layout_paragraph(
        &paragraph,
        flow,
        ParagraphLayoutTarget {
          current: &mut current,
          pages: &mut pages,
          anchor_pages: None,
          text_metrics: &mut metrics,
        },
        flow.content_top_pt,
        flow.content_top_pt,
        0.0,
      );
      pages.push(current);
      assert_eq!(pages.len(), 2);
      let heading = pages[1]
        .items
        .iter()
        .find_map(|item| match item {
          PageItem::Text(text) if text.text == "Heading 4" => Some(text),
          _ => None,
        })
        .expect("heading after page break");
      assert!(
        (heading.x_pt - (flow.content_left_pt + expected_indent)).abs() < 0.01,
        "has_prior_text={has_prior_text}: heading x={} expected indent={expected_indent}",
        heading.x_pt
      );
    }
  }

  #[test]
  fn page_break_preserves_bidi_first_line_geometry_and_tab_capacity() {
    let style = TextStyle {
      font_family: Some(Arc::from("Times New Roman")),
      font_size_pt: 14.0,
      character_spacing_pt: -0.1,
      ..Default::default()
    };
    let run = |text: &str| {
      InlineItem::Text(TextRun {
        text: text.into(),
        style: style.clone(),
        hyperlink_url: None,
        dynamic_field: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        preserve_text_portion: false,
      })
    };
    let flow = flow_context(
      PageSetup::default(),
      0,
      SectionColumns::default(),
      0,
      0,
      DEFAULT_TAB_STOP_PT,
    );
    let mut paragraph = Paragraph {
      inlines: Vec::new(),
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: style.clone(),
      runs: Vec::new(),
      format: Box::new(ParagraphFormat {
        indent_left_pt: 90.0,
        indent_right_pt: 40.0,
        indent_left_set: true,
        indent_right_set: true,
        first_line_indent_set: true,
        line_height_rule: LineHeightRule::Exact,
        line_height_pt: Some(18.0),
        widow_control: Some(false),
        ..Default::default()
      }),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: style.clone(),
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    };
    let mut metrics = TextMetrics::new();
    let mut positions = |paragraph: &Paragraph, expected_pages| {
      let mut current = empty_page(flow.setup, flow.section_index);
      let mut pages = Vec::new();
      layout_paragraph(
        paragraph,
        flow,
        ParagraphLayoutTarget {
          current: &mut current,
          pages: &mut pages,
          anchor_pages: None,
          text_metrics: &mut metrics,
        },
        flow.content_top_pt,
        flow.content_top_pt,
        0.0,
      );
      pages.push(current);
      assert_eq!(pages.len(), expected_pages);
      let mut texts = pages
        .into_iter()
        .flat_map(|page| page.items)
        .filter_map(|item| match item {
          PageItem::Text(text) if !text.text.trim().is_empty() && text.text.trim() != "قبل" => {
            Some((text.text, text.x_pt, text.y_pt, text.word_spacing_pt))
          }
          _ => None,
        })
        .collect::<Vec<_>>();
      let first_y = texts[0].2;
      for text in &mut texts {
        text.2 -= first_y;
      }
      assert!(texts.iter().any(|text| text.2 > LAYOUT_EPSILON_PT));
      texts
    };
    for bidi in [false, true] {
      paragraph.format.bidi = bidi;
      for first_indent in [-54.0, 0.0, 54.0] {
        paragraph.format.first_line_indent_pt = first_indent;
        for adjust in [
          crate::docx::ParagraphAdjust::Block,
          crate::docx::ParagraphAdjust::Right,
        ] {
          paragraph.format.justification.adjust = adjust;
          paragraph.format.alignment = paragraph.format.justification.alignment();
          for tabs in ["", "\t\t\t"] {
            let heading = run(&format!(
              "{tabs}التقريران المدمجان السادس والسابع لبنغلاديش عن تنفيذ اتفاقية القضاء على جميع أشكال التمييز ضد المرأة (2001-2009)"
            ));
            for has_prior_text in [false, true] {
              // Office retains first-line geometry after a leading page
              // break. After visible text, the page follow instead matches
              // an ordinary subsequent line in the same paragraph.
              paragraph.inlines = if has_prior_text {
                vec![run("قبل\n"), heading.clone()]
              } else {
                vec![heading.clone()]
              };
              let expected = positions(&paragraph, 1);
              paragraph.inlines = if has_prior_text {
                vec![run("قبل"), InlineItem::PageBreak, heading.clone()]
              } else {
                vec![InlineItem::PageBreak, heading.clone()]
              };
              let actual = positions(&paragraph, 2);
              assert_eq!(actual.len(), expected.len());
              for (actual, expected) in actual.iter().zip(&expected) {
                assert_eq!(actual.0, expected.0);
                assert!(
                  (actual.1 - expected.1).abs() < 0.001
                    && (actual.2 - expected.2).abs() < 0.001
                    && (actual.3 - expected.3).abs() < 0.001,
                  "bidi={bidi}, indent={first_indent}, {adjust:?}, tabs={tabs:?}, prior={has_prior_text}: {actual:?} != {expected:?}"
                );
              }
            }
          }
        }
      }
    }
  }

  #[test]
  fn cached_body_page_boundaries_preserve_ordinary_text_flow() {
    let style = TextStyle {
      font_family: Some("Times New Roman".into()),
      font_size_pt: 12.0,
      ..Default::default()
    };
    let run = |text: &str| {
      InlineItem::Text(TextRun {
        text: text.into(),
        style: style.clone(),
        hyperlink_url: None,
        dynamic_field: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        preserve_text_portion: false,
      })
    };
    let paragraph = |inlines, after, widow, starts_after_last_rendered_page_break| Paragraph {
      inlines,
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break,
      base_style: style.clone(),
      runs: Vec::new(),
      format: Box::new(ParagraphFormat {
        alignment: ParagraphAlignment::Justify,
        justification: crate::docx::ParagraphJustification {
          adjust: crate::docx::ParagraphAdjust::Block,
          ..Default::default()
        },
        line_height_rule: LineHeightRule::Exact,
        line_height_pt: Some(14.0),
        spacing_after_pt: after,
        widow_control: Some(widow),
        ..Default::default()
      }),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: style.clone(),
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    };

    let render_columns = |blocks: &[Block], width: f32, count: usize| {
      let setup = PageSetup {
        width_pt: width * count as f32 + (count - 1) as f32 * 24.0 + 72.0,
        height_pt: 142.0,
        margin_top_pt: 36.0,
        margin_bottom_pt: 36.0,
        margin_left_pt: 36.0,
        margin_right_pt: 36.0,
        ..Default::default()
      };
      let mut flow = flow_context(
        setup,
        0,
        SectionColumns {
          count,
          gap_pt: 24.0,
          ..SectionColumns::default()
        },
        0,
        0,
        DEFAULT_TAB_STOP_PT,
      );
      flow.compatibility_mode = 14;
      let mut current = empty_page(setup, 0);
      let mut pages = Vec::new();
      let mut metrics = TextMetrics::new();
      let mut y = flow.content_top_pt;
      for (index, block) in blocks.iter().enumerate() {
        (flow, y) = layout_document_block(
          index.checked_sub(1).map(|index| &blocks[index]),
          block,
          None,
          flow,
          LayoutBlockTarget {
            current: &mut current,
            pages: &mut pages,
            anchor_pages: None,
            text_metrics: &mut metrics,
            paragraph_decoration_outer_bottom_pt: None,
          },
          y,
        );
      }
      pages.push(current);
      pages
    };
    let render = |blocks: &[Block], width| render_columns(blocks, width, 1);
    let text_positions = |pages: &[Page]| {
      pages
        .iter()
        .map(|page| {
          page
            .items
            .iter()
            .filter_map(|item| match item {
              PageItem::Text(text) => Some((
                text.text.clone(),
                text.x_pt,
                text.y_pt,
                text.word_spacing_pt,
              )),
              _ => None,
            })
            .collect::<Vec<_>>()
        })
        .collect::<Vec<_>>()
    };

    // Native Word controls: five exact14pt lines in70pt. Cached markers
    // between words and inside Ego-States leave natural wraps unchanged.
    for width in [60.0, 90.0, 180.0, 288.0] {
      for (left, right, expected_pages) in [
        ("first last", " follow", if width == 60.0 { 2 } else { 1 }),
        (
          "Ego-",
          "States erfolgt jetzt in",
          if width <= 90.0 { 2 } else { 1 },
        ),
      ] {
        let mut layouts = Vec::new();
        for marker in [
          None,
          Some(InlineItem::LastRenderedPageBreak),
          Some(InlineItem::PageBreak),
        ] {
          let mut inlines = vec![run(&format!("a\na\na\na\n{left}"))];
          if let Some(marker) = marker {
            inlines.push(marker);
          }
          inlines.push(run(right));
          layouts.push(render(
            &[Block::paragraph(paragraph(inlines, 0.0, false, false))],
            width,
          ));
        }
        assert_eq!(
          layouts[0].len(),
          expected_pages,
          "width={width}, left={left}"
        );
        assert_eq!(
          text_positions(&layouts[0]),
          text_positions(&layouts[1]),
          "cached boundary must preserve natural flow: width={width}, left={left}"
        );
        assert_eq!(
          layouts[2].len(),
          2,
          "an authored break still owns its follow"
        );
        let authored_master: String = text_positions(&layouts[2])[0]
          .iter()
          .map(|text| text.0.as_str())
          .collect();
        assert!(!authored_master.contains(right.trim()));
      }
    }
    // Native markers inside the final line of either column leave the word
    // and line intact; a saved pagination cache must not finish that line.
    for leading_lines in [4, 9] {
      for width in [90.0, 180.0] {
        let mut layouts = Vec::new();
        for cached in [false, true] {
          let mut inlines = vec![run(&format!("{}LI", "a\n".repeat(leading_lines)))];
          if cached {
            inlines.push(InlineItem::LastRenderedPageBreak);
          }
          inlines.push(run("NE follow"));
          layouts.push(render_columns(
            &[Block::paragraph(paragraph(inlines, 0.0, false, false))],
            width,
            2,
          ));
        }
        assert_eq!(
          text_positions(&layouts[0]),
          text_positions(&layouts[1]),
          "cached column line: width={width}, preceding={leading_lines}"
        );
      }
    }
    // Native leading-marker controls: four14pt lines followed by one14pt
    // paragraph. Positive lower spacing does not push its fitting text line.
    for after in [0.0, 10.0, 30.0] {
      for widow in [false, true] {
        let mut layouts = Vec::new();
        for marker in [
          None,
          Some(InlineItem::LastRenderedPageBreak),
          Some(InlineItem::PageBreak),
        ] {
          let first = Block::paragraph(paragraph(vec![run("a\na\na\na")], 0.0, false, false));
          let cached = matches!(marker, Some(InlineItem::LastRenderedPageBreak));
          let mut inlines = Vec::new();
          if let Some(marker) = marker {
            inlines.push(marker);
          }
          inlines.push(run("Literatur:"));
          let second = Block::paragraph(paragraph(inlines, after, widow, cached));
          layouts.push(render(&[first, second], 180.0));
        }
        assert_eq!(layouts[0].len(), 1, "after={after}, widow={widow}");
        assert_eq!(
          text_positions(&layouts[0]),
          text_positions(&layouts[1]),
          "leading cache must preserve a fitting line: after={after}, widow={widow}"
        );
        assert_eq!(
          layouts[2].len(),
          2,
          "an authored break still owns its follow"
        );
      }
    }
  }

