  #[test]
  fn cross_run_numeric_separator_breaks_follow_run_direction() {
    fn run(text: &str, direction: Option<bool>, size: f32) -> InlineItem {
      InlineItem::Text(TextRun {
        text: text.into(),
        style: TextStyle {
          font_family: Some(Arc::from("Times New Roman")),
          font_size_pt: size,
          right_to_left: direction,
          ..TextStyle::default()
        },
        hyperlink_url: None,
        dynamic_field: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        preserve_text_portion: false,
      })
    }
    let mut metrics = TextMetrics::new();
    for separator in [":", ".", ",", "\u{00A0}", "\u{202F}"] {
      for direction in [None, Some(false), Some(true)] {
        for next_direction in [Some(false), Some(true)] {
          for size in [8.0, 12.0] {
            for split_digits in [false, true] {
              let mut inlines = vec![
                run("100", Some(true), 12.0),
                run(separator, direction, size),
              ];
              if split_digits {
                for digit in ["1", "0", "0"] {
                  inlines.push(run(digit, next_direction, 12.0));
                }
              } else {
                inlines.push(run("100", next_direction, 12.0));
              }
              let continuation =
                cross_run_unbreakable_continuation_width(&inlines, 0, "100", &mut metrics)
                  .expect("number separator remains attached to the preceding number");
              let foreign_region = direction != Some(true)
                && next_direction == Some(true)
                && !separator.chars().all(char::is_whitespace);
              let expected_end = if foreign_region {
                InlineCursor {
                  inline_index: 1,
                  text_offset: separator.len(),
                }
              } else {
                InlineCursor {
                  inline_index: inlines.len() - 1,
                  text_offset: if split_digits { 1 } else { 3 },
                }
              };
              assert_eq!(
                continuation.source_end, expected_end,
                "separator={separator:?}, direction={direction:?}, next={next_direction:?}, size={size}, split={split_digits}"
              );
              let following =
                cross_run_unbreakable_continuation_width(&inlines, 1, separator, &mut metrics);
              assert_eq!(following.is_none(), foreign_region);
            }
          }
        }
      }
    }
  }

  #[test]
  fn smart_justify_cross_run_continuation_distinguishes_punctuation_words_and_fields() {
    fn run(text: &str, field_group: bool) -> InlineItem {
      InlineItem::Text(TextRun {
        text: text.to_string(),
        style: TextStyle {
          wordprocessingml_field_group: field_group,
          ..TextStyle::default()
        },
        hyperlink_url: None,
        dynamic_field: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        preserve_text_portion: false,
      })
    }

    let mut text_metrics = TextMetrics::new();
    let punctuation_runs = vec![
      run("Hathaway", false),
      run(", ", false),
      run("haziness", false),
    ];
    let punctuation =
      cross_run_unbreakable_continuation_width(&punctuation_runs, 0, "Hathaway", &mut text_metrics)
        .expect("following comma portion");
    assert!(punctuation.western_forbidden_line_start_only);
    assert!(punctuation.outside_field_group);
    assert_eq!(
      punctuation.source_start,
      InlineCursor {
        inline_index: 1,
        text_offset: 0,
      }
    );
    assert_eq!(
      punctuation.source_end,
      InlineCursor {
        inline_index: 1,
        text_offset: 2,
      }
    );
    assert!(
      (punctuation.fit_width_pt - text_metrics.measure_text(",", &TextStyle::default())).abs()
        < LAYOUT_EPSILON_PT
    );

    for postfix in ["% ", "‰ "] {
      let numeric_runs = vec![run("2", false), run(postfix, false), run("next", false)];
      let numeric =
        cross_run_unbreakable_continuation_width(&numeric_runs, 0, "2", &mut text_metrics)
          .expect("attached numeric postfix");
      assert!(numeric.western_forbidden_line_start_only);
      assert!(numeric.numeric_postfix_only);
      assert!(numeric.outside_field_group);
    }

    let split_word_runs = vec![
      run("Hatha", false),
      run("way ", false),
      run("haziness", false),
    ];
    let split_word =
      cross_run_unbreakable_continuation_width(&split_word_runs, 0, "Hatha", &mut text_metrics)
        .expect("alphabetic continuation");
    assert!(!split_word.western_forbidden_line_start_only);

    for (first, separator) in [("Scholar", " · "), ("Scholar ", "· ")] {
      let dot_runs = vec![
        run(first, false),
        run(separator, false),
        run("View at", false),
      ];
      let dot = cross_run_unbreakable_continuation_width(&dot_runs, 0, first, &mut text_metrics)
        .expect("middle dot connects the next word across spaces and run boundaries");
      assert_eq!(
        dot.source_end,
        InlineCursor {
          inline_index: 2,
          text_offset: 5
        }
      );
      assert!(
        (dot.fit_width_pt
          - text_metrics.measure_text(&format!("{separator}View"), &TextStyle::default()))
        .abs()
          < LAYOUT_EPSILON_PT
      );
    }

    for (first, separator) in [("Panikattacken", "…"), ("Panikattacken ", "…")] {
      let ellipsis_runs = vec![
        run(first, false),
        run(separator, false),
        run("die Krankheit", false),
      ];
      let continuation =
        cross_run_unbreakable_continuation_width(&ellipsis_runs, 0, first, &mut text_metrics)
          .expect("ellipsis connects the following Western word across formatting runs");
      assert_eq!(
        continuation.source_end,
        InlineCursor {
          inline_index: 2,
          text_offset: "die ".len(),
        },
      );
      assert!(!continuation.western_forbidden_line_start_only);
      assert!(
        (continuation.fit_width_pt - text_metrics.measure_text("…die", &TextStyle::default()))
          .abs()
          < LAYOUT_EPSILON_PT,
      );
    }

    let dash_runs = vec![
      run("order", false),
      run("—even ", false),
      run("omega", false),
    ];
    let modern_dash =
      cross_run_unbreakable_continuation_width(&dash_runs, 0, "order", &mut text_metrics)
        .expect("modern em-dash continuation");
    assert!(
      (modern_dash.fit_width_pt - text_metrics.measure_text("—", &TextStyle::default())).abs()
        < LAYOUT_EPSILON_PT
    );
    let word_2007_dash = cross_run_unbreakable_continuation_width_for_break_options(
      &dash_runs,
      0,
      "order",
      WordprocessingLineBreakOptions {
        compatibility_mode: 12,
        compress_punctuation: true,
        strict_japanese: false,
        kashida: false,
      },
      None,
      &mut text_metrics,
    )
    .expect("Word 2007 dash-connected token continuation");
    assert!(
      (word_2007_dash.fit_width_pt - text_metrics.measure_text("—even", &TextStyle::default()))
        .abs()
        < LAYOUT_EPSILON_PT
    );
    assert_eq!(
      word_2007_dash.source_end,
      InlineCursor {
        inline_index: 1,
        text_offset: "—even ".len(),
      }
    );

    let field_runs = vec![
      run("Hathaway", false),
      run(", ", true),
      run("haziness", false),
    ];
    let field_punctuation =
      cross_run_unbreakable_continuation_width(&field_runs, 0, "Hathaway", &mut text_metrics)
        .expect("field punctuation continuation");
    assert!(!field_punctuation.outside_field_group);
  }

  #[test]
  fn smart_justify_fits_the_current_portion_before_its_terminal_punctuation_portion() {
    fn text_item(x_pt: f32, text: &str, style: &TextStyle) -> PageItem {
      PageItem::Text(Box::new(TextItem {
        x_pt,
        y_pt: 20.0,
        line_height_pt: DEFAULT_LINE_HEIGHT_PT,
        wordprocessing_auto_line_spacing_units: None,
        wordprocessing_line_metrics: None,
        origin_is_baseline: false,
        line_metrics_participant: true,
        paint_clip: None,
        wordprocessing_effect_host: None,
        wordprocessing_terminal_effect_style: None,
        text: text.to_string(),
        style: style.clone(),
        rotation_center_pt: None,
        hyperlink_url: None,
        dynamic_field: None,
        dynamic_field_line_anchor: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        form_widget_id: None,
        paragraph_bidi: false,
        word_spacing_pt: 0.0,
        preserve_text_portion: false,
        decoration_span_start_x_pt: None,
        pdf_text_segmentation: PdfTextSegmentation::Line,
      }))
    }

    let mut text_metrics = TextMetrics::new();
    let style = TextStyle::default();
    let prefix = "one two three four ";
    let candidate = "Hathaway";
    let prefix_width = text_metrics.measure_text(prefix, &style);
    let candidate_width = text_metrics.measure_text(candidate, &style);
    let punctuation_width = text_metrics.measure_text(",", &style);
    let space_width = text_metrics.measure_text(" ", &style);
    let line_right = prefix_width + candidate_width - space_width * 0.8;
    let word_spacing = crate::docx::JustificationWordSpacing {
      desired_pct: 100,
      minimum_pct: 75,
      maximum_pct: 150,
    };

    assert!(line_fits_with_word_space_shrink(
      LineShrinkFit {
        x: prefix_width,
        width: candidate_width,
        text: candidate,
        line_right,
        items: &[],
        item_start: 0,
        chunk: prefix,
        style: &style,
        word_spacing,
      },
      &mut text_metrics,
    ));
    assert!(!line_fits_with_word_space_shrink(
      LineShrinkFit {
        x: prefix_width,
        width: candidate_width + punctuation_width,
        text: candidate,
        line_right,
        items: &[],
        item_start: 0,
        chunk: prefix,
        style: &style,
        word_spacing,
      },
      &mut text_metrics,
    ));
    assert_eq!(
      smart_justify_fit_terminal_overhang(
        LineShrinkFit {
          x: prefix_width,
          width: candidate_width + punctuation_width,
          text: candidate,
          line_right,
          items: &[],
          item_start: 0,
          chunk: prefix,
          style: &style,
          word_spacing,
        },
        punctuation_width,
        false,
        &mut text_metrics,
      ),
      Some(punctuation_width)
    );

    let full_candidate_line_right = line_right + punctuation_width;
    assert_eq!(
      smart_justify_fit_terminal_overhang(
        LineShrinkFit {
          x: prefix_width,
          width: candidate_width + punctuation_width,
          text: candidate,
          line_right: full_candidate_line_right,
          items: &[],
          item_start: 0,
          chunk: prefix,
          style: &style,
          word_spacing,
        },
        punctuation_width,
        false,
        &mut text_metrics,
      ),
      Some(0.0)
    );

    let mut items = vec![
      text_item(0.0, prefix, &style),
      text_item(prefix_width, candidate, &style),
      text_item(prefix_width + candidate_width, ", ", &style),
    ];
    justify_line_items(
      &mut items,
      LineJustificationContext {
        item_start: 0,
        y_pt: 20.0,
        left_pt: 0.0,
        right_pt: line_right,
        terminal_overhang_pt: punctuation_width,
        source_frame_right_pt: None,
        preserve_foreign_tail: false,
      },
      crate::docx::ParagraphJustification::default(),
      &mut text_metrics,
    );
    let PageItem::Text(word) = &items[1] else {
      panic!("candidate word item");
    };
    let PageItem::Text(punctuation) = &items[2] else {
      panic!("terminal punctuation item");
    };
    assert!((word.x_pt + candidate_width - line_right).abs() < LAYOUT_EPSILON_PT);
    assert!((punctuation.x_pt - line_right).abs() < LAYOUT_EPSILON_PT);
  }

  #[test]
  fn smart_justify_hangs_current_portion_terminal_punctuation_after_shrinking() {
    let mut text_metrics = TextMetrics::new();
    let style = TextStyle::default();
    let prefix = "one two three four five six seven ";
    let candidate = "vel. ";
    let overflow_punctuation = WordprocessingOverflowPunctuationPolicy {
      enabled: true,
      allow_legacy_western: false,
      inside_field_group: false,
      preceding_language: WordprocessingTextLanguage::Unknown,
    };
    let prefix_width = text_metrics.measure_text(prefix, &style);
    let candidate_width = appended_line_fit_width(
      prefix,
      candidate,
      &style,
      overflow_punctuation,
      &mut text_metrics,
    );
    let punctuation = smart_justify_western_terminal_punctuation(
      prefix,
      candidate,
      &style,
      overflow_punctuation,
      &mut text_metrics,
    )
    .expect("terminal punctuation");
    let punctuation_width = punctuation.width_pt;
    let space_width = text_metrics.measure_text(" ", &style);
    assert!((punctuation_width - text_metrics.measure_text(".", &style)).abs() < 0.01);
    assert!(
      smart_justify_western_terminal_punctuation(
        prefix,
        "velocity ",
        &style,
        overflow_punctuation,
        &mut text_metrics,
      )
      .is_none()
    );

    let word_spacing = crate::docx::JustificationWordSpacing {
      desired_pct: 100,
      minimum_pct: 75,
      maximum_pct: 150,
    };
    let shrink_capacity = 7.0 * space_width * 0.25;
    let full_overflow = shrink_capacity + punctuation_width * 0.5;
    let line_right = prefix_width + candidate_width - full_overflow;
    assert!(!line_fits_with_word_space_shrink(
      LineShrinkFit {
        x: prefix_width,
        width: candidate_width,
        text: candidate,
        line_right,
        items: &[],
        item_start: 0,
        chunk: prefix,
        style: &style,
        word_spacing,
      },
      &mut text_metrics,
    ));
    assert!(line_fits_with_word_space_shrink(
      LineShrinkFit {
        x: prefix_width,
        width: candidate_width - punctuation_width,
        text: candidate,
        line_right,
        items: &[],
        item_start: 0,
        chunk: prefix,
        style: &style,
        word_spacing,
      },
      &mut text_metrics,
    ));
  }

  #[test]
  fn smart_justify_compares_normal_expansion_with_candidate_shrink() {
    let line_right = 100.0;
    let space_width = 10.0;
    let normal_space_count = 7;
    let terminal_space_count = 1;
    let shrink_space_count = 8;
    let comparison = |normal_ratio: f32, shrink_ratio: f32| {
      let original_printable_right =
        line_right - normal_space_count as f32 * space_width * (normal_ratio - 1.0);
      SmartJustifyComparison {
        original_x_pt: original_printable_right + terminal_space_count as f32 * space_width,
        candidate_right_pt: line_right
          + shrink_space_count as f32 * space_width * (1.0 - shrink_ratio),
        line_right_pt: line_right,
        normal_space_count,
        terminal_space_count,
        shrink_space_count,
        space_width_pt: space_width,
        minimum_ratio: 0.75,
        maximum_ratio: 1.5,
      }
    };

    // The old break consumes 40% of its expansion range, whereas the new
    // break would consume 64% of its contraction range.
    assert!(!smart_justify_prefers_shrinking(comparison(1.2, 0.84)));
    // At 140% the old break consumes 80%, so the same contraction is better.
    assert!(smart_justify_prefers_shrinking(comparison(1.4, 0.84)));
  }

  #[test]
  fn smart_justify_matches_native_preference_boundaries() {
    // Native fixed-format outputs bracket each decision by one twip. All
    // candidates fit at 75% spacing; these observations test which fitting
    // candidate is preferred, separately from the maximum shrink capacity.
    // The source prefix has eight ordinary spaces and one trailing separator.
    for (candidate_width, lower, upper) in [
      (3.996_093_8, 460.55, 460.6), // I
      (6.0, 461.85, 461.9),         // 1
      (7.992_187_5, 463.1, 463.15), // II
      (12.0, 465.65, 465.7),        // 11
      (11.988_281, 465.65, 465.7),  // III
      (15.0, 467.6, 467.65),        // 1.1
    ] {
      for (line_right, retained) in [(lower, false), (upper, true)] {
        assert_eq!(
          smart_justify_prefers_shrinking(SmartJustifyComparison {
            original_x_pt: 459.093_75,
            candidate_right_pt: 459.093_75 + candidate_width,
            line_right_pt: line_right,
            normal_space_count: 8,
            terminal_space_count: 1,
            shrink_space_count: 9,
            space_width_pt: 3.0,
            minimum_ratio: 0.75,
            maximum_ratio: 1.5,
          }),
          retained,
          "candidate={candidate_width}, width={line_right}"
        );
      }
    }
  }

  #[test]
  fn numeric_postfix_uses_native_full_fit_then_hanging_retry() {
    let mut metrics = TextMetrics::new();
    let style = TextStyle {
      font_family: Some(Arc::from("Times New Roman")),
      high_ansi_font_family: Some(Arc::from("Times New Roman")),
      font_size_pt: 12.0,
      kerning_minimum_size_pt: Some(100.0),
      ligatures: Some(crate::common::OpenTypeLigatures::default()),
      use_windows_font_metrics: true,
      ..Default::default()
    };
    let prefix =
      "Государственный заказчик выплачивает Подрядчику неустойку в виде штрафа в размере ";
    let prefix_width = metrics.measure_text(prefix, &style);
    let word_spacing = crate::docx::JustificationWordSpacing {
      desired_pct: 100,
      minimum_pct: 75,
      maximum_pct: 150,
    };
    // Actual MSLS70 observations: the original 467.7pt line expands its ten
    // spaces by a total 2.0495605pt and hangs '%'. At +1pt it contracts them
    // by 6.946533pt, retaining the complete token inside the text extent.
    for (postfix, deltas) in [
      ("%", &[-2.0, -1.0, 0.0, 1.0, 2.0][..]),
      ("‰", &[-1.0, 0.0, 1.0][..]),
    ] {
      let postfix_width = metrics.measure_text(postfix, &style);
      for delta in deltas {
        let result = smart_justify_fit_terminal_overhang(
          LineShrinkFit {
            x: prefix_width,
            width: metrics.measure_text("2", &style) + postfix_width,
            text: "2",
            line_right: 467.7 + delta,
            items: &[],
            item_start: 0,
            chunk: prefix,
            style: &style,
            word_spacing,
          },
          postfix_width,
          true,
          &mut metrics,
        );
        assert_eq!(
          result,
          Some(if postfix == "%" && *delta >= 1.0 {
            0.0
          } else {
            postfix_width
          }),
          "{postfix} width delta={delta}"
        );
      }
    }
    // An alphabetic continuation has no postfix overhang. The native -1/0pt
    // controls retain the old break; only +1pt chooses full-word contraction.
    let width = metrics.measure_text("2X", &style);
    for (delta, expected) in [(-1.0, None), (0.0, None), (1.0, Some(0.0))] {
      assert_eq!(
        smart_justify_fit_terminal_overhang(
          LineShrinkFit {
            x: prefix_width,
            width,
            text: "2",
            line_right: 467.7 + delta,
            items: &[],
            item_start: 0,
            chunk: prefix,
            style: &style,
            word_spacing,
          },
          0.0,
          false,
          &mut metrics,
        ),
        expected,
        "alphabetic width delta={delta}"
      );
    }
  }

  #[test]
  fn word_compat_justified_line_shrink_counts_separator_and_stops_at_twenty_percent() {
    let mut text_metrics = TextMetrics::new();
    let mut style = TextStyle::default();
    crate::docx::quantize_word_fixed_output_text_style(&mut style);
    let space_width = text_metrics.measure_text(" ", &style);
    let line_right = 100.0;
    let shrink_capacity = 2.0 * space_width * 0.20;
    let word_spacing = crate::docx::JustificationWordSpacing {
      desired_pct: 100,
      minimum_pct: 80,
      maximum_pct: 150,
    };
    let fit = |overflow| LineShrinkFit {
      x: 0.0,
      width: line_right + overflow,
      text: "three",
      line_right,
      items: &[],
      item_start: 0,
      chunk: "one two ",
      style: &style,
      word_spacing,
    };

    assert!(line_fits_with_word_space_shrink(
      fit(shrink_capacity * 0.999),
      &mut text_metrics,
    ));
    assert!(!line_fits_with_word_space_shrink(
      fit(shrink_capacity * 1.001),
      &mut text_metrics,
    ));
  }

  #[test]
  fn smart_justify_breaks_at_native_logical_width_boundaries() {
    fn paragraph(text: &str, style_id: &str, before: f32, after: f32) -> Paragraph {
      Paragraph {
        inlines: vec![InlineItem::Text(TextRun {
          text: text.into(),
          style: TextStyle::default(),
          hyperlink_url: None,
          dynamic_field: None,
          style_ref_keys: Vec::new(),
          style_ref_text: None,
          style_ref_numbering_text: None,
          preserve_text_portion: false,
        })],
        field_events: Vec::new(),
        footnote_reference_ids: Vec::new(),
        endnote_reference_ids: Vec::new(),
        starts_after_last_rendered_page_break: false,
        base_style: TextStyle::default(),
        #[cfg(test)]
        runs: Vec::new(),
        format: Box::new(ParagraphFormat {
          style_id: Some(style_id.into()),
          spacing_before_pt: before,
          spacing_after_pt: after,
          ..Default::default()
        }),
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        list_label: None,
        list_label_image: None,
        list_label_style: TextStyle::default(),
        list_label_hyperlink_url: None,
        list_label_tab_stop_pt: None,
      }
    }
    // Native Word Print controls. Each pair brackets the observed break by
    // one twip; values are fixed observations, not recomputed from our metrics.
    let texts = [
      "безналичных перечислений в соответствии с утвержденными бюджетными ассигнованиями",
      "alpha beta gamma delta epsilon zeta eta internationalization",
    ];
    let cases = [
      ("Times New Roman", 12.0, 0, 467.4, 467.45),
      ("Times New Roman", 12.0, 1, 281.6, 281.65),
      ("Times New Roman", 13.0, 0, 506.4, 506.45),
      ("Times New Roman", 13.0, 1, 305.05, 305.1),
      ("Times New Roman", 24.0, 0, 934.85, 934.9),
      ("Times New Roman", 24.0, 1, 563.2, 563.25),
      ("Arial", 12.0, 0, 511.2, 511.25),
      ("Arial", 12.0, 1, 313.7, 313.75),
      ("Arial", 13.0, 0, 553.8, 553.85),
      ("Arial", 13.0, 1, 339.85, 339.9),
      ("Arial", 24.0, 0, 1022.4, 1022.45),
      ("Arial", 24.0, 1, 627.4, 627.45),
      ("Calibri", 12.0, 0, 470.9, 470.95),
      ("Calibri", 12.0, 1, 291.4, 291.45),
      ("Calibri", 13.0, 0, 510.15, 510.2),
      ("Calibri", 13.0, 1, 315.7, 315.75),
      ("Calibri", 24.0, 0, 941.8, 941.85),
      ("Calibri", 24.0, 1, 582.85, 582.9),
    ];
    let mut metrics = TextMetrics::new();
    for (family, size, text_index, lower, upper) in cases {
      let text = texts[text_index];
      for (width, accepted) in [(lower, false), (upper, true)] {
        for justified in [false, true] {
          let style = TextStyle {
            font_family: Some(Arc::from(family)),
            high_ansi_font_family: Some(Arc::from(family)),
            font_size_pt: size,
            kerning_minimum_size_pt: Some(100.0),
            ligatures: Some(crate::common::OpenTypeLigatures::default()),
            use_windows_font_metrics: true,
            ..Default::default()
          };
          let mut paragraph = paragraph(&format!("{text} next next next"), "Normal", 0.0, 0.0);
          paragraph.base_style = style.clone();
          if let InlineItem::Text(run) = &mut paragraph.inlines[0] {
            run.style = style;
          }
          if justified {
            paragraph.format.alignment = ParagraphAlignment::Justify;
            paragraph.format.justification.adjust = crate::docx::ParagraphAdjust::Block;
          }
          paragraph.format.justification.word_spacing = crate::docx::JustificationWordSpacing {
            desired_pct: 100,
            minimum_pct: 75,
            maximum_pct: 150,
          };
          let mut flow = flow_context(
            PageSetup::default(),
            0,
            SectionColumns::default(),
            0,
            0,
            DEFAULT_TAB_STOP_PT,
          );
          flow.justify_lines_with_shrinking = true;
          flow.content_width = width;
          let mut current = empty_page(flow.setup, 0);
          let mut pages = Vec::new();
          layout_paragraph(
            &paragraph,
            flow,
            ParagraphLayoutTarget {
              current: &mut current,
              pages: &mut pages,
              anchor_pages: None,
              text_metrics: &mut metrics,
            },
            flow.content_top_pt,
            flow.content_top_pt,
            0.0,
          );
          let first = current
            .items
            .iter()
            .find_map(|item| match item {
              PageItem::Text(text) => Some(text),
              _ => None,
            })
            .expect("first line");
          let first_line: String = current
            .items
            .iter()
            .filter_map(|item| match item {
              PageItem::Text(text) if (text.y_pt - first.y_pt).abs() < 0.01 => {
                Some(text.text.as_str())
              }
              _ => None,
            })
            .collect();
          assert_eq!(
            first_line.contains(text.split_whitespace().last().unwrap()),
            accepted && justified,
            "{family} {size}pt width={width} justified={justified}: {first_line}"
          );
        }
      }
    }

    // Native left-tab controls independently vary prefix blanks, a preceding
    // tab, leaders and the right margin. The fixed prefix never contributes
    // glue to the following span; all six variants have identical body origins.
    let body = "По требованию Государственного заказчика, согласно Рекламационному акту next next";
    let tab_style = TextStyle {
      font_family: Some(Arc::from("Times New Roman")),
      high_ansi_font_family: Some(Arc::from("Times New Roman")),
      font_size_pt: 12.0,
      kerning_minimum_size_pt: Some(100.0),
      ligatures: Some(crate::common::OpenTypeLigatures::default()),
      use_windows_font_metrics: true,
      ..Default::default()
    };
    for (prefix, leader) in [
      ("", TabLeader::None),
      ("AB", TabLeader::None),
      ("A B C", TabLeader::None),
      ("A B C", TabLeader::Dot),
      ("A B C", TabLeader::Underscore),
      ("A\tB C", TabLeader::None),
    ] {
      for delta in [-2.0, -1.0, 0.0, 1.0, 2.0, 3.0] {
        let mut paragraph = paragraph(&format!("{prefix}\t{body}"), "Normal", 0.0, 0.0);
        paragraph.base_style = tab_style.clone();
        if let InlineItem::Text(run) = &mut paragraph.inlines[0] {
          run.style = tab_style.clone();
        }
        paragraph.format.alignment = ParagraphAlignment::Justify;
        paragraph.format.justification.adjust = crate::docx::ParagraphAdjust::Block;
        paragraph.format.justification.word_spacing.minimum_pct = 75;
        paragraph.format.justification.word_spacing.maximum_pct = 150;
        paragraph.format.first_line_indent_pt = 28.35;
        if prefix.contains('\t') {
          paragraph.format.tab_stops.push(crate::docx::TabStop {
            position_pt: 50.0,
            alignment: TabStopAlignment::Left,
            leader: TabLeader::None,
          });
        }
        paragraph.format.tab_stops.push(crate::docx::TabStop {
          position_pt: 72.0,
          alignment: TabStopAlignment::Left,
          leader,
        });
        let mut flow = flow_context(
          PageSetup::default(),
          0,
          SectionColumns::default(),
          0,
          0,
          DEFAULT_TAB_STOP_PT,
        );
        flow.content_left_pt = 85.05;
        flow.content_width = 467.7 + delta;
        flow.justify_lines_with_shrinking = true;
        let mut current = empty_page(flow.setup, 0);
        layout_paragraph(
          &paragraph,
          flow,
          ParagraphLayoutTarget {
            current: &mut current,
            pages: &mut Vec::new(),
            anchor_pages: None,
            text_metrics: &mut metrics,
          },
          flow.content_top_pt,
          flow.content_top_pt,
          0.0,
        );
        let body_item = current
          .items
          .iter()
          .find_map(|item| match item {
            PageItem::Text(text) if text.text.starts_with("По требованию") => {
              Some(text)
            }
            _ => None,
          })
          .expect("body following the final tab");
        assert_eq!(
          body_item.text.contains("акту"),
          delta >= 1.0,
          "prefix={prefix:?} leader={leader:?} delta={delta}: {}",
          body_item.text
        );
        assert!(
          (body_item.x_pt - 157.05).abs() < 0.001,
          "fixed tab origin: prefix={prefix:?} leader={leader:?} delta={delta}"
        );
        for item in &current.items {
          if let PageItem::Text(text) = item
            && (text.y_pt - body_item.y_pt).abs() < 0.01
            && text.x_pt < body_item.x_pt
          {
            assert_eq!(
              text.word_spacing_pt, 0.0,
              "fixed prefix/leader: {}",
              text.text
            );
          }
        }
      }
    }

    let full_tab_body = "По требованию Государственного заказчика, согласно Рекламационному акту (приложение № 3 к Контракту), составляемому в порядке, установленном \nпунктом 5.3 Контракта, произвести необходимые исправления в выполненной работе \nбез дополнительной оплаты при условии, что они не выходят за рамки Технического задания. ";
    // Native +2pt retains five lines with a short, unexpanded final line.
    // Native +3pt admits the last word on line four, contracting its spaces.
    for (delta, native_line_count) in [(2.0, 5), (3.0, 4)] {
      let mut paragraph = paragraph(&format!("\t{full_tab_body}"), "Normal", 0.0, 0.0);
      paragraph.base_style = tab_style.clone();
      if let InlineItem::Text(run) = &mut paragraph.inlines[0] {
        run.style = tab_style.clone();
      }
      paragraph.format.alignment = ParagraphAlignment::Justify;
      paragraph.format.justification.adjust = crate::docx::ParagraphAdjust::Block;
      paragraph.format.justification.word_spacing.minimum_pct = 75;
      paragraph.format.justification.word_spacing.maximum_pct = 150;
      paragraph.format.first_line_indent_pt = 28.35;
      paragraph.format.tab_stops.push(crate::docx::TabStop {
        position_pt: 72.0,
        alignment: TabStopAlignment::Left,
        leader: TabLeader::None,
      });
      let mut flow = flow_context(
        PageSetup::default(),
        0,
        SectionColumns::default(),
        0,
        0,
        DEFAULT_TAB_STOP_PT,
      );
      flow.content_left_pt = 85.05;
      flow.content_width = 467.7 + delta;
      flow.compatibility_mode = 15;
      flow.justify_lines_with_shrinking = true;
      flow.do_not_expand_shift_return = false;
      let mut current = empty_page(flow.setup, 0);
      layout_paragraph(
        &paragraph,
        flow,
        ParagraphLayoutTarget {
          current: &mut current,
          pages: &mut Vec::new(),
          anchor_pages: None,
          text_metrics: &mut metrics,
        },
        flow.content_top_pt,
        flow.content_top_pt,
        0.0,
      );
      let text_items: Vec<_> = current
        .items
        .iter()
        .filter_map(|item| match item {
          PageItem::Text(text) => Some(text),
          _ => None,
        })
        .collect();
      let mut baselines = Vec::<f32>::new();
      for text in &text_items {
        if baselines
          .last()
          .is_none_or(|y| (text.y_pt - y).abs() >= 0.01)
        {
          baselines.push(text.y_pt);
        }
      }
      assert_eq!(baselines.len(), native_line_count, "width delta={delta}");
      let last = text_items.last().expect("final paragraph line");
      assert!(last.text.trim_end().ends_with("задания."));
      if delta == 3.0 {
        assert!(
          last.word_spacing_pt < 0.0,
          "accepted final-line contraction must be painted"
        );
      } else {
        assert_eq!(
          last.word_spacing_pt, 0.0,
          "short final line remains unexpanded"
        );
      }
    }

    // Native ordinary-cell controls have the same break for joined text,
    // separate punctuation, and a word split across formatting portions.
    // Narrow controls still move the complete final word to the next line.
    let style = TextStyle {
      font_family: Some(Arc::from("Times New Roman")),
      high_ansi_font_family: Some(Arc::from("Times New Roman")),
      font_size_pt: 12.0,
      kerning_minimum_size_pt: Some(100.0),
      ligatures: Some(crate::common::OpenTypeLigatures::default()),
      use_windows_font_metrics: true,
      ..Default::default()
    };
    for (cell_width, accepted) in [
      (267.0, false),
      (272.0, false),
      (275.0, true),
      (277.0, true),
      (279.0, true),
      (283.0, true),
    ] {
      for parts in [
        vec!["Интерфейсы 10/100/1000 Base-T/1000 Base-X: 4 шт. "],
        vec![
          "Интерфейсы",
          " 10/100/1000 Base-T/1000 Base-X: 4 ",
          "шт",
          ". ",
        ],
        vec![
          "Интерфейсы",
          " 10/100/1000 Base-T/1000 Base-X: 4 ",
          "ш",
          "т",
          ". ",
        ],
      ] {
        let mut paragraph = paragraph("", "Normal", 0.0, 0.0);
        paragraph.base_style = style.clone();
        paragraph.inlines = parts
          .iter()
          .map(|part| {
            InlineItem::Text(TextRun {
              text: (*part).into(),
              style: style.clone(),
              hyperlink_url: None,
              dynamic_field: None,
              style_ref_keys: Vec::new(),
              style_ref_text: None,
              style_ref_numbering_text: None,
              preserve_text_portion: false,
            })
          })
          .collect();
        paragraph.format.alignment = ParagraphAlignment::Justify;
        paragraph.format.justification.adjust = crate::docx::ParagraphAdjust::Block;
        paragraph.format.justification.word_spacing = crate::docx::JustificationWordSpacing {
          desired_pct: 100,
          minimum_pct: 75,
          maximum_pct: 150,
        };
        paragraph.format.first_line_indent_pt = 1.7;
        let mut flow = flow_context(
          PageSetup::default(),
          0,
          SectionColumns::default(),
          0,
          0,
          DEFAULT_TAB_STOP_PT,
        );
        flow.text_segmentation = TextSegmentation::TableCell;
        flow.horizontal_table_cell = true;
        flow.compatibility_mode = 15;
        flow.justify_lines_with_shrinking = true;
        flow.content_width = cell_width - 10.8;
        let mut current = empty_page(flow.setup, 0);
        layout_paragraph(
          &paragraph,
          flow,
          ParagraphLayoutTarget {
            current: &mut current,
            pages: &mut Vec::new(),
            anchor_pages: None,
            text_metrics: &mut metrics,
          },
          flow.content_top_pt,
          flow.content_top_pt,
          0.0,
        );
        let first_y = current
          .items
          .iter()
          .find_map(|item| match item {
            PageItem::Text(text) => Some(text.y_pt),
            _ => None,
          })
          .unwrap();
        let first_line: String = current
          .items
          .iter()
          .filter_map(|item| match item {
            PageItem::Text(text) if (text.y_pt - first_y).abs() < 0.01 => Some(text.text.as_str()),
            _ => None,
          })
          .collect();
        assert_eq!(
          first_line.contains("шт."),
          accepted,
          "cell width {cell_width}, parts {parts:?}: {first_line}"
        );
      }
    }
  }

  #[test]
  fn legacy_word_text_frame_line_fit_matches_native_logical_width_boundaries() {
    // Independently exported Word controls at integral-twip widths. Native
    // Line Services arrays also retain the design advances for Calibri 24pt
    // and Arial 8pt; the latter remains logical even with an hdmx record.
    let controls = [
      ("Calibri", 24.0, true, "should be hidden by", 201.9, 202.0),
      ("Arial", 8.0, false, "should be hidden by", 71.6, 71.7),
      ("Arial", 11.0, false, "should be hidden by", 98.45, 98.55),
      (
        "Times New Roman",
        11.0,
        false,
        "should be hidden by",
        88.9,
        89.0,
      ),
      (
        "Times New Roman",
        12.0,
        false,
        "should be hidden by",
        96.9,
        97.0,
      ),
      ("Calibri", 11.0, false, "should be hidden by", 90.55, 90.65),
      (
        "Times New Roman",
        11.0,
        false,
        "Аукцион признается несостоявшимся",
        177.3,
        177.4,
      ),
    ];
    let mut text_metrics = TextMetrics::new();
    for (family, size, bold, prefix, rejected_width, accepted_width) in controls {
      let style = TextStyle {
        font_family: Some(Arc::from(family)),
        high_ansi_font_family: Some(Arc::from(family)),
        font_size_pt: size,
        bold,
        kerning_minimum_size_pt: Some(32767.0),
        wordprocessingml_font_slots: true,
        use_windows_font_metrics: true,
        ..TextStyle::default()
      };
      for (width, accepted) in [(rejected_width, false), (accepted_width, true)] {
        // Formatting portions may divide a connected word. Cover both one
        // source run and a split inside the final word at the same boundary.
        let last_word_start = prefix.rfind(' ').unwrap() + 1;
        let split = last_word_start + prefix[last_word_start..].chars().next().unwrap().len_utf8();
        for parts in [vec![prefix], vec![&prefix[..split], &prefix[split..]]] {
          let mut paragraph = Paragraph {
            inlines: Vec::new(),
            field_events: Vec::new(),
            footnote_reference_ids: Vec::new(),
            endnote_reference_ids: Vec::new(),
            starts_after_last_rendered_page_break: false,
            base_style: style.clone(),
            runs: Vec::new(),
            format: Box::new(ParagraphFormat {
              word_text_frame_story: true,
              ..Default::default()
            }),
            style_ref_keys: Vec::new(),
            style_ref_text: None,
            style_ref_numbering_text: None,
            list_label: None,
            list_label_image: None,
            list_label_style: TextStyle::default(),
            list_label_hyperlink_url: None,
            list_label_tab_stop_pt: None,
          };
          paragraph.inlines = parts
            .iter()
            .chain(std::iter::once(&" next"))
            .map(|part| {
              InlineItem::Text(TextRun {
                text: (*part).into(),
                style: style.clone(),
                hyperlink_url: None,
                dynamic_field: None,
                style_ref_keys: Vec::new(),
                style_ref_text: None,
                style_ref_numbering_text: None,
                preserve_text_portion: false,
              })
            })
            .collect();
          let mut flow = flow_context(
            PageSetup::default(),
            0,
            SectionColumns::default(),
            0,
            0,
            DEFAULT_TAB_STOP_PT,
          );
          flow.text_segmentation = TextSegmentation::TableCell;
          flow.content_width = width;
          let mut current = empty_page(flow.setup, 0);
          layout_paragraph(
            &paragraph,
            flow,
            ParagraphLayoutTarget {
              current: &mut current,
              pages: &mut Vec::new(),
              anchor_pages: None,
              text_metrics: &mut text_metrics,
            },
            flow.content_top_pt,
            flow.content_top_pt,
            0.0,
          );
          let first_y = current
            .items
            .iter()
            .find_map(|item| match item {
              PageItem::Text(text) => Some(text.y_pt),
              _ => None,
            })
            .unwrap();
          let first_line: String = current
            .items
            .iter()
            .filter_map(|item| match item {
              PageItem::Text(text) if (text.y_pt - first_y).abs() < 0.01 => {
                Some(text.text.as_str())
              }
              _ => None,
            })
            .collect();
          assert_eq!(
            first_line.contains(prefix),
            accepted,
            "{family} {size}pt, width {width}, parts {parts:?}: {first_line}"
          );
        }
      }
    }
  }

  #[test]
  fn distributed_paragraph_last_line_reaches_the_right_margin() {
    fn text_item(x_pt: f32, text: &str) -> PageItem {
      PageItem::Text(Box::new(TextItem {
        x_pt,
        y_pt: 20.0,
        line_height_pt: DEFAULT_LINE_HEIGHT_PT,
        wordprocessing_auto_line_spacing_units: None,
        wordprocessing_line_metrics: None,
        origin_is_baseline: false,
        line_metrics_participant: true,
        paint_clip: None,
        wordprocessing_effect_host: None,
        wordprocessing_terminal_effect_style: None,
        text: text.to_string(),
        style: TextStyle::default(),
        rotation_center_pt: None,
        hyperlink_url: None,
        dynamic_field: None,
        dynamic_field_line_anchor: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        form_widget_id: None,
        paragraph_bidi: false,
        word_spacing_pt: 0.0,
        preserve_text_portion: false,
        decoration_span_start_x_pt: None,
        pdf_text_segmentation: PdfTextSegmentation::Line,
      }))
    }

    let mut text_metrics = TextMetrics::new();
    let style = TextStyle::default();
    let first_width = text_metrics.measure_text("alpha ", &style);
    let second_width = text_metrics.measure_text("beta gamma", &style);
    let natural_right = first_width + second_width;
    let line_right = natural_right + 12.0;
    let mut items = vec![
      text_item(0.0, "alpha "),
      text_item(first_width, "beta gamma "),
    ];

    justify_paragraph_last_line(
      crate::docx::ParagraphJustification {
        adjust: crate::docx::ParagraphAdjust::Block,
        last_line_adjust: crate::docx::ParagraphAdjust::Block,
        ..Default::default()
      },
      &mut items,
      LineJustificationContext {
        item_start: 0,
        y_pt: 20.0,
        left_pt: 0.0,
        right_pt: line_right,
        terminal_overhang_pt: 0.0,
        source_frame_right_pt: None,
        preserve_foreign_tail: false,
      },
      false,
      &mut text_metrics,
    );

    let PageItem::Text(first) = &items[0] else {
      panic!("expected text item");
    };
    let PageItem::Text(second) = &items[1] else {
      panic!("expected text item");
    };
    assert!((first.word_spacing_pt - 6.0).abs() < 0.001);
    assert!((second.word_spacing_pt - 6.0).abs() < 0.001);
    assert!((second.x_pt - (first_width + 6.0)).abs() < 0.001);
    assert!((second.x_pt + second_width + second.word_spacing_pt - line_right).abs() < 0.001);
  }

  #[test]
  fn limited_kashida_joins_leave_the_remainder_for_word_spaces() {
    let style = TextStyle {
      font_family: Some(Arc::from("Arial")),
      complex_font_family: Some(Arc::from("Arial")),
      font_size_pt: 14.0,
      complex_font_size_pt: Some(14.0),
      right_to_left: Some(true),
      resolved_bidi_level: Some(1),
      ..Default::default()
    };
    let mut metrics = TextMetrics::new();
    let minimum = metrics.kashida_opportunities("بالقرآن", &style)[0].minimum_width_pt;
    // Native Word: two eligible words and room for only one extender use
    // one minimum extender plus space glue. When both fit, all extra width
    // goes to the joins. The trailing semantic blank stays outside the frame.
    for text in ["بالقرآن بالقرآن", "بالقرآن بالقرآن "] {
      for (extra, expected_joins, expected_spacing) in
        [(minimum * 1.5, 1, minimum * 0.5), (minimum * 3.0, 2, 0.0)]
      {
        let visible = text.trim_end_matches(' ');
        let width = metrics.measure_text(visible, &style);
        let mut items = vec![PageItem::Text(Box::new(TextItem {
          x_pt: 0.0,
          y_pt: 20.0,
          line_height_pt: DEFAULT_LINE_HEIGHT_PT,
          wordprocessing_auto_line_spacing_units: None,
          wordprocessing_line_metrics: None,
          origin_is_baseline: false,
          line_metrics_participant: true,
          paint_clip: None,
          wordprocessing_effect_host: None,
          wordprocessing_terminal_effect_style: None,
          text: text.to_string(),
          style: style.clone(),
          rotation_center_pt: None,
          hyperlink_url: None,
          dynamic_field: None,
          dynamic_field_line_anchor: None,
          style_ref_keys: Vec::new(),
          style_ref_text: None,
          style_ref_numbering_text: None,
          form_widget_id: None,
          paragraph_bidi: true,
          word_spacing_pt: 0.0,
          preserve_text_portion: false,
          decoration_span_start_x_pt: None,
          pdf_text_segmentation: PdfTextSegmentation::Line,
        }))];
        assert!(justify_kashida_line(
          &mut items,
          LineJustificationContext {
            item_start: 0,
            y_pt: 20.0,
            left_pt: 0.0,
            right_pt: width + extra,
            terminal_overhang_pt: 0.0,
            source_frame_right_pt: None,
            preserve_foreign_tail: false,
          },
          Some(0),
          1,
          &mut metrics,
        ));
        let PageItem::Text(item) = &items[0] else {
          unreachable!()
        };
        let expansions = item.style.kashida_expansions.as_ref().unwrap();
        assert_eq!(expansions.len(), expected_joins);
        if expected_joins == 1 {
          assert_eq!(expansions[0].glyph_count, 1);
          assert!((expansions[0].advance.0 - minimum).abs() < 0.001);
        }
        assert!((item.word_spacing_pt - expected_spacing).abs() < 0.001);
        assert_eq!(item.text, text);
        let full_width = metrics.measure_text(text, &item.style)
          + text.matches(' ').count() as f32 * item.word_spacing_pt;
        assert!((item.x_pt + full_width - width - extra).abs() < 0.001);
        let tail_advance = metrics.measure_text(text, &style) - width
          + (text.len() - visible.len()) as f32 * item.word_spacing_pt;
        assert!((item.x_pt + tail_advance).abs() < 0.001);
      }
    }
  }

  #[test]
  fn rtl_justification_tail_width_is_independent_of_portion_boundaries() {
    fn text_item(x_pt: f32, text: &str) -> PageItem {
      PageItem::Text(Box::new(TextItem {
        x_pt,
        y_pt: 20.0,
        line_height_pt: DEFAULT_LINE_HEIGHT_PT,
        wordprocessing_auto_line_spacing_units: None,
        wordprocessing_line_metrics: None,
        origin_is_baseline: false,
        line_metrics_participant: true,
        paint_clip: None,
        wordprocessing_effect_host: None,
        wordprocessing_terminal_effect_style: None,
        text: text.to_string(),
        style: TextStyle::default(),
        rotation_center_pt: None,
        hyperlink_url: None,
        dynamic_field: None,
        dynamic_field_line_anchor: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        form_widget_id: None,
        paragraph_bidi: false,
        word_spacing_pt: 0.0,
        preserve_text_portion: false,
        decoration_span_start_x_pt: None,
        pdf_text_segmentation: PdfTextSegmentation::Line,
      }))
    }
    for tails in [1, 2] {
      for portions in [
        vec!["وكذلك الأسماء للرحمن"],
        vec!["وكذلك ", "الأسماء ", "للرحمن"],
        vec!["وكذل", "ك", " الأسماء للرحمن"],
      ] {
        let mut metrics = TextMetrics::new();
        let mut x = 0.0;
        let mut items = portions
          .iter()
          .enumerate()
          .map(|(i, value)| {
            let value = if i + 1 == portions.len() {
              format!("{value}{}", " ".repeat(tails))
            } else {
              value.to_string()
            };
            let mut item = text_item(x, &value);
            let PageItem::Text(text) = &mut item else {
              unreachable!()
            };
            text.paragraph_bidi = true;
            text.style.font_family = Some(Arc::from("Arial"));
            text.style.complex_font_family = Some(Arc::from("Arial"));
            text.style.font_size_pt = 14.0;
            text.style.complex_font_size_pt = Some(14.0);
            text.style.right_to_left = Some(true);
            x += metrics.measure_text(&value, &text.style);
            item
          })
          .collect::<Vec<_>>();
        reorder_bidi_line_items(&mut items, 0, 20.0, &mut metrics);
        let line_right = x + 30.0;
        justify_line_items(
          &mut items,
          LineJustificationContext {
            item_start: 0,
            y_pt: 20.0,
            left_pt: 0.0,
            right_pt: line_right,
            terminal_overhang_pt: 0.0,
            source_frame_right_pt: None,
            preserve_foreign_tail: false,
          },
          crate::docx::ParagraphJustification::default(),
          &mut metrics,
        );
        align_paragraph_items(
          &mut items,
          ParagraphAlignment::Right,
          &mut metrics,
          line_right,
        );
        let mut logical_text = String::new();
        let mut bounds = Vec::new();
        for item in &items {
          let PageItem::Text(text) = item else {
            unreachable!()
          };
          logical_text.push_str(&text.text);
          let width = metrics.measure_text(&text.text, &text.style)
            + text.text.matches(' ').count() as f32 * text.word_spacing_pt;
          bounds.push((text.x_pt, width));
        }
        bounds.sort_by(|a, b| a.0.total_cmp(&b.0));
        for pair in bounds.windows(2) {
          assert!(
            (pair[0].0 + pair[0].1 - pair[1].0).abs() < 0.001,
            "{bounds:?}"
          );
        }
        let PageItem::Text(tail) = items.last().unwrap() else {
          unreachable!()
        };
        let tail_width = metrics.measure_text(&tail.text, &tail.style)
          - metrics.measure_text(tail.text.trim_end_matches(' '), &tail.style)
          + tails as f32 * tail.word_spacing_pt;
        assert!(
          (bounds[0].0 + tail_width).abs() < 0.001,
          "{portions:?}, tails={tails}, bounds={bounds:?}, tail={tail_width}"
        );
        let (right_x, right_width) = bounds.last().copied().unwrap();
        assert!((right_x + right_width - line_right).abs() < 0.001);
        assert_eq!(
          logical_text,
          format!("وكذلك الأسماء للرحمن{}", " ".repeat(tails))
        );
      }
    }
  }

  #[test]
  fn justification_preserves_visual_portion_adjacency_after_bidi_reordering() {
    fn text_item(x_pt: f32, text: &str) -> PageItem {
      PageItem::Text(Box::new(TextItem {
        x_pt,
        y_pt: 20.0,
        line_height_pt: DEFAULT_LINE_HEIGHT_PT,
        wordprocessing_auto_line_spacing_units: None,
        wordprocessing_line_metrics: None,
        origin_is_baseline: false,
        line_metrics_participant: true,
        paint_clip: None,
        wordprocessing_effect_host: None,
        wordprocessing_terminal_effect_style: None,
        text: text.to_string(),
        style: TextStyle::default(),
        rotation_center_pt: None,
        hyperlink_url: None,
        dynamic_field: None,
        dynamic_field_line_anchor: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        form_widget_id: None,
        paragraph_bidi: false,
        word_spacing_pt: 0.0,
        preserve_text_portion: false,
        decoration_span_start_x_pt: None,
        pdf_text_segmentation: PdfTextSegmentation::Line,
      }))
    }

    for (bidi, portions) in [
      (false, ["alpha ", "beta ", "gamma"]),
      (true, ["وكذل", "ك", " الأسماء للرحمن"]),
      (true, ["وكذلك ", "الأسماء ", "للرحمن"]),
      (true, ["אב ", "CD EF ", "גד"]),
    ] {
      for extra_width in [-2.0, 12.0, 30.0] {
        let mut metrics = TextMetrics::new();
        let mut x = 0.0;
        let mut items = portions
          .iter()
          .map(|value| {
            let mut item = text_item(x, value);
            let PageItem::Text(text) = &mut item else {
              unreachable!()
            };
            text.paragraph_bidi = bidi;
            x += metrics.measure_text(value, &text.style);
            item
          })
          .collect::<Vec<_>>();
        if bidi {
          reorder_bidi_line_items(&mut items, 0, 20.0, &mut metrics);
        }
        let logical_text = |items: &[PageItem]| {
          items
            .iter()
            .filter_map(|item| match item {
              PageItem::Text(text) => Some(text.text.as_str()),
              _ => None,
            })
            .collect::<String>()
        };
        let before = logical_text(&items);
        let natural_right = items
          .iter()
          .filter_map(|item| item_horizontal_bounds(item, &mut metrics))
          .map(|(x, width)| x + width)
          .reduce(f32::max)
          .unwrap();
        let line_right = natural_right + extra_width;
        justify_line_items(
          &mut items,
          LineJustificationContext {
            item_start: 0,
            y_pt: 20.0,
            left_pt: 0.0,
            right_pt: line_right,
            terminal_overhang_pt: 0.0,
            source_frame_right_pt: None,
            preserve_foreign_tail: false,
          },
          crate::docx::ParagraphJustification::default(),
          &mut metrics,
        );
        align_paragraph_items(
          &mut items,
          ParagraphAlignment::Right,
          &mut metrics,
          line_right,
        );
        let mut bounds = items
          .iter()
          .filter_map(|item| item_horizontal_bounds(item, &mut metrics))
          .collect::<Vec<_>>();
        bounds.sort_by(|a, b| a.0.total_cmp(&b.0));
        assert!(bounds[0].0.abs() < 0.001);
        for pair in bounds.windows(2) {
          assert!(
            (pair[0].0 + pair[0].1 - pair[1].0).abs() < 0.001,
            "bidi={bidi}, extra={extra_width}, portions={portions:?}, bounds={bounds:?}"
          );
        }
        let &(x, width) = bounds.last().unwrap();
        assert!((x + width - line_right).abs() < 0.001);
        assert_eq!(logical_text(&items), before);
      }
    }
  }

  #[test]
  fn rtl_tab_justification_preserves_fixed_edge_and_excludes_reserved_margin() {
    fn text_item(x_pt: f32, text: &str) -> PageItem {
      PageItem::Text(Box::new(TextItem {
        x_pt,
        y_pt: 20.0,
        line_height_pt: DEFAULT_LINE_HEIGHT_PT,
        wordprocessing_auto_line_spacing_units: None,
        wordprocessing_line_metrics: None,
        origin_is_baseline: false,
        line_metrics_participant: true,
        paint_clip: None,
        wordprocessing_effect_host: None,
        wordprocessing_terminal_effect_style: None,
        text: text.to_string(),
        style: TextStyle::default(),
        rotation_center_pt: None,
        hyperlink_url: None,
        dynamic_field: None,
        dynamic_field_line_anchor: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        form_widget_id: None,
        paragraph_bidi: false,
        word_spacing_pt: 0.0,
        preserve_text_portion: false,
        decoration_span_start_x_pt: None,
        pdf_text_segmentation: PdfTextSegmentation::Line,
      }))
    }
    let mut metrics = TextMetrics::new();
    for kashida in [None, Some(crate::docx::KashidaLevel::Low)] {
      for tail in ["", " "] {
        for portions in [
          vec![format!("بالقرآن 18 وكذلك الأسماء{tail}")],
          vec![
            "بالقرآن ".into(),
            "18".into(),
            format!(" وكذلك الأسماء{tail}"),
          ],
        ] {
          let mut x = 60.0;
          let mut source = portions
            .iter()
            .map(|value| {
              let mut item = text_item(x, value);
              let PageItem::Text(text) = &mut item else {
                unreachable!()
              };
              text.paragraph_bidi = true;
              text.style.font_family = Some(Arc::from("Arial"));
              text.style.complex_font_family = Some(Arc::from("Arial"));
              text.style.right_to_left = Some(true);
              x += metrics.measure_text(value, &text.style);
              item
            })
            .collect::<Vec<_>>();
          reorder_bidi_line_items(&mut source, 0, 20.0, &mut metrics);
          let right = source
            .iter()
            .filter_map(|item| item_horizontal_bounds(item, &mut metrics))
            .map(|(x, width)| x + width)
            .reduce(f32::max)
            .unwrap();
          let justification = crate::docx::ParagraphJustification {
            adjust: crate::docx::ParagraphAdjust::Block,
            kashida,
            ..Default::default()
          };
          let line = LineJustificationContext {
            item_start: 0,
            y_pt: 20.0,
            left_pt: 60.0,
            right_pt: 420.0,
            terminal_overhang_pt: 0.0,
            source_frame_right_pt: None,
            preserve_foreign_tail: false,
          };
          let mut expected = source.clone();
          justify_line_items(&mut expected, line, justification, &mut metrics);
          align_paragraph_items(
            &mut expected,
            ParagraphAlignment::Right,
            &mut metrics,
            420.0,
          );
          // Native Word both/lowKashida controls: the text span reaches the
          // paragraph's trailing edge and its leading tab, independently of
          // unused physical space beyond that tab. Mixed levels and semantic
          // trailing blanks must preserve the same adjacency and expansion.
          for (margin, with_prefix) in
            [(450.0, false), (620.0, false), (450.0, true), (620.0, true)]
          {
            let anchor = DynamicFieldLineAnchor {
              position_pt: 420.0,
              alignment: ParagraphAlignment::Right,
              aligned_tab: Some(DynamicFieldAlignedTab {
                start_x_pt: margin,
                leader: TabLeader::None,
                inside_field_result: false,
                leader_layout: TabLeaderLayout::NaturalStart,
                logical_repeat_width_pt: 0.0,
              }),
            };
            let mut actual = source.clone();
            for item in &mut actual {
              let PageItem::Text(text) = item else {
                unreachable!()
              };
              text.x_pt += 420.0 - right;
              text.dynamic_field_line_anchor = Some(anchor);
            }
            let prefix_x = with_prefix.then(|| {
              let mut prefix = text_item(0.0, "بند");
              let PageItem::Text(text) = &mut prefix else {
                unreachable!()
              };
              text.paragraph_bidi = true;
              text.style.font_family = Some(Arc::from("Arial"));
              text.style.complex_font_family = Some(Arc::from("Arial"));
              text.style.right_to_left = Some(true);
              text.x_pt = margin - metrics.measure_text(&text.text, &text.style);
              text.dynamic_field_line_anchor = Some(DynamicFieldLineAnchor {
                position_pt: margin,
                ..anchor
              });
              let x = text.x_pt;
              actual.insert(0, prefix);
              x
            });
            justify_line_items(
              &mut actual,
              LineJustificationContext {
                right_pt: margin,
                ..line
              },
              justification,
              &mut metrics,
            );
            if let Some(x) = prefix_x {
              let PageItem::Text(prefix) = &actual[0] else {
                unreachable!()
              };
              assert_eq!(prefix.x_pt, x);
              assert_eq!(prefix.word_spacing_pt, 0.0);
              assert!(prefix.style.kashida_expansions.is_none());
            }
            for (actual, expected) in actual.iter().skip(usize::from(with_prefix)).zip(&expected) {
              let (PageItem::Text(actual), PageItem::Text(expected)) = (actual, expected) else {
                unreachable!()
              };
              assert_eq!(actual.text, expected.text);
              assert_eq!(actual.dynamic_field_line_anchor, Some(anchor));
              assert!((actual.x_pt - expected.x_pt).abs() < 0.001);
              assert!((actual.word_spacing_pt - expected.word_spacing_pt).abs() < 0.001);
              let actual_width = metrics.measure_text(&actual.text, &actual.style);
              let expected_width = metrics.measure_text(&expected.text, &expected.style);
              assert!((actual_width - expected_width).abs() < 0.001);
            }
          }
        }
      }
    }
  }

