  #[test]
  fn rtl_page_field_before_tab_keeps_its_right_edge_when_cached_result_shrinks() {
    let mut metrics = TextMetrics::new();
    let mut field = text_warp_bounds_test_item(14.0);
    field.x_pt = 300.0;
    field.y_pt = 20.0;
    field.text = "102".to_string();
    field.paragraph_bidi = true;
    field.dynamic_field = Some(DynamicFieldKind::Page {
      number_format: FieldNumberFormat::Decimal,
    });
    let cached_right = field.x_pt + metrics.measure_text(&field.text, &field.style);
    let mut title = text_warp_bounds_test_item(14.0);
    title.y_pt = 20.0;
    title.text = "Header".to_string();
    title.paragraph_bidi = true;
    title.dynamic_field_line_anchor = Some(DynamicFieldLineAnchor {
      position_pt: 50.0,
      alignment: ParagraphAlignment::Left,
      aligned_tab: Some(DynamicFieldAlignedTab {
        start_x_pt: 250.0,
        leader: TabLeader::None,
        inside_field_result: false,
        leader_layout: TabLeaderLayout::NaturalStart,
        logical_repeat_width_pt: 0.0,
      }),
    });
    let mut pages = Vec::new();
    for title_x in [50.0, 400.0] {
      let mut page = empty_page(PageSetup::default(), pages.len());
      let mut title = title.clone();
      title.x_pt = title_x;
      page.items = vec![
        PageItem::Text(Box::new(field.clone())),
        PageItem::Text(Box::new(title)),
      ];
      pages.push(page);
    }

    resolve_dynamic_fields(&mut pages, &[], &[], &[], 1, None, &mut metrics);

    let PageItem::Text(first) = &pages[0].items[0] else {
      unreachable!()
    };
    assert_eq!(first.text, "1");
    assert!(
      (first.x_pt + metrics.measure_text(&first.text, &first.style) - cached_right).abs() < 0.01
    );
    let PageItem::Text(second) = &pages[1].items[0] else {
      unreachable!()
    };
    assert_eq!(second.text, "2");
    assert!((second.x_pt - field.x_pt).abs() < 0.01);
  }

  #[test]
  fn resolved_sequence_field_replaces_the_cached_advance_before_following_text() {
    let style = TextStyle::default();
    let mut text_metrics = TextMetrics::new();
    let mut x_pt = 10.0;
    let mut text_item = |text: &str, dynamic_field| {
      let item = PageItem::Text(Box::new(TextItem {
        x_pt,
        y_pt: 20.0,
        line_height_pt: DEFAULT_LINE_HEIGHT_PT,
        wordprocessing_auto_line_spacing_units: None,
        wordprocessing_line_metrics: None,
        origin_is_baseline: false,
        line_metrics_participant: true,
        paint_clip: None,
        wordprocessing_effect_host: None,
        wordprocessing_terminal_effect_style: None,
        text: text.to_string(),
        style: style.clone(),
        rotation_center_pt: None,
        hyperlink_url: None,
        dynamic_field,
        dynamic_field_line_anchor: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        form_widget_id: None,
        paragraph_bidi: false,
        word_spacing_pt: 0.0,
        preserve_text_portion: false,
        decoration_span_start_x_pt: None,
        pdf_text_segmentation: PdfTextSegmentation::Line,
      }));
      x_pt += text_metrics.measure_text(text, &style);
      item
    };
    let mut page = empty_page(PageSetup::default(), 0);
    page.items = vec![
      text_item("Figure ", None),
      text_item(
        "10",
        Some(DynamicFieldKind::Sequence {
          identifier: Arc::from("Figure"),
          number_format: FieldNumberFormat::Decimal,
        }),
      ),
      text_item(": Tools", None),
    ];
    let cached_right = x_pt;
    align_paragraph_items(
      &mut page.items,
      ParagraphAlignment::Left,
      &mut text_metrics,
      500.0,
    );
    let mut pages = vec![page];

    resolve_dynamic_fields(&mut pages, &[], &[], &[], 1, None, &mut text_metrics);

    let [
      PageItem::Text(prefix),
      PageItem::Text(field),
      PageItem::Text(suffix),
    ] = pages[0].items.as_slice()
    else {
      panic!("expected three text portions");
    };
    assert_eq!(field.text, "1");
    assert!((prefix.x_pt - 10.0).abs() < 0.001);
    assert!(
      (suffix.x_pt - field.x_pt - text_metrics.measure_text(&field.text, &field.style)).abs()
        < 0.001
    );
    let resolved_right = suffix.x_pt + text_metrics.measure_text(&suffix.text, &suffix.style);
    assert!((cached_right - resolved_right - text_metrics.measure_text("0", &style)).abs() < 0.001);
  }

  #[test]
  fn terminal_tab_leaders_do_not_require_following_text_or_underlining() {
    for bidi in [false, true] {
      for alignment in [
        TabStopAlignment::Left,
        TabStopAlignment::Center,
        TabStopAlignment::Right,
      ] {
        for leader in [TabLeader::None, TabLeader::Dot, TabLeader::Hyphen] {
          let style = TextStyle {
            font_family: Some(Arc::from("Arial")),
            ..TextStyle::default()
          };
          let run = |text: &str, dynamic_field| {
            InlineItem::Text(TextRun {
              text: text.into(),
              style: style.clone(),
              hyperlink_url: None,
              dynamic_field,
              style_ref_keys: Vec::new(),
              style_ref_text: None,
              style_ref_numbering_text: None,
              preserve_text_portion: false,
            })
          };
          let paragraph = Paragraph {
            inlines: vec![run("Title\t", None)],
            field_events: Vec::new(),
            footnote_reference_ids: Vec::new(),
            endnote_reference_ids: Vec::new(),
            starts_after_last_rendered_page_break: false,
            base_style: style.clone(),
            runs: Vec::new(),
            format: Box::new(ParagraphFormat {
              bidi,
              alignment: ParagraphAlignment::Justify,
              justification: crate::docx::ParagraphJustification {
                adjust: crate::docx::ParagraphAdjust::Block,
                ..Default::default()
              },
              tab_stops: vec![TabStop {
                position_pt: 180.0,
                alignment,
                leader,
              }],
              ..Default::default()
            }),
            style_ref_keys: Vec::new(),
            style_ref_text: None,
            style_ref_numbering_text: None,
            list_label: None,
            list_label_image: None,
            list_label_style: style.clone(),
            list_label_hyperlink_url: None,
            list_label_tab_stop_pt: None,
          };
          let mut flow = flow_context(
            PageSetup {
              width_pt: 420.0,
              margin_left_pt: 60.0,
              margin_right_pt: 60.0,
              ..PageSetup::default()
            },
            0,
            SectionColumns::default(),
            0,
            0,
            DEFAULT_TAB_STOP_PT,
          );
          flow.compatibility_mode = 11;
          let mut current = empty_page(flow.setup, 0);
          let mut pages = Vec::new();
          let mut metrics = TextMetrics::new();
          layout_paragraph(
            &paragraph,
            flow,
            ParagraphLayoutTarget {
              current: &mut current,
              pages: &mut pages,
              anchor_pages: None,
              text_metrics: &mut metrics,
            },
            flow.content_top_pt,
            flow.content_top_pt,
            0.0,
          );
          assert!(pages.is_empty(), "terminal tab must not add a page");
          let texts = current
            .items
            .iter()
            .filter_map(|item| match item {
              PageItem::Text(text) => Some(text),
              _ => None,
            })
            .collect::<Vec<_>>();
          assert!(texts.iter().any(|text| text.text == "Title"));
          let painted = texts
            .iter()
            .find(|text| tab_leader_text_char(text).is_some());
          assert_eq!(
            painted.is_some(),
            leader != TabLeader::None,
            "{bidi}/{alignment:?}/{leader:?}"
          );
          if let Some(painted) = painted {
            assert!(painted.text.len() > 10);
            let right = painted.x_pt + metrics.measure_text(&painted.text, &painted.style);
            assert!(painted.x_pt >= 60.0 && right <= 360.0);
          }
        }
      }
    }
  }

  #[test]
  fn rtl_tab_segments_keep_page_fields_and_leaders_at_their_authored_stops() {
    for (bidi, prefix) in [
      (false, "Title"),
      (true, "Title"),
      (false, ""),
      (true, ""),
      (false, "Title\t"),
      (true, "Title\t"),
    ] {
      for alignment in [
        TabStopAlignment::Left,
        TabStopAlignment::Center,
        TabStopAlignment::Right,
      ] {
        let style = TextStyle {
          font_family: Some(Arc::from("Arial")),
          ..TextStyle::default()
        };
        let run = |text: &str, dynamic_field| {
          InlineItem::Text(TextRun {
            text: text.into(),
            style: style.clone(),
            hyperlink_url: None,
            dynamic_field,
            style_ref_keys: Vec::new(),
            style_ref_text: None,
            style_ref_numbering_text: None,
            preserve_text_portion: false,
          })
        };
        let paragraph = Paragraph {
          inlines: vec![
            run(prefix, None),
            run("\t", None),
            run(
              "42",
              Some(DynamicFieldKind::Page {
                number_format: FieldNumberFormat::Decimal,
              }),
            ),
          ],
          field_events: Vec::new(),
          footnote_reference_ids: Vec::new(),
          endnote_reference_ids: Vec::new(),
          starts_after_last_rendered_page_break: false,
          base_style: style.clone(),
          runs: Vec::new(),
          format: Box::new(ParagraphFormat {
            bidi,
            alignment: ParagraphAlignment::Justify,
            justification: crate::docx::ParagraphJustification {
              adjust: crate::docx::ParagraphAdjust::Block,
              ..Default::default()
            },
            tab_stops: {
              let mut stops = Vec::new();
              if prefix.ends_with("\t") {
                stops.push(TabStop {
                  position_pt: 120.0,
                  alignment: TabStopAlignment::Center,
                  leader: TabLeader::Dot,
                });
              }
              stops.push(TabStop {
                position_pt: 240.0,
                alignment,
                leader: TabLeader::Dot,
              });
              stops
            },
            ..Default::default()
          }),
          style_ref_keys: Vec::new(),
          style_ref_text: None,
          style_ref_numbering_text: None,
          list_label: None,
          list_label_image: None,
          list_label_style: style.clone(),
          list_label_hyperlink_url: None,
          list_label_tab_stop_pt: None,
        };
        let mut flow = flow_context(
          PageSetup {
            width_pt: 420.0,
            margin_left_pt: 60.0,
            margin_right_pt: 60.0,
            ..PageSetup::default()
          },
          0,
          SectionColumns::default(),
          0,
          0,
          DEFAULT_TAB_STOP_PT,
        );
        // Natural-advance leaders make their geometric span an exact bound.
        // Legacy printer-grid leaders use different count/paint advances;
        // their existing rounding is independent of RTL anchor reflection.
        flow.compatibility_mode = 14;
        let mut current = empty_page(flow.setup, 0);
        let mut pages = Vec::new();
        let mut metrics = TextMetrics::new();
        layout_paragraph(
          &paragraph,
          flow,
          ParagraphLayoutTarget {
            current: &mut current,
            pages: &mut pages,
            anchor_pages: None,
            text_metrics: &mut metrics,
          },
          flow.content_top_pt,
          flow.content_top_pt,
          0.0,
        );
        pages.push(current);
        resolve_dynamic_fields(&mut pages, &[], &[], &[], 1, None, &mut metrics);
        assert_eq!(pages.len(), 1);
        let texts = pages[0]
          .items
          .iter()
          .filter_map(|item| match item {
            PageItem::Text(text) => Some(text),
            _ => None,
          })
          .collect::<Vec<_>>();
        let title = texts.iter().find(|text| text.text == "Title");
        let field = texts
          .iter()
          .find(|text| text.dynamic_field.is_some())
          .expect("page field");
        assert_eq!(field.text, "1");
        let field_width = metrics.measure_text(&field.text, &field.style);
        let factor = match alignment {
          TabStopAlignment::Left => {
            if bidi {
              1.0
            } else {
              0.0
            }
          }
          TabStopAlignment::Center => 0.5,
          TabStopAlignment::Right => {
            if bidi {
              0.0
            } else {
              1.0
            }
          }
        };
        let expected_stop = if bidi { 120.0 } else { 300.0 };
        assert!(
          (field.x_pt + field_width * factor - expected_stop).abs() < 0.01,
          "bidi={bidi}, {alignment:?}: field x {} width {field_width}",
          field.x_pt
        );
        if let Some(title) = title {
          let title_width = metrics.measure_text(&title.text, &title.style);
          let title_edge = if bidi {
            title.x_pt + title_width
          } else {
            title.x_pt
          };
          assert!((title_edge - if bidi { 360.0 } else { 60.0 }).abs() < 0.01);
        }
        let leaders = texts
          .iter()
          .filter(|text| tab_leader_text_char(text).is_some())
          .count();
        assert_eq!(
          leaders,
          if prefix.ends_with("\t") { 2 } else { 1 },
          "bidi={bidi}, prefix={prefix:?}, {alignment:?}"
        );
        let leader = texts
          .iter()
          .rev()
          .find(|text| tab_leader_text_char(text).is_some())
          .expect("leader retained");
        let leader_right = leader.x_pt + metrics.measure_text(&leader.text, &leader.style);
        let (gap_left, gap_right) = if bidi {
          (
            field.x_pt + field_width,
            if prefix.ends_with("\t") {
              240.0
            } else {
              title.map_or(360.0, |title| title.x_pt)
            },
          )
        } else {
          (
            if prefix.ends_with("\t") {
              180.0
            } else {
              title.map_or(60.0, |title| {
                title.x_pt + metrics.measure_text(&title.text, &title.style)
              })
            },
            field.x_pt,
          )
        };
        assert!(
          leader.x_pt >= gap_left - 0.01 && leader_right <= gap_right + 0.01,
          "bidi={bidi}, {alignment:?}: leader {}..{leader_right}, gap {gap_left}..{gap_right}",
          leader.x_pt
        );
        assert!(leader_right - leader.x_pt > (gap_right - gap_left) * 0.9);
      }
    }
  }

  #[test]
  fn refreshed_field_advance_stops_at_following_fixed_tab() {
    let setup = PageSetup {
      width_pt: 500.0,
      height_pt: 500.0,
      margin_top_pt: 36.0,
      margin_bottom_pt: 36.0,
      margin_left_pt: 36.0,
      margin_right_pt: 36.0,
      ..PageSetup::default()
    };
    let flow = flow_context(setup, 0, SectionColumns::default(), 0, 0, 36.0);
    let style = TextStyle {
      font_family: Some(Arc::from("Courier New")),
      font_size_pt: 12.0,
      ..TextStyle::default()
    };
    let run = TextRun {
      text: String::new(),
      style: style.clone(),
      hyperlink_url: None,
      dynamic_field: None,
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      preserve_text_portion: false,
    };
    let mut paragraph = Paragraph {
      inlines: Vec::new(),
      runs: Vec::new(),
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: style.clone(),
      format: Box::new(ParagraphFormat {
        line_height_rule: LineHeightRule::Exact,
        line_height_pt: Some(18.0),
        widow_control: Some(false),
        tab_stops_set: true,
        ..ParagraphFormat::default()
      }),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: style,
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    };
    for alignment in [
      TabStopAlignment::Left,
      TabStopAlignment::Center,
      TabStopAlignment::Right,
    ] {
      paragraph.format.tab_stops = vec![TabStop {
        position_pt: 240.0,
        alignment,
        leader: TabLeader::None,
      }];
      for cached in ["1", "27", "999"] {
        for resolved in [1, 99] {
          paragraph.inlines = [cached, ":suffix", "\t", "STATIC"]
            .into_iter()
            .enumerate()
            .map(|(index, text)| {
              let mut run = run.clone();
              run.text = text.into();
              if index == 0 {
                run.dynamic_field = Some(DynamicFieldKind::Page {
                  number_format: FieldNumberFormat::Decimal,
                });
              }
              InlineItem::Text(run)
            })
            .collect();
          let mut metrics = TextMetrics::new();
          let mut page = empty_page(setup, 0);
          let mut pages = Vec::new();
          layout_paragraph(
            &paragraph,
            flow,
            ParagraphLayoutTarget {
              current: &mut page,
              pages: &mut pages,
              anchor_pages: None,
              text_metrics: &mut metrics,
            },
            36.0,
            36.0,
            0.0,
          );
          assert!(pages.is_empty());
          let static_x = page
            .items
            .iter()
            .find_map(|item| match item {
              PageItem::Text(text) if text.text == "STATIC" => Some(text.x_pt),
              _ => None,
            })
            .unwrap();
          pages.push(page);
          resolve_dynamic_fields(&mut pages, &[], &[], &[], resolved, None, &mut metrics);
          let texts = pages[0]
            .items
            .iter()
            .filter_map(|item| match item {
              PageItem::Text(text) => Some(text),
              _ => None,
            })
            .collect::<Vec<_>>();
          let field = texts
            .iter()
            .find(|text| text.dynamic_field.is_some())
            .unwrap();
          assert_eq!(field.text, resolved.to_string());
          let suffix = texts.iter().find(|text| text.text == ":suffix").unwrap();
          assert!(
            (suffix.x_pt - field.x_pt - metrics.measure_text(&field.text, &field.style)).abs()
              < 0.001
          );
          let fixed = texts.iter().find(|text| text.text == "STATIC").unwrap();
          assert!(
            (fixed.x_pt - static_x).abs() < 0.001,
            "{alignment:?}, {cached} -> {resolved}"
          );
        }
      }
    }
  }

  #[test]
  fn bookmarks_preserve_the_complete_aligned_tab_span() {
    let setup = PageSetup {
      width_pt: 500.0,
      height_pt: 500.0,
      margin_top_pt: 36.0,
      margin_bottom_pt: 36.0,
      margin_left_pt: 36.0,
      margin_right_pt: 36.0,
      ..PageSetup::default()
    };
    let flow = flow_context(setup, 0, SectionColumns::default(), 0, 0, 36.0);
    let style = TextStyle {
      font_family: Some(Arc::from("Courier New")),
      font_size_pt: 12.0,
      ..TextStyle::default()
    };
    let run = TextRun {
      text: String::new(),
      style: style.clone(),
      hyperlink_url: None,
      dynamic_field: None,
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      preserve_text_portion: false,
    };
    let mut paragraph = Paragraph {
      inlines: Vec::new(),
      runs: Vec::new(),
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: style.clone(),
      format: Box::new(ParagraphFormat {
        line_height_rule: LineHeightRule::Exact,
        line_height_pt: Some(18.0),
        widow_control: Some(false),
        tab_stops_set: true,
        ..ParagraphFormat::default()
      }),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: style,
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    };
    // Office preserves positions for bookmarks before, within, and after an
    // aligned span, in both directions and for right/center tabs. Include the
    // following tab to check the logical cursor as well as the first label.
    let positions = |paragraph: &Paragraph| {
      let mut metrics = TextMetrics::new();
      let mut page = empty_page(setup, 0);
      let mut pages = Vec::new();
      layout_paragraph(
        paragraph,
        flow,
        ParagraphLayoutTarget {
          current: &mut page,
          pages: &mut pages,
          anchor_pages: None,
          text_metrics: &mut metrics,
        },
        36.0,
        36.0,
        0.0,
      );
      assert!(pages.is_empty());
      page
        .items
        .into_iter()
        .filter_map(|item| match item {
          PageItem::Text(text) => Some((text.text, text.x_pt, text.y_pt)),
          _ => None,
        })
        .collect::<Vec<_>>()
    };
    for bidi in [false, true] {
      paragraph.format.bidi = bidi;
      for alignment in [TabStopAlignment::Right, TabStopAlignment::Center] {
        paragraph.format.tab_stops = vec![
          TabStop {
            position_pt: 100.0,
            alignment,
            leader: TabLeader::None,
          },
          TabStop {
            position_pt: 200.0,
            alignment: TabStopAlignment::Left,
            leader: TabLeader::None,
          },
        ];
        let inlines = ["\t", "ABC", "XYZ", "\t", "END"].map(|text| {
          let mut run = run.clone();
          run.text = text.into();
          InlineItem::Text(run)
        });
        paragraph.inlines = inlines.to_vec();
        let expected = positions(&paragraph);
        for insertion in 1..=3 {
          paragraph.inlines = inlines.to_vec();
          paragraph
            .inlines
            .insert(insertion, InlineItem::BookmarkStart("target".into()));
          let actual = positions(&paragraph);
          assert_eq!(
            actual, expected,
            "bidi={bidi}, {alignment:?}, bookmark={insertion}"
          );
        }
      }
    }
  }

  #[test]
  fn aligned_tab_overflow_preserves_paragraph_line_capacity() {
    let setup = PageSetup {
      width_pt: 500.0,
      height_pt: 500.0,
      margin_top_pt: 36.0,
      margin_bottom_pt: 36.0,
      margin_left_pt: 36.0,
      margin_right_pt: 36.0,
      ..PageSetup::default()
    };
    let flow = flow_context(setup, 0, SectionColumns::default(), 0, 0, 36.0);
    let style = TextStyle {
      font_family: Some(Arc::from("Courier New")),
      font_size_pt: 12.0,
      ..TextStyle::default()
    };
    let title = "This title remains together after its tab";
    let run = TextRun {
      text: String::new(),
      style: style.clone(),
      hyperlink_url: None,
      dynamic_field: None,
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      preserve_text_portion: false,
    };
    let mut paragraph = Paragraph {
      inlines: Vec::new(),
      runs: Vec::new(),
      field_events: Vec::new(),
      footnote_reference_ids: Vec::new(),
      endnote_reference_ids: Vec::new(),
      starts_after_last_rendered_page_break: false,
      base_style: style.clone(),
      format: Box::new(ParagraphFormat {
        line_height_rule: LineHeightRule::Exact,
        line_height_pt: Some(18.0),
        widow_control: Some(false),
        tab_stops_set: true,
        ..ParagraphFormat::default()
      }),
      style_ref_keys: Vec::new(),
      style_ref_text: None,
      style_ref_numbering_text: None,
      list_label: None,
      list_label_image: None,
      list_label_style: style,
      list_label_hyperlink_url: None,
      list_label_tab_stop_pt: None,
    };
    let mut metrics = TextMetrics::new();
    for bidi in [false, true] {
      paragraph.format.bidi = bidi;
      for alignment in [TabStopAlignment::Right, TabStopAlignment::Center] {
        for position_pt in [24.0, 180.0, 390.0] {
          paragraph.format.tab_stops = vec![TabStop {
            position_pt,
            alignment,
            leader: TabLeader::None,
          }];
          for copies in [1, 2] {
            let mut run = run.clone();
            run.text = format!("\t{}", vec![title; copies].join(" "));
            paragraph.inlines = vec![InlineItem::Text(run.clone())];
            paragraph.runs = vec![run];
            let mut page = empty_page(setup, 0);
            let mut pages = Vec::new();
            layout_paragraph(
              &paragraph,
              flow,
              ParagraphLayoutTarget {
                current: &mut page,
                pages: &mut pages,
                anchor_pages: None,
                text_metrics: &mut metrics,
              },
              36.0,
              36.0,
              0.0,
            );
            assert!(pages.is_empty());
            let mut baselines = Vec::new();
            for item in &page.items {
              let PageItem::Text(text) = item else {
                continue;
              };
              if !baselines.contains(&text.y_pt) {
                baselines.push(text.y_pt);
              }
              // A preserved line-end blank may sit outside the print band;
              // check the visible title rather than its semantic blank.
              let left = text.x_pt;
              let width = metrics.measure_text(text.text.trim_end(), &text.style);
              assert!(left >= 36.0 - 0.01);
              assert!(
                left + width <= 464.0 + 0.01,
                "bidi={bidi}, {alignment:?}, position={position_pt}, copies={copies}"
              );
            }
            assert_eq!(
              baselines.len(),
              copies,
              "bidi={bidi}, {alignment:?}, position={position_pt}"
            );
          }
        }
      }
    }
    let mut positions = |paragraph: &Paragraph| {
      let mut page = empty_page(setup, 0);
      let mut pages = Vec::new();
      layout_paragraph(
        paragraph,
        flow,
        ParagraphLayoutTarget {
          current: &mut page,
          pages: &mut pages,
          anchor_pages: None,
          text_metrics: &mut metrics,
        },
        36.0,
        36.0,
        0.0,
      );
      assert!(pages.is_empty());
      pages.push(page);
      resolve_dynamic_fields(&mut pages, &[], &[], &[], 1, None, &mut metrics);
      pages
        .remove(0)
        .items
        .into_iter()
        .filter_map(|item| match item {
          PageItem::Text(text) => Some((text.text, text.x_pt, text.y_pt)),
          _ => None,
        })
        .collect::<Vec<_>>()
    };
    paragraph.format.bidi = true;
    paragraph.format.tab_stops[0].position_pt = 24.0;
    for adjust in [
      crate::docx::ParagraphAdjust::Right,
      crate::docx::ParagraphAdjust::Center,
    ] {
      paragraph.format.justification.adjust = adjust;
      paragraph.format.alignment = paragraph.format.justification.alignment();
      let mut control = run.clone();
      control.text = title.into();
      paragraph.inlines = vec![InlineItem::Text(control.clone())];
      let expected = positions(&paragraph);
      control.text.insert(0, '\t');
      paragraph.inlines = vec![InlineItem::Text(control)];
      let actual = positions(&paragraph);
      assert_eq!(actual.len(), expected.len());
      for (actual, expected) in actual.iter().zip(expected) {
        assert_eq!(actual.0, expected.0);
        assert!((actual.1 - expected.1).abs() < 0.001, "{adjust:?}");
        assert_eq!(actual.2, expected.2);
      }
    }
    // Office's omitted-tab controls also cover a subsequent authored tab:
    // collapsing the leading tab must preserve every span, leader and PAGE
    // anchor, independently of the paragraph's own left/center/right jc.
    for first_tab in [TabStopAlignment::Right, TabStopAlignment::Center] {
      for following_tab in [
        TabStopAlignment::Left,
        TabStopAlignment::Center,
        TabStopAlignment::Right,
      ] {
        paragraph.format.tab_stops = vec![
          TabStop {
            position_pt: 24.0,
            alignment: first_tab,
            leader: TabLeader::None,
          },
          TabStop {
            position_pt: 240.0,
            alignment: following_tab,
            leader: TabLeader::Dot,
          },
        ];
        for adjust in [
          crate::docx::ParagraphAdjust::Block,
          crate::docx::ParagraphAdjust::Left,
          crate::docx::ParagraphAdjust::Center,
          crate::docx::ParagraphAdjust::Right,
        ] {
          paragraph.format.justification.adjust = adjust;
          paragraph.format.alignment = paragraph.format.justification.alignment();
          for field in [false, true] {
            let mut prefix = run.clone();
            prefix.text = "Chapter Two:".into();
            let mut tab = run.clone();
            tab.text = "\t".into();
            let mut following = run.clone();
            following.text = if field { "42" } else { "Title" }.into();
            following.dynamic_field = field.then_some(DynamicFieldKind::Page {
              number_format: FieldNumberFormat::Decimal,
            });
            paragraph.inlines = vec![
              InlineItem::Text(prefix.clone()),
              InlineItem::Text(tab.clone()),
              InlineItem::Text(following.clone()),
            ];
            let expected = positions(&paragraph);
            prefix.text.insert(0, '\t');
            paragraph.inlines = vec![
              InlineItem::Text(prefix),
              InlineItem::Text(tab),
              InlineItem::Text(following),
            ];
            let actual = positions(&paragraph);
            assert_eq!(actual.len(), expected.len());
            for (actual, expected) in actual.iter().zip(expected) {
              assert_eq!(actual.0, expected.0);
              assert!(
                (actual.1 - expected.1).abs() < 0.001,
                "{first_tab:?}/{following_tab:?}/{adjust:?}/field={field}: {actual:?} != {expected:?}"
              );
              assert_eq!(actual.2, expected.2);
            }
          }
        }
      }
    }
    paragraph.format.tab_stops.truncate(1);
    paragraph.format.bidi = false;
    paragraph.format.justification = crate::docx::ParagraphJustification::default();
    paragraph.format.alignment = ParagraphAlignment::Left;
    paragraph.format.indent_left_pt = 64.0;
    paragraph.format.first_line_indent_pt = -64.0;
    paragraph.format.tab_stops[0].position_pt = 390.0;
    let placed = positions(&paragraph);
    assert!((placed[0].1 - 100.0).abs() < 0.001, "hanging implicit tab");
  }

  #[test]
  fn aligned_tab_keeps_raised_inline_object_and_following_text_together() {
    let mut metrics = TextMetrics::new();
    for alignment in [
      TabStopAlignment::Left,
      TabStopAlignment::Center,
      TabStopAlignment::Right,
    ] {
      let mut page = empty_page(PageSetup::default(), 0);
      wrap_inline_vector_shape_with_baseline_anchor(&mut page.items, 0, 0, 100.0, 5.0, 30.0, 30.0);
      let mut text = text_warp_bounds_test_item(12.0);
      text.text = "ABC".into();
      text.x_pt = 130.0;
      text.y_pt = 20.0;
      text.paragraph_bidi = true;
      let total_width = 30.0 + metrics.measure_text(&text.text, &text.style);
      page.items.push(PageItem::Text(Box::new(text)));
      let mut tab = Some(PendingAlignedTab {
        stop: ResolvedTabStop {
          x_pt: 100.0,
          alignment,
          leader: TabLeader::None,
          automatic: false,
        },
        leader_start_x_pt: 0.0,
        leader_layout: TabLeaderLayout::NaturalStart,
        y_pt: 20.0,
        line_height_pt: 18.0,
        style: TextStyle::default(),
        item_start_index: 0,
        field_result_tab: false,
        paragraph_bidi: true,
      });
      apply_pending_aligned_tab(&mut page, &mut tab, &mut metrics, 20.0, 0.0, 300.0);
      realign_resolved_dynamic_field_lines(&mut page.items, &mut metrics);
      let expected_left = 100.0
        - total_width
          * match alignment {
            TabStopAlignment::Center => 0.5,
            TabStopAlignment::Right => 1.0,
            _ => 0.0,
          };
      let (left, width) = item_horizontal_bounds(&page.items[0], &mut metrics).unwrap();
      assert!((left - expected_left).abs() < 0.001);
      assert_eq!(width, 30.0);
      let PageItem::Text(text) = &page.items[1] else {
        panic!()
      };
      assert!((text.x_pt - left - width).abs() < 0.001);
      assert!(tab.is_none());
    }
  }

  #[test]
  fn inline_object_line_uses_one_baseline_before_horizontal_alignment() {
    let mut metrics = TextMetrics::new();
    let mut before = text_warp_bounds_test_item(12.0);
    before.text = "ABC".into();
    before.x_pt = 10.0;
    before.y_pt = 20.0;
    before.line_height_pt = 14.0;
    let width = metrics.measure_text(&before.text, &before.style);
    let mut after = before.clone();
    after.text = "DEF".into();
    after.x_pt += width + 10.0;
    after.line_height_pt = 18.0;
    let mut items = vec![PageItem::Text(Box::new(before))];
    wrap_inline_vector_shape_with_baseline_anchor(&mut items, 1, 1, 10.0 + width, 18.0, 10.0, 16.0);
    let PageItem::Group(children) = &mut items[1] else {
      panic!()
    };
    let PageItem::Image(image) = &mut children[0] else {
      panic!()
    };
    image.inline_baseline_gap_pt = -5.0;
    items.push(PageItem::Text(Box::new(after)));
    let before_positions = items
      .iter()
      .map(|item| item_horizontal_bounds(item, &mut metrics).unwrap().0)
      .collect::<Vec<_>>();
    align_line_items_to_inline_object_baseline(
      &mut items,
      0,
      20.0,
      InlineBaselineMode::LineTop,
      &mut metrics,
    );
    let baselines = items
      .iter()
      .map(|item| item_alignment_y(item, &mut metrics, true).unwrap())
      .collect::<Vec<_>>();
    assert!(baselines.iter().all(|y| (y - baselines[0]).abs() < 0.001));
    align_paragraph_items(&mut items, ParagraphAlignment::Right, &mut metrics, 200.0);
    let shifts = items
      .iter()
      .zip(before_positions)
      .map(|(item, x)| item_horizontal_bounds(item, &mut metrics).unwrap().0 - x)
      .collect::<Vec<_>>();
    assert!(shifts[0] > 0.0);
    assert!(shifts.iter().all(|x| (x - shifts[0]).abs() < 0.001));
  }

  #[test]
  fn bidi_line_treats_inline_objects_as_atomic_neutrals_with_their_full_width() {
    let mut metrics = TextMetrics::new();
    for (before, after, before_rtl, after_rtl, order) in [
      ("אב", "גד", true, true, [2, 1, 0]),
      ("AB", "CD", false, false, [0, 1, 2]),
      ("אב", "CD", true, false, [2, 1, 0]),
      ("AB", "גד", false, true, [2, 1, 0]),
    ] {
      let text = |value: &str, rtl, x| {
        let mut item = text_warp_bounds_test_item(12.0);
        item.text = value.into();
        item.style.right_to_left = Some(rtl);
        item.x_pt = x;
        item.y_pt = 20.0;
        item.paragraph_bidi = true;
        PageItem::Text(Box::new(item))
      };
      let first = text(before, before_rtl, 10.0);
      let first_width = item_horizontal_bounds(&first, &mut metrics).unwrap().1;
      let object_x = 10.0 + first_width;
      for checkbox in [false, true] {
        let mut items = vec![first.clone()];
        if checkbox {
          items.push(PageItem::LegacyFormCheckBox(Box::new(
            LegacyFormCheckBoxItem {
              x_pt: object_x,
              y_pt: 20.0,
              line_height_pt: 20.0,
              size_pt: 30.0,
              portion_ascent_pt: 24.0,
              table_cell_resolved_baseline: false,
              checked: true,
              style: TextStyle::default(),
              hyperlink_url: None,
              rotation_deg: 0.0,
              rotation_center_pt: None,
            },
          )));
        } else {
          items.push(PageItem::Rect(RectItem {
            x_pt: object_x + 4.0,
            y_pt: 5.0,
            width_pt: 22.0,
            height_pt: 30.0,
            paragraph_alignment_locked: false,
            fill_color: Some(RgbColor { r: 0, g: 0, b: 0 }),
            fill_opacity: 1.0,
            stroke: None,
            stroke_opacity: 1.0,
          }));
          wrap_inline_vector_shape_with_baseline_anchor(
            &mut items, 1, 2, object_x, 5.0, 30.0, 30.0,
          );
          let PageItem::Group(children) = &mut items[1] else {
            panic!()
          };
          let PageItem::Image(first) = &mut children[0] else {
            panic!()
          };
          first.width_pt = 20.0;
          first.content_type = Some("application/vnd.ooxmlsdk.office-math+xml".into());
          let mut second = first.clone();
          second.x_pt += 25.0;
          second.width_pt = 5.0;
          children.push(PageItem::Image(second));
        }
        items.push(text(after, after_rtl, object_x + 30.0));
        reorder_bidi_line_items(&mut items, 0, 20.0, &mut metrics);
        assert_eq!(items.len(), 3);
        let mut x = 10.0;
        for index in order {
          let (left, width) = item_horizontal_bounds(&items[index], &mut metrics).unwrap();
          assert!(
            (left - x).abs() < 0.001,
            "{before}/{after}, object={checkbox}"
          );
          x += width;
        }
        if let PageItem::Group(children) = &items[1] {
          let PageItem::Image(anchor) = &children[0] else {
            panic!()
          };
          let PageItem::Rect(paint) = &children[1] else {
            panic!()
          };
          assert!((paint.x_pt - anchor.x_pt - 4.0).abs() < 0.001);
          assert_eq!(anchor.y_pt, 5.0);
          assert_eq!(paint.y_pt, 5.0);
          assert_eq!(anchor.width_pt, 20.0);
          let PageItem::Image(second) = &children[2] else {
            panic!()
          };
          assert!((second.x_pt - anchor.x_pt - 25.0).abs() < 0.001);
          assert_eq!(second.width_pt, 5.0);
        }
        for index in [0, 2] {
          let PageItem::Text(text) = &items[index] else {
            panic!()
          };
          assert_eq!(text.text, if index == 0 { before } else { after });
          assert!(
            text.style.shaping_context.is_none(),
            "object breaks shaping context"
          );
        }
      }
    }
  }

  #[test]
  fn bidi_inline_picture_follows_preceding_level_instead_of_math_neutral_rule() {
    let mut metrics = TextMetrics::new();
    for math in [false, true] {
      for (before, after, picture_first) in [
        ("On", "", math),
        ("123", "", math),
        ("", "On", false),
        ("אב", "", true),
      ] {
        let mut items = Vec::new();
        let mut text = text_warp_bounds_test_item(12.0);
        text.text = if before.is_empty() { after } else { before }.into();
        text.style.right_to_left = Some(before == "אב");
        text.x_pt = 10.0;
        text.y_pt = 20.0;
        text.paragraph_bidi = true;
        let text_width = metrics.measure_text(&text.text, &text.style);
        if !before.is_empty() {
          items.push(PageItem::Text(Box::new(text.clone())));
        }
        let index = items.len();
        wrap_inline_vector_shape_with_baseline_anchor(
          &mut items,
          index,
          index,
          10.0 + if before.is_empty() { 0.0 } else { text_width },
          5.0,
          30.0,
          30.0,
        );
        let PageItem::Group(children) = &mut items[index] else {
          panic!()
        };
        let PageItem::Image(image) = &mut children[0] else {
          panic!()
        };
        image.content_type = Some(if math {
          "application/vnd.ooxmlsdk.office-math+xml".into()
        } else {
          "image/png".into()
        });
        if before.is_empty() {
          text.x_pt += 30.0;
          items.push(PageItem::Text(Box::new(text)));
        }
        reorder_bidi_line_items(&mut items, 0, 20.0, &mut metrics);
        let (picture_x, _) = item_horizontal_bounds(&items[index], &mut metrics).unwrap();
        let expected_x = 10.0 + if picture_first { 0.0 } else { text_width };
        assert!(
          (picture_x - expected_x).abs() < 0.001,
          "{before}/{after}, math={math}"
        );
      }
    }
  }

  #[test]
  fn bidi_line_preserves_arabic_joining_across_language_and_color_runs() {
    fn text_item(x_pt: f32, text: &str) -> PageItem {
      PageItem::Text(Box::new(TextItem {
        x_pt,
        y_pt: 20.0,
        line_height_pt: DEFAULT_LINE_HEIGHT_PT,
        wordprocessing_auto_line_spacing_units: None,
        wordprocessing_line_metrics: None,
        origin_is_baseline: false,
        line_metrics_participant: true,
        paint_clip: None,
        wordprocessing_effect_host: None,
        wordprocessing_terminal_effect_style: None,
        text: text.to_string(),
        style: TextStyle::default(),
        rotation_center_pt: None,
        hyperlink_url: None,
        dynamic_field: None,
        dynamic_field_line_anchor: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        form_widget_id: None,
        paragraph_bidi: false,
        word_spacing_pt: 0.0,
        preserve_text_portion: false,
        decoration_span_start_x_pt: None,
        pdf_text_segmentation: PdfTextSegmentation::Line,
      }))
    }
    let mut metrics = TextMetrics::new();
    let style = TextStyle {
      font_family: Some(Arc::from("Arial")),
      complex_font_family: Some(Arc::from("Arial")),
      font_size_pt: 14.0,
      complex_font_size_pt: Some(14.0),
      right_to_left: Some(true),
      resolved_bidi_level: Some(1),
      ..TextStyle::default()
    };
    for parts in [
      ["وكذل", "ك"],
      ["للر", "حمن"],
      ["ب", "بي"],
      ["س", "بي"],
      ["سل", "ي"],
      ["ب", "ب"],
      ["ب\u{200c}", "ب"],
      ["ب ", "ب"],
    ] {
      let whole = parts.concat();
      let expected = metrics.shape_text(&whole, &style).unwrap();
      let mut items = Vec::new();
      let mut x = 0.0;
      for (index, part) in parts.iter().enumerate() {
        let mut item = text_item(x, part);
        let PageItem::Text(text) = &mut item else {
          unreachable!()
        };
        text.paragraph_bidi = true;
        text.style = style.clone();
        text.style.bidi_language = Some(Arc::from(if index == 0 { "fa-IR" } else { "ar-SA" }));
        text.style.color = RgbColor {
          r: if index == 0 { 144 } else { 0 },
          g: 0,
          b: if index == 1 { 144 } else { 0 },
        };
        x += metrics.measure_text(part, &text.style);
        items.push(item);
      }
      let authored = items
        .iter()
        .map(|item| {
          let PageItem::Text(text) = item else {
            unreachable!()
          };
          text.style.clone()
        })
        .collect::<Vec<_>>();
      reorder_bidi_line_items(&mut items, 0, 20.0, &mut metrics);
      let mut actual = Vec::new();
      let mut total = 0.0;
      for (index, item) in items.iter().enumerate().rev() {
        let PageItem::Text(text) = item else {
          unreachable!()
        };
        assert_eq!(text.text, parts[index]);
        let mut retained = text.style.clone();
        retained.shaping_context = None;
        assert_eq!(retained, authored[index]);
        let shaped = metrics.shape_text(&text.text, &text.style).unwrap();
        let width = metrics.measure_text(&text.text, &text.style);
        assert!((width - shaped.width_pt).abs() < 0.001);
        assert!((text.x_pt - total).abs() < 0.001, "{parts:?}");
        total += width;
        actual.extend(shaped.glyphs.into_iter().map(|glyph| glyph.glyph_id));
      }
      assert_eq!(
        actual,
        expected
          .glyphs
          .iter()
          .map(|glyph| glyph.glyph_id)
          .collect::<Vec<_>>(),
        "{parts:?}"
      );
      assert!(
        (total - expected.width_pt).abs() < 0.001,
        "{parts:?}: {total} vs {}",
        expected.width_pt
      );
      assert!((metrics.measure_text(&whole, &style) - expected.width_pt).abs() < 0.001);
    }

    // Native Word keeps the color/language joins above, but changes to the
    // selected font properties terminate them, including distinct authored
    // family names which happen to use the same installed fallback font.
    for change in ["family", "size", "bold", "italic", "spacing", "scale"] {
      let mut right_style = style.clone();
      match change {
        "family" => right_style.complex_font_family = Some(Arc::from("Times New Roman")),
        "size" => right_style.complex_font_size_pt = Some(18.0),
        "bold" => right_style.complex_bold = Some(true),
        "italic" => right_style.complex_italic = Some(true),
        "spacing" => right_style.character_spacing_pt = 1.0,
        "scale" => right_style.horizontal_scale = Some(1.5),
        _ => unreachable!(),
      }
      let mut items = [text_item(0.0, "ثوبان"), text_item(40.0, "س")].to_vec();
      for (item, item_style) in items.iter_mut().zip([style.clone(), right_style]) {
        let PageItem::Text(text) = item else {
          unreachable!()
        };
        text.paragraph_bidi = true;
        text.style = item_style;
      }
      let isolated = metrics.shape_text("ثوبان", &style).unwrap();
      reorder_bidi_line_items(&mut items, 0, 20.0, &mut metrics);
      for item in &items {
        let PageItem::Text(text) = item else {
          unreachable!()
        };
        assert!(text.style.shaping_context.is_none(), "{change}");
        if text.text == "ثوبان" {
          let actual = metrics.shape_text(&text.text, &text.style).unwrap();
          assert_eq!(
            actual
              .glyphs
              .iter()
              .map(|glyph| glyph.glyph_id)
              .collect::<Vec<_>>(),
            isolated
              .glyphs
              .iter()
              .map(|glyph| glyph.glyph_id)
              .collect::<Vec<_>>(),
            "{change}: the final noon must not join the next font run"
          );
        }
      }
    }
  }

  #[test]
  fn bidi_line_items_follow_visual_run_order_without_reversing_source_text() {
    let mut text_metrics = TextMetrics::new();
    let style = TextStyle::default();
    let mut x = 0.0;
    let mut items = ["ارمان", "(", "ArmanAg", ")"]
      .into_iter()
      .map(|value| {
        let item = PageItem::Text(Box::new(TextItem {
          x_pt: x,
          y_pt: 20.0,
          line_height_pt: DEFAULT_LINE_HEIGHT_PT,
          wordprocessing_auto_line_spacing_units: None,
          wordprocessing_line_metrics: None,
          origin_is_baseline: false,
          line_metrics_participant: true,
          paint_clip: None,
          wordprocessing_effect_host: None,
          wordprocessing_terminal_effect_style: None,
          text: value.to_string(),
          style: style.clone(),
          rotation_center_pt: None,
          hyperlink_url: None,
          dynamic_field: None,
          dynamic_field_line_anchor: None,
          style_ref_keys: Vec::new(),
          style_ref_text: None,
          style_ref_numbering_text: None,
          form_widget_id: None,
          paragraph_bidi: true,
          word_spacing_pt: 0.0,
          preserve_text_portion: false,
          decoration_span_start_x_pt: None,
          pdf_text_segmentation: PdfTextSegmentation::Line,
        }));
        x += text_metrics.measure_text(value, &style);
        item
      })
      .collect::<Vec<_>>();

    reorder_bidi_line_items(&mut items, 0, 20.0, &mut text_metrics);

    let x = |index: usize| {
      let PageItem::Text(text) = &items[index] else {
        panic!("expected text");
      };
      text.x_pt
    };
    assert!(x(1) < x(2));
    assert!(x(2) < x(3));
    assert!(x(3) < x(0));
    let PageItem::Text(arabic) = &items[0] else {
      panic!("expected Arabic text");
    };
    assert_eq!(arabic.text, "ارمان");
    let levels = items
      .iter()
      .map(|item| {
        let PageItem::Text(text) = item else {
          panic!("expected text");
        };
        text.style.resolved_bidi_level
      })
      .collect::<Vec<_>>();
    assert_eq!(levels, [Some(1), Some(2), Some(2), Some(2)]);
  }

  #[test]
  fn bidi_tab_anchor_survives_splitting_ordinary_mixed_direction_text() {
    let mut metrics = TextMetrics::new();
    for alignment in [
      ParagraphAlignment::Left,
      ParagraphAlignment::Center,
      ParagraphAlignment::Right,
    ] {
      let anchor = DynamicFieldLineAnchor {
        position_pt: 300.0,
        alignment,
        aligned_tab: Some(DynamicFieldAlignedTab {
          start_x_pt: 360.0,
          leader: TabLeader::None,
          inside_field_result: false,
          leader_layout: TabLeaderLayout::OfficeLegacyPrintGridEnd,
          logical_repeat_width_pt: 0.0,
        }),
      };
      let mut text = text_warp_bounds_test_item(15.0);
      text.text = "المادة 18 من".into();
      text.x_pt = 0.0;
      text.y_pt = 20.0;
      text.paragraph_bidi = true;
      text.style.right_to_left = Some(true);
      text.style.bidi_language = Some(Arc::from("ar-LB"));
      text.dynamic_field_line_anchor = Some(anchor);
      let mut items = vec![PageItem::Text(Box::new(text))];
      reorder_bidi_line_items(&mut items, 0, 20.0, &mut metrics);
      let texts = items
        .iter()
        .map(|item| {
          let PageItem::Text(text) = item else {
            unreachable!()
          };
          text
        })
        .collect::<Vec<_>>();
      assert_eq!(texts.len(), 3);
      assert_eq!(
        texts
          .iter()
          .map(|text| text.text.as_str())
          .collect::<Vec<_>>(),
        ["المادة ", "18", " من"]
      );
      assert!(texts[2].x_pt < texts[1].x_pt && texts[1].x_pt < texts[0].x_pt);
      assert!(
        texts
          .iter()
          .all(|text| text.dynamic_field_line_anchor == Some(anchor))
      );
      assert_eq!(texts[1].style.resolved_bidi_level, Some(2));
      let positions = texts.iter().map(|text| text.x_pt).collect::<Vec<_>>();
      // Static tab spans have already been aligned; refreshing fields must
      // retain every portion's position and the shared tab bookkeeping.
      realign_resolved_dynamic_field_lines(&mut items, &mut metrics);
      let refreshed = items
        .iter()
        .map(|item| {
          let PageItem::Text(text) = item else {
            unreachable!()
          };
          text.x_pt
        })
        .collect::<Vec<_>>();
      assert_eq!(refreshed, positions);
    }
  }

