  #[test]
  fn bidi_line_preserves_word_numeric_direction_regions() {
    let mut metrics = TextMetrics::new();
    for prefix in ["", "First ", "كلمة "] {
      for suffix in ["", " Last", " كلمة"] {
        for separator in [":", "."] {
          for separator_rtl in [None, Some(false), Some(true)] {
            for split_digits in [false, true] {
              let mut items = Vec::new();
              let mut x = 0.0;
              let mut push = |value: &str, rtl: Option<bool>, size: f32| {
                if value.is_empty() {
                  return;
                }
                let mut text = text_warp_bounds_test_item(size);
                text.text = value.into();
                text.paragraph_bidi = true;
                text.y_pt = 20.0;
                text.x_pt = x;
                text.style.font_family = Some(Arc::from("Times New Roman"));
                text.style.right_to_left = rtl;
                x += metrics.measure_text(&text.text, &text.style);
                items.push(PageItem::Text(Box::new(text)));
              };
              push(prefix, Some(prefix.contains('ك')), 8.0);
              for digits in if split_digits {
                vec!["3", "4"]
              } else {
                vec!["34"]
              } {
                push(digits, Some(true), 12.0);
              }
              push(separator, separator_rtl, 8.0);
              for digits in if split_digits {
                vec!["6", "6"]
              } else {
                vec!["66"]
              } {
                push(digits, Some(true), 12.0);
              }
              push(suffix, Some(suffix.contains('ك')), 8.0);
              reorder_bidi_line_items(&mut items, 0, 20.0, &mut metrics);
              let mut texts = items
                .iter()
                .filter_map(|item| match item {
                  PageItem::Text(text) => Some(text.as_ref()),
                  _ => None,
                })
                .collect::<Vec<_>>();
              texts.sort_by(|left, right| left.x_pt.total_cmp(&right.x_pt));
              let visual = texts
                .iter()
                .map(|text| text.text.as_str())
                .collect::<String>();
              let value = if separator_rtl == Some(true) {
                format!("34{separator}66")
              } else {
                format!("66{separator}34")
              };
              assert_eq!(
                visual,
                format!("{suffix}{value}{prefix}"),
                "prefix={prefix:?}, suffix={suffix:?}, separator={separator:?}, rtl={separator_rtl:?}, split={split_digits}"
              );
              for text in texts {
                if text.text.chars().all(|ch| ch.is_ascii_digit()) {
                  assert_eq!(text.style.resolved_bidi_level, Some(2));
                }
              }
            }
          }
        }
      }
    }
  }

  #[test]
  fn bidi_line_keeps_nbsp_as_an_independent_directional_blank() {
    let mut metrics = TextMetrics::new();
    for prefix in ["", "Test ", "كلمة "] {
      for suffix in ["", " Test", " كلمة"] {
        for separator in ['\u{00A0}', '\u{202F}', ' ', ','] {
          for rtl in [false, true] {
            for split in [false, true] {
              let number = format!("153{separator}1");
              let pieces = if split {
                vec!["153".to_string(), separator.to_string(), "1".to_string()]
              } else {
                vec![number.clone()]
              };
              let mut items = Vec::new();
              let mut x = 0.0;
              let mut push = |value: &str, direction: bool| {
                if value.is_empty() {
                  return;
                }
                let mut text = text_warp_bounds_test_item(12.0);
                text.text = value.into();
                text.paragraph_bidi = true;
                text.y_pt = 20.0;
                text.x_pt = x;
                text.style.font_family = Some(Arc::from("Times New Roman"));
                text.style.right_to_left = Some(direction);
                x += metrics.measure_text(&text.text, &text.style);
                items.push(PageItem::Text(Box::new(text)));
              };
              push(prefix, prefix.contains('ك'));
              for piece in &pieces {
                push(piece, rtl);
              }
              push(suffix, suffix.contains('ك'));
              reorder_bidi_line_items(&mut items, 0, 20.0, &mut metrics);
              let mut numeric = items
                .iter()
                .filter_map(|item| match item {
                  PageItem::Text(text)
                    if text
                      .text
                      .chars()
                      .all(|ch| ch.is_ascii_digit() || ch == separator) =>
                  {
                    Some(text.as_ref())
                  }
                  _ => None,
                })
                .collect::<Vec<_>>();
              numeric.sort_by(|left, right| left.x_pt.total_cmp(&right.x_pt));
              let visual = numeric
                .iter()
                .map(|text| text.text.as_str())
                .collect::<String>();
              let expected = if rtl && matches!(separator, '\u{00A0}' | ' ') {
                format!("1{separator}153")
              } else {
                number
              };
              assert_eq!(
                visual, expected,
                "prefix={prefix:?}, suffix={suffix:?}, separator={separator:?}, rtl={rtl}, split={split}"
              );
              for text in numeric {
                if text.text.chars().any(|ch| ch.is_ascii_digit()) {
                  assert_eq!(text.style.resolved_bidi_level, Some(2));
                }
              }
            }
          }
        }
      }
    }
  }

  #[test]
  fn bidi_line_keeps_rtl_numeric_terminators_outside_the_number() {
    let mut metrics = TextMetrics::new();
    for prefix in ["", "كلمة "] {
      for suffix in ["", " كلمة"] {
        for sign in ['#', '%', '$', '€', '£', '¥'] {
          for leading in [false, true] {
            for rtl in [false, true] {
              for split in [false, true] {
                let number = if leading {
                  format!("{sign}1.0")
                } else {
                  format!("1.0{sign}")
                };
                let mut items = Vec::new();
                let mut x = 0.0;
                let mut push = |value: &str, direction: bool| {
                  if value.is_empty() {
                    return;
                  }
                  let mut text = text_warp_bounds_test_item(12.0);
                  text.text = value.into();
                  text.paragraph_bidi = true;
                  text.y_pt = 20.0;
                  text.x_pt = x;
                  text.style.font_family = Some(Arc::from("Times New Roman"));
                  text.style.right_to_left = Some(direction);
                  x += metrics.measure_text(&text.text, &text.style);
                  items.push(PageItem::Text(Box::new(text)));
                };
                push(prefix, true);
                if split {
                  let sign = sign.to_string();
                  if leading {
                    push(&sign, rtl);
                    push("1.0", true);
                  } else {
                    push("1.0", true);
                    push(&sign, rtl);
                  }
                } else {
                  push(&number, rtl);
                }
                push(suffix, true);
                reorder_bidi_line_items(&mut items, 0, 20.0, &mut metrics);
                let mut numeric = items
                  .iter()
                  .filter_map(|item| match item {
                    PageItem::Text(text)
                      if text
                        .text
                        .chars()
                        .all(|ch| ch.is_ascii_digit() || ch == '.' || ch == sign) =>
                    {
                      Some(text.as_ref())
                    }
                    _ => None,
                  })
                  .collect::<Vec<_>>();
                numeric.sort_by(|left, right| left.x_pt.total_cmp(&right.x_pt));
                let visual = numeric
                  .iter()
                  .map(|text| text.text.as_str())
                  .collect::<String>();
                // In the split LTR-sign controls, the digits are still an
                // independent w:rtl region. Native Word reverses those two
                // outer regions while retaining the digits' inner LTR order.
                let numeric_region_rtl = rtl || split;
                let expected = if numeric_region_rtl && leading {
                  format!("1.0{sign}")
                } else if numeric_region_rtl {
                  format!("{sign}1.0")
                } else {
                  number
                };
                assert_eq!(
                  visual, expected,
                  "prefix={prefix:?}, suffix={suffix:?}, sign={sign}, rtl={rtl}, split={split}"
                );
                for text in numeric {
                  if text.text.chars().any(|ch| ch.is_ascii_digit()) {
                    assert_eq!(text.style.resolved_bidi_level, Some(2));
                  } else if rtl {
                    assert_eq!(text.style.resolved_bidi_level, Some(1));
                  }
                }
              }
            }
          }
        }
      }
    }
  }

  #[test]
  fn bidi_line_uses_bidi_language_for_numeric_separators() {
    fn item(language: &str, value: &str) -> PageItem {
      PageItem::Text(Box::new(TextItem {
        x_pt: 0.0,
        y_pt: 20.0,
        line_height_pt: DEFAULT_LINE_HEIGHT_PT,
        wordprocessing_auto_line_spacing_units: None,
        wordprocessing_line_metrics: None,
        origin_is_baseline: false,
        line_metrics_participant: true,
        paint_clip: None,
        wordprocessing_effect_host: None,
        wordprocessing_terminal_effect_style: None,
        text: value.to_string(),
        style: TextStyle {
          right_to_left: Some(true),
          bidi_language: Some(Arc::from(language)),
          ..TextStyle::default()
        },
        rotation_center_pt: None,
        hyperlink_url: None,
        dynamic_field: None,
        dynamic_field_line_anchor: None,
        style_ref_keys: Vec::new(),
        style_ref_text: None,
        style_ref_numbering_text: None,
        form_widget_id: None,
        paragraph_bidi: true,
        word_spacing_pt: 0.0,
        preserve_text_portion: false,
        decoration_span_start_x_pt: None,
        pdf_text_segmentation: PdfTextSegmentation::Line,
      }))
    }

    let mut text_metrics = TextMetrics::new();
    let mut arabic = vec![item("ar-SA", "25-12")];
    reorder_bidi_line_items(&mut arabic, 0, 20.0, &mut text_metrics);
    assert_eq!(arabic.len(), 3);
    let arabic_parts = arabic
      .iter()
      .map(|item| {
        let PageItem::Text(text) = item else {
          panic!("expected Arabic numeric text");
        };
        (
          text.text.as_str(),
          text.x_pt,
          text.style.resolved_bidi_level,
        )
      })
      .collect::<Vec<_>>();
    assert_eq!(
      arabic_parts
        .iter()
        .map(|(text, _, level)| (*text, *level))
        .collect::<Vec<_>>(),
      [("25", Some(2)), ("-", Some(1)), ("12", Some(2))]
    );
    assert!(arabic_parts[2].1 < arabic_parts[1].1);
    assert!(arabic_parts[1].1 < arabic_parts[0].1);

    let mut hebrew = vec![item("he-IL", "25-12")];
    reorder_bidi_line_items(&mut hebrew, 0, 20.0, &mut text_metrics);
    assert_eq!(hebrew.len(), 1);
    let PageItem::Text(text) = &hebrew[0] else {
      panic!("expected Hebrew numeric text");
    };
    assert_eq!(text.text, "25-12");
    assert_eq!(text.style.resolved_bidi_level, Some(2));

    // Native Word output: Persian and Urdu treat the solidus like Arabic,
    // while isolated plus and minus remain number separators. Each numeric
    // component itself remains left-to-right.
    for (language, source, expected_visual) in [
      ("fa-IR", "5/663", "663/5"),
      ("fa-IR", "25/12/2007", "2007/12/25"),
      ("fa-IR", "25-12-2007", "25-12-2007"),
      ("fa-IR", "25+12+2007", "25+12+2007"),
      ("ur-PK", "5/663", "663/5"),
      ("ur-PK", "25-12-2007", "25-12-2007"),
      ("ar-SA", "25/12/2007", "2007/12/25"),
      ("ar-SA", "25+12+2007", "2007+12+25"),
      ("he-IL", "25/12/2007", "25/12/2007"),
      ("en-US", "5/663", "5/663"),
    ] {
      let mut parts = vec![item(language, source)];
      reorder_bidi_line_items(&mut parts, 0, 20.0, &mut text_metrics);
      let logical = parts
        .iter()
        .map(|item| match item {
          PageItem::Text(text) => text.text.as_str(),
          _ => panic!("expected bidi text portion"),
        })
        .collect::<String>();
      assert_eq!(logical, source, "{language}");
      parts.sort_by(|a, b| {
        let PageItem::Text(a) = a else { panic!() };
        let PageItem::Text(b) = b else { panic!() };
        a.x_pt.total_cmp(&b.x_pt)
      });
      let visual = parts
        .iter()
        .map(|item| match item {
          PageItem::Text(text) => text.text.as_str(),
          _ => panic!("expected bidi text portion"),
        })
        .collect::<String>();
      assert_eq!(visual, expected_visual, "{language}: {source}");
    }

    // The inherited bidi language does not decide whether ES binds two
    // European digit groups when an RTL strong character precedes them.
    // Word footnote controls under stage117-footnote/office distinguish
    // Arabic/Persian prefixes from a Latin prefix and an isolated number.
    for (language, source, expected_numeric) in [
      ("fa-IR", "تعظیم: 1-92.", "92-1"),
      ("fa-IR", "کتاب 1+92", "92+1"),
      ("fa-IR", "تعظیم: 25-12-2007.", "2007-12-25"),
      ("en-US", "تعظیم: 1-92.", "92-1"),
      ("fa-IR", "abc 1-92", "1-92"),
      ("fa-IR", "1-92 تعظیم", "1-92"),
    ] {
      let mut parts = vec![item(language, source)];
      reorder_bidi_line_items(&mut parts, 0, 20.0, &mut text_metrics);
      parts.sort_by(|a, b| {
        let PageItem::Text(a) = a else { panic!() };
        let PageItem::Text(b) = b else { panic!() };
        a.x_pt.total_cmp(&b.x_pt)
      });
      let numeric = parts
        .iter()
        .filter_map(|item| match item {
          PageItem::Text(text) => Some(text.text.as_str()),
          _ => None,
        })
        .flat_map(str::chars)
        .filter(|&ch| ch.is_ascii_digit() || matches!(ch, '-' | '+' | '/'))
        .collect::<String>();
      assert_eq!(numeric, expected_numeric, "{language}: {source}");
    }
  }

  #[test]
  fn consecutive_rtl_note_references_reverse_as_whole_number_portions() {
    let mut metrics = TextMetrics::new();
    for labels in [["3", "4", "5"], ["12", "13", "14"]] {
      let mut base = text_warp_bounds_test_item(9.0);
      base.x_pt = 0.0;
      base.y_pt = 20.0;
      base.paragraph_bidi = true;
      base.style.right_to_left = Some(true);
      base.style.bidi_language = Some(Arc::from("fa-IR"));
      base.text = "هستیم".into();
      let mut items = vec![PageItem::Text(Box::new(base.clone()))];
      for (index, label) in labels.into_iter().enumerate() {
        let mut reference = base.clone();
        reference.text = label.into();
        reference.hyperlink_url = Some(format!("ooxmlsdk-pdf:footnote-reference:{}", index + 20));
        items.push(PageItem::Text(Box::new(reference)));
      }
      reorder_bidi_line_items(&mut items, 0, 20.0, &mut metrics);
      let mut references = items
        .iter()
        .filter_map(|item| match item {
          PageItem::Text(text) if text.hyperlink_url.is_some() => {
            Some((text.x_pt, text.text.as_str()))
          }
          _ => None,
        })
        .collect::<Vec<_>>();
      references.sort_by(|a, b| a.0.total_cmp(&b.0));
      assert_eq!(
        references.iter().map(|(_, text)| *text).collect::<Vec<_>>(),
        labels.into_iter().rev().collect::<Vec<_>>()
      );
    }
  }

  #[test]
  fn explicit_ltr_portions_keep_their_glyph_direction_inside_an_rtl_override() {
    let mut metrics = TextMetrics::new();
    let outer = crate::model::WordprocessingBidiScope {
      id: 0,
      right_to_left: true,
      override_direction: true,
    };
    let inner = crate::model::WordprocessingBidiScope {
      id: 1,
      right_to_left: false,
      override_direction: false,
    };
    // Native Word PDF/XPS and AnalyzeBidi controls reorder these portions in
    // both paragraph directions. Their glyph directions differ: ABC/DEF stay
    // LTR only in the bidi paragraph, where w:rtl participates in resolution.
    for paragraph_bidi in [false, true] {
      let mut x = 0.0;
      let mut items = ["LEFT ", "ABC 12:34 ", "nested 56:78 ", "DEF", " RIGHT"]
        .into_iter()
        .enumerate()
        .map(|(index, content)| {
          let mut text = text_warp_bounds_test_item(14.0);
          text.text = content.into();
          text.x_pt = x;
          text.y_pt = 20.0;
          text.paragraph_bidi = paragraph_bidi;
          text.style.right_to_left = Some(false);
          text.style.wordprocessing_bidi_scopes = match index {
            1 | 3 => Some(vec![outer].into()),
            2 => Some(vec![outer, inner].into()),
            _ => None,
          };
          x += metrics.measure_text(&text.text, &text.style);
          PageItem::Text(Box::new(text))
        })
        .collect::<Vec<_>>();
      reorder_bidi_line_items(&mut items, 0, 20.0, &mut metrics);
      items.sort_by(|a, b| {
        let (PageItem::Text(a), PageItem::Text(b)) = (a, b) else {
          unreachable!()
        };
        a.x_pt.total_cmp(&b.x_pt)
      });
      let texts = items
        .iter()
        .map(|item| {
          let PageItem::Text(text) = item else {
            unreachable!()
          };
          text
        })
        .collect::<Vec<_>>();
      assert_eq!(
        texts
          .iter()
          .map(|text| text.text.as_str())
          .collect::<Vec<_>>(),
        ["LEFT ", "DEF", "nested 56:78 ", "ABC 12:34 ", " RIGHT"]
      );
      for text in texts
        .iter()
        .filter(|text| text.style.wordprocessing_bidi_scopes.is_some())
      {
        let expected = if paragraph_bidi {
          None
        } else if text.text.starts_with("nested") {
          Some(2)
        } else {
          Some(1)
        };
        assert_eq!(text.style.resolved_bidi_level, expected);
      }
    }
  }

  #[test]
  fn ltr_paragraph_resolves_an_embedded_rtl_quote_without_reversing_english() {
    let mut metrics = TextMetrics::new();
    let outer = crate::model::WordprocessingBidiScope {
      id: 0,
      right_to_left: true,
      override_direction: false,
    };
    let inner = crate::model::WordprocessingBidiScope {
      id: 1,
      right_to_left: false,
      override_direction: false,
    };
    let mut x = 0.0;
    let mut items = ["BEFORE", "ראשון", "English", "אחרון", "AFTER"]
      .into_iter()
      .enumerate()
      .map(|(index, content)| {
        let mut text = text_warp_bounds_test_item(14.0);
        text.text = content.into();
        text.x_pt = x;
        text.y_pt = 20.0;
        text.paragraph_bidi = false;
        text.style.right_to_left = Some(false);
        text.style.wordprocessing_bidi_scopes = match index {
          1 | 3 => Some(vec![outer].into()),
          2 => Some(vec![outer, inner].into()),
          _ => None,
        };
        x += metrics.measure_text(&text.text, &text.style);
        PageItem::Text(Box::new(text))
      })
      .collect::<Vec<_>>();
    assert!(line_has_wordprocessing_bidi_scopes(&items, 0, 20.0));
    reorder_bidi_line_items(&mut items, 0, 20.0, &mut metrics);
    let english = items
      .iter()
      .find_map(|item| match item {
        PageItem::Text(text) if text.text == "English" => Some(text),
        _ => None,
      })
      .expect("English remains one logical portion");
    assert_eq!(english.style.resolved_bidi_level, Some(2));
    items.sort_by(|a, b| {
      let (PageItem::Text(a), PageItem::Text(b)) = (a, b) else {
        unreachable!()
      };
      a.x_pt.total_cmp(&b.x_pt)
    });
    assert_eq!(
      items
        .iter()
        .map(|item| match item {
          PageItem::Text(text) => text.text.as_str(),
          _ => unreachable!(),
        })
        .collect::<Vec<_>>(),
      ["BEFORE", "אחרון", "English", "ראשון", "AFTER"]
    );
  }

  #[test]
  fn rtl_numbering_resolves_visual_runs_without_reversing_digits_or_source_text() {
    let mut metrics = TextMetrics::new();
    for rtl in [None, Some(false), Some(true)] {
      for (label, visual) in [
        ("18-", "-18"),
        ("(18)", ")18("),
        ("18.", ".18"),
        ("18.2.", ".18.2"),
        ("A18-", "-A18"),
        ("18/2", "18/2"),
      ] {
        let source = TextItem {
          x_pt: 100.0,
          y_pt: 20.0,
          line_height_pt: DEFAULT_LINE_HEIGHT_PT,
          wordprocessing_auto_line_spacing_units: None,
          wordprocessing_line_metrics: None,
          origin_is_baseline: false,
          line_metrics_participant: true,
          paint_clip: None,
          wordprocessing_effect_host: None,
          wordprocessing_terminal_effect_style: None,
          text: label.into(),
          style: TextStyle {
            font_family: Some(Arc::from("Courier New")),
            right_to_left: rtl,
            ..TextStyle::default()
          },
          rotation_center_pt: None,
          hyperlink_url: Some("https://example.org/number".into()),
          dynamic_field: None,
          dynamic_field_line_anchor: None,
          style_ref_keys: Vec::new(),
          style_ref_text: None,
          style_ref_numbering_text: Some(Arc::from(label)),
          form_widget_id: None,
          paragraph_bidi: true,
          word_spacing_pt: 0.0,
          preserve_text_portion: false,
          decoration_span_start_x_pt: None,
          pdf_text_segmentation: PdfTextSegmentation::Line,
        };
        let mut items = vec![PageItem::Text(Box::new(source.clone()))];
        materialize_numbering_bidi(&mut items, &mut metrics);
        assert_eq!(items.len(), 1, "preserve enclosing frame item ranges");
        let portions = match &items[0] {
          PageItem::Group(portions) => portions.as_slice(),
          _ => items.as_slice(),
        };
        let mut text = portions
          .iter()
          .map(|item| {
            let PageItem::Text(text) = item else { panic!() };
            assert_eq!(text.style_ref_numbering_text.as_deref(), Some(label));
            assert_eq!(text.hyperlink_url, source.hyperlink_url);
            text.as_ref()
          })
          .collect::<Vec<_>>();
        assert_eq!(
          text.iter().map(|t| t.text.as_str()).collect::<String>(),
          label
        );
        text.sort_by(|a, b| a.x_pt.total_cmp(&b.x_pt));
        // Parentheses here are source characters; the shaper mirrors odd-level
        // glyphs. Do not replace their Unicode values to achieve that effect.
        assert_eq!(
          text.iter().map(|t| t.text.as_str()).collect::<String>(),
          visual
        );
        assert!((text[0].x_pt - source.x_pt).abs() < 0.001);
        for portion in &text {
          if portion.text.chars().any(|ch| ch.is_ascii_digit()) {
            assert_eq!(portion.style.resolved_bidi_level, Some(2));
          }
        }

        let mut ltr = source;
        ltr.paragraph_bidi = false;
        let mut items = vec![PageItem::Text(Box::new(ltr))];
        materialize_numbering_bidi(&mut items, &mut metrics);
        let PageItem::Text(ltr) = &items[0] else {
          panic!()
        };
        assert_eq!(ltr.text, label);
        assert_eq!(ltr.style.resolved_bidi_level, None);
      }
    }
  }

  #[test]
  fn bidi_line_splits_visual_portions_without_splitting_style_ref_caches() {
    let mut text_metrics = TextMetrics::new();
    for preserve in [false, true] {
      for numbering in [None, Some(Arc::<str>::from("3"))] {
        let mut items = vec![PageItem::Text(Box::new(TextItem {
          x_pt: 0.0,
          y_pt: 20.0,
          line_height_pt: DEFAULT_LINE_HEIGHT_PT,
          wordprocessing_auto_line_spacing_units: None,
          wordprocessing_line_metrics: None,
          origin_is_baseline: false,
          line_metrics_participant: true,
          paint_clip: None,
          wordprocessing_effect_host: None,
          wordprocessing_terminal_effect_style: None,
          text: "1-".to_string(),
          style: TextStyle {
            right_to_left: Some(true),
            ..TextStyle::default()
          },
          rotation_center_pt: None,
          hyperlink_url: None,
          dynamic_field: None,
          dynamic_field_line_anchor: None,
          style_ref_keys: vec![Arc::from("Heading 1")],
          style_ref_text: Some(Arc::from("1-")),
          style_ref_numbering_text: numbering.clone(),
          form_widget_id: None,
          paragraph_bidi: true,
          word_spacing_pt: 0.0,
          preserve_text_portion: preserve,
          decoration_span_start_x_pt: None,
          pdf_text_segmentation: PdfTextSegmentation::Line,
        }))];

        reorder_bidi_line_items(&mut items, 0, 20.0, &mut text_metrics);

        assert_eq!(items.len(), 2);
        let portions = items
          .iter()
          .map(|item| {
            let PageItem::Text(text) = item else {
              panic!("expected text portion");
            };
            assert_eq!(text.style_ref_keys.as_slice(), [Arc::from("Heading 1")]);
            assert_eq!(text.style_ref_text.as_deref(), Some("1-"));
            assert_eq!(text.style_ref_numbering_text, numbering);
            assert_eq!(text.preserve_text_portion, preserve);
            (
              text.text.as_str(),
              text.x_pt,
              text.style.resolved_bidi_level,
            )
          })
          .collect::<Vec<_>>();
        assert_eq!(portions[0].0, "1");
        assert_eq!(portions[1].0, "-");
        assert_eq!(portions[0].2, Some(2));
        assert_eq!(portions[1].2, Some(1));
        assert!(portions[1].1 < portions[0].1);
        let mut page = empty_page(PageSetup::default(), 0);
        page.items = items;
        let candidates = style_ref_candidates_by_page(&[page]);
        assert_eq!(candidates[0].len(), 1);
        assert_eq!(candidates[0][0].text.as_ref(), "1-");
        assert_eq!(candidates[0][0].numbering_text, numbering);
      }
    }
  }

